_G.__MonoConns = _G.__MonoConns or {}
function trackConn(conn)
    table.insert(_G.__MonoConns, conn)
    return conn
end

monoBindCapturing = false
monoBindCaptureCb = nil
monoBindCancelCb = nil
monoBindConn = nil
monoBindSwallow = false

function monoBindStopListener()
    if monoBindConn then
        pcall(function() monoBindConn:Disconnect() end)
        monoBindConn = nil
    end
end

function monoBindEnsureListener()
    if monoBindConn then return end
    monoBindConn = UserInputService.InputBegan:Connect(function(input)
        if not monoBindCapturing then return end
        if input.UserInputType ~= Enum.UserInputType.Keyboard then return end
        if input.KeyCode == Enum.KeyCode.Unknown then return end
        monoBindSwallow = true
        local cb = monoBindCaptureCb
        monoBindEndCapture(true)
        if cb then pcall(cb, input) end
    end)
end

function monoBindEndCapture(quiet)
    local cancel = monoBindCancelCb
    monoBindCapturing = false
    monoBindCaptureCb = nil
    monoBindCancelCb = nil
    monoKeyCaptureActive = false
    if not quiet and cancel then pcall(cancel) end
    if monoToggleConnect then monoToggleConnect() end
    if monoCmdBindConnect then monoCmdBindConnect() end
end

function monoBindCapture(onKey, onCancel)
    monoBindEnsureListener()
    if monoBindCapturing then
        monoBindEndCapture()
        return
    end
    monoBindCapturing = true
    monoBindCaptureCb = onKey
    monoBindCancelCb = onCancel
    monoKeyCaptureActive = true
    if monoToggleDisconnect then monoToggleDisconnect() end
    if monoCmdBindDisconnect then monoCmdBindDisconnect() end
end

monoAlive = true

function runDestroyHooks()
    monoAlive = false
    monoBindEndCapture()
    monoBindStopListener()
    if monoToggleDisconnect then monoToggleDisconnect() end
    if monoCmdBindDisconnect then monoCmdBindDisconnect() end
    if monoCmdSorted then
        for _, cmd in ipairs(monoCmdSorted()) do
            local fn = monoCmdDestroy[cmd.name]
            if fn then
                monoCmdDestroy[cmd.name] = nil
                pcall(fn)
            end
        end
    end
    for name, fn in pairs(monoCmdDestroy) do
        monoCmdDestroy[name] = nil
        pcall(fn)
    end
    local hooks = table.move(Library._onDestroy, 1, #Library._onDestroy, 1, {})
    table.clear(Library._onDestroy)
    for _, fn in ipairs(hooks) do pcall(fn) end
    pcall(function() monoEnv.MONO_LOADED = nil end)
    pcall(function() monoEnv.MONO_LIBRARY = nil end)
    pcall(function() _G.MONO_LOADED = nil end)
    pcall(function() _G.MONO_LIBRARY = nil end)
end

function Library:OnDestroy(fn)
    if type(fn) == "function" then table.insert(Library._onDestroy, fn) end
    return Library
end

C = {
    bg         = Color3.fromRGB(0, 0, 0),
    bgDeep     = Color3.fromRGB(0, 0, 0),
    panel      = Color3.fromRGB(8, 8, 8),
    surface    = Color3.fromRGB(14, 14, 14),
    surfaceHi  = Color3.fromRGB(26, 26, 26),
    input      = Color3.fromRGB(18, 18, 18),
    text       = Color3.fromRGB(240, 240, 240),
    textMut    = Color3.fromRGB(160, 160, 160),
    textDim    = Color3.fromRGB(100, 100, 100),
    border     = Color3.fromRGB(36, 36, 36),
    borderSoft = Color3.fromRGB(24, 24, 24),
    card        = Color3.fromRGB(14, 14, 14),
    sep         = Color3.fromRGB(36, 36, 36),
    accent     = Color3.fromRGB(255, 255, 255),
}

function create(class, props, parent)
    local i = Instance.new(class)
    for k, v in pairs(props or {}) do
        if k ~= "Parent" then
            pcall(function() i[k] = v end)
        end
    end
    i.Parent = parent
    return i
end

function corner(inst, r)
    return create("UICorner", { CornerRadius = UDim.new(0, r or 8) }, inst)
end

function stroke(inst, color, thick, transp)
    return create("UIStroke", {
        Color = color or C.borderSoft,
        Thickness = thick or 1,
        Transparency = transp == nil and 0.5 or transp,
        ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
    }, inst)
end

function tween(inst, props, t, style, dir)
    pcall(function()
        TweenService:Create(inst, TweenInfo.new(t or 0.2,
            style or Enum.EasingStyle.Quint,
            dir or Enum.EasingDirection.Out), props):Play()
    end)
end

function monoBuildFlakes(parent, count, speedBase, speedRange, swayBase, swayRange, transBase, transRange)
    local flakes = {}
    for i = 1, count do
        local size = math.random(1, 3)
        local flake = create("Frame", {
            Size = UDim2.new(0, size, 0, size),
            BackgroundColor3 = C.accent, BorderSizePixel = 0,
            BackgroundTransparency = transBase + math.random() * transRange,
        }, parent)
        corner(flake, 999)
        flakes[i] = {
            f = flake,
            x = math.random(),
            y = -math.random() * 0.6,
            speed = speedBase + math.random() * speedRange,
            sway = swayBase + math.random() * swayRange,
            freq = 0.6 + math.random() * 1.2,
            phase = math.random() * math.pi * 2,
        }
    end
    return flakes
end

function monoStartSnow(canvas, flakes)
    local acc = 0
    return trackConn(RunService.Heartbeat:Connect(function(dt)
        if not canvas.Parent or not canvas.Visible then return end
        acc += dt
        if acc < 0.033 then return end
        local step = acc
        acc = 0
        if canvas.AbsoluteSize.X < 1 or canvas.AbsoluteSize.Y < 1 then return end
        local now = tick()
        for _, fl in ipairs(flakes) do
            if fl.f.Parent then
                fl.y = fl.y + fl.speed * step
                if fl.y > 1.02 then
                    fl.y = -0.02
                    fl.x = math.random()
                end
                fl.f.Position = UDim2.new(fl.x, math.sin(now * fl.freq + fl.phase) * fl.sway, fl.y, 0)
            end
        end
    end))
end

function monoBuildPanelSlider(parent, cfg)
    local state = cfg.state
    local min, max = cfg.min, cfg.max
    local initial = cfg.value or state.value or min
    local sec = monoPanelSection(parent, cfg.order or 2)
    sec.Size = UDim2.new(1, 0, 0, 52)
    create("UIPadding", { PaddingTop = UDim.new(0, 5), PaddingBottom = UDim.new(0, 5) }, sec)
    create("UIListLayout", { Padding = UDim.new(0, 2), SortOrder = Enum.SortOrder.LayoutOrder }, sec)

    local labelRow = create("Frame", { Size = UDim2.new(1, 0, 0, 20), BackgroundTransparency = 1, LayoutOrder = 1 }, sec)
    create("UIPadding", { PaddingLeft = UDim.new(0, 12), PaddingRight = UDim.new(0, 12) }, labelRow)
    create("TextLabel", {
        Size = UDim2.new(1, -60, 1, 0), BackgroundTransparency = 1,
        Text = cfg.label, TextColor3 = C.text, TextSize = 12,
        Font = Enum.Font.Gotham, TextXAlignment = Enum.TextXAlignment.Left,
    }, labelRow)
    local valLabel = create("TextLabel", {
        Size = UDim2.new(0, 55, 1, 0), Position = UDim2.new(1, -55, 0, 0),
        BackgroundTransparency = 1, Text = (cfg.format or tostring)(initial),
        TextColor3 = C.textMut, TextSize = 11, Font = Enum.Font.Gotham,
        TextXAlignment = Enum.TextXAlignment.Right,
    }, labelRow)

    local sliderRow = create("Frame", { Size = UDim2.new(1, 0, 0, 18), BackgroundTransparency = 1, LayoutOrder = 2 }, sec)
    create("UIPadding", { PaddingLeft = UDim.new(0, 12), PaddingRight = UDim.new(0, 12) }, sliderRow)
    local track = create("Frame", {
        Size = UDim2.new(1, 0, 0, 6), Position = UDim2.new(0, 0, 0.5, -3),
        BackgroundColor3 = C.input, BorderSizePixel = 0, Active = true,
    }, sliderRow)
    corner(track, 999)
    local scale = math.clamp((initial - min) / (max - min), 0, 1)
    local fill = create("Frame", {
        Size = UDim2.new(scale, 0, 1, 0), BackgroundColor3 = C.accent, BorderSizePixel = 0,
    }, track)
    corner(fill, 999)
    local knob = create("Frame", {
        Size = UDim2.new(0, 14, 0, 14), Position = UDim2.new(scale, 0, 0.5, 0),
        AnchorPoint = Vector2.new(0.5, 0.5), BackgroundColor3 = C.text,
        BorderSizePixel = 0, ZIndex = 3,
    }, track)
    corner(knob, 999)

    state.fill = fill
    state.knob = knob
    state.track = track
    state.valLabel = valLabel
    state.dragging = false

    local function slideTo(input)
        local w = math.max(1, track.AbsoluteSize.X)
        local rel = math.clamp((input.Position.X - track.AbsolutePosition.X) / w, 0, 1)
        cfg.onSet(min + rel * (max - min))
    end

    knob.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
        or input.UserInputType == Enum.UserInputType.Touch then
            state.dragging = true
        end
    end)
    track.InputBegan:Connect(function(input)
        if input.UserInputType ~= Enum.UserInputType.MouseButton1
        and input.UserInputType ~= Enum.UserInputType.Touch then return end
        local now = tick()
        if now - state.lastClick < 0.3 then
            state.lastClick = 0
            state.dragging = false
            cfg.onSet(cfg.reset)
        else
            state.lastClick = now
            state.dragging = true
            slideTo(input)
        end
    end)
    state.moveConn = trackConn(UserInputService.InputChanged:Connect(function(input)
        if not state.dragging then return end
        if input.UserInputType ~= Enum.UserInputType.MouseMovement
        and input.UserInputType ~= Enum.UserInputType.Touch then return end
        slideTo(input)
    end))
    state.endConn = trackConn(UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
        or input.UserInputType == Enum.UserInputType.Touch then
            state.dragging = false
        end
    end))
end

