function applyDisplayOrder(gui, hi, lo)
    if not gui then return nil end
    pcall(function() gui.DisplayOrder = hi end)
    if gui.DisplayOrder < 1000 then
        pcall(function() gui.DisplayOrder = lo end)
    end
    return gui.DisplayOrder
end

function monoGuiRoot()
    if typeof(gethui) == "function" then
        local ok, host = pcall(gethui)
        if ok and host and typeof(host) == "Instance" then return host end
    end
    if typeof(get_hidden_gui) == "function" then
        local ok, host = pcall(get_hidden_gui)
        if ok and host and typeof(host) == "Instance" then return host end
    end
    return CoreGui
end

function monoGuiParent(gui)
    if not gui then return nil end
    pcall(function()
        if syn and syn.protect_gui then syn.protect_gui(gui) end
        if protect_gui then protect_gui(gui) end
    end)
    local host = monoGuiRoot()
    if host then pcall(function() gui.Parent = host end) end
    if not gui.Parent then pcall(function() gui.Parent = CoreGui end) end
    if not gui.Parent then pcall(function() gui.Parent = PlayerGui end) end
    return gui.Parent
end

function monoGuiFind(name)
    local host = monoGuiRoot()
    local found = nil
    if host then found = host:FindFirstChild(name) end
    if not found then found = CoreGui:FindFirstChild(name) end
    if not found then found = PlayerGui:FindFirstChild(name) end
    return found
end

pcall(function()
    local hosts = {}
    local function push(h)
        if h and typeof(h) == "Instance" then
            for _, c in ipairs(hosts) do if c == h then return end end
            hosts[#hosts + 1] = h
        end
    end
    push(monoGuiRoot())
    push(CoreGui)
    push(PlayerGui)
    for _, host in ipairs(hosts) do
        for _, child in ipairs(host:GetChildren()) do
            if typeof(child) == "Instance" and child:IsA("BillboardGui") then
                local n = child.Name
                if n == "MonochromeNametag" or n:sub(1, #"MonochromeNametag_") == "MonochromeNametag_" then
                    pcall(function() child:Destroy() end)
                end
            end
        end
    end
end)

function monoClampPosToScreen(pos, sz)
    local cam = workspace.CurrentCamera
    if not cam then return pos end
    local vs = cam.ViewportSize
    local absX = pos.X.Scale * vs.X + pos.X.Offset
    local absY = pos.Y.Scale * vs.Y + pos.Y.Offset
    absX = math.clamp(absX, 0, math.max(0, vs.X - sz.X))
    absY = math.clamp(absY, 0, math.max(0, vs.Y - sz.Y))
    return UDim2.new(pos.X.Scale, absX - pos.X.Scale * vs.X,
        pos.Y.Scale, absY - pos.Y.Scale * vs.Y)
end

function clampFrameToScreen(frame, w, h)
    if not workspace.CurrentCamera then return end
    local sz = (w and h) and Vector2.new(w, h) or frame.AbsoluteSize
    frame.Position = monoClampPosToScreen(frame.Position, sz)
end

monoMainWindowFrame = nil

function monoCollisionTargets(skipFrame)
    local out = {}
    for _, entry in ipairs(monoPanelCols or {}) do
        if entry.frame and entry.frame ~= skipFrame then out[#out + 1] = entry.frame end
    end
    if monoMainWindowFrame and monoMainWindowFrame ~= skipFrame then
        out[#out + 1] = monoMainWindowFrame
    end
    return out
end

function makeDraggable(frame, handle, onEnd)
    local dragging, dragStart, startPos = false, nil, nil
    local lastInputPos, curX, curY = nil, nil, nil

    local function clampToScreen(pos)
        return monoClampPosToScreen(pos, frame.AbsoluteSize)
    end

    handle.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
        or input.UserInputType == Enum.UserInputType.Touch then
            dragging = true
            dragStart = input.Position
            startPos = frame.Position
            curX = frame.Position.X.Offset
            curY = frame.Position.Y.Offset
            lastInputPos = input.Position
        end
    end)

    handle.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
        or input.UserInputType == Enum.UserInputType.Touch then
            dragging = false
            if onEnd then pcall(onEnd) end
        end
    end)
    local dragEndConn = trackConn(UserInputService.InputEnded:Connect(function(input)
        if not dragging then return end
        if input.UserInputType == Enum.UserInputType.MouseButton1
        or input.UserInputType == Enum.UserInputType.Touch then
            dragging = false
            if onEnd then pcall(onEnd) end
        end
    end))

    local dragChangedConn = trackConn(UserInputService.InputChanged:Connect(function(input)
        if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement
        or input.UserInputType == Enum.UserInputType.Touch) then
            if (monoReanimWin and frame == monoReanimWin)
                or (monoMainWindowFrame and frame == monoMainWindowFrame) then
                local cam = workspace.CurrentCamera
                local vs = cam and cam.ViewportSize or Vector2.new(1920, 1080)
                local w, h = frame.AbsoluteSize.X, frame.AbsoluteSize.Y
                local dx = input.Position.X - (lastInputPos and lastInputPos.X or input.Position.X)
                local dy = input.Position.Y - (lastInputPos and lastInputPos.Y or input.Position.Y)
                if lastInputPos then
                    lastInputPos = input.Position
                else
                    lastInputPos = input.Position
                end
                local x = curX or frame.Position.X.Offset
                local y = curY or frame.Position.Y.Offset
                local targets = monoCollisionTargets(frame)
                local steps = math.max(1, math.ceil(math.max(math.abs(dx), math.abs(dy)) / 8))
                for _ = 1, steps do
                    x = x + dx / steps
                    y = y + dy / steps
                    for _ = 1, 8 do
                        local moved = false
                        for _, of in ipairs(targets) do
                            if not of or not of.Parent or of == frame then continue end
                            if not of.Visible then continue end
                            local hostGui = of:FindFirstAncestorOfClass("ScreenGui")
                            if hostGui and not hostGui.Enabled then continue end
                            local ox = of.Position.X.Offset
                            local oy = of.Position.Y.Offset
                            local ow = of.AbsoluteSize.X
                            local oh = of.AbsoluteSize.Y
                            if x < ox + ow and x + w > ox and y < oy + oh and y + h > oy then
                                local overlapX = math.min(x + w, ox + ow) - math.max(x, ox)
                                local overlapY = math.min(y + h, oy + oh) - math.max(y, oy)
                                if overlapX < overlapY then
                                    if x + w * 0.5 < ox + ow * 0.5 then
                                        x = ox - w
                                    else
                                        x = ox + ow
                                    end
                                else
                                    if y + h * 0.5 < oy + oh * 0.5 then
                                        y = oy - h
                                    else
                                        y = oy + oh
                                    end
                                end
                                moved = true
                            end
                        end
                        if not moved then break end
                    end
                end
                x = math.clamp(x, 0, math.max(0, vs.X - w))
                y = math.clamp(y, 0, math.max(0, vs.Y - h))
                curX = x
                curY = y
                frame.Position = UDim2.new(0, x, 0, y)
            else
                local delta = input.Position - dragStart
                local newPos = clampToScreen(UDim2.new(
                    startPos.X.Scale, startPos.X.Offset + delta.X,
                    startPos.Y.Scale, startPos.Y.Offset + delta.Y))
                frame.Position = newPos
            end
        end
    end))

    return function()
        pcall(function() dragEndConn:Disconnect() end)
        pcall(function() dragChangedConn:Disconnect() end)
    end
end

RunService = game:GetService("RunService")
ContextActionService = game:GetService("ContextActionService")

monoFreeCam = {
    running = false, followHead = false, camera = nil,
    pos = Vector3.zero, rot = Vector2.zero, fov = 70, navSpeed = 1,
    keys = {}, mouseDelta = Vector2.zero, lastMouse = nil,
    saved = nil, headData = nil,
    speed = 64, key = nil, keyConn = nil,
    btn = nil, bindBtn = nil, fill = nil, knob = nil, track = nil, valLabel = nil,
    dragging = false, lastClick = 0, moveConn = nil, endConn = nil,
}
monoFreeCamMin = 10
monoFreeCamMax = 500
monoFreeCamReset = 64

function monoFreeCamSave()
    if type(setData) == "table" then
        setData.freecamSpeed = monoFreeCam.speed
        setData.freecamBind = monoFreeCam.key or false
        if type(setSave) == "function" then setSave() end
    end
end

monoFreeCamSpeedRefresh = nil

function monoFreeCamSpeed(v)
    local n = math.clamp(math.floor(v + 0.5), monoFreeCamMin, monoFreeCamMax)
    monoFreeCam.speed = n
    local scale = (n - monoFreeCamMin) / (monoFreeCamMax - monoFreeCamMin)
    if monoFreeCam.fill then monoFreeCam.fill.Size = UDim2.new(scale, 0, 1, 0) end
    if monoFreeCam.knob then monoFreeCam.knob.Position = UDim2.new(scale, 0, 0.5, 0) end
    if monoFreeCam.valLabel then monoFreeCam.valLabel.Text = tostring(n) end
    if type(monoFreeCamSpeedRefresh) == "function" then pcall(monoFreeCamSpeedRefresh, n) end
    monoFreeCamSave()
end

function monoFreeCamLoad()
    if type(setData) ~= "table" then return end
    local raw = setData.freecamSpeed
    if raw ~= nil then
        monoFreeCam.speed = math.clamp(math.floor((tonumber(raw) or monoFreeCamReset) + 0.5), monoFreeCamMin, monoFreeCamMax)
    end
    if type(setData.freecamBind) == "string" and setData.freecamBind ~= "" then
        monoFreeCam.key = setData.freecamBind
    end
end
local monoFreeCamPriority = Enum.ContextActionPriority.High.Value

local MONO_FREECAM_MOUSE_STEP = "MonoFreeCamMouse"
local monoFreeCamMouseGen = 0
local monoFreeCamReleaseConn = nil

local function monoFreeCamApplyMouse()
    pcall(function()
        UserInputService.MouseIconEnabled = true
        if not UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton2) then
            UserInputService.MouseBehavior = Enum.MouseBehavior.Default
        end
    end)
end

local function monoFreeCamStopMouseEnforce()
    monoFreeCamMouseGen = monoFreeCamMouseGen + 1
    pcall(function() RunService:UnbindFromRenderStep(MONO_FREECAM_MOUSE_STEP) end)
end

local function monoFreeCamFreeMouse()
    monoFreeCamStopMouseEnforce()
    local gen = monoFreeCamMouseGen
    monoFreeCamApplyMouse()
    RunService:BindToRenderStep(MONO_FREECAM_MOUSE_STEP, Enum.RenderPriority.Camera.Value + 1, function()
        if gen ~= monoFreeCamMouseGen then return end
        monoFreeCamApplyMouse()
    end)
end

local function monoFreeCamReleaseMouse()
    monoFreeCamStopMouseEnforce()
    if monoFreeCamReleaseConn then
        pcall(function() monoFreeCamReleaseConn:Disconnect() end)
        monoFreeCamReleaseConn = nil
    end
    local gen = monoFreeCamMouseGen
    monoFreeCamApplyMouse()
    local frames = 0
    monoFreeCamReleaseConn = RunService.Heartbeat:Connect(function()
        if gen ~= monoFreeCamMouseGen then
            pcall(function() monoFreeCamReleaseConn:Disconnect() end)
            monoFreeCamReleaseConn = nil
            return
        end
        monoFreeCamApplyMouse()
        frames = frames + 1
        if frames >= 30 then
            pcall(function() monoFreeCamReleaseConn:Disconnect() end)
            monoFreeCamReleaseConn = nil
        end
    end)
end

local function monoFreeCamMouseSensitivity()
    local ok, v = pcall(function()
        return UserSettings():GetService("UserGameSettings").MouseSensitivity
    end)
    if ok and type(v) == "number" and v == v and v > 0 then return v end
    local legacy = UserInputService.MouseDeltaSensitivity
    if type(legacy) == "number" and legacy == legacy and legacy > 0 then return legacy end
    return 1
end

local function monoFreeCamYInvert()
    local ok, v = pcall(function()
        return UserSettings():GetService("UserGameSettings"):GetCameraYInvertValue()
    end)
    if ok and type(v) == "number" and v == v then return v end
    return 1
end

local function monoFreeCamKeyCb(action, state, input)
    monoFreeCam.keys[input.KeyCode.Name] = (state == Enum.UserInputState.Begin) and 1 or 0
    return Enum.ContextActionResult.Sink
end

local function monoFreeCamPanCb(action, state, input)
    if input.UserInputType == Enum.UserInputType.MouseMovement then
        local d = input.Delta
        monoFreeCam.mouseDelta = monoFreeCam.mouseDelta + Vector2.new(-d.Y, -d.X)
    end
    return Enum.ContextActionResult.Sink
end

local function monoFreeCamFocusDistance(cf)
    local znear = 0.1
    local cam = workspace.CurrentCamera
    local viewport = cam and cam.ViewportSize or Vector2.new(1920, 1080)
    local fov = monoFreeCam.fov or 70
    local projy = 2 * math.tan(math.rad(fov / 2))
    local projx = (viewport.X / math.max(1, viewport.Y)) * projy
    local fx, fy, fz = cf.RightVector, cf.UpVector, cf.LookVector
    local minDist, minVect = 512, Vector3.zero
    local ignore = LocalPlayer.Character and { LocalPlayer.Character } or {}
    for x = 0, 1, 0.5 do
        for y = 0, 1, 0.5 do
            local offset = fx * ((x - 0.5) * projx) - fy * ((y - 0.5) * projy) + fz
            local origin = cf.Position + offset * znear
            local ok, hit = pcall(function()
                local params = RaycastParams.new()
                params.FilterType = Enum.RaycastFilterType.Exclude
                params.FilterDescendantsInstances = ignore
                return workspace:Raycast(origin, offset.Unit * minDist, params)
            end)
            if ok and hit then
                local dist = (hit.Position - origin).Magnitude
                if dist < minDist then
                    minDist = dist
                    minVect = offset.Unit
                end
            end
        end
    end
    if minVect.Magnitude < 0.01 then return 5 end
    return math.clamp(fz:Dot(minVect) * minDist, 1, 500)
end

local function monoFreeCamStep(dt)
    if not monoFreeCam.running then return end
    local k = monoFreeCam.keys
    monoFreeCam.navSpeed = math.clamp(monoFreeCam.navSpeed + dt * ((k.Up or 0) - (k.Down or 0)) * 0.75, 0.01, 4)
    local shift = UserInputService:IsKeyDown(Enum.KeyCode.LeftShift) or UserInputService:IsKeyDown(Enum.KeyCode.RightShift)
    local kb = Vector3.new((k.D or 0) - (k.A or 0), (k.E or 0) - (k.Q or 0), (k.S or 0) - (k.W or 0)) * monoFreeCam.navSpeed
    local goalVel = kb * (shift and 0.25 or 1)

    local rmbHeld = UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton2)
    pcall(function()
        if rmbHeld then
            UserInputService.MouseBehavior = Enum.MouseBehavior.LockCenter
            UserInputService.MouseIconEnabled = false
        else
            UserInputService.MouseBehavior = Enum.MouseBehavior.Default
            UserInputService.MouseIconEnabled = true
        end
    end)

    local panInput = Vector2.zero
    if rmbHeld then
        local okDelta, md = pcall(function() return UserInputService:GetMouseDelta() end)
        if okDelta and md and md.Magnitude > 0 then
            panInput = Vector2.new(-md.Y, -md.X)
        else
            local raw = monoFreeCam.mouseDelta
            if raw.Magnitude < 0.001 and monoFreeCam.lastMouse then
                local mouseNow = UserInputService:GetMouseLocation()
                local cx = mouseNow.X - monoFreeCam.lastMouse.X
                local cy = mouseNow.Y - monoFreeCam.lastMouse.Y
                if math.abs(cx) < 200 and math.abs(cy) < 200 then
                    raw = Vector2.new(-cy, -cx)
                end
            end
            panInput = raw * monoFreeCamMouseSensitivity()
        end
    end
    monoFreeCam.mouseDelta = Vector2.zero
    monoFreeCam.lastMouse = UserInputService:GetMouseLocation()
    panInput = panInput * Vector2.new(1, monoFreeCamYInvert())

    local zoomFactor = math.sqrt(math.tan(math.rad(70 / 2)) / math.tan(math.rad((monoFreeCam.fov or 70) / 2)))
    if zoomFactor ~= zoomFactor or zoomFactor <= 0 then zoomFactor = 1 end
    local lookScale = math.rad(0.3) / zoomFactor
    local rx = math.clamp(monoFreeCam.rot.x + panInput.X * lookScale, -math.rad(90), math.rad(90))
    local ry = (monoFreeCam.rot.y + panInput.Y * lookScale) % (2 * math.pi)
    monoFreeCam.rot = Vector2.new(rx, ry)

    local cf = CFrame.new(monoFreeCam.pos)
        * CFrame.fromOrientation(rx, ry, 0)
        * CFrame.new(goalVel * monoFreeCam.speed * dt)
    monoFreeCam.pos = cf.Position

    local cam = monoFreeCam.camera
    if cam then
        cam.CFrame = cf
        cam.Focus = cf * CFrame.new(0, 0, -monoFreeCamFocusDistance(cf))
        cam.FieldOfView = monoFreeCam.fov
    end

    if monoFreeCam.followHead and monoFreeCam.headData then
        pcall(function()
            local h = monoFreeCam.headData
            if h.head and h.head.Parent then
                h.head.CFrame = cf
            end
        end)
    end
end

function monoFreeCamStart(followHead, optCF)
    if monoFreeCam.running then monoFreeCamStop() end
    local cam = workspace.CurrentCamera
    monoFreeCam.camera = cam
    local startCF = optCF or cam.CFrame
    monoFreeCam.pos = startCF.Position
    local rx, ry = startCF:ToOrientation()
    monoFreeCam.rot = Vector2.new(rx, ry)
    monoFreeCam.fov = cam.FieldOfView
    monoFreeCam.navSpeed = 1
    monoFreeCam.mouseDelta = Vector2.zero
    for key in pairs(monoFreeCam.keys) do monoFreeCam.keys[key] = 0 end

    pcall(function()
        monoFreeCam.saved = {
            ctype = cam.CameraType, cf = cam.CFrame, focus = cam.Focus, fov = cam.FieldOfView,
            mb = UserInputService.MouseBehavior, mi = UserInputService.MouseIconEnabled,
            devMouseLock = LocalPlayer.DevEnableMouseLock,
        }
        LocalPlayer.DevEnableMouseLock = false
        cam.CameraType = Enum.CameraType.Custom
        cam.FieldOfView = monoFreeCam.fov
    end)
    monoFreeCamFreeMouse()
    monoFreeCam.lastMouse = UserInputService:GetMouseLocation()

    monoFreeCam.followHead = followHead and true or false
    monoFreeCam.running = true
    pcall(function()
        ContextActionService:BindActionAtPriority("MonoFreeCamKeys", monoFreeCamKeyCb, false, monoFreeCamPriority,
            Enum.KeyCode.W, Enum.KeyCode.A, Enum.KeyCode.S, Enum.KeyCode.D,
            Enum.KeyCode.E, Enum.KeyCode.Q, Enum.KeyCode.Up, Enum.KeyCode.Down)
        ContextActionService:BindActionAtPriority("MonoFreeCamPan", monoFreeCamPanCb, false, monoFreeCamPriority,
            Enum.UserInputType.MouseMovement)
        RunService:BindToRenderStep("MonoFreeCam", Enum.RenderPriority.Camera.Value, monoFreeCamStep)
    end)
end

function monoFreeCamStop()
    if not monoFreeCam.running then return end
    pcall(function()
        UserInputService.MouseBehavior = Enum.MouseBehavior.Default
        UserInputService.MouseIconEnabled = true
    end)
    monoFreeCamReleaseMouse()
    pcall(function() RunService:UnbindFromRenderStep("MonoFreeCam") end)
    pcall(function() ContextActionService:UnbindAction("MonoFreeCamKeys") end)
    pcall(function() ContextActionService:UnbindAction("MonoFreeCamPan") end)
    local s = monoFreeCam.saved
    local cam = monoFreeCam.camera or workspace.CurrentCamera
    if s then
        pcall(function()
            cam.CameraType = s.ctype
            cam.CFrame = s.cf
            cam.Focus = s.focus
            cam.FieldOfView = s.fov or 70
            if s.devMouseLock ~= nil then
                LocalPlayer.DevEnableMouseLock = s.devMouseLock
            end
        end)
    end
    monoFreeCam.saved = nil
    monoFreeCam.running = false
    monoFreeCam.followHead = false
    monoFreeCam.headData = nil
    monoFreeCam.lastMouse = nil
    for key in pairs(monoFreeCam.keys) do monoFreeCam.keys[key] = 0 end
end

function monoFreeCamToggle()
    if type(monoHeadCtrlStop) == "function" and monoHeadCtrlActive then
        monoHeadCtrlStop()
        return false
    end
    if monoFreeCam.running then
        monoFreeCamStop()
        return false
    end
    monoFreeCamStart(false)
    return true
end

function monoFreeCamReleaseAll()
    if type(monoHeadCtrlStop) == "function" and monoHeadCtrlActive then
        monoHeadCtrlStop()
    end
    monoFreeCamStop()
    monoFreeCamReleaseMouse()
end

trackConn(LocalPlayer.CharacterRemoving:Connect(function()
    if monoFreeCam.running or monoHeadCtrlActive then
        pcall(monoFreeCamReleaseAll)
    end
end))

function monoFreeCamKeySet(name)
    monoFreeCam.key = name
    if name then
        for k, v in pairs(monoCmdBinds) do
            if v == name then monoCmdBindSet(k, nil) end
        end
        if type(monoSneak) == "table" and monoSneak.key == name then monoSneakKeySet(nil) end
    end
    monoFreeCamSave()
    if type(monoCmdRefresh) == "function" then monoCmdRefresh() end
    monoFreeCamKeyConnect()
end

function monoFreeCamKeyDisconnect()
    if monoFreeCam.keyConn then
        pcall(function() monoFreeCam.keyConn:Disconnect() end)
        monoFreeCam.keyConn = nil
    end
end

function monoFreeCamKeyConnect()
    monoFreeCamKeyDisconnect()
    if not monoFreeCam.key then return end
    monoFreeCam.keyConn = UserInputService.InputBegan:Connect(function(input, gpe)
        if gpe or monoBindCapturing or monoBindSwallow then return end
        if input.UserInputType ~= Enum.UserInputType.Keyboard then return end
        local kn = input.KeyCode.Name
        if kn == "Unknown" or kn ~= monoFreeCam.key then return end
        monoFreeCamToggle()
    end)
end

function monoFreeCamPanelOpen()
    for i = #monoPanelCols, 1, -1 do
        if monoPanelCols[i].name == "freecam" then return true end
    end
    return false
end

function monoFreeCamBuildPanel()
    local entry = monoPanelOpen("freecam", "Free Cam", 108, function()
        monoFreeCamKeyDisconnect()
        monoFreeCamReleaseAll()
        monoPanelDrop("freecam")
        monoFreeCam.btn = nil
        monoFreeCam.bindBtn = nil
    end)
    if not entry then return end
    monoFreeCamKeyConnect()

    local btnSec = monoPanelSection(entry.content, 1)
    local fcBtn = monoPanelBtn(btnSec, monoFreeCam.running and "Stop" or "Free Cam", nil, 142,
        UDim2.new(0, 18, 0.5, -12))
    local bindBtn = monoPanelBtn(btnSec, monoCmdBindShort(monoFreeCam.key), nil, 52,
        UDim2.new(1, -58, 0.5, -12))
    monoFreeCam.btn = fcBtn
    monoFreeCam.bindBtn = bindBtn

    local function bindPaint()
        pcall(function()
            bindBtn.Text = monoCmdBindShort(monoFreeCam.key)
            bindBtn.TextColor3 = monoFreeCam.key and C.accent or C.textDim
        end)
    end
    bindPaint()

    fcBtn.MouseButton1Click:Connect(function()
        local on = monoFreeCamToggle()
        pcall(function() fcBtn.Text = on and "Stop" or "Free Cam" end)
    end)

    bindBtn.MouseButton1Click:Connect(function()
        if monoBindCapturing then
            monoBindEndCapture()
            local had = monoFreeCam.key
            monoFreeCamKeySet(nil)
            bindPaint()
            if had then notify("Monochrome", "freecam keybind cleared", 2) end
            return
        end
        bindBtn.Text = "..."
        bindBtn.TextColor3 = C.accent
        monoBindCapture(function(input)
            monoFreeCamKeySet(input.KeyCode.Name)
            bindPaint()
            notify("Monochrome", "freecam bound to " .. input.KeyCode.Name, 2)
        end, function()
            bindPaint()
        end)
    end)

    monoBuildPanelSlider(entry.content, {
        state = monoFreeCam, value = monoFreeCam.speed, label = "Speed",
        min = monoFreeCamMin, max = monoFreeCamMax, reset = monoFreeCamReset,
        onSet = monoFreeCamSpeed,
    })
end

function clearGui(name)
    local o = monoGuiFind(name)
    if o then o:Destroy() end
end

toastGui, toastList = nil, nil
toastLive = setmetatable({}, { __mode = "k" })
toastOrder = {}
notificationsEnabled = true

function toastFinish(card, rec)
    for i = #toastOrder, 1, -1 do
        if toastOrder[i] == card then table.remove(toastOrder, i) end
    end
    if not rec or rec.dead then return end
    rec.dead = true
    if rec.conn then
        pcall(function() rec.conn:Disconnect() end)
        rec.conn = nil
    end
    pcall(function() card:Destroy() end)
end

function toastSnowAllowed()
    return not (setData and setData.disableSnow)
end

function toastSnowApply()
    local allowed = toastSnowAllowed()
    if Window and Window._snow then
        Window._snow.Visible = allowed
    end
    if allowed and Window and Window._snowFlakes then
        for _, fl in ipairs(Window._snowFlakes) do
            if fl.f.Parent then
                fl.y = -math.random() * 0.6
                fl.x = math.random()
            end
        end
    end
    for card, rec in pairs(toastLive) do
        if rec and rec.snow and rec.snow.Parent then
            rec.snow.Visible = allowed
            if allowed and rec.flakes then
                for _, fl in ipairs(rec.flakes) do
                    if fl.f.Parent then
                        fl.y = -math.random() * 0.6
                        fl.x = math.random()
                    end
                end
            end
        end
    end
end

function ensureToasts()
    if toastGui and toastGui.Parent then return end
    toastGui = create("ScreenGui", {
        Name = "MonochromeToast", ResetOnSpawn = false,
        IgnoreGuiInset = true, ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
    })
    monoGuiParent(toastGui)
    applyDisplayOrder(toastGui, MONO_ORDER.Toast, MONO_ORDER_OLD.Toast)
    toastList = create("Frame", {
        AnchorPoint = Vector2.new(1, 1),
        Size = UDim2.new(0, 260, 1, -40),
        Position = UDim2.new(1, -16, 1, -16),
        BackgroundTransparency = 1,
    }, toastGui)
    create("UIListLayout", {
        FillDirection = Enum.FillDirection.Vertical,
        HorizontalAlignment = Enum.HorizontalAlignment.Right,
        VerticalAlignment = Enum.VerticalAlignment.Bottom,
        Padding = UDim.new(0, 8),
        SortOrder = Enum.SortOrder.LayoutOrder,
    }, toastList)
end

function scheduleToastFade(card, delay)
    local rec = toastLive[card]
    if not rec then return end
    rec.gen = (rec.gen or 0) + 1
    local gen = rec.gen
    task.delay(delay, function()
        local cur = toastLive[card]
        if not cur or cur.gen ~= gen then return end
        toastLive[card] = nil
        tween(card, { BackgroundTransparency = 1 }, 0.25)
        tween(rec.stroke, { Transparency = 1 }, 0.25)
        if rec.bg then tween(rec.bg, { ImageTransparency = 1 }, 0.25) end
        if rec.bgShade then tween(rec.bgShade, { BackgroundTransparency = 1 }, 0.25) end
        tween(rec.snow, { GroupTransparency = 1 }, 0.25)
        tween(rec.bar, { BackgroundTransparency = 1 }, 0.25)
        tween(rec.title, { TextTransparency = 1 }, 0.25)
        tween(rec.desc, { TextTransparency = 1 }, 0.25)
        task.delay(0.3, function() toastFinish(card, rec) end)
    end)
end

function clearToast(card)
    if not card or not card.Parent then return end
    local rec = toastLive[card]
    toastLive[card] = nil
    if not rec then
        pcall(function() card:Destroy() end)
        return
    end
    tween(card, { BackgroundTransparency = 1 }, 0.2)
    tween(rec.stroke, { Transparency = 1 }, 0.2)
    if rec.bg then tween(rec.bg, { ImageTransparency = 1 }, 0.2) end
    if rec.bgShade then tween(rec.bgShade, { BackgroundTransparency = 1 }, 0.2) end
    tween(rec.snow, { GroupTransparency = 1 }, 0.2)
    tween(rec.bar, { BackgroundTransparency = 1 }, 0.2)
    tween(rec.title, { TextTransparency = 1 }, 0.2)
    tween(rec.desc, { TextTransparency = 1 }, 0.2)
    task.delay(0.22, function() toastFinish(card, rec) end)
end

function clearAllToasts()
    for card in pairs(toastLive) do
        clearToast(card)
    end
end

function monoUiPanelTransparency()
    local t = tonumber(MONO_UI_TRANSPARENCY or monoUiTransparency) or 0.12
    if monoBgImage and monoBgImage.Parent and monoBgImage.Visible and monoBgImage.Image ~= "" then
        return 1
    end
    return t
end

function monoCustomBgTransparency()
    local t = tonumber(MONO_UI_TRANSPARENCY or monoUiTransparency) or 0.12
    if t ~= t then t = 0.12 end
    return math.clamp(t, 0, 1)
end

function toastBgSync(card)
    local rec = card and toastLive[card]
    if not rec or not rec.bg then return end
    local alreadySynced = (rec.bgFade ~= nil)
    local on = (monoBgImage
        and typeof(monoBgImage) == "Instance"
        and monoBgImage.Parent ~= nil
        and monoBgImage.Visible == true
        and monoBgImage.Image ~= "") and true or false
    rec.bg.Visible = on
    rec.bg.Image = on and monoBgImage.Image or ""
    rec.bg.ImageTransparency = on and monoCustomBgTransparency() or 0
    if rec.bgShade then
        local dim = setData and setData.bgDim or 55
        local target = on and (dim / 100) or 1
        if rec.bgFade == nil then
            rec.bgShade.BackgroundTransparency = target
        elseif math.abs(rec.bgShade.BackgroundTransparency - target) > 0.001 then
            tween(rec.bgShade, { BackgroundTransparency = target }, 0.25)
        end
        rec.bgFade = true
    end
    if card.Parent then
        local cardTarget = monoUiPanelTransparency()
        if alreadySynced and math.abs(card.BackgroundTransparency - cardTarget) > 0.001 then
            tween(card, { BackgroundTransparency = cardTarget }, 0.25)
        end
    end
end

function notify(title, desc, time)
    if not notificationsEnabled then return nil end
    for i = #toastOrder, 1, -1 do
        if not toastOrder[i] or not toastOrder[i].Parent then table.remove(toastOrder, i) end
    end
    while #toastOrder >= (notificationLimit or 5) do
        local oldest = toastOrder[1]
        table.remove(toastOrder, 1)
        if oldest then clearToast(oldest) end
    end
    ensureToasts()
    time = time or 3
    local card = create("Frame", {
        Size = UDim2.new(0, 250, 0, 58),
        BackgroundColor3 = C.bg, BorderSizePixel = 0, Active = true,
    }, toastList)
    corner(card, 10)
    local cardStroke = stroke(card, C.border, 1, 1)
    card.BackgroundTransparency = 1
    local bgClip = create("Frame", {
        Name = "BgClip", Size = UDim2.new(1, 0, 1, 0),
        BackgroundTransparency = 1, BorderSizePixel = 0, ClipsDescendants = true,
    }, card)
    corner(bgClip, 10)
    local bgBack = create("ImageLabel", {
        Name = "Bg", Size = UDim2.new(1, 0, 1, 0),
        BackgroundTransparency = 1, BorderSizePixel = 0,
        Image = "", ScaleType = Enum.ScaleType.Crop, Visible = false,
    }, bgClip)
    corner(bgBack, 10)
    local bgShade = create("Frame", {
        Name = "BgShade", Size = UDim2.new(1, 0, 1, 0),
        BackgroundColor3 = C.bg, BackgroundTransparency = 1, BorderSizePixel = 0,
    }, bgClip)
    corner(bgShade, 10)
    local snow = create("CanvasGroup", {
        Name = "Snow", Size = UDim2.new(1, 0, 1, 0),
        BackgroundTransparency = 1, BorderSizePixel = 0,
        Active = false, ClipsDescendants = true, ZIndex = 0,
        GroupTransparency = 1, Visible = toastSnowAllowed(),
    }, card)
    corner(snow, 10)
    local flakes = monoBuildFlakes(snow, 8, 0.25, 0.35, 3, 6, 0.65, 0.25)
    local snowConn = monoStartSnow(snow, flakes)
    for _, d in ipairs(card:GetDescendants()) do
        if d:IsA("TextLabel") then d.TextTransparency = 1 end
    end
    local bar = create("Frame", {
        Size = UDim2.new(0, 3, 0, 30), Position = UDim2.new(0, 10, 0, 12),
        BackgroundColor3 = C.accent, BorderSizePixel = 0,
        BackgroundTransparency = 1,
    }, card)
    corner(bar, 999)
    local t = create("TextLabel", {
        Size = UDim2.new(1, -32, 0, 16), Position = UDim2.new(0, 20, 0, 10),
        BackgroundTransparency = 1, Text = title or "Monochrome",
        TextColor3 = C.text, TextSize = 11, Font = Enum.Font.GothamBold,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextTruncate = Enum.TextTruncate.AtEnd,
    }, card)
    t.TextTransparency = 1
    local d = create("TextLabel", {
        Size = UDim2.new(1, -32, 0, 26), Position = UDim2.new(0, 20, 0, 26),
        BackgroundTransparency = 1, Text = desc or "",
        TextColor3 = C.textMut, TextSize = 10, Font = Enum.Font.Gotham,
        TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Top,
        TextWrapped = true,
    }, card)
    d.TextTransparency = 1
    tween(card, { BackgroundTransparency = monoUiPanelTransparency() }, 0.2)
    tween(cardStroke, { Transparency = 0.3 }, 0.2)
    tween(snow, { GroupTransparency = 0 }, 0.2)
    tween(bar, { BackgroundTransparency = 0.55 }, 0.2)
    tween(t, { TextTransparency = 0 }, 0.2)
    tween(d, { TextTransparency = 0.15 }, 0.2)
    toastLive[card] = { stroke = cardStroke, bar = bar, title = t, desc = d, gen = 0, snow = snow, flakes = flakes, conn = snowConn, bg = bgBack, bgShade = bgShade }
    toastOrder[#toastOrder + 1] = card

    pcall(toastBgSync, card)
    scheduleToastFade(card, time)
    return card
end

function ensureFolder(folder)
    if typeof(makefolder) == "function" then
        pcall(function()
            if typeof(isfolder) == "function" and not isfolder(folder) then
                makefolder(folder)
            elseif typeof(isfolder) ~= "function" then
                makefolder(folder)
            end
        end)
    end
end

function configPath(folder, name)
    return folder .. "/" .. tostring(name) .. ".json"
end

function saveConfig(folder, name)
    if typeof(writefile) ~= "function" then return false, "writefile unsupported" end
    ensureFolder(folder)
    local data = {}
    for flag, val in pairs(Library.Flags) do
        if typeof(val) == "Color3" then
            data[flag] = { __color = true, r = val.R, g = val.G, b = val.B }
        elseif typeof(val) == "EnumItem" then
            data[flag] = { __key = true, name = val.Name }
        else
            data[flag] = val
        end
    end
    local ok, json = pcall(function() return HttpService:JSONEncode(data) end)
    if not ok then return false, "encode failed" end
    local wok, werr = pcall(function() writefile(configPath(folder, name), json) end)
    return wok, werr
end

function loadConfig(folder, name)
    if typeof(readfile) ~= "function" or typeof(isfile) ~= "function" then
        return false, "readfile unsupported"
    end
    local p = configPath(folder, name)
    local okExists = false
    pcall(function() okExists = isfile(p) end)
    if not okExists then return false, "no config" end
    local ok, content = pcall(function() return readfile(p) end)
    if not ok then return false, "read failed" end
    local ok2, data = pcall(function() return HttpService:JSONDecode(content) end)
    if not ok2 or typeof(data) ~= "table" then return false, "decode failed" end
    for flag, val in pairs(data) do
        if typeof(val) == "table" and val.__color then
            Library.Flags[flag] = Color3.new(val.r or 1, val.g or 1, val.b or 1)
        elseif typeof(val) == "table" and val.__key then
            pcall(function() Library.Flags[flag] = Enum.KeyCode[val.name] end)
        else
            Library.Flags[flag] = val
        end
    end
    for _, applier in ipairs(Library._appliers or {}) do
        pcall(applier)
    end
    return true
end

Library._appliers = {}

function windowSavePath(folder) return folder .. "/window.json" end
function saveWindowState(folder, pos, isMin)
    if typeof(writefile) ~= "function" then return end
    ensureFolder(folder)
    pcall(function()
        writefile(windowSavePath(folder), HttpService:JSONEncode({
            position = {
                X = { Scale = pos.X.Scale, Offset = pos.X.Offset },
                Y = { Scale = pos.Y.Scale, Offset = pos.Y.Offset },
            },
            minimized = isMin and true or false,
        }))
    end)
end
function loadWindowState(folder)
    if typeof(readfile) ~= "function" or typeof(isfile) ~= "function" then return nil end
    local ok, exists = pcall(function() return isfile(windowSavePath(folder)) end)
    if not ok or not exists then return nil end
    local ok2, content = pcall(function() return readfile(windowSavePath(folder)) end)
    if not ok2 then return nil end
    local ok3, data = pcall(function() return HttpService:JSONDecode(content) end)
    if not ok3 or typeof(data) ~= "table" then return nil end
    return data
end

monoGlobalLastVis = nil

function monoApplyExternalVisibility(v, reason)
    local showExternal = v and true or false
    if not showExternal and type(setData) == "table" then
        if reason == "minimize" and setData.hideExternalOnMinimize == false then showExternal = true end
        if reason == "hidden" and setData.hideExternalOnHide == false then showExternal = true end
    end
    if monoPanelExtGui then pcall(function() monoPanelExtGui.Enabled = showExternal end) end
    if monoReanimGui then pcall(function() monoReanimGui.Enabled = showExternal end) end
end

function Library:Window(opts)
    opts = opts or {}
    local oldGui = monoGuiFind("MonochromeUI")
    if oldGui then
        oldGui.Enabled = true
        local oldToast = monoGuiFind("MonochromeToast")
        if oldToast then oldToast.Enabled = true end
        local Stub = {}
        Stub._isStub = true
        function Stub:Tab() return Stub end
        function Stub:Section() return Stub end
        function Stub:Label() return Stub end
        function Stub:Toggle() return Stub end
        function Stub:Slider() return Stub end
        function Stub:Dropdown() return Stub end
        function Stub:Button() return Stub end
        function Stub:Textbox() return Stub end
        function Stub:Keybind() return Stub end
        function Stub:Colorpicker() return Stub end
        function Stub:Welcome() return Stub end
        function Stub:Stats() return Stub end
        function Stub:Note() return Stub end
        function Stub:Notify() end
        function Stub:SetStatus() end
        function Stub:SaveConfig() return false end
        function Stub:LoadConfig() return false end
        function Stub:ToggleUI()
            oldGui.Enabled = not oldGui.Enabled
            local t = monoGuiFind("MonochromeToast")
            if t then t.Enabled = oldGui.Enabled end
        end
        function Stub:Destroy()
            for _, c in ipairs(_G.__MonoConns) do pcall(function() c:Disconnect() end) end
            table.clear(_G.__MonoConns)
            runDestroyHooks()
            pcall(function() oldGui:Destroy() end)
            local t = monoGuiFind("MonochromeToast")
            if t then pcall(function() t:Destroy() end) end
        end
        return Stub
    end

