    local function iconBtn(text, xOff)
        local b = create("TextButton", {
            Size = UDim2.new(0, 22, 0, 22), Position = UDim2.new(1, xOff, 0, 12),
            BackgroundColor3 = C.surface, BackgroundTransparency = 0.4,
            BorderSizePixel = 0, Text = text,
            TextColor3 = C.textMut, TextSize = 13, Font = Enum.Font.GothamBold,
            AutoButtonColor = false,
        }, content)
        corner(b, 7); stroke(b, C.borderSoft, 1, 0.6)
        b.MouseEnter:Connect(function()
            tween(b, { BackgroundColor3 = C.surfaceHi, BackgroundTransparency = 0.15 }, 0.15)
            b.TextColor3 = C.accent
        end)
        b.MouseLeave:Connect(function()
            tween(b, { BackgroundColor3 = C.surface, BackgroundTransparency = 0.4 }, 0.15)
            b.TextColor3 = C.textMut
        end)
        return b
    end
    local minBtn = iconBtn("-", -58)
    local closeBtn = iconBtn("x", -32)

    local pageArea = create("Frame", {
        Size = UDim2.new(1, -16, 1, -54), Position = UDim2.new(0, 8, 0, 46),
        BackgroundTransparency = 1, ClipsDescendants = true,
    }, content)

    local miniFrame = create("TextButton", {
        Size = UDim2.new(0, MINI, 0, MINI), Visible = false,
        BackgroundColor3 = C.surface, BackgroundTransparency = 0.4, BorderSizePixel = 0, Text = "",
        AutoButtonColor = false,
    }, window)
    corner(miniFrame, 999); stroke(miniFrame, C.border, 1, 0.3)
    if type(monoBgLayers) == "table" then
            table.insert(monoBgLayers, miniFrame)
            monoBgRest = monoBgRest or {}
            monoBgRest[miniFrame] = 0.4
        end
    local miniDot = create("Frame", {
        Size = UDim2.new(0, 16, 0, 16), Position = UDim2.new(0.5, -8, 0.5, -8),
        BackgroundColor3 = C.accent, BorderSizePixel = 0,
    }, miniFrame)
    corner(miniDot, 999)
    monoBgDot = miniDot
    makeDraggable(window, miniFrame, function() persistWin() end)

    local uiVisible, minimized = true, startMin
    persistWin = function()
        saveWindowState(cfgFolder, window.Position, minimized)
    end
    local function applyVisible()
        window.Size = minimized and UDim2.new(0, MINI, 0, MINI)
            or UDim2.new(0, WIN_W, 0, WIN_H)
        clampFrameToScreen(window)
        side.Visible = uiVisible and not minimized
        content.Visible = uiVisible and not minimized
        miniFrame.Visible = uiVisible and minimized
        if minimized then
        end
    end
    local visHooks = {}
    monoPanelHost = nil
    monoPanelVisible = true
    local monoPanelSync = function()
        if monoPanelHost then monoPanelHost.Visible = monoPanelVisible and true or false end
        monoApplyExternalVisibility(monoPanelVisible, monoGlobalLastVis and monoGlobalLastVis.reason)
    end
    local function fireVis(v, reason)
        monoPanelVisible = v and true or false
        monoGlobalLastVis = { v = monoPanelVisible, reason = reason }
        monoApplyExternalVisibility(monoPanelVisible, reason)
        for _, fn in ipairs(visHooks) do pcall(fn, monoPanelVisible) end
    end
    local function applyMiniShape(v)
        if monoBgWinCorner then monoBgWinCorner.CornerRadius = v and UDim.new(0, MINI / 2) or UDim.new(0, 18) end
        if monoBgWinStroke then monoBgWinStroke.Enabled = not v end
        if snowCorner then snowCorner.CornerRadius = v and UDim.new(0, MINI / 2) or UDim.new(0, 18) end
        if snowLayer then snowLayer.ZIndex = v and 5 or 0 end
        if monoBgCorners then
            for _, c in ipairs(monoBgCorners) do
                c.CornerRadius = v and UDim.new(0, MINI / 2) or UDim.new(0, 18)
            end
        end
    end
    local function setMinimized(v)
        if minimized == v then return end
        minimized = v
        persistWin()
        fireVis(uiVisible and not v, "minimize")
        applyMiniShape(v)
        if v then
            side.Visible = false; content.Visible = false
            miniFrame.Visible = false
            clampFrameToScreen(window, MINI, MINI)
            tween(window, { Size = UDim2.new(0, MINI, 0, MINI) }, 0.2,
                Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
            task.delay(0.2, function()
                if not minimized then return end
                miniFrame.Visible = true
            end)
        else
            miniFrame.Visible = false
            side.Visible = true; content.Visible = true
            clampFrameToScreen(window, WIN_W, WIN_H)
            tween(window, { Size = UDim2.new(0, WIN_W, 0, WIN_H) }, 0.2,
                Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
        end
        fireVis(uiVisible and not minimized, "minimize")
    end
    if minimized then
        window.Size = UDim2.new(0, MINI, 0, MINI)
        side.Visible = false; content.Visible = false; miniFrame.Visible = true
        applyMiniShape(true)
    end
    fireVis(not startMin, "init")
    local miniPressPos = nil
    miniFrame.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
        or input.UserInputType == Enum.UserInputType.Touch then
            miniPressPos = input.Position
        end
    end)
    miniFrame.InputEnded:Connect(function(input)
        if (input.UserInputType == Enum.UserInputType.MouseButton1
        or input.UserInputType == Enum.UserInputType.Touch)
        and miniPressPos then
            local moved = (input.Position - miniPressPos).Magnitude
            miniPressPos = nil
            if moved <= 8 then
                setMinimized(false)
            end
        end
    end)
    minBtn.MouseButton1Click:Connect(function() setMinimized(true) end)
    local hideToast = nil
    local function requireToggleKey()
        if toggleUIKeyName then return true end
        notify(title, "Bind a key to hide the UI first (Settings > Toggle UI keybind)", 3)
        return false
    end
    closeBtn.MouseButton1Click:Connect(function()
        if not requireToggleKey() then return end
        if monoBindCapturing then monoBindEndCapture() end
        uiVisible = false
        side.Visible = false; content.Visible = false; miniFrame.Visible = false
        window.Visible = false
        hideToast = notify(title, monoToggleHideToast(), 3)
    end)

    local MonoWindow = {}
    function MonoWindow:OnVisibility(fn)
        if type(fn) == "function" then table.insert(visHooks, fn) end
        return fn
    end
    MonoWindow._gui = gui
    MonoWindow._win = window
    MonoWindow._winW = WIN_W
    MonoWindow._winH = WIN_H
    MonoWindow._toggleKey = toggleKey
    MonoWindow._defaultToggleKey = toggleKey
    MonoWindow._toggleHint = nil
    MonoWindow._toggleBtn = nil

    function MonoWindow:SetToggleKeyName(name)
        if type(name) ~= "string" or name == "" then return end
        local ok, k = pcall(function() return Enum.KeyCode[name] end)
        if not ok or typeof(k) ~= "EnumItem" then return end
        toggleUIKeyName = name
        toggleKey = k
        MonoWindow._toggleKey = k
        if MonoWindow._toggleHint then pcall(function() MonoWindow._toggleHint.Text = "Press " .. name .. " to show / hide" end) end
        if MonoWindow._toggleBtn then pcall(function() MonoWindow._toggleBtn.Text = monoToggleBtnText() end) end
    end

    function MonoWindow:ClearToggleKeyName()
        toggleUIKeyName = nil
        toggleKey = MonoWindow._defaultToggleKey
        MonoWindow._toggleKey = MonoWindow._defaultToggleKey
        if MonoWindow._toggleHint then pcall(function() MonoWindow._toggleHint.Text = "No key bound" end) end
        if MonoWindow._toggleBtn then pcall(function() MonoWindow._toggleBtn.Text = monoToggleBtnText() end) end
    end

    MonoWindow.RequireToggleKey = requireToggleKey

    function MonoWindow:ToggleUI()
        if loading then return end
        if monoBindCapturing then monoBindEndCapture() end
        uiVisible = not uiVisible
        window.Visible = uiVisible
        if toastGui then toastGui.Enabled = true end
        if uiVisible then
            applyVisible()
            clearToast(hideToast)
            hideToast = nil
        else
            hideToast = notify(title, monoToggleHideToast(), 3)
        end
        fireVis(uiVisible and not minimized, "hidden")
    end
    function MonoWindow:Destroy()
        for _, c in ipairs(_G.__MonoConns) do pcall(function() c:Disconnect() end) end
        table.clear(_G.__MonoConns)
        runDestroyHooks()
        table.clear(Library._windows)
        for _, e in ipairs(monoPanelCols or {}) do
            if e and e.frame then pcall(function() e.frame:Destroy() end) end
        end
        monoPanelCols = {}
        if monoPanelExtGui then pcall(function() monoPanelExtGui:Destroy() end) end
        monoPanelExtGui = nil
        pcall(function() gui:Destroy() end)
        local tg = monoGuiFind("MonochromeToast")
        if tg then pcall(function() tg:Destroy() end) end
        local lg = monoGuiFind("MonochromeLoad")
        if lg then pcall(function() lg:Destroy() end) end
        local te = monoGuiFind("MonochromeTerminal")
        if te then pcall(function() te:Destroy() end) end
    end
    function MonoWindow:Notify(o)
        notify(o.Title or title, o.Desc or o.Text or "", o.Time or 3)
    end
    function MonoWindow:SetStatus() end
    function MonoWindow:SaveConfig(name)
        local ok, err = saveConfig(cfgFolder, name or "default")
        return ok, err
    end
    function MonoWindow:LoadConfig(name)
        local ok, err = loadConfig(cfgFolder, name or "default")
        return ok, err
    end

    monoToggleConnect = function()
        if toggleUIConn then return end
        toggleUIConn = UserInputService.InputBegan:Connect(function(input, gpe)
            if gpe then return end
            if monoKeyCaptureActive then return end
            if input.UserInputType ~= Enum.UserInputType.Keyboard then return end
            if not toggleUIKeyName then return end
            if input.KeyCode.Name == toggleUIKeyName then
                MonoWindow:ToggleUI()
            end
        end)
    end
    monoToggleDisconnect = function()
        if toggleUIConn then
            pcall(function() toggleUIConn:Disconnect() end)
            toggleUIConn = nil
        end
    end
    MonoWindow:OnVisibility(monoPanelSync)
    trackConn({ Disconnect = monoToggleDisconnect })
    monoToggleConnect()

    local tabButtons, pages, currentTab = {}, {}, nil
    local tabOrderCounter = 0
    local _indicator = nil

    setActiveTab = function(name)
        if name == currentTab then return end
        currentTab = name
        for n, b in pairs(tabButtons) do
            local active = (n == name)
            tween(b, {
                BackgroundColor3 = active and C.surfaceHi or C.panel,
                BackgroundTransparency = active and 0.15 or 0.4,
            }, 0.2)
            local s = b:FindFirstChildOfClass("UIStroke")
            if s then
                s.Color = active and C.border or C.borderSoft
                s.Transparency = active and 0.15 or 0.7
            end
            local lbl = b:FindFirstChild("Label")
            if lbl then tween(lbl, { TextColor3 = active and C.accent or C.textMut }, 0.2) end
            local bar = b:FindFirstChild("Bar")
            if bar then bar.Visible = active end
        end
        for n, pg in pairs(pages) do pg.Visible = (n == name) end
        if profile then
            profileActive = (name == "Profile")
            tween(profile, {
                BackgroundColor3 = profileActive and C.surfaceHi or C.panel,
                BackgroundTransparency = profileActive and 0.15 or 0.4,
            }, 0.2)
            local ps = profile:FindFirstChildOfClass("UIStroke")
            if ps then
                ps.Color = profileActive and C.border or C.borderSoft
                ps.Transparency = profileActive and 0.15 or 0.7
            end
        end
    end

    function MonoWindow:Tab(def)
        def = def or {}
        tabOrderCounter = tabOrderCounter + 1
        local name = def.Name or ("Tab" .. tabOrderCounter)
        local order = def.Order or tabOrderCounter

        if not def.Hidden then
            local btn = create("TextButton", {
                Size = UDim2.new(1, 0, 0, 32),
                BackgroundColor3 = C.panel, BackgroundTransparency = 0.4,
                BorderSizePixel = 0,
                Text = "", AutoButtonColor = false, LayoutOrder = order,
            }, tabList)
            corner(btn, 9); stroke(btn, C.borderSoft, 1, 0.7)
            create("Frame", {
                Name = "Bar", Size = UDim2.new(0, 3, 0, 16),
                Position = UDim2.new(0, 7, 0.5, -8),
                BackgroundColor3 = C.accent, BorderSizePixel = 0, Visible = false,
            }, btn).Name = "Bar"
            do local bar = btn:FindFirstChild("Bar") ;if bar then corner(bar, 999) end end
            create("TextLabel", {
                Name = "Label", Size = UDim2.new(1, -28, 1, -2), Position = UDim2.new(0, 18, 0, 1),
                BackgroundTransparency = 1, Text = name, TextColor3 = C.textMut,
                TextSize = 10, Font = Enum.Font.GothamMedium,
                TextXAlignment = Enum.TextXAlignment.Left,
                TextTruncate = Enum.TextTruncate.AtEnd,
            }, btn)
            btn.MouseButton1Click:Connect(function() setActiveTab(name) end)
            btn.MouseEnter:Connect(function()
                if currentTab ~= name then
                    tween(btn, { BackgroundColor3 = C.surface, BackgroundTransparency = 0.15 }, 0.15)
                end
            end)
            btn.MouseLeave:Connect(function()
                if currentTab ~= name then
                    tween(btn, { BackgroundColor3 = C.panel, BackgroundTransparency = 0.4 }, 0.15)
                end
            end)
            tabButtons[name] = btn
        end

        local page = create("ScrollingFrame", {
            Name = name .. "Page", Size = UDim2.new(1, 0, 1, 0),
            BackgroundTransparency = 1, BorderSizePixel = 0, Visible = false,
            ClipsDescendants = true,
            CanvasSize = UDim2.new(0,0,0,0), AutomaticCanvasSize = Enum.AutomaticSize.Y,
            ScrollBarThickness = 3, ScrollBarImageColor3 = C.border,
            ScrollingDirection = Enum.ScrollingDirection.Y,
        }, pageArea)
        create("UIListLayout", {
            Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder,
        }, page)
        create("UIPadding", {
            PaddingTop = UDim.new(0,6), PaddingBottom = UDim.new(0,0),
            PaddingLeft = UDim.new(0,2), PaddingRight = UDim.new(0,8),
        }, page)
        pages[name] = page
        if currentTab == nil then
            setActiveTab(name)
        end

        local Tab = {}
        Tab._page = page
        local compOrder = 0
        local function nextOrder()
            compOrder = compOrder + 1
            return compOrder
        end

        local function mkRow(h, order)
            local r = create("Frame", {
                Size = UDim2.new(1, 0, 0, h or 36),
                BackgroundColor3 = C.surface, BackgroundTransparency = 0.4, BorderSizePixel = 0,
                LayoutOrder = order,
            }, page)
            corner(r, 10); stroke(r, C.borderSoft, 1, 0.55)
            return r
        end

        function Tab:Section(titleText, order)
            if order ~= nil then compOrder = math.max(compOrder, order) end
            local holder = create("Frame", {
                Size = UDim2.new(1, 0, 0, 18), BackgroundTransparency = 1,
                LayoutOrder = order or nextOrder(),
            }, page)
            local bar = create("Frame", {
                Size = UDim2.new(0, 3, 0, 10), Position = UDim2.new(0, 2, 0.5, -5),
                BackgroundColor3 = C.accent, BorderSizePixel = 0,
            }, holder)
            corner(bar, 999)
            create("TextLabel", {
                Size = UDim2.new(1, -14, 1, 0), Position = UDim2.new(0, 12, 0, 0),
                BackgroundTransparency = 1, Text = string.upper(tostring(titleText or "SECTION")),
                TextColor3 = C.textDim, TextSize = 8, Font = Enum.Font.GothamBold,
                TextXAlignment = Enum.TextXAlignment.Left,
            }, holder)
            return Tab
        end

        function Tab:Label(text)
            local l = create("TextLabel", {
                Size = UDim2.new(1, 0, 0, 24), BackgroundTransparency = 1,
                Text = tostring(text or ""), TextColor3 = C.textMut,
                TextSize = 9, Font = Enum.Font.Gotham,
                TextXAlignment = Enum.TextXAlignment.Left,
                TextWrapped = true, LayoutOrder = nextOrder(),
            }, page)
            return { Set = function(_, v) l.Text = tostring(v) end }
        end

        function Tab:Welcome(o)
            o = o or {}
            local row = create("Frame", {
                Size = UDim2.new(1, 0, 0, 84),
                BackgroundColor3 = C.surface, BackgroundTransparency = 0.4, BorderSizePixel = 0,
                LayoutOrder = nextOrder(),
            }, page)
            corner(row, 10); stroke(row, C.borderSoft, 1, 0.55)
            local av = create("ImageLabel", {
                Size = UDim2.new(0, 60, 0, 60), Position = UDim2.new(0, 12, 0.5, -30),
                BackgroundColor3 = C.input, BorderSizePixel = 0,
                Image = "rbxasset://textures/ui/GuiImagePlaceholder.png",
                ScaleType = Enum.ScaleType.Crop,
            }, row)
