            create("TextLabel", {
                Size = UDim2.new(1, -96, 0, 20), Position = UDim2.new(0, 84, 0, 20),
                BackgroundTransparency = 1, Text = "Hello, " .. LocalPlayer.DisplayName,
                TextColor3 = C.text, TextSize = 15, Font = Enum.Font.GothamBold,
                TextXAlignment = Enum.TextXAlignment.Left,
                TextTruncate = Enum.TextTruncate.AtEnd,
            }, row)
            create("TextLabel", {
                Size = UDim2.new(1, -96, 0, 14), Position = UDim2.new(0, 84, 0, 42),
                BackgroundTransparency = 1, Text = "@" .. LocalPlayer.Name,
                TextColor3 = C.textDim, TextSize = 10, Font = Enum.Font.Gotham,
                TextXAlignment = Enum.TextXAlignment.Left,
                TextTruncate = Enum.TextTruncate.AtEnd,
            }, row)
            MonoWindow._toggleHint = create("TextLabel", {
                Size = UDim2.new(1, -96, 0, 12), Position = UDim2.new(0, 84, 0, 60),
                BackgroundTransparency = 1, Text = "Press " .. toggleKey.Name .. " to show / hide",
                TextColor3 = C.textDim, TextSize = 9, Font = Enum.Font.Gotham,
                TextXAlignment = Enum.TextXAlignment.Left,
                TextTruncate = Enum.TextTruncate.AtEnd,
            }, row)
            task.spawn(function()
                local ok, content = pcall(function()
                    return Players:GetUserThumbnailAsync(LocalPlayer.UserId,
                        Enum.ThumbnailType.HeadShot, Enum.ThumbnailSize.Size180x180, false)
                end)
                if ok and typeof(content) == "string" then
                    av.Image = content
                end
            end)
