        function Tab:Stats(o)
            o = o or {}
            local holder = create("Frame", {
                Size = UDim2.new(1, 0, 0, 58),
                BackgroundTransparency = 1, BorderSizePixel = 0,
                LayoutOrder = nextOrder(),
            }, page)
            create("UIListLayout", {
                FillDirection = Enum.FillDirection.Horizontal,
                HorizontalAlignment = Enum.HorizontalAlignment.Left,
                Padding = UDim.new(0, 8),
                SortOrder = Enum.SortOrder.LayoutOrder,
            }, holder)
            local function makeBox(titleText, order)
                local box = create("Frame", {
                    Size = UDim2.new(0.3333, -6, 1, 0),
                    BackgroundColor3 = C.surface, BackgroundTransparency = 0.4, BorderSizePixel = 0,
                    LayoutOrder = order,
                }, holder)
                corner(box, 10); stroke(box, C.borderSoft, 1, 0.55)
                create("TextLabel", {
                    Size = UDim2.new(1, -18, 0, 11), Position = UDim2.new(0, 12, 0, 10),
                    BackgroundTransparency = 1, Text = titleText,
                    TextColor3 = C.textDim, TextXAlignment = Enum.TextXAlignment.Left,
                    TextSize = 8, Font = Enum.Font.GothamBold,
                }, box)
                local value = create("TextLabel", {
                    Size = UDim2.new(1, -18, 0, 22), Position = UDim2.new(0, 12, 0, 23),
                    BackgroundTransparency = 1, Text = "--",
                    TextColor3 = C.accent, TextXAlignment = Enum.TextXAlignment.Left,
                    TextSize = 15, Font = Enum.Font.GothamBold,
                    TextTruncate = Enum.TextTruncate.AtEnd,
                }, box)
                return value
            end
            local fpsValue = makeBox("FPS", 1)
            local pingValue = makeBox("PING", 2)
            local execValue = makeBox("EXECUTOR", 3)
            local frames, last = 0, tick()
            trackConn(RunService.Heartbeat:Connect(function()
                if not fpsValue.Parent then return end
                frames = frames + 1
                if tick() - last >= 1 then
                    fpsValue.Text = tostring(frames)
                    frames, last = 0, tick()
                end
            end))
            task.spawn(function()
                while pingValue.Parent do
                    local ok, ms = pcall(function() return math.floor(LocalPlayer:GetNetworkPing() * 1000) end)
                    pingValue.Text = (ok and ms and tostring(ms) .. "ms") or "--"
                    task.wait(1)
                end
            end)
            local execName = "Unknown"
            pcall(function()
                if identifyexecutor then execName = identifyexecutor()
                elseif getexecutorname then execName = getexecutorname() end
            end)
            execValue.Text = tostring(execName)
            return Tab
        end

        function Tab:Note(titleText, bodyText, minHeight)
            local card = create("Frame", {
                Size = UDim2.new(1, 0, 0, typeof(minHeight) == "number" and minHeight or 0),
                AutomaticSize = Enum.AutomaticSize.Y,
                BackgroundColor3 = C.panel, BorderSizePixel = 0,
                LayoutOrder = nextOrder(),
            }, page)
            corner(card, 10); stroke(card, C.borderSoft, 1, 0.55)
            create("UIListLayout", {
                Padding = UDim.new(0, 4),
                SortOrder = Enum.SortOrder.LayoutOrder,
            }, card)
            create("UIPadding", {
                PaddingTop = UDim.new(0, 10), PaddingBottom = UDim.new(0, 10),
                PaddingLeft = UDim.new(0, 14), PaddingRight = UDim.new(0, 14),
            }, card)
            create("TextLabel", {
                Size = UDim2.new(1, 0, 0, 16), BackgroundTransparency = 1,
                Text = tostring(titleText or ""), TextColor3 = C.text,
                TextSize = 11, Font = Enum.Font.GothamBold,
                TextXAlignment = Enum.TextXAlignment.Left,
                TextTruncate = Enum.TextTruncate.AtEnd,
                LayoutOrder = 1,
            }, card)
            local _body = create("TextLabel", {
                Size = UDim2.new(1, 0, 0, 0),
                AutomaticSize = Enum.AutomaticSize.Y,
                BackgroundTransparency = 1, Text = tostring(bodyText or ""),
                TextColor3 = C.textMut, TextSize = 10, Font = Enum.Font.Gotham,
                TextXAlignment = Enum.TextXAlignment.Left,
                TextYAlignment = Enum.TextYAlignment.Top,
                TextWrapped = true,
                LayoutOrder = 2,
            }, card)
            if minHeight == "fill" then
                task.spawn(function()
                    local tries = 0
                    while tries < 100 do
                        tries = tries + 1
                        task.wait(0.1)
                        if not card.Parent then return end
                        if page.AbsoluteSize.Y > 50 then break end
                    end
                    if not card.Parent then return end
                    local rel = card.AbsolutePosition.Y - page.AbsolutePosition.Y
                    local h = page.AbsoluteSize.Y - rel
                    if h > 40 then card.Size = UDim2.new(1, 0, 0, math.floor(h)) end
                end)
            end
            return Tab
        end

        function Tab:Toggle(o)
            o = o or {}
            local row = mkRow(36, o.Order or nextOrder())
            create("TextLabel", {
                Size = UDim2.new(1, -64, 1, 0), Position = UDim2.new(0, 14, 0, 0),
                BackgroundTransparency = 1, Text = o.Name or "Toggle",
                TextColor3 = C.text, TextSize = 10, Font = Enum.Font.GothamMedium,
                TextXAlignment = Enum.TextXAlignment.Left,
                TextTruncate = Enum.TextTruncate.AtEnd,
            }, row)
            local state = o.Default and true or false
            if o.Flag and Library.Flags[o.Flag] ~= nil then
                state = Library.Flags[o.Flag] and true or false
            end
            local bg = create("TextButton", {
                Size = UDim2.new(0, 38, 0, 20), Position = UDim2.new(1, -52, 0.5, -10),
                BackgroundColor3 = state and C.accent or C.input,
                BorderSizePixel = 0, Text = "", AutoButtonColor = false,
            }, row)
            corner(bg, 999); stroke(bg, C.borderSoft, 1, 0.55)
            local knob = create("Frame", {
                Size = UDim2.new(0, 14, 0, 14),
                Position = state and UDim2.new(1, -17, 0.5, -7) or UDim2.new(0, 3, 0.5, -7),
                BackgroundColor3 = state and C.bg or C.text, BorderSizePixel = 0,
            }, bg)
            corner(knob, 999)
            local cb = o.Callback
            local flag = o.Flag
            local function apply(v, silent)
                state = v and true or false
                if flag then Library.Flags[flag] = state end
                tween(bg, { BackgroundColor3 = state and C.accent or C.input }, 0.2)
                tween(knob, {
                    BackgroundColor3 = state and C.bg or C.text,
                    Position = state and UDim2.new(1, -17, 0.5, -7) or UDim2.new(0, 3, 0.5, -7),
                }, 0.22)
                if not silent and cb then task.spawn(cb, state) end
            end
            bg.MouseButton1Click:Connect(function() apply(not state) end)
            if flag then
                Library.Flags[flag] = state
                table.insert(Library._appliers, function()
                    local v = Library.Flags[flag]
                    if v ~= nil and v ~= state then apply(v, true) end
                end)
            end
            if cb and state then task.defer(cb, state) end
            return { Set = apply, Get = function() return state end }
        end

        function Tab:Slider(o)
            o = o or {}
            local min, max = o.Min or 0, o.Max or 100
            local dec = o.Decimals or 0
            local val = o.Default ~= nil and o.Default or min
            if o.Flag and tonumber(Library.Flags[o.Flag]) ~= nil then
                val = tonumber(Library.Flags[o.Flag])
            end
            val = math.clamp(val, min, max)
            local row = mkRow(52, o.Order or nextOrder())
            local topLabel = create("TextLabel", {
                Size = UDim2.new(1, -70, 0, 16), Position = UDim2.new(0, 14, 0, 7),
                BackgroundTransparency = 1, Text = o.Name or "Slider",
                TextColor3 = C.text, TextSize = 10, Font = Enum.Font.GothamMedium,
                TextXAlignment = Enum.TextXAlignment.Left,
                TextTruncate = Enum.TextTruncate.AtEnd,
            }, row)
            local function formatValue(v)
                if o.Format then return o.Format(v) end
                return string.format("%." .. dec .. "f", v)
            end
            local valLabel = create("TextLabel", {
                Size = UDim2.new(0, 56, 0, 16), Position = UDim2.new(1, -64, 0, 7),
                BackgroundTransparency = 1, Text = formatValue(val),
                TextColor3 = C.textMut, TextSize = 10, Font = Enum.Font.Gotham,
                TextXAlignment = Enum.TextXAlignment.Right,
            }, row)
            _ = topLabel
            local track = create("Frame", {
                Size = UDim2.new(1, -28, 0, 5), Position = UDim2.new(0, 14, 0, 33),
                BackgroundColor3 = C.input, BorderSizePixel = 0,
            }, row)
            corner(track, 999)
            local fill = create("Frame", {
                Size = UDim2.new((val - min) / math.max(1e-6, (max - min)), 0, 1, 0),
                BackgroundColor3 = C.accent, BorderSizePixel = 0,
            }, track)
            corner(fill, 999)
            local knobS = create("Frame", {
                Size = UDim2.new(0, 12, 0, 12),
                Position = UDim2.new((val - min) / math.max(1e-6, (max - min)), -6, 0.5, -6),
                BackgroundColor3 = C.text, BorderSizePixel = 0, ZIndex = 2,
            }, track)
            corner(knobS, 999)
            local cb, flag = o.Callback, o.Flag
            local dragging = false
            local defaultVal = o.Reset ~= nil and o.Reset or (o.Default ~= nil and o.Default or min)
            defaultVal = math.clamp(defaultVal, min, max)
            local lastClickT = 0
            local function setFromAlpha(a, silent)
                local v = min + (max - min) * math.clamp(a, 0, 1)
                if dec == 0 then v = math.floor(v + 0.5) end
                val = v
                if flag then Library.Flags[flag] = val end
                fill.Size = UDim2.new(math.clamp(a, 0, 1), 0, 1, 0)
                knobS.Position = UDim2.new(math.clamp(a, 0, 1), -6, 0.5, -6)
                valLabel.Text = formatValue(val)
                if not silent and cb then task.spawn(cb, val) end
            end
            local function toAlphaFromInput(input)
                local rel = (input.Position.X - track.AbsolutePosition.X) / math.max(1, track.AbsoluteSize.X)
                setFromAlpha(rel)
            end
            track.InputBegan:Connect(function(input)
                if input.UserInputType == Enum.UserInputType.MouseButton1
                or input.UserInputType == Enum.UserInputType.Touch then
                    local now = tick()
                    if now - lastClickT <= 0.35 then
                        lastClickT = 0
                        dragging = false
                        setFromAlpha((defaultVal - min) / math.max(1e-6, (max - min)))
                        if o.OnReset then task.spawn(o.OnReset) end
                        return
                    end
                    lastClickT = now
                    dragging = true ;toAlphaFromInput(input)
                end
            end)
            trackConn(UserInputService.InputChanged:Connect(function(input)
                if not dragging then return end
                if input.UserInputType == Enum.UserInputType.MouseMovement
                or input.UserInputType == Enum.UserInputType.Touch then
                    toAlphaFromInput(input)
                end
            end))
            trackConn(UserInputService.InputEnded:Connect(function(input)
                if input.UserInputType == Enum.UserInputType.MouseButton1
                or input.UserInputType == Enum.UserInputType.Touch then
                    dragging = false
                end
            end))
            if flag then
                Library.Flags[flag] = val
                table.insert(Library._appliers, function()
                    local v = tonumber(Library.Flags[flag])
                    if v and v ~= val then
                        setFromAlpha((v - min) / math.max(1e-6, (max - min)), true)
                    end
                end)
            end
            return { Set = function(_, v) setFromAlpha((v - min) / math.max(1e-6, (max - min))) end,
                Get = function() return val end,
                SetDefault = function(_, v) defaultVal = v end }
        end

        function Tab:Dropdown(o)
            o = o or {}
            local options = o.Options or {}
            local current = o.Default or options[1]
            if o.Flag and Library.Flags[o.Flag] ~= nil then
                current = Library.Flags[o.Flag]
            end
            local OPT_H, MAXV = 26, o.MaxVisible or 5
            local card = create("Frame", {
                Size = UDim2.new(1, 0, 0, 36),
                BackgroundColor3 = C.surface, BackgroundTransparency = 0.4, BorderSizePixel = 0,
                LayoutOrder = o.Order or nextOrder(), ClipsDescendants = true,
            }, page)
            corner(card, 10); stroke(card, C.borderSoft, 1, 0.55)
            local header = create("TextButton", {
                Size = UDim2.new(1, 0, 0, 36), BackgroundTransparency = 1,
                Text = "", AutoButtonColor = false,
            }, card)
            create("TextLabel", {
                Size = UDim2.new(1, -70, 0, 14), Position = UDim2.new(0, 14, 0, 5),
                BackgroundTransparency = 1, Text = o.Name or "Dropdown",
                TextColor3 = C.textDim, TextSize = 8, Font = Enum.Font.GothamBold,
                TextXAlignment = Enum.TextXAlignment.Left,
            }, header)
            local curLabel = create("TextLabel", {
                Size = UDim2.new(1, -70, 0, 13), Position = UDim2.new(0, 14, 0, 18),
                BackgroundTransparency = 1, Text = tostring(current or "Select..."),
                TextColor3 = C.text, TextSize = 10, Font = Enum.Font.GothamMedium,
                TextXAlignment = Enum.TextXAlignment.Left,
                TextTruncate = Enum.TextTruncate.AtEnd,
            }, header)
            local arrow = create("TextLabel", {
                Size = UDim2.new(0, 20, 0, 20), Position = UDim2.new(1, -30, 0.5, -10),
                BackgroundTransparency = 1, Text = "+", TextColor3 = C.textMut,
                TextSize = 14, Font = Enum.Font.GothamBold,
            }, header)
            local listHolder = create("Frame", {
                Size = UDim2.new(1, -16, 0, 0), Position = UDim2.new(0, 8, 0, 38),
                BackgroundTransparency = 1,
            }, card)
            create("UIListLayout", {
                Padding = UDim.new(0, 3), SortOrder = Enum.SortOrder.LayoutOrder,
            }, listHolder)
            local open = false
            local cb, flag = o.Callback, o.Flag
            local optionRows = {}
            local function refreshH(animate)
                local n = math.min(#options, MAXV)
                local target = open and (38 + n * (OPT_H + 3) + 8) or 36
                if animate then
                    tween(card, { Size = UDim2.new(1, 0, 0, target) }, 0.18, Enum.EasingStyle.Quart)
                else
                    card.Size = UDim2.new(1, 0, 0, target)
                end
            end
            local function setOpt(v, silent)
                current = v
                curLabel.Text = tostring(v)
                if flag then Library.Flags[flag] = v end
                if not silent and cb then task.spawn(cb, v) end
            end
            for _, opt in ipairs(options) do
                local b = create("TextButton", {
                    Size = UDim2.new(1, 0, 0, OPT_H),
                    BackgroundColor3 = C.input, BorderSizePixel = 0,
                    Text = "  " .. tostring(opt), TextColor3 = C.textMut,
                    TextSize = 9, Font = Enum.Font.Gotham,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    AutoButtonColor = false,
                }, listHolder)
                corner(b, 6)
                optionRows[#optionRows + 1] = b
                b.MouseButton1Click:Connect(function()
                    setOpt(opt)
                    open = false ;arrow.Text = "+" ;refreshH(true)
                    tween(b, { BackgroundColor3 = C.surfaceHi }, 0.15)
                end)
                b.MouseEnter:Connect(function()
                    tween(b, { BackgroundColor3 = C.surfaceHi }, 0.12)
                    b.TextColor3 = C.accent
                end)
                b.MouseLeave:Connect(function()
                    tween(b, { BackgroundColor3 = C.input }, 0.12)
                    b.TextColor3 = C.textMut
                end)
            end
            header.MouseButton1Click:Connect(function()
                open = not open
                arrow.Text = open and "-" or "+"
                refreshH(true)
                for _, rb in ipairs(optionRows) do
                    tween(rb, { BackgroundTransparency = open and 0 or 1 }, 0.16)
                end
            end)
            for _, rb in ipairs(optionRows) do rb.BackgroundTransparency = 1 end
            refreshH()
            if flag then
                Library.Flags[flag] = current
                table.insert(Library._appliers, function()
                    local v = Library.Flags[flag]
                    if v ~= nil and v ~= current then setOpt(v, true) end
                end)
            end
            return { Set = setOpt, Get = function() return current end }
        end

        function Tab:Button(o)
            o = o or {}
            local b = create("TextButton", {
                Size = UDim2.new(1, 0, 0, 32),
                BackgroundColor3 = C.surface, BackgroundTransparency = 0.4,
                BorderSizePixel = 0,
                Text = o.Name or "Button", TextColor3 = C.text,
                TextSize = 10, Font = Enum.Font.GothamMedium,
                AutoButtonColor = false, LayoutOrder = o.Order or nextOrder(),
            }, page)
            corner(b, 8); stroke(b, C.borderSoft, 1, 0.55)
            local btnHover = false
            local function btnRepaint()
                tween(b, { BackgroundTransparency = btnHover and 0.15 or 0.4 }, 0.12)
            end
            b.MouseEnter:Connect(function() btnHover = true ;btnRepaint() end)
            b.MouseLeave:Connect(function() btnHover = false ;btnRepaint() end)
            b.MouseButton1Down:Connect(function() tween(b, { BackgroundTransparency = 0 }, 0.06) end)
            b.MouseButton1Up:Connect(function() task.defer(btnRepaint) end)
            b.MouseButton1Click:Connect(function()
                tween(b, { BackgroundTransparency = 0 }, 0.06)
                task.delay(0.1, btnRepaint)
                task.delay(0.3, btnRepaint)
                if o.Callback then task.spawn(o.Callback) end
            end)
            return b
        end

        function Tab:Textbox(o)
            o = o or {}
            local function wireTextbox(box)
                box.FocusLost:Connect(function()
                    if o.Flag then Library.Flags[o.Flag] = box.Text end
                    if o.Callback then task.spawn(o.Callback, box.Text) end
                end)
                if o.Flag then
                    Library.Flags[o.Flag] = o.Default or ""
                    table.insert(Library._appliers, function()
                        local v = Library.Flags[o.Flag]
                        if v ~= nil then box.Text = tostring(v) end
                    end)
                end
            end
            local lines = tonumber(o.Lines) or 0
            local boxH = 24 + lines * 13
            local rowH = 22 + boxH + 6
            local row = mkRow(rowH, o.Order or nextOrder())
            create("TextLabel", {
                Size = UDim2.new(1, -28, 0, 14), Position = UDim2.new(0, 14, 0, 6),
                BackgroundTransparency = 1, Text = o.Name or "Textbox",
                TextColor3 = C.textDim, TextSize = 8, Font = Enum.Font.GothamBold,
                TextXAlignment = Enum.TextXAlignment.Left,
            }, row)
            if lines > 0 then
                local frame = create("Frame", {
                    Size = UDim2.new(1, -28, 0, boxH), Position = UDim2.new(0, 14, 0, 22),
                    BackgroundColor3 = C.input, BackgroundTransparency = 0.4, BorderSizePixel = 0, ClipsDescendants = true,
                }, row)
                corner(frame, 6); stroke(frame, C.borderSoft, 1, 0.6)
                local scroller = create("ScrollingFrame", {
                    Size = UDim2.new(1, -10, 1, -6), Position = UDim2.new(0, 5, 0, 3),
                    BackgroundTransparency = 1, BorderSizePixel = 0,
                    CanvasSize = UDim2.new(0, 0, 0, 0),
                    ScrollBarThickness = 3, ScrollBarImageColor3 = C.border,
                    ScrollingDirection = Enum.ScrollingDirection.Y,
                }, frame)
                local box = create("TextBox", {
                    Size = UDim2.new(1, 0, 1, 0), Position = UDim2.new(0, 0, 0, 0),
                    BackgroundTransparency = 1, BorderSizePixel = 0,
                    Text = o.Default or "", PlaceholderText = o.Placeholder or "Type here...",
                    PlaceholderColor3 = C.textDim, TextColor3 = C.text,
                    TextSize = 10, Font = Enum.Font.Gotham,
                    TextXAlignment = Enum.TextXAlignment.Left, ClearTextOnFocus = false,
                    TextWrapped = true, MultiLine = true,
                    TextYAlignment = Enum.TextYAlignment.Top,
                }, scroller)
                create("UIPadding", {
                    PaddingLeft = UDim.new(0, 7), PaddingRight = UDim.new(0, 12),
                    PaddingTop = UDim.new(0, 4), PaddingBottom = UDim.new(0, 4),
                }, box)
                box.RichText = false
                local fitting = false
                local function fit()
                    if fitting or not scroller.Parent then return end
                    fitting = true
                    local w, viewH = scroller.AbsoluteSize.X, scroller.AbsoluteSize.Y
                    if w > 1 and viewH > 1 then
                        local contentH = 16
                        local okTs, ts = pcall(function()
                            return game:GetService("TextService"):GetTextSize(
                                box.Text, 10, Enum.Font.Gotham, Vector2.new(w - 19, math.huge))
                        end)
                        if okTs and ts then contentH = ts.Y + 8 end
                        local total = math.max(contentH, viewH)
                        box.Size = UDim2.new(1, 0, 0, total)
                        scroller.CanvasSize = UDim2.new(0, 0, 0, total + 6)
                    end
                    fitting = false
                end
                task.spawn(function()
                    local tries = 0
                    while tries < 40 do
                        tries = tries + 1
                        if not frame.Parent then return end
                        if scroller.AbsoluteSize.X > 20 and scroller.AbsoluteSize.Y > 1 then
                            fit()
                            return
                        end
                        task.wait(0.05)
                    end
                end)
                box:GetPropertyChangedSignal("Text"):Connect(fit)
                scroller:GetPropertyChangedSignal("AbsoluteSize"):Connect(fit)
                wireTextbox(box)
                return box
            end

            local box = create("TextBox", {
                Size = UDim2.new(1, -28, 0, 24), Position = UDim2.new(0, 14, 0, 22),
                BackgroundColor3 = C.input, BackgroundTransparency = 0.4, BorderSizePixel = 0,
                Text = o.Default or "", PlaceholderText = o.Placeholder or "Type here...",
                PlaceholderColor3 = C.textDim, TextColor3 = C.text,
                TextSize = 10, Font = Enum.Font.Gotham,
                TextXAlignment = Enum.TextXAlignment.Left, ClearTextOnFocus = false,
            }, row)
            corner(box, 6); stroke(box, C.borderSoft, 1, 0.6)
            wireTextbox(box)
            return box
        end

        function Tab:Keybind(o)
            o = o or {}
            local row = mkRow(36, o.Order or nextOrder())
            create("TextLabel", {
                Size = UDim2.new(1, -90, 1, 0), Position = UDim2.new(0, 14, 0, 0),
                BackgroundTransparency = 1, Text = o.Name or "Keybind",
                TextColor3 = C.text, TextSize = 10, Font = Enum.Font.GothamMedium,
                TextXAlignment = Enum.TextXAlignment.Left,
                TextTruncate = Enum.TextTruncate.AtEnd,
            }, row)
            local cur = o.Default or Enum.KeyCode.E
            if o.Flag and Library.Flags[o.Flag] ~= nil then
                pcall(function()
                    local n = Library.Flags[o.Flag]
                    if typeof(n) == "table" and n.__key then cur = Enum.KeyCode[n.name]
                    elseif typeof(n) == "string" then cur = Enum.KeyCode[n] end
                end)
            end
            local keyBtn = create("TextButton", {
                Size = UDim2.new(0, 64, 0, 22), Position = UDim2.new(1, -76, 0.5, -11),
                BackgroundColor3 = C.input, BorderSizePixel = 0,
                Text = cur.Name, TextColor3 = C.textMut,
                TextSize = 9, Font = Enum.Font.Gotham,
                AutoButtonColor = false,
            }, row)
            corner(keyBtn, 6); stroke(keyBtn, C.borderSoft, 1, 0.6)
            local cb, flag = o.Callback, o.Flag
            local function applyKey(k)
                cur = k
                keyBtn.Text = cur.Name
                if flag then Library.Flags[flag] = cur end
            end
            keyBtn.MouseButton1Click:Connect(function()
                if monoBindCapturing then
                    monoBindEndCapture()
                    keyBtn.Text = cur.Name
                    return
                end
                keyBtn.Text = "..."
                monoBindCapture(function(input)
                    applyKey(input.KeyCode)
                    if cb then task.spawn(cb, input.KeyCode) end
                end, function() keyBtn.Text = cur.Name end)
            end)
            if flag then Library.Flags[flag] = cur end
            return { Set = function(_, k) cur = k ;keyBtn.Text = k.Name end,
                Get = function() return cur end }
        end

        function Tab:Colorpicker(o)
            o = o or {}
            local cur = o.Default or Color3.fromRGB(255, 255, 255)
            if o.Flag and Library.Flags[o.Flag] ~= nil then
                local v = Library.Flags[o.Flag]
                if typeof(v) == "Color3" then cur = v end
            end
            local card = create("Frame", {
                Size = UDim2.new(1, 0, 0, 36),
                BackgroundColor3 = C.surface, BackgroundTransparency = 0.4, BorderSizePixel = 0,
                LayoutOrder = o.Order or nextOrder(), ClipsDescendants = true,
            }, page)
            corner(card, 10); stroke(card, C.borderSoft, 1, 0.55)
            local header = create("TextButton", {
                Size = UDim2.new(1, 0, 0, 36), BackgroundTransparency = 1,
                Text = "", AutoButtonColor = false,
            }, card)
            create("TextLabel", {
                Size = UDim2.new(1, -60, 1, 0), Position = UDim2.new(0, 14, 0, 0),
                BackgroundTransparency = 1, Text = o.Name or "Color",
                TextColor3 = C.text, TextSize = 10, Font = Enum.Font.GothamMedium,
                TextXAlignment = Enum.TextXAlignment.Left,
            }, header)
            local preview = create("Frame", {
                Size = UDim2.new(0, 44, 0, 20), Position = UDim2.new(1, -56, 0.5, -10),
                BackgroundColor3 = cur, BorderSizePixel = 0,
            }, header)
            corner(preview, 6); stroke(preview, C.borderSoft, 1, 0.4)
            local open = false
            local cb, flag = o.Callback, o.Flag
            local function apply(c, silent)
                cur = c
                preview.BackgroundColor3 = c
                if flag then Library.Flags[flag] = c end
                if not silent and cb then task.spawn(cb, c) end
            end
            local comps = { R = math.floor(cur.R * 255), G = math.floor(cur.G * 255), B = math.floor(cur.B * 255) }
            local defaultComps = { R = comps.R, G = comps.G, B = comps.B }
            if o.Reset then
                defaultComps.R = math.floor(o.Reset.R * 255)
                defaultComps.G = math.floor(o.Reset.G * 255)
                defaultComps.B = math.floor(o.Reset.B * 255)
            end
            local y = 40
            for _, ch in ipairs({ "R", "G", "B" }) do
                create("TextLabel", {
                    Size = UDim2.new(0, 14, 0, 20), Position = UDim2.new(0, 14, 0, y),
                    BackgroundTransparency = 1, Text = ch, TextColor3 = C.textMut,
                    TextSize = 9, Font = Enum.Font.GothamBold,
                }, card)
                local tr = create("Frame", {
                    Size = UDim2.new(1, -96, 0, 5), Position = UDim2.new(0, 32, 0, y + 8),
                    BackgroundColor3 = C.input, BorderSizePixel = 0,
                }, card)
                corner(tr, 999)
                local fl = create("Frame", {
                    Size = UDim2.new(comps[ch] / 255, 0, 1, 0),
                    BackgroundColor3 = C.accent, BorderSizePixel = 0,
                }, tr)
                corner(fl, 999)
                local kn = create("Frame", {
                    Size = UDim2.new(0, 10, 0, 10),
                    Position = UDim2.new(comps[ch] / 255, -5, 0.5, -5),
                    BackgroundColor3 = C.text, BorderSizePixel = 0,
                }, tr)
                corner(kn, 999)
                local num = create("TextLabel", {
                    Size = UDim2.new(0, 40, 0, 20), Position = UDim2.new(1, -52, 0, y),
                    BackgroundTransparency = 1, Text = tostring(comps[ch]),
                    TextColor3 = C.textMut, TextSize = 9, Font = Enum.Font.Gotham,
                    TextXAlignment = Enum.TextXAlignment.Right,
                }, card)
                local drag = false
                local lastClickT = 0
                local function setFromA(a)
                    local v = math.floor(math.clamp(a, 0, 1) * 255 + 0.5)
                    comps[ch] = v
                    fl.Size = UDim2.new(v / 255, 0, 1, 0)
                    kn.Position = UDim2.new(v / 255, -5, 0.5, -5)
                    num.Text = tostring(v)
                    apply(Color3.fromRGB(comps.R, comps.G, comps.B))
                end
                tr.InputBegan:Connect(function(input)
                    if input.UserInputType == Enum.UserInputType.MouseButton1
                    or input.UserInputType == Enum.UserInputType.Touch then
                        local now = tick()
                        if now - lastClickT <= 0.35 then
                            lastClickT = 0
                            drag = false
                            setFromA(defaultComps[ch] / 255)
                            return
                        end
                        lastClickT = now
                        drag = true
                        local rel = (input.Position.X - tr.AbsolutePosition.X) / math.max(1, tr.AbsoluteSize.X)
                        setFromA(rel)
                    end
                end)
                trackConn(UserInputService.InputChanged:Connect(function(input)
                    if not drag then return end
                    if input.UserInputType == Enum.UserInputType.MouseMovement
                    or input.UserInputType == Enum.UserInputType.Touch then
                        local rel = (input.Position.X - tr.AbsolutePosition.X) / math.max(1, tr.AbsoluteSize.X)
                        setFromA(rel)
                    end
                end))
                trackConn(UserInputService.InputEnded:Connect(function(input)
                    if input.UserInputType == Enum.UserInputType.MouseButton1
                    or input.UserInputType == Enum.UserInputType.Touch then
                        drag = false
                    end
                end))
                y = y + 24
            end
            local function refreshH()
                tween(card, { Size = UDim2.new(1, 0, 0, open and 122 or 36) }, 0.18, Enum.EasingStyle.Quart)
            end
            header.MouseButton1Click:Connect(function()
                open = not open
                refreshH()
            end)
            if flag then
                Library.Flags[flag] = cur
                table.insert(Library._appliers, function()
                    local v = Library.Flags[flag]
                    if typeof(v) == "Color3" then apply(v, true) end
                end)
            end
            return { Set = apply, Get = function() return cur end }
        end

        return Tab
    end

    snowLayer = create("CanvasGroup", {
        Name = "Snow", BackgroundTransparency = 1, BorderSizePixel = 0,
        Size = UDim2.new(1, 0, 1, 0),
        Active = false, ClipsDescendants = true, ZIndex = 0,
    }, window)
    corner(snowLayer, 18)
    snowCorner = snowLayer:FindFirstChildOfClass("UICorner")
    local snowflakes = monoBuildFlakes(snowLayer, 16, 0.08, 0.14, 4, 10, 0.6, 0.25)
    monoStartSnow(snowLayer, snowflakes)

    MonoWindow._snow = snowLayer
    MonoWindow._snowFlakes = snowflakes

    loading = (opts.Loading ~= false)

    if loading then
        window.Visible = false
        local loadTime = tonumber(opts.LoadTime) or 2.5
        local loadGui = create("ScreenGui", {
            Name = "MonochromeLoad", ResetOnSpawn = false,
            IgnoreGuiInset = true, ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
        })
        monoGuiParent(loadGui)
        applyDisplayOrder(loadGui, MONO_ORDER.Load, MONO_ORDER_OLD.Load)
        local overlay = create("Frame", {
            Name = "Loading",
            Size = UDim2.new(0, WIN_W, 0, WIN_H),
            Position = startPos,
            BackgroundColor3 = C.bg, BorderSizePixel = 0,
            ClipsDescendants = true,
        }, loadGui)
        corner(overlay, 18)
        local loadStroke = stroke(overlay, C.border, 1, 0.25)
        snowLayer.Parent = overlay
        local loadTitle = create("TextLabel", {
            Size = UDim2.new(1, 0, 0, 22), Position = UDim2.new(0, 0, 0.5, -26),
            BackgroundTransparency = 1, Text = title,
            TextColor3 = C.text, TextSize = 20, Font = Enum.Font.GothamBold,
            ZIndex = 51,
        }, overlay)
        local track = create("Frame", {
            Size = UDim2.new(0, 180, 0, 4), Position = UDim2.new(0.5, -90, 0.5, 4),
            BackgroundColor3 = C.surfaceHi, BorderSizePixel = 0, ZIndex = 51,
        }, overlay)
        corner(track, 999)
        local fill = create("Frame", {
            Size = UDim2.new(0, 0, 1, 0),
            BackgroundColor3 = C.accent, BorderSizePixel = 0, ZIndex = 52,
        }, track)
        corner(fill, 999)
        local pct = create("TextLabel", {
            Size = UDim2.new(0, 180, 0, 12), Position = UDim2.new(0.5, -90, 0.5, 14),
            BackgroundTransparency = 1, Text = "0%",
            TextColor3 = C.textMut, TextSize = 9, Font = Enum.Font.GothamMedium,
            ZIndex = 51,
        }, overlay)
        overlay.BackgroundTransparency = 1
        loadStroke.Transparency = 1
        loadTitle.TextTransparency = 1
        track.BackgroundTransparency = 1
        fill.BackgroundTransparency = 0
        pct.TextTransparency = 1
        tween(overlay, { BackgroundTransparency = 0 }, 0.5)
        tween(loadStroke, { Transparency = 0.25 }, 0.5)
        task.delay(0.5, function() loadStroke.Transparency = 0.25 end)
        tween(loadTitle, { TextTransparency = 0 }, 0.5)
        tween(track, { BackgroundTransparency = 0 }, 0.5)
        tween(pct, { TextTransparency = 0 }, 0.5)
        task.spawn(function()
            local t0 = tick()
            while loading and overlay.Parent do
                local a = math.clamp((tick() - t0) / loadTime, 0, 1)
                fill.Size = UDim2.new(a, 0, 1, 0)
                pct.Text = math.floor(a * 100 + 0.5) .. "%"
                if a >= 1 then break end
                task.wait()
            end
            task.wait(0.2)
            window.Visible = uiVisible
            snowLayer.Parent = window
            tween(overlay, { BackgroundTransparency = 1 }, 0.35)
            tween(loadStroke, { Transparency = 1 }, 0.35)
            tween(loadTitle, { TextTransparency = 1 }, 0.35)
            tween(track, { BackgroundTransparency = 1 }, 0.35)
            tween(fill, { BackgroundTransparency = 1 }, 0.35)
            tween(pct, { TextTransparency = 1 }, 0.35)
            task.delay(0.4, function()
                loading = false

                pcall(function() loadGui:Destroy() end)
            end)
        end)
    end

    table.insert(Library._windows, MonoWindow)
    return MonoWindow
end

