function miscAnnMeasure()
    if not miscAnnCard or not miscAnnCard.Parent then return false end
    local page = Home._page
    local scroll = miscAnnScroll
    if not page or not page.Parent or not scroll or not scroll.Parent then return false end
    local ph = page.AbsoluteSize.Y
    local sw = scroll.AbsoluteSize.X
    if ph <= 50 or sw <= 1 then return false end
    local rel = miscAnnCard.AbsolutePosition.Y - page.AbsolutePosition.Y
    if rel < 0 then rel = 0 end
    local h = ph - rel
    if h <= 60 then return false end
    local textW = math.max(40, sw - 4)
    local okTs, ts = pcall(function()
        return game:GetService("TextService"):GetTextSize(
            miscAnnText, 10, Enum.Font.Gotham, Vector2.new(textW, math.huge))
    end)
    if not okTs or not ts then return false end
    miscAnnCard.Size = UDim2.new(1, 0, 0, math.floor(h))
    local textH = math.max(16, math.ceil(ts.Y) + 4)
    miscAnnLabel.Size = UDim2.new(1, -4, 0, textH)
    scroll.CanvasSize = UDim2.new(0, 0, 0, textH + 8)
    return true
end

task.spawn(function()
    local tries = 0
    while tries < 300 do
        tries = tries + 1
        task.wait(0.1)
        if not miscAnnCard.Parent then return end
        if miscAnnMeasure() then break end
    end
end)

