monoStarOff = string.char(226, 152, 134)

function registerMonoCommand(name, run, hold)
    monoCommands[#monoCommands + 1] = {
        name = name, run = run, hold = hold == true,
    }
    if monoCmdHolder then monoCmdRefresh() end
    return monoCommands[#monoCommands]
end

function monoCmdIsFav(name)
    return monoCmdFavs[name] == true
end

function monoCmdToggleFav(name)
    if monoCmdFavs[name] then
        monoCmdFavs[name] = nil
    else
        monoCmdFavs[name] = true
    end
    setSave()
    return monoCmdIsFav(name)
end

monoCmdNoAuto = {
    fakeout = true, trip = true,
    rejoin = true, serverhop = true,
    serverhopmost = true, serverhopping = true, serverhopfew = true,
    tptospawn = true,
    mute = true, unmute = true, muteall = true, unmuteall = true,
    to = true, view = true, headsit = true, backpack = true,
    hide = true, unhide = true, hideall = true, unhideall = true,
    inspect = true,
    destroy = true,
    aitools = true,
}

function monoCmdIsAuto(name)
    if monoCmdNoAuto[name] then return false end
    if type(name) == "string" and name:sub(1, 9) == "vcbypass" then
        if type(monoVcIsLoaded) == "function" and monoVcIsLoaded() then return false end
        if type(setData) == "table" and setData.vcBypassRan ~= nil and setData.vcBypassRan ~= "" then
            return false
        end
    end
    return monoCmdAuto[name] == true
end

function monoCmdSorted()
    local favs, rest = {}, {}
    for _, c in ipairs(monoCommands) do
        if not monoGlobalCmdNames[c.name] then
            if monoCmdIsFav(c.name) then favs[#favs + 1] = c else rest[#rest + 1] = c end
        end
    end
    table.sort(favs, function(a, b) return a.name:lower() < b.name:lower() end)
    table.sort(rest, function(a, b) return a.name:lower() < b.name:lower() end)
    for _, c in ipairs(rest) do favs[#favs + 1] = c end
    return favs
end

monoCmdDestroy = {}

function monoCmdOnDestroy(name, fn)
    if type(fn) == "function" then monoCmdDestroy[name] = fn end
    return fn
end

monoChatPrefix = "."
monoChatConn = nil

monoChatEngage = {}

function monoChatRun(args)
    local name = args[1]
    if not name then return end
    for _, cmd in ipairs(monoCommands) do
        if cmd.name == name then
            if cmd.hold then
                if monoChatEngage[name] then monoChatEngage[name]() end
                return
            end
            local rest = {}
            for i = 2, #args do rest[#rest + 1] = args[i] end
            pcall(cmd.run, nil, rest)
            return
        end
    end
end

function monoChatDisconnect()
    if monoChatConn then
        pcall(function() monoChatConn:Disconnect() end)
        monoChatConn = nil
    end
end

function monoChatOnMessage(msg)
    if type(msg) ~= "string" then return end
    if msg:sub(1, #monoChatPrefix) ~= monoChatPrefix then return end
    local trimmed = msg:sub(#monoChatPrefix + 1):gsub("^%s+", "")
    if trimmed == "" then return end
    local args = {}
    for part in trimmed:gmatch("%S+") do args[#args + 1] = part end
    monoChatRun(args)
end

monoChatConn = LocalPlayer.Chatted:Connect(monoChatOnMessage)
monoCmdOnDestroy("chat", monoChatDisconnect)

monoGlobalPrefix = "/"
monoGlobalConn = nil
monoGlobalTCSConns = {}
monoGlobalFlingJobs = {}
monoGlobalSeen = { text = "", at = 0 }
monoGlobalBypassUid = 7275889224

function monoGlobalBypassUser(uid)
    return tonumber(uid) == monoGlobalBypassUid
end

function monoGlobalFlag(name)
    if type(setData) ~= "table" then return true end
    local v = setData[name]
    if v == nil then return true end
    return v and true or false
end

function monoGlobalFindPlayer(query)
    if type(query) ~= "string" or query == "" then return nil end
    local q = query:lower()
    for _, p in ipairs(Players:GetPlayers()) do
        if p.Name:lower() == q or (p.DisplayName and p.DisplayName:lower() == q) then
            return p
        end
    end
    for _, p in ipairs(Players:GetPlayers()) do
        local n = p.Name:lower()
        local dn = p.DisplayName and p.DisplayName:lower() or ""
        if n:find(q, 1, true) or dn:find(q, 1, true) then return p end
    end
    return nil
end

monoGlobalFlingSpeed    = 650
monoGlobalFlingSpread   = 1
monoGlobalFlingUpBias   = 0.7
monoGlobalFlingDuration = 2.5

function monoGlobalFlingStop(plr)
    local job = monoGlobalFlingJobs[plr]
    if not job then return end
    if job.timer then pcall(function() task.cancel(job.timer) end) end
    monoGlobalFlingJobs[plr] = nil
end

function monoGlobalFlingDirection()
    local dir = Vector3.new(
        (math.random() * 2 - 1) * monoGlobalFlingSpread,
        monoGlobalFlingUpBias,
        (math.random() * 2 - 1) * monoGlobalFlingSpread)
    if dir.Magnitude < 0.001 then dir = Vector3.new(0, 1, 0) end
    return dir.Unit
end

function monoGlobalFlingPlayer(plr)
    if not plr then return false end
    local char = plr.Character
    local root = char and char:FindFirstChild("HumanoidRootPart")
    if not root or not root.Parent then return false end

    monoGlobalFlingStop(plr)

    pcall(function()
        root.AssemblyLinearVelocity = monoGlobalFlingDirection() * monoGlobalFlingSpeed
    end)

    local job = {}
    monoGlobalFlingJobs[plr] = job
    job.timer = task.delay(monoGlobalFlingDuration, function()
        if monoGlobalFlingJobs[plr] == job then
            monoGlobalFlingJobs[plr] = nil
        end
    end)
    return true
end

registerMonoCommand("fling", function(auto, args)
    local name = args and args[1]
    local target = monoGlobalFindPlayer(name)
    if not target then
        notify("Monochrome", "No player matching " .. tostring(name), 3)
        return
    end
    if monoGlobalFlingPlayer(target) then
        notify("Monochrome", "Flung " .. target.Name, 2)
    else
        notify("Monochrome", "Could not fling " .. target.Name, 3)
    end
end)

function monoGlobalTripPlayer(plr)
    if not plr then return false end
    local char = plr.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    local root = char and char:FindFirstChild("HumanoidRootPart")
    if not hum or not root or not root.Parent then return false end

    local locked = false
    pcall(function() locked = not hum:GetStateEnabled(Enum.HumanoidStateType.FallingDown) end)
    if locked then
        pcall(function() hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, true) end)
    end
    pcall(function() hum:ChangeState(Enum.HumanoidStateType.FallingDown) end)
    if locked then
        task.delay(0.25, function()
            pcall(function() hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, false) end)
        end)
    end
    pcall(function() root.AssemblyLinearVelocity = root.CFrame.LookVector * 30 end)
    return true
end

function monoGlobalStopFeatures()
    pcall(StopAll)
    pcall(monoFlyStop)
    pcall(monoFoStop)
    pcall(monoSneakStop)
    pcall(monoFreeCamReleaseAll)
    pcall(monoHeadCtrlStop)
    pcall(monoReanimStopBody)
end

function monoGlobalBringPlayer(plr)
    if not plr then return false end
    local char = LocalPlayer.Character
    local root = char and char:FindFirstChild("HumanoidRootPart")
    local tRoot = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
    if not root or not root.Parent or not tRoot or not tRoot.Parent then return false end

    pcall(function()
        local front = tRoot.CFrame.Position + tRoot.CFrame.LookVector * 3
        root.CFrame = CFrame.new(front, tRoot.Position)
        root.AssemblyLinearVelocity = Vector3.zero
        root.AssemblyAngularVelocity = Vector3.zero
        local hum = char:FindFirstChildOfClass("Humanoid")
        if hum then hum.Sit = false; hum.AutoRotate = true end
    end)
    return true
end

