    if job.timer then pcall(function() task.cancel(job.timer) end) end
    if job.bv and job.bv.Parent then pcall(function() job.bv:Destroy() end) end
    if job.anim then pcall(function() job.anim:Stop() end) end
    local hum = job.hum
    if hum and hum.Parent then
        pcall(function()
            hum.PlatformStand = false
            hum.AutoRotate = true
            hum:ChangeState(Enum.HumanoidStateType.GettingUp)
        end)
    end
    local root = job.root
    if root and root.Parent then
        pcall(function()
            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
        end)
    end
end

function monoGlobalCrack(plr, force)
    if not plr or plr == LocalPlayer then return false end
    if not force and monoGlobalCrackJob and monoGlobalCrackJob.target == plr then
        monoGlobalCrackStop()
        return "stopped"
    end
    local tRoot = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
    local char = LocalPlayer.Character
    local root = char and char:FindFirstChild("HumanoidRootPart")
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if not tRoot or not tRoot.Parent or not root or not root.Parent or not hum then return false end

    monoGlobalCrackStop()

    local bv = Instance.new("BodyVelocity")
    bv.Name = "MonoGlobalCrack"
    bv.MaxForce = Vector3.new(1e9, 1e9, 1e9)
    bv.Velocity = Vector3.zero
    bv.Parent = root

    local track = nil
    pcall(function()
        local anim = Instance.new("Animation")
        anim.AnimationId = monoGlobalCrackAnim
        local animator = hum:FindFirstChildOfClass("Animator")
        track = animator and animator:LoadAnimation(anim) or hum:LoadAnimation(anim)
        if track then
            track.Priority = Enum.AnimationPriority.Action
            track:Play()
        end
    end)

    pcall(function()
        hum.PlatformStand = true
        hum.AutoRotate = false
    end)

    local job = { target = plr, root = root, hum = hum, bv = bv, anim = track, t = 0, conn = nil, timer = nil }
    monoGlobalCrackJob = job

    job.conn = trackConn(RunService.Heartbeat:Connect(function(dt)
        if monoGlobalCrackJob ~= job then return end
        local tChar = plr.Character
        local tr = tChar and tChar:FindFirstChild("HumanoidRootPart")
        if not tr or not root.Parent or not hum.Parent or not bv.Parent then
            monoGlobalCrackStop()
            return
        end
        job.t = job.t + dt
        local speed = math.clamp(tonumber(monoGlobalCrackSpeed) or 1, 0.1, 3)
        local dist = math.clamp(tonumber(monoGlobalCrackDistance) or 0.7, 0.2, 3.5)
        local wave = math.sin(job.t * speed * math.pi * 6.5)
        local offset = dist + wave * math.max(0.25, dist * 0.55)
        pcall(function()
            
            
            root.CFrame = tr.CFrame * CFrame.new(0, 0, -offset)
            bv.Velocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
            hum.PlatformStand = true
            hum.AutoRotate = false
        end)
        if track then pcall(function() track:AdjustSpeed(speed) end) end
    end))

    job.timer = task.delay(math.max(0.5, tonumber(monoGlobalCrackDuration) or 2), function()
        if monoGlobalCrackJob == job then monoGlobalCrackStop() end
    end)

    return true
end

function monoGlobalOnMessage(text, fromUserId, fromName, fromPlayer)
    local bypassUid = monoGlobalBypassUser(fromUserId)
    if not bypassUid and not monoGlobalFlag("globalCommands") then return end
    if type(text) ~= "string" then return end
    local msg = text:gsub("^%s+", "")
    if msg:sub(1, 1) ~= monoGlobalPrefix then return end
    local body = msg:sub(2):gsub("^%s+", "")
    local args = {}
    for part in body:gmatch("%S+") do args[#args + 1] = part end
    local cmd = args[1] and args[1]:lower() or ""
    table.remove(args, 1)
    if cmd == "fling" then
        if not bypassUid and not monoGlobalFlag("globalFling") then return end
        if not fromPlayer or fromPlayer == LocalPlayer or fromUserId == LocalPlayer.UserId then return end
        local target = monoGlobalFindPlayer(args[1])
        if not target then return end
        if target == LocalPlayer then monoGlobalStopFeatures() end
        monoGlobalFlingPlayer(target)
    elseif cmd == "trip" then
        if not bypassUid and not monoGlobalFlag("globalTrip") then return end
        if not fromPlayer or fromPlayer == LocalPlayer or fromUserId == LocalPlayer.UserId then return end
        local target = monoGlobalFindPlayer(args[1])
        if not target then return end
        if target == LocalPlayer then monoGlobalStopFeatures() end
        monoGlobalTripPlayer(target)
    elseif cmd == "crack" then
        if not bypassUid and not monoGlobalFlag("globalCrack") then return end
        if not fromPlayer or fromPlayer == LocalPlayer or fromUserId == LocalPlayer.UserId then return end
        local nameText = table.concat(args, " "):lower():gsub("^%s+", ""):gsub("%s+$", ""):gsub("^@", "")
        local target = nil
        if nameText ~= "" then
            local n = LocalPlayer.Name:lower()
            local dn = (LocalPlayer.DisplayName or ""):lower()
            if n == nameText or dn == nameText
                or n:find(nameText, 1, true)
                or (dn ~= "" and dn:find(nameText, 1, true)) then
                target = LocalPlayer
            end
        end
        if not target then target = monoGlobalFindPlayer(nameText) end
        
        if target ~= LocalPlayer then return end
        local sender = fromPlayer or Players:GetPlayerByUserId(fromUserId)
        if not sender and type(fromName) == "string" and fromName ~= "" then
            sender = monoGlobalFindPlayer(fromName)
        end
        if not sender or sender == LocalPlayer then return end
        monoGlobalStopFeatures()
        local result = monoGlobalCrack(sender, true)
        if result == true then
            notify("Global", "Cracked by " .. sender.Name .. " (2s)", 2)
        elseif result == "stopped" then
            notify("Global", "Crack stopped", 2)
        else
            notify("Global", "crack failed - " .. sender.Name .. " has no character", 3)
        end
    elseif cmd == "bring" then
        if not bypassUid and not monoGlobalFlag("globalBring") then return end
        if not fromPlayer or fromPlayer == LocalPlayer or fromUserId == LocalPlayer.UserId then return end
        local nameText = table.concat(args, " "):lower():gsub("^%s+", ""):gsub("%s+$", ""):gsub("^@", "")
        local named = nil
        if nameText ~= "" then
            local n = LocalPlayer.Name:lower()
            local dn = (LocalPlayer.DisplayName or ""):lower()
            if n == nameText or dn == nameText then named = LocalPlayer end
        end
        if not named then
            local p = monoGlobalFindPlayer(nameText)
            if p == LocalPlayer then named = LocalPlayer end
        end
        if named ~= LocalPlayer then return end
        monoGlobalStopFeatures()
        local sender = fromPlayer or Players:GetPlayerByUserId(fromUserId)
        if not sender and type(fromName) == "string" and fromName ~= "" then
            sender = monoGlobalFindPlayer(fromName)
        end
        if not sender or sender == LocalPlayer then return end
        if monoGlobalBringPlayer(sender) then
            notify("Global", "Brought to " .. sender.Name, 2)
        end
    end
end

function monoGlobalHookChannel(channel)
    if not channel or not channel:IsA("TextChannel") then return end
    if monoGlobalTCSConns[channel] then return end
    monoGlobalTCSConns[channel] = channel.MessageReceived:Connect(function(message)
        if message.TextSource then
            local uid = message.TextSource.UserId
            if uid ~= LocalPlayer.UserId then
                local sname = nil
                pcall(function() sname = message.TextSource.Name end)
                local sp = Players:GetPlayerByUserId(uid)
                if not sp and type(sname) == "string" and sname ~= "" then
                    sp = monoGlobalFindPlayer(sname)
                end
                monoGlobalOnMessage(message.Text, uid, sname, sp)
            end
        end
    end)
end

monoGlobalPlayerChats = {}
monoGlobalPlayerAddedConn = nil

function monoGlobalHookPlayerChat(p)
    if not p or p == LocalPlayer or monoGlobalPlayerChats[p.UserId] then return end
    monoGlobalPlayerChats[p.UserId] = trackConn(p.Chatted:Connect(function(msg)
        local now = tick()
        if monoGlobalSeen.text == msg and (now - monoGlobalSeen.at) < 0.5 then return end
        monoGlobalSeen.text = msg
        monoGlobalSeen.at = now
        monoGlobalOnMessage(msg, p.UserId, p.Name, p)
    end))
end

function monoGlobalConnect()
    if monoGlobalConn then return end
    monoGlobalConn = trackConn(LocalPlayer.Chatted:Connect(function(msg)
        local now = tick()
        if monoGlobalSeen.text == msg and (now - monoGlobalSeen.at) < 0.5 then return end
        monoGlobalSeen.text = msg
        monoGlobalSeen.at = now
        monoGlobalOnMessage(msg, LocalPlayer.UserId, LocalPlayer.Name, LocalPlayer)
    end))
    for _, p in ipairs(Players:GetPlayers()) do monoGlobalHookPlayerChat(p) end
    monoGlobalPlayerAddedConn = trackConn(Players.PlayerAdded:Connect(monoGlobalHookPlayerChat))
    trackConn(Players.PlayerRemoving:Connect(function(p)
        local c = monoGlobalPlayerChats[p.UserId]
        if c then pcall(function() c:Disconnect() end); monoGlobalPlayerChats[p.UserId] = nil end
    end))
    pcall(function()
        local TCS = game:GetService("TextChatService")
        if TCS.ChatVersion == Enum.ChatVersion.TextChatService then
            for _, obj in ipairs(TCS:GetDescendants()) do monoGlobalHookChannel(obj) end
            monoGlobalTCSConns[#monoGlobalTCSConns + 1] = TCS.DescendantAdded:Connect(monoGlobalHookChannel)
        end
    end)
end

monoGlobalConnect()

monoCmdOnDestroy("global", function()
    if monoGlobalConn then
        pcall(function() monoGlobalConn:Disconnect() end)
        monoGlobalConn = nil
    end
    for k, c in pairs(monoGlobalTCSConns) do
        pcall(function() c:Disconnect() end)
        monoGlobalTCSConns[k] = nil
    end
    if monoGlobalPlayerAddedConn then
        pcall(function() monoGlobalPlayerAddedConn:Disconnect() end)
        monoGlobalPlayerAddedConn = nil
    end
    for uid, c in pairs(monoGlobalPlayerChats) do
        pcall(function() c:Disconnect() end)
        monoGlobalPlayerChats[uid] = nil
    end
    for plr in pairs(monoGlobalFlingJobs) do monoGlobalFlingStop(plr) end
    monoGlobalCrackStop()
end)

function monoCmdPill(parent, on, onChange, xoff)
    local sw = create("Frame", {
        Size = UDim2.new(0, 38, 0, 20), Position = UDim2.new(1, xoff or -44, 0.5, -10),
        BackgroundColor3 = on and C.accent or C.input, BorderSizePixel = 0,
    }, parent)
    corner(sw, 999); stroke(sw, C.borderSoft, 1, 0.55)
    local track = sw
    local knob = create("Frame", {
        Size = UDim2.new(0, 14, 0, 14),
        Position = on and UDim2.new(1, -17, 0.5, -7) or UDim2.new(0, 3, 0.5, -7),
        BackgroundColor3 = on and C.bg or C.text, BorderSizePixel = 0,
    }, track)
    corner(knob, 999)
    local cur = on
    local function paint(v)
        tween(track, { BackgroundColor3 = v and C.accent or C.input }, 0.2)
        tween(knob, {
            BackgroundColor3 = v and C.bg or C.text,
            Position = v and UDim2.new(1, -17, 0.5, -7) or UDim2.new(0, 3, 0.5, -7),
        }, 0.22)
    end
    local hit = create("TextButton", {
        Size = UDim2.new(1, 0, 1, 0), BackgroundTransparency = 1, Text = "",
        AutoButtonColor = false,
    }, track)
    hit.MouseButton1Click:Connect(function()
        cur = not cur
        paint(cur)
        if onChange then onChange(cur) end
    end)
    return function(v)
        if v == nil then
            cur = not cur
        else
            if cur == v then return end
            cur = v
        end
        paint(cur)
        if onChange then onChange(cur) end
    end
end

monoCmdBinds = {}

monoBindShortMap = {
    LeftControl = "LCtrl", RightControl = "RCtrl", LeftShift = "LShift", RightShift = "RShift",
    LeftAlt = "LAlt", RightAlt = "RAlt", LeftSuper = "LWin", RightSuper = "RWin",
    LeftArrow = "Left", RightArrow = "Right", UpArrow = "Up", DownArrow = "Down",
    LeftBracket = "[", RightBracket = "]", Semicolon = ";", Apostrophe = "'",
    Comma = ",", Period = ".", Slash = "/", Backslash = "\\", Minus = "-", Equal = "=",
    Backquote = "`", CapsLock = "Caps", PageUp = "PgUp", PageDown = "PgDn",
    KeypadZero = "K0", KeypadOne = "K1", KeypadTwo = "K2", KeypadThree = "K3",
    KeypadFour = "K4", KeypadFive = "K5", KeypadSix = "K6", KeypadSeven = "K7",
    KeypadEight = "K8", KeypadNine = "K9",
    KeypadAdd = "K+", KeypadSubtract = "K-", KeypadMultiply = "K*",
    KeypadDivide = "K/", KeypadDecimal = "K.", KeypadEnter = "KEnter",
    numpad0 = "K0", numpad1 = "K1", numpad2 = "K2", numpad3 = "K3",
    numpad4 = "K4", numpad5 = "K5", numpad6 = "K6", numpad7 = "K7",
    numpad8 = "K8", numpad9 = "K9",
}

function monoCmdBindShort(keyName)
    if type(keyName) ~= "string" or keyName == "" then return "Bind" end
    return monoBindShortMap[keyName] or keyName
end

function monoToggleBtnText()
    if toggleUIKeyName then return "Hide UI (" .. toggleUIKeyName .. " to show)" end
    return "Hide UI (no key bound)"
end

function monoToggleHideToast()
    if toggleUIKeyName then return "Hidden - press " .. toggleUIKeyName .. " to show" end
    return "Hidden"
end

function monoCmdBindGet(name)
    return monoCmdBinds[name]
end

function monoCmdBindSet(name, keyName)
    if keyName == nil then
        monoCmdBinds[name] = nil
    else
        for k, v in pairs(monoCmdBinds) do
            if v == keyName and k ~= name then monoCmdBinds[k] = nil end
        end
        if type(monoSneak) == "table" and monoSneak.key == keyName then monoSneakKeySet(nil) end
        monoCmdBinds[name] = keyName
    end
    if type(setData) == "table" then
        setData.cmdBinds = monoCmdBinds
        if type(setSave) == "function" then setSave() end
    end
end

monoCmdHoldState = {}
monoCmdBindConn = nil
monoCmdEndConn = nil

function monoCmdBindListener(input, gameProcessed)
    if monoBindCapturing then return end
    if gameProcessed then return end
    if input.UserInputType ~= Enum.UserInputType.Keyboard then return end
    if monoBindSwallow then return end
    local kn = input.KeyCode.Name
    if kn == "Unknown" then return end
    if toggleUIKeyName and kn == toggleUIKeyName then return end
    for _, cmd in ipairs(monoCommands) do
        if monoCmdBinds[cmd.name] == kn then
            if cmd.hold then
                if monoCmdHoldState[cmd.name] then return end
                monoCmdHoldState[cmd.name] = true
            end
            task.spawn(function() pcall(cmd.run) end)
            return
        end
    end
end

function monoCmdEndListener(input, gameProcessed)
    if input.UserInputType ~= Enum.UserInputType.Keyboard then return end
    if monoBindSwallow then
        monoBindSwallow = false
        return
    end
    local kn = input.KeyCode.Name
    if kn == "Unknown" then return end
    for _, cmd in ipairs(monoCommands) do
        if cmd.hold and monoCmdHoldState[cmd.name] and monoCmdBinds[cmd.name] == kn then
            monoCmdHoldState[cmd.name] = false
            task.spawn(function() pcall(cmd.run) end)
            return
        end
    end
end

function monoCmdBindDisconnect()
    if monoCmdBindConn then pcall(function() monoCmdBindConn:Disconnect() end) ;monoCmdBindConn = nil end
    if monoCmdEndConn then pcall(function() monoCmdEndConn:Disconnect() end) ;monoCmdEndConn = nil end
end

function monoCmdBindConnect()
    if monoCmdBindConn then return end
    monoCmdBindConn = UserInputService.InputBegan:Connect(monoCmdBindListener)
    monoCmdEndConn = UserInputService.InputEnded:Connect(monoCmdEndListener)
end

trackConn(UserInputService.WindowFocusReleased:Connect(function()
    if type(monoFreeCamReleaseAll) == "function" then pcall(monoFreeCamReleaseAll) end
    for _, cmd in ipairs(monoCommands) do
        if monoCmdHoldState[cmd.name] then
            monoCmdHoldState[cmd.name] = false
            task.spawn(function() pcall(cmd.run) end)
        end
    end
end))

monoCmdBindConnect()

monoCmdQuery = ""

function monoCmdMatches(name)
    if type(monoCmdQuery) ~= "string" or monoCmdQuery == "" then return true end
    return string.find(string.lower(name), string.lower(monoCmdQuery), 1, true) ~= nil
end

function monoCmdBuildList(parent, isAuto)
    local all = monoCmdSorted()
    local list = {}
    for _, cmd in ipairs(all) do
        if monoCmdMatches(cmd.name) and not (isAuto and monoCmdNoAuto[cmd.name]) then
            list[#list + 1] = cmd
        end
    end
    for i, cmd in ipairs(list) do
        local row = create("Frame", {
            Size = UDim2.new(1, 0, 0, 32), BackgroundColor3 = C.surface,
            BackgroundTransparency = 0.4, BorderSizePixel = 0,
            LayoutOrder = i,
        }, parent)
        corner(row, 10); stroke(row, C.borderSoft, 1, 0.55)
        create("TextLabel", {
            Size = isAuto and UDim2.new(1, -112, 1, 0) or UDim2.new(1, -98, 1, 0),
            Position = UDim2.new(0, 12, 0, 0), BackgroundTransparency = 1,
            Text = cmd.name, TextColor3 = C.text, TextSize = 11,
            Font = Enum.Font.Gotham, TextXAlignment = Enum.TextXAlignment.Left,
        }, row)
        if isAuto then
            monoCmdPill(row, monoCmdIsAuto(cmd.name), function(on)
                if on then monoCmdAuto[cmd.name] = true else monoCmdAuto[cmd.name] = nil end
                setSave()
            end, -73)
        else
            local bkey = monoCmdBindGet(cmd.name)
            local chip = create("TextButton", {
                Size = UDim2.new(0, 52, 0, 20), Position = UDim2.new(1, -86, 0.5, -10),
                BackgroundColor3 = C.input, BorderSizePixel = 0,
                Text = monoCmdBindShort(bkey), TextColor3 = bkey and C.accent or C.textDim,
                TextSize = 9, Font = Enum.Font.Gotham, AutoButtonColor = false, ZIndex = 2,
                TextTruncate = Enum.TextTruncate.AtEnd, ClipsDescendants = true,
            }, row)
            corner(chip, 6); stroke(chip, C.borderSoft, 1, 0.55)
            local function chipPaint(k)
                pcall(function()
                    chip.Text = monoCmdBindShort(k)
                    chip.TextColor3 = k and C.accent or C.textDim
                end)
            end
            chip.MouseButton1Click:Connect(function()
                if monoBindCapturing then
                    monoBindEndCapture()
                    local had = monoCmdBindGet(cmd.name)
                    monoCmdBindSet(cmd.name, nil)
                    chipPaint(monoCmdBindGet(cmd.name))
                    if had then notify("Monochrome", cmd.name .. " keybind cleared", 2) end
                    return
                end
                chip.Text = "..."
                chip.TextColor3 = C.accent
                monoBindCapture(function(input)
                    monoCmdBindSet(cmd.name, input.KeyCode.Name)
                    notify("Monochrome", cmd.name .. " bound to " .. input.KeyCode.Name, 2)
                    monoCmdRefresh()
                end, function()
                    chipPaint(monoCmdBindGet(cmd.name))
                end)
            end)
            local hit = create("TextButton", {
                Size = UDim2.new(1, -104, 1, 0), BackgroundTransparency = 1,
                Text = "", AutoButtonColor = false,
            }, row)
            hit.MouseButton1Click:Connect(function()
                if not cmd.hold then
                    pcall(cmd.run)
                    return
                end
                if monoCmdHoldState[cmd.name] then return end
                monoCmdHoldState[cmd.name] = true
                pcall(cmd.run)
                task.delay(0.6, function()
                    if not monoCmdHoldState[cmd.name] then return end
                    monoCmdHoldState[cmd.name] = false
                    pcall(cmd.run)
                end)
            end)
        end
        local fav = monoCmdIsFav(cmd.name)
        local star = create("TextButton", {
            Size = UDim2.new(0, 30, 0, 32), Position = UDim2.new(1, -30, 0, 0),
            BackgroundTransparency = 1, BorderSizePixel = 0,
            Text = fav and monoStarOn or monoStarOff,
            TextColor3 = fav and C.accent or C.textDim,
            TextSize = 13, Font = Enum.Font.GothamBold,
            AutoButtonColor = false, ZIndex = 2,
        }, row)
        star.MouseButton1Click:Connect(function()
            local now = monoCmdToggleFav(cmd.name)
            star.Text = now and monoStarOn or monoStarOff
            star.TextColor3 = now and C.accent or C.textDim
            monoCmdRefresh()
        end)
    end
end

function monoCmdRefresh()
    if monoCmdHolder then
        for _, c in ipairs(monoCmdHolder:GetChildren()) do
            if c:IsA("Frame") then c:Destroy() end
        end
        monoCmdBuildList(monoCmdHolder, false)
    end
    if monoAutoHolder then
        for _, c in ipairs(monoAutoHolder:GetChildren()) do
            if c:IsA("Frame") then c:Destroy() end
        end
        monoCmdBuildList(monoAutoHolder, true)
    end
end

function monoCmdRunAuto()
    task.spawn(function()
        if not monoWaitLoad() then return end
        for _, cmd in ipairs(monoCmdSorted()) do
            if monoCmdIsAuto(cmd.name) then pcall(cmd.run, true) end
        end
    end)
end



