monoTpToolActive = false
monoTpToolConn = nil
monoTpToolWatchBp = nil
monoTpToolWatchChar = nil
monoTpToolRespawning = false
monoTpToolBpWait = nil

function monoTpToolStop()
    monoTpToolActive = false
    monoTpToolRespawning = false
    if monoTpToolConn then pcall(function() monoTpToolConn:Disconnect() end) ;monoTpToolConn = nil end
    if monoTpToolWatchBp then pcall(function() monoTpToolWatchBp:Disconnect() end) ;monoTpToolWatchBp = nil end
    if monoTpToolWatchChar then pcall(function() monoTpToolWatchChar:Disconnect() end) ;monoTpToolWatchChar = nil end
    if monoTpToolBpWait then pcall(function() monoTpToolBpWait:Disconnect() end) ;monoTpToolBpWait = nil end
    local bp = LocalPlayer:FindFirstChildOfClass("Backpack")
    if bp then local t = bp:FindFirstChild("Teleport Tool") ;if t then pcall(function() t:Destroy() end) end end
    local char = LocalPlayer.Character
    if char then local t = char:FindFirstChild("Teleport Tool") ;if t then pcall(function() t:Destroy() end) end end
end

function monoTpToolBreakVelocity()
    local char = LocalPlayer.Character
    if not char then return end
    local zero = Vector3.zero
    for _, v in ipairs(char:GetDescendants()) do
        if v:IsA("BasePart") then
            v.Velocity = zero
            v.RotVelocity = zero
        end
    end
end

function monoTpFootOffset(char, h, root)

    local okBB, bb, size = pcall(function()
        local cf, s = char:GetBoundingBox()
        return cf, s
    end)
    if okBB and bb and size and size.Y > 0.1 then
        local off = root.Position.Y - (bb.Position.Y - size.Y * 0.5)
        if off and off == off and off > 0 and off < 100 then return off end
    end
    if h then
        if h.RigType == Enum.HumanoidRigType.R6 then return 3 end
        local hip = tonumber(h.HipHeight)
        if hip and hip == hip and hip > 0 then return hip end
    end
    return 3
end

function monoTpToolGo(root, h, targetPos, lookTarget)

    local char = root.Parent
    local off = monoTpFootOffset(char, h, root)
    local finalPos = Vector3.new(targetPos.X, targetPos.Y + off, targetPos.Z)
    local lookDir = Vector3.new(lookTarget.X - targetPos.X, 0, lookTarget.Z - targetPos.Z)
    if lookDir.Magnitude < 0.01 then
        lookDir = Vector3.new(0, 0, 1)
    end
    root.CFrame = CFrame.new(finalPos, finalPos + lookDir.Unit)
    monoTpToolBreakVelocity()
    if h then h.Sit = false ;h.AutoRotate = true end
end

function monoTpToolCheckGone()
    if monoTpToolRespawning then return end
    if monoTpToolHas() then return end
    local c = LocalPlayer.Character
    if not c or not c.Parent or not c:FindFirstChildOfClass("Humanoid") then return end
    monoTpToolStop()
end

function monoTpToolBpRemoved(child)
    if child.Name ~= "Teleport Tool" then return end
    task.defer(monoTpToolCheckGone)
end

function monoTpToolCharRemoved(child)
    if child.Name ~= "Teleport Tool" then return end
    local c = LocalPlayer.Character
    if not c or not c.Parent then return end
    task.defer(monoTpToolCheckGone)
end

function monoTpToolWatch()
    if not monoTpToolWatchBp then
        local b = LocalPlayer:FindFirstChildOfClass("Backpack")
        if b then monoTpToolWatchBp = b.ChildRemoved:Connect(monoTpToolBpRemoved) end
    end
    if not monoTpToolWatchChar then
        local c = LocalPlayer.Character
        if c then monoTpToolWatchChar = c.ChildRemoved:Connect(monoTpToolCharRemoved) end
    end
end

function monoTpToolHas()
    local b = LocalPlayer:FindFirstChildOfClass("Backpack")
    if b and b:FindFirstChild("Teleport Tool") then return true end
    local c = LocalPlayer.Character
    if c and c:FindFirstChild("Teleport Tool") then return true end
    return false
end

function monoTpToolBuild()
    local tool = Instance.new("Tool")
    tool.Name = "Teleport Tool"
    tool.RequiresHandle = false
    tool.ToolTip = "Click to teleport"
    tool.Activated:Connect(function()
        local c = LocalPlayer.Character
        if not c then return end
        local h = c:FindFirstChildOfClass("Humanoid")
        local root = c:FindFirstChild("HumanoidRootPart")
        if not root then return end
        local hit = LocalPlayer:GetMouse().Hit
        if not hit then return end
        local pos = hit.Position
        local targetPos = pos 
        local lookDir = Vector3.new(pos.X, root.Position.Y, pos.Z) - root.Position
        lookDir = lookDir.Magnitude > 0.01 and lookDir.Unit or root.CFrame.LookVector
        monoTpToolGo(root, h, targetPos, targetPos + lookDir)
    end)
    return tool
end

function monoTpToolGive()
    if not monoTpToolActive then return end
    local bp = LocalPlayer:FindFirstChildOfClass("Backpack")
    if not bp then
        if not monoTpToolBpWait then
            monoTpToolBpWait = trackConn(LocalPlayer.ChildAdded:Connect(function(child)
                if not child:IsA("Backpack") then return end
                if monoTpToolBpWait then pcall(function() monoTpToolBpWait:Disconnect() end) ;monoTpToolBpWait = nil end
                monoTpToolGive()
            end))
        end
        return
    end
    if monoTpToolBpWait then pcall(function() monoTpToolBpWait:Disconnect() end) ;monoTpToolBpWait = nil end
    if not monoTpToolHas() then
        local tool = monoTpToolBuild()
        tool.Parent = bp
    end
    monoTpToolWatch()
end

function monoTpToolRespawn()
    monoTpToolRespawning = true
    local c = LocalPlayer.Character
    if c then pcall(function() c:WaitForChild("Humanoid", 10) end) end
    if not monoTpToolActive then monoTpToolRespawning = false ;return end
    if monoTpToolWatchChar then pcall(function() monoTpToolWatchChar:Disconnect() end) ;monoTpToolWatchChar = nil end
    monoTpToolGive()
    monoTpToolRespawning = false
end

monoCmdOnDestroy("tptool", monoTpToolStop)

registerMonoCommand("tptool", function(auto)
    if auto then
        if monoTpToolActive then monoTpToolGive() ;return end
    else
        if monoTpToolActive then
            monoTpToolStop()
            return
        end
    end
    monoTpToolActive = true
    monoTpToolGive()
    if monoTpToolConn then pcall(function() monoTpToolConn:Disconnect() end) end
    monoTpToolConn = trackConn(LocalPlayer.CharacterAdded:Connect(function()
        task.spawn(monoTpToolRespawn)
    end))
end)

monoTpSpawnCache = {}

function monoTpSpawnScan()
    local found = {}
    for _, obj in ipairs(workspace:GetDescendants()) do
        if obj:IsA("SpawnLocation") then
            table.insert(found, obj.CFrame)
        end
    end
    if #found > 0 then monoTpSpawnCache = found end
    return found
end

function monoTpSpawnCFrame(root)
    local assigned = LocalPlayer.RespawnLocation
    if assigned and assigned:IsA("SpawnLocation") then
        local c = assigned.CFrame
        return c.Position, c.Position + c.LookVector
    end

    local spawns = monoTpSpawnScan()
    if #spawns == 0 then spawns = monoTpSpawnCache end

    if #spawns > 0 then
        local nearest, nearestDist = spawns[1], math.huge
        for _, c in ipairs(spawns) do
            local d = (c.Position - root.Position).Magnitude
            if d < nearestDist then
                nearest = c
                nearestDist = d
            end
        end
        return nearest.Position, nearest.Position + nearest.LookVector
    end

    return Vector3.new(0, 0, 0), Vector3.new(0, 0, -1)
end

registerMonoCommand("tptospawn", function()
    local char = LocalPlayer.Character
    local root = char and char:FindFirstChild("HumanoidRootPart")
    if not root then
        notify("Monochrome", "Teleport to spawn needs a character", 3)
        return false
    end
    local h = char:FindFirstChildOfClass("Humanoid")
    local pos, look = monoTpSpawnCFrame(root)
    monoTpToolGo(root, h, pos, look)
    notify("Monochrome", "Teleported to spawn", 3)
    return true
end)

monoRsLastEnabled = false
monoRsLastCFrame = nil
monoRsLastDiedConn = nil
monoRsLastBaseY = nil
pcall(function()
    local ok, y = pcall(function() return workspace.FallenPartsDestroyHeight end)
    monoRsLastBaseY = (ok and tonumber(y)) or -500
end)

function _monoRsLastCurrentChar()
    local char = LocalPlayer.Character
    pcall(function()
        if monoReanimAPI and type(monoReanimAPI.is_reanimated) == "function"
        and monoReanimAPI.is_reanimated() then
            if type(monoReanimAPI.get_clone) == "function" then
                local clone = monoReanimAPI.get_clone()
                if clone and clone.Parent then char = clone end
            end
        end
    end)
    return char
end

monoRsLastIgnoreNext = false
function monoRsLastOnChar(char)
    local root = char:WaitForChild("HumanoidRootPart", 5)
    local hum = char:WaitForChild("Humanoid", 5)
    if not root or not hum then return end
    local ignore = monoRsLastIgnoreNext
    if ignore then monoRsLastIgnoreNext = false end
    if (not ignore) and monoRsLastEnabled and monoRsLastCFrame then
        task.wait(0.1)
        if root and root.Parent then root.CFrame = monoRsLastCFrame end
    end
    if monoRsLastDiedConn then pcall(function() monoRsLastDiedConn:Disconnect() end) ;monoRsLastDiedConn = nil end
    monoRsLastDiedConn = hum.Died:Connect(function()
        if monoReanimAPI and type(monoReanimAPI.is_reanimated) == "function"
        and monoReanimAPI.is_reanimated() then
            return
        end
        local base = monoRsLastBaseY or -500
        if root and root.Parent and root.Position.Y > (base + 10) then
            monoRsLastCFrame = root.CFrame
        else
            monoRsLastCFrame = nil
        end
    end)
end

monoRsLastReanimDiedConn = nil
function monoRsLastHookReanim()
    if monoRsLastReanimDiedConn then
        pcall(function() monoRsLastReanimDiedConn:Disconnect() end)
        monoRsLastReanimDiedConn = nil
    end
    if not (monoReanimAPI and type(monoReanimAPI.is_reanimated) == "function"
    and monoReanimAPI.is_reanimated()) then
        return
    end
    local clone = nil
    pcall(function() clone = monoReanimAPI.get_clone() end)
    if not (clone and clone.Parent) then return end
    local hum = clone:FindFirstChildOfClass("Humanoid")
    if not hum then return end
    monoRsLastReanimDiedConn = hum.Died:Connect(function()
        local r = clone:FindFirstChild("HumanoidRootPart")
        local base = monoRsLastBaseY or -500
        if r and r.Parent and r.Position.Y > (base + 10) then
            monoRsLastCFrame = r.CFrame
        end
    end)
end
if LocalPlayer.Character then task.spawn(monoRsLastOnChar, LocalPlayer.Character) end
trackConn(LocalPlayer.CharacterAdded:Connect(monoRsLastOnChar))

monoCmdOnDestroy("respawnlastlocation", function()
    if monoRsLastDiedConn then pcall(function() monoRsLastDiedConn:Disconnect() end) ;monoRsLastDiedConn = nil end
    if monoRsLastReanimDiedConn then pcall(function() monoRsLastReanimDiedConn:Disconnect() end) ;monoRsLastReanimDiedConn = nil end
end)

registerMonoCommand("respawnlastlocation", function(auto)
    if auto then monoRsLastEnabled = true else monoRsLastEnabled = not monoRsLastEnabled end
    if not monoRsLastEnabled then monoRsLastCFrame = nil end
    if type(setData) == "table" then
        setData.respawnLastLoc = monoRsLastEnabled
        if type(setSave) == "function" then setSave() end
    end
    notify("Monochrome", "Respawn to last location " .. (monoRsLastEnabled and "enabled" or "disabled"), 3)
end)

monoAntiVoidOn = false
monoAntiVoidOrigY = nil
monoAntiVoidConn = nil

function monoAntiVoidStart()
    if monoAntiVoidConn then return end
    if monoAntiVoidOrigY == nil then
        local ok, y = pcall(function() return workspace.FallenPartsDestroyHeight end)
        local n = ok and tonumber(y) or nil
        monoAntiVoidOrigY = (n ~= nil and n == n) and n or -500
    end
    monoAntiVoidConn = trackConn(RunService.Heartbeat:Connect(function()
        pcall(function() workspace.FallenPartsDestroyHeight = 0 / 0 end)
        local char = LocalPlayer.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        if not root or not root:IsA("BasePart") then return end
        local refY = monoAntiVoidOrigY or workspace.FallenPartsDestroyHeight
        if root.Position.Y < (refY + 50) and not monoFoHold
            and not (type(monoSneak) == "table" and (monoSneak.on or monoSneak.busy)) then
            root.AssemblyLinearVelocity = Vector3.new(0, 500, 0)
        end
    end))
end

function monoAntiVoidStop()
    if monoAntiVoidConn then pcall(function() monoAntiVoidConn:Disconnect() end) ;monoAntiVoidConn = nil end
    if monoAntiVoidOrigY ~= nil then
        local y = monoAntiVoidOrigY
        pcall(function() workspace.FallenPartsDestroyHeight = y end)
    end
end

