monoAntiSitOn = false
monoAntiSitConn = nil
monoAntiSitCharConn = nil
monoAntiSitHum = nil
monoAntiSitConns = nil
monoAntiSitWas = nil
monoAntiSitHold = false

function monoAntiSitUnseat(h)
    if not h or not h.Parent then return end
    local seat = h.SeatPart
    if seat then pcall(function() seat:Sit(nil) end) end
    pcall(function() h.Sit = false end)
    pcall(function() h:ChangeState(Enum.HumanoidStateType.GettingUp) end)
    local root = h.RootPart
    if root and root.Parent then
        pcall(function() root.AssemblyLinearVelocity = Vector3.new(0, 0, 0) end)
    end
end

function monoAntiSitPause(on)
    if (on and true) == (monoAntiSitHold == true) then return end
    monoAntiSitHold = (on and true) or false
    if not monoAntiSitConn then return end
    local ch = LocalPlayer.Character
    local h = ch and ch:FindFirstChildOfClass("Humanoid")
    if h then monoAntiSitAttach(h) end
end

function monoAntiSitDetach()
    if type(monoAntiSitConns) == "table" then
        for _, c in ipairs(monoAntiSitConns) do
            pcall(function() c:Disconnect() end)
        end
    end
    monoAntiSitConns = nil
    if monoAntiSitHum and monoAntiSitWas ~= nil then
        pcall(function() monoAntiSitHum:SetStateEnabled(Enum.HumanoidStateType.Seated, monoAntiSitWas) end)
    end
    monoAntiSitHum = nil
    monoAntiSitWas = nil
end

function monoAntiSitAttach(h)
    if not h or not h.Parent then return end
    monoAntiSitDetach()
    monoAntiSitHum = h
    local was = true
    pcall(function() was = h:GetStateEnabled(Enum.HumanoidStateType.Seated) == true end)
    monoAntiSitWas = was
    if monoAntiSitHold then
        pcall(function() h:SetStateEnabled(Enum.HumanoidStateType.Seated, monoAntiSitWas) end)
        return
    end
    pcall(function() h:SetStateEnabled(Enum.HumanoidStateType.Seated, false) end)
    monoAntiSitUnseat(h)
    local list = {}
    local function push(c)
        if c then list[#list + 1] = c end
    end
    push(trackConn(h.Seated:Connect(function(on)
        if on and not monoAntiSitHold then monoAntiSitUnseat(h) end
    end)))
    local okSig, sig = pcall(function() return h:GetStateChangedSignal() end)
    if okSig and sig then
        push(trackConn(sig:Connect(function(_, now)
            if now == Enum.HumanoidStateType.Seated and not monoAntiSitHold then monoAntiSitUnseat(h) end
        end)))
    end
    monoAntiSitConns = list
end

function monoAntiSitStop()
    if monoAntiSitConn then pcall(function() monoAntiSitConn:Disconnect() end) ;monoAntiSitConn = nil end
    if monoAntiSitCharConn then pcall(function() monoAntiSitCharConn:Disconnect() end) ;monoAntiSitCharConn = nil end
    monoAntiSitDetach()
end

function monoAntiSitStart()
    if monoAntiSitConn then return end
    local char = LocalPlayer.Character
    if char then
        local h = char:FindFirstChildOfClass("Humanoid")
        if h then monoAntiSitAttach(h) end
    end
    monoAntiSitCharConn = trackConn(LocalPlayer.CharacterAdded:Connect(function(nc)
        task.defer(function()
            if not monoAntiSitConn then return end
            local h = nc:FindFirstChildOfClass("Humanoid")
            if h then monoAntiSitAttach(h) end
        end)
    end))
    monoAntiSitConn = trackConn(RunService.Heartbeat:Connect(function()
        if not monoAntiSitConn or monoAntiSitHold then return end
        local ch = LocalPlayer.Character
        if not ch then return end
        local h = ch:FindFirstChildOfClass("Humanoid")
        if not h then return end
        if h ~= monoAntiSitHum then
            monoAntiSitAttach(h)
            return
        end
        if h.SeatPart then monoAntiSitUnseat(h) end
    end))
end

monoCmdOnDestroy("antisit", monoAntiSitStop)

