    end
    notify("Monochrome", "Anti sit " .. (monoAntiSitOn and "enabled" or "disabled"), 3)
end)

monoAntiRagdollOn = false
monoAntiRagdollConn = nil
monoAntiRagdollCharConn = nil
monoAntiRagdollSaved = {}

function monoAntiRagdollUnstick(h)
    if not h or not h.Parent then return end
    if h.PlatformStand then pcall(function() h.PlatformStand = false end) end
    local st = nil
    pcall(function() st = h:GetState() end)
    if st == Enum.HumanoidStateType.Ragdoll or st == Enum.HumanoidStateType.FallingDown
    or st == Enum.HumanoidStateType.Freefall or st == Enum.HumanoidStateType.None then
        pcall(function() h:ChangeState(Enum.HumanoidStateType.GettingUp) end)
    end
    local root = h.RootPart
    if root and root.Parent then
        pcall(function() root.AssemblyLinearVelocity = Vector3.new(0, 0, 0) end)
    end
end

function monoAntiRagdollApply(h, disable)
    if not h or not h.Parent then return end
    if disable then
        if not monoAntiRagdollSaved[h] then
            local rag, fall = true, true
            pcall(function() rag = h:GetStateEnabled(Enum.HumanoidStateType.Ragdoll) end)
            pcall(function() fall = h:GetStateEnabled(Enum.HumanoidStateType.FallingDown) end)
            monoAntiRagdollSaved[h] = { rag = rag, fall = fall }
        end
        pcall(function()
            h:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, false)
            h:SetStateEnabled(Enum.HumanoidStateType.FallingDown, false)
        end)
        monoAntiRagdollUnstick(h)
    else
        local rec = monoAntiRagdollSaved[h]
        if rec then
            pcall(function()
                h:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, rec.rag)
                h:SetStateEnabled(Enum.HumanoidStateType.FallingDown, rec.fall)
            end)
            monoAntiRagdollSaved[h] = nil
        else
            pcall(function()
                h:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, true)
                h:SetStateEnabled(Enum.HumanoidStateType.FallingDown, true)
            end)
        end
    end
end

function monoAntiRagdollStop()
    if monoAntiRagdollConn then pcall(function() monoAntiRagdollConn:Disconnect() end) ;monoAntiRagdollConn = nil end
    if monoAntiRagdollCharConn then pcall(function() monoAntiRagdollCharConn:Disconnect() end) ;monoAntiRagdollCharConn = nil end
    for h, _ in pairs(monoAntiRagdollSaved) do
        monoAntiRagdollApply(h, false)
    end
    monoAntiRagdollSaved = {}
end

function monoAntiRagdollStart()
    if monoAntiRagdollConn then return end
    local c = LocalPlayer.Character
    if c then
        local h = c:FindFirstChildOfClass("Humanoid")
        if h then monoAntiRagdollApply(h, true) end
    end
    monoAntiRagdollCharConn = trackConn(LocalPlayer.CharacterAdded:Connect(function(char)
        task.defer(function()
            if not monoAntiRagdollConn then return end
            local h = char:FindFirstChildOfClass("Humanoid")
            if h then monoAntiRagdollApply(h, true) end
        end)
    end))
    monoAntiRagdollConn = trackConn(RunService.Heartbeat:Connect(function()
        local ch = LocalPlayer.Character
        if not ch then return end
        local h = ch:FindFirstChildOfClass("Humanoid")
        if h then
            local rag = true
            pcall(function() rag = h:GetStateEnabled(Enum.HumanoidStateType.Ragdoll) end)
            if rag then monoAntiRagdollApply(h, true) end
        end
    end))
end

monoCmdOnDestroy("antiragdoll", monoAntiRagdollStop)

registerMonoCommand("antiragdoll", function(auto)
    if auto then monoAntiRagdollOn = true else monoAntiRagdollOn = not monoAntiRagdollOn end
    if monoAntiRagdollOn then monoAntiRagdollStart() else monoAntiRagdollStop() end
    if type(setData) == "table" then
        setData.antiRagdoll = monoAntiRagdollOn
        if type(setSave) == "function" then setSave() end
    end
    notify("Monochrome", "Anti ragdoll " .. (monoAntiRagdollOn and "enabled" or "disabled"), 3)
end)

monoFoHold = false
monoFoDepth = 1000
monoFoChar = nil
monoFoSavedCF = nil
monoFoSavedVoid = nil
monoFoPlatform = nil
monoFoConn = nil

function monoFoStop()
    monoFoHold = false
    if monoFoConn then pcall(function() monoFoConn:Disconnect() end) ;monoFoConn = nil end
    if monoFoPlatform then pcall(function() monoFoPlatform:Destroy() end) ;monoFoPlatform = nil end
    local cf = monoFoSavedCF
    local srcChar = monoFoChar
    monoFoSavedCF = nil
    monoFoChar = nil
    local c = LocalPlayer.Character
    local r = c and c:FindFirstChild("HumanoidRootPart")
    if cf and r and r.Parent and c == srcChar then
        pcall(function()
            r.CFrame = cf
            r.AssemblyLinearVelocity = Vector3.zero
            r.AssemblyAngularVelocity = Vector3.zero
        end)
    end
    local y = monoFoSavedVoid
    monoFoSavedVoid = nil
    if y ~= nil and not monoAntiVoidOn then
        pcall(function() workspace.FallenPartsDestroyHeight = y end)
    end
end

function monoFoStart()
    if monoFoHold then return false end
    if type(monoSneakHardStop) == "function" then pcall(monoSneakHardStop) end
    local char = LocalPlayer.Character
    local root = char and char:FindFirstChild("HumanoidRootPart")
    if not root or not root.Parent then
        notify("Monochrome", "Fake out: no character", 3)
        return false
    end
    monoFoHold = true
    monoFoChar = char
    monoFoSavedCF = root.CFrame
    if not monoAntiVoidOn then
        local ok, y = pcall(function() return workspace.FallenPartsDestroyHeight end)
        local n = ok and tonumber(y) or nil
        monoFoSavedVoid = (n ~= nil and n == n) and n or -500
        pcall(function() workspace.FallenPartsDestroyHeight = -(monoFoDepth * 2) end)
    end
    local plat = Instance.new("Part")
    plat.Name = "MonoFakeOutPlatform"
    plat.Anchored = true
    plat.CanCollide = true
    plat.Transparency = 1
    plat.Size = Vector3.new(3, 5, 3)
    plat.CFrame = CFrame.new(root.Position.X, -(monoFoDepth + 5), root.Position.Z)
    plat.Parent = workspace
    monoFoPlatform = plat
    pcall(function()
        root.AssemblyLinearVelocity = Vector3.zero
        root.AssemblyAngularVelocity = Vector3.zero
        root.CFrame = CFrame.new(root.Position.X, -monoFoDepth, root.Position.Z)
    end)
    monoFoConn = trackConn(RunService.Heartbeat:Connect(function()
        if not monoFoHold then return end
        local c = LocalPlayer.Character
        local r = c and c:FindFirstChild("HumanoidRootPart")
        if not r or not r.Parent or c ~= monoFoChar then monoFoStop() ;return end
        pcall(function() r.AssemblyLinearVelocity = Vector3.zero end)
        if monoFoPlatform and monoFoPlatform.Parent then
            pcall(function()
                monoFoPlatform.CFrame = CFrame.new(r.Position.X, -(monoFoDepth + 5), r.Position.Z)
            end)
        end
    end))
    return true
end

monoCmdOnDestroy("fakeout", monoFoStop)

registerMonoCommand("fakeout", function()
    if monoFoHold then
        monoFoStop()
        return
    end
    monoFoStart()
end, true)

monoChatEngage.fakeout = monoFoStart




monoSneak = {
    on = false, busy = false, t = 0, duration = 0.8,
    depth = 5, key = nil, keyConn = nil,
    btn = nil, bindBtn = nil,
    char = nil, root = nil, savedCF = nil, savedAnchored = false, anchorSaved = false,
    fromCF = nil, toCF = nil, fromY = nil, toY = nil, platform = nil, conn = nil,
    fill = nil, knob = nil, track = nil, valLabel = nil,
    dragging = false, lastClick = 0, moveConn = nil, endConn = nil,
    noclipOwned = false,
}
monoSneakMin = 1
monoSneakMax = 10
monoSneakReset = 5

function monoSneakSave()
    if type(setData) == "table" then
        setData.sneakBind = monoSneak.key or false
        setData.sneakDepth = monoSneak.depth
        if type(setSave) == "function" then setSave() end
    end
end

function monoSneakLoad()
    if type(setData) ~= "table" then return end
    local raw = tonumber(setData.sneakDepth)
    if raw and raw == raw then
        monoSneak.depth = math.clamp(math.floor(raw + 0.5), monoSneakMin, monoSneakMax)
    end
    if type(setData.sneakBind) == "string" and setData.sneakBind ~= "" then
        monoSneak.key = setData.sneakBind
    end
end

local function monoSneakEase(k)
    local a = math.clamp(k, 0, 1)
    return a * a * (3 - 2 * a)
end

function monoSneakDestroyPlatform()
    if monoSneak.platform then
        pcall(function() monoSneak.platform:Destroy() end)
        monoSneak.platform = nil
    end
end

local MONO_SNEAK_PLAT_H = 5

local function monoSneakFootOffset()
    local root = monoSneak.root
    local char = LocalPlayer.Character
    if type(monoTpFootOffset) == "function" and root and char then
        local hum = char:FindFirstChildOfClass("Humanoid")
        local ok, v = pcall(function()
            return monoTpFootOffset(char, hum, root)
        end)
        if ok and type(v) == "number" and v == v and v > 0 and v < 100 then
            return v
        end
    end
    return 3
end

local function monoSneakIgnoreList(root)
    local list = { root.Parent, monoSneak.platform }
    pcall(function()
        for _, plr in ipairs(Players:GetPlayers()) do
            local c = plr.Character
            if c and c ~= root.Parent then
                list[#list + 1] = c
            end
        end
    end)
    return list
end

local function monoSneakSpotClear(root, feetY)
    local ok, parts = pcall(function()
        local op = OverlapParams.new()
        op.FilterType = Enum.RaycastFilterType.Exclude
        op.FilterDescendantsInstances = monoSneakIgnoreList(root)
        pcall(function() op.CollisionGroup = root.CollisionGroup end)
        return workspace:GetPartBoundsInBox(
            CFrame.new(root.Position.X, feetY + 2.6, root.Position.Z),
            Vector3.new(2.4, 5, 2.4), op)
    end)
    if not ok or type(parts) ~= "table" then return true end
    for _, p in ipairs(parts) do
        if p.CanCollide then
            return false
        end
    end
    return true
end

local function monoSneakSnapDown(root, rootY)
    local foot = monoSneakFootOffset()
    local feetY = rootY - foot
    local ok, hit = pcall(function()
        local params = RaycastParams.new()
        params.FilterType = Enum.RaycastFilterType.Exclude
        params.FilterDescendantsInstances = monoSneakIgnoreList(root)
        pcall(function() params.CollisionGroup = root.CollisionGroup end)
        params.IgnoreWater = true
        return workspace:Raycast(
            Vector3.new(root.Position.X, feetY + 0.5, root.Position.Z),
            Vector3.new(0, -30, 0), params)
    end)
    if not ok or not hit or not hit.Instance then return rootY end
    if not hit.Instance.CanCollide or hit.Normal.Y < 0.6 then return rootY end
    local snapFeet = hit.Position.Y + 0.1
    if not monoSneakSpotClear(root, snapFeet) then return rootY end
    return snapFeet + foot
end

local function monoSneakFindReturnY(root, maxSteps)
    local result = nil
    pcall(function()
        local foot = monoSneakFootOffset()
        local startFeet = root.Position.Y - foot
        local sawBlocked = false
        for step = 0, (maxSteps or 200) do
            local feetY = startFeet + step + 0.1
            if monoSneakSpotClear(root, feetY) then
                if sawBlocked then
                    result = monoSneakSnapDown(root, feetY + foot)
                    break
                end
            else
                sawBlocked = true
            end
        end
    end)
    return result
end

local function monoSneakPlatformCFrame(y, root)
    if not root then return nil end
    local top = y - monoSneakFootOffset() - 0.5
    return CFrame.new(root.Position.X, top - MONO_SNEAK_PLAT_H * 0.5, root.Position.Z)
end

local function monoSneakEnsurePlatform()
    monoSneakDestroyPlatform()
    local root = monoSneak.root
    if not root or not root.Parent then return end
    local plat = Instance.new("Part")
    plat.Name = "MonoSneakPlatform"
    plat.Anchored = true
    plat.CanCollide = true
    plat.CanTouch = false
    plat.CanQuery = false
    plat.CastShadow = false
    plat.Transparency = 1
    plat.Size = Vector3.new(4, MONO_SNEAK_PLAT_H, 4)
    plat.CFrame = monoSneakPlatformCFrame(root.Position.Y, root)
    plat.Parent = workspace
    monoSneak.platform = plat
end

local function monoSneakMovePlatform(y)
    local plat = monoSneak.platform
    if not plat or not plat.Parent then return end
    local root = monoSneak.root
    if not root or not root.Parent then return end
    pcall(function()
        local cf = monoSneakPlatformCFrame(y, root)
        if cf then plat.CFrame = cf end
    end)
end

function monoSneakPaint()
    if monoSneak.btn then
        pcall(function() monoSneak.btn.Text = monoSneak.on and "Return" or "Sneak" end)
    end
    if monoSneak.bindBtn then
        pcall(function()
            monoSneak.bindBtn.Text = monoCmdBindShort(monoSneak.key)
            monoSneak.bindBtn.TextColor3 = monoSneak.key and C.accent or C.textDim
        end)
    end
end

function monoSneakHardStop()
    if monoSneak.conn then
        pcall(function() monoSneak.conn:Disconnect() end)
        monoSneak.conn = nil
    end
    monoSneakDestroyPlatform()
    local root = monoSneak.root
    local cf = monoSneak.savedCF
    if root and root.Parent and cf and monoSneak.char == LocalPlayer.Character then
        pcall(function()
            root.Anchored = monoSneak.savedAnchored
            root.CFrame = cf
            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
        end)
    elseif root and root.Parent and monoSneak.anchorSaved then
        pcall(function() root.Anchored = monoSneak.savedAnchored end)
    end
    monoSneak.on = false
    monoSneak.busy = false
    monoSneak.t = 0
    monoSneak.savedCF = nil
    monoSneak.char = nil
    monoSneak.root = nil
    monoSneak.anchorSaved = false
    monoSneak.fromCF = nil
    monoSneak.toCF = nil
    if monoSneak.noclipOwned then
        monoSneak.noclipOwned = false
        pcall(function() if type(monoNcStop) == "function" then monoNcStop() end end)
    end
    monoSneakPaint()
end



function monoSneakReturn()
    local root = monoSneak.root
    local cf = monoSneak.savedCF
    if root and root.Parent and cf and monoSneak.char == LocalPlayer.Character then
        if monoSneakStartSlide(false) then
            return
        end
    end
    monoSneak.savedCF = nil
    monoSneakHardStop()
end

local function monoSneakEnsureDriver()
    if monoSneak.conn then return end
    monoSneak.conn = trackConn(RunService.Heartbeat:Connect(function(dt)
        if not monoSneak.busy and not monoSneak.on then
            monoSneakHardStop()
            return
        end
        local root = monoSneak.root
        if not root or not root.Parent then
            monoSneakHardStop()
            return
        end
        local char = LocalPlayer.Character
        if (char and char:FindFirstChild("HumanoidRootPart")) ~= root then
            monoSneakHardStop()
            return
        end
        if monoSneak.on or monoSneak.busy then
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            if hum then
                local st = hum:GetState()
                if st == Enum.HumanoidStateType.Freefall
                or st == Enum.HumanoidStateType.FallingDown then
                    pcall(function() hum:ChangeState(Enum.HumanoidStateType.Running) end)
                end
            end
        end
        if monoSneak.busy then
            local returning = not monoSneak.on
            if returning then
                local px, pz = root.Position.X, root.Position.Z
                local last = monoSneak.lastXZ
                local moved = false
                if last then
                    local dx, dz = px - last.X, pz - last.Z
                    moved = (dx * dx + dz * dz) > 1
                end
                if moved then
                    monoSneak.lastXZ = Vector3.new(px, 0, pz)
                    local newY = monoSneakFindReturnY(root, 100)
                    if newY and math.abs(newY - root.Position.Y) > 0.5 then
                        local e = math.min(monoSneakEase(monoSneak.t), 0.9)
                        if e < 0.9 then
                            monoSneak.fromY = (root.Position.Y - newY * e) / (1 - e)
                        end
                        monoSneak.toY = newY
                    end
                end
            end
            monoSneak.t = math.min(1, monoSneak.t + dt / monoSneak.duration)
            local e = monoSneakEase(monoSneak.t)
            local y = monoSneak.fromY + (monoSneak.toY - monoSneak.fromY) * e
            pcall(function()
                local v = root.AssemblyLinearVelocity
                local hx, hz = v.X, v.Z
                local rot = root.CFrame - root.CFrame.Position
                root.CFrame = CFrame.new(root.Position.X, y, root.Position.Z) * rot
                root.AssemblyLinearVelocity = Vector3.new(hx, 0, hz)
                root.AssemblyAngularVelocity = Vector3.zero
                monoSneakMovePlatform(y)
            end)
            if monoSneak.t >= 1 then
                monoSneak.busy = false
                pcall(function()
                    local v = root.AssemblyLinearVelocity
                    local hx, hz = v.X, v.Z
                    local rot = root.CFrame - root.CFrame.Position
                    root.CFrame = CFrame.new(root.Position.X, monoSneak.toY, root.Position.Z) * rot
                    root.AssemblyLinearVelocity = Vector3.new(hx, 0, hz)
                    root.AssemblyAngularVelocity = Vector3.zero
                    monoSneakMovePlatform(monoSneak.toY)
                end)
                if not monoSneak.on then
                    monoSneak.savedCF = root.CFrame
                    monoSneakHardStop()
                end
            end
        else
            local holdY = monoSneak.toY or root.Position.Y
            pcall(function()
                local v = root.AssemblyLinearVelocity
                local rot = root.CFrame - root.CFrame.Position
                root.CFrame = CFrame.new(root.Position.X, holdY, root.Position.Z) * rot
                root.AssemblyLinearVelocity = Vector3.new(v.X, 0, v.Z)
                root.AssemblyAngularVelocity = Vector3.zero
            end)
            monoSneakMovePlatform(holdY)
        end
    end))
end

function monoSneakStartSlide(toDown)
    local root = monoSneak.root
    if not root or not root.Parent then return false end
    monoSneakEnsurePlatform()
    monoSneak.lastXZ = Vector3.new(root.Position.X, 0, root.Position.Z)
    monoSneak.fromY = root.Position.Y
    if toDown then
        monoSneak.toY = -monoSneak.depth
    else
        monoSneak.toY = monoSneakFindReturnY(root)
            or (monoSneak.savedCF and monoSneak.savedCF.Position.Y)
            or monoSneak.fromY
    end
    monoSneak.t = 0
    monoSneak.busy = true
    pcall(function()
        local v = root.AssemblyLinearVelocity
        root.AssemblyLinearVelocity = Vector3.new(v.X, 0, v.Z)
        root.AssemblyAngularVelocity = Vector3.zero
    end)
    monoSneakEnsureDriver()
    return true
end

function monoSneakSet(on, silent)
    on = on and true or false
    if on == monoSneak.on then return monoSneak.on end

    if not on then
        if not monoSneak.root or not monoSneak.root.Parent or not monoSneak.savedCF then
            monoSneakHardStop()
            return false
        end
        monoSneak.on = false
        monoSneakReturn()
        monoSneakPaint()
        return false
    end

    if monoFoHold then pcall(monoFoStop) end
    local char = LocalPlayer.Character
    local root = char and char:FindFirstChild("HumanoidRootPart")
    if not root or not root.Parent then
        return false
    end
    monoSneak.char = char
    monoSneak.root = root
    if not monoSneak.savedCF then monoSneak.savedCF = root.CFrame end

    monoSneak.on = true
    if not monoSneakStartSlide(true) then
        monoSneakHardStop()
        return false
    end

    if not monoNcOn and type(monoNcStart) == "function" then
        pcall(monoNcStart)
        monoSneak.noclipOwned = true
    end

    monoSneakPaint()
    return true
end

function monoSneakStop()
    if monoSneak.on or monoSneak.busy then
        monoSneakSet(false, true)
    end
end

function monoSneakDepthSet(v)
    local n = math.clamp(math.floor(v + 0.5), monoSneakMin, monoSneakMax)
    monoSneak.depth = n
    local scale = (n - monoSneakMin) / (monoSneakMax - monoSneakMin)
    if monoSneak.fill then monoSneak.fill.Size = UDim2.new(scale, 0, 1, 0) end
    if monoSneak.knob then monoSneak.knob.Position = UDim2.new(scale, 0, 0.5, 0) end
    if monoSneak.valLabel then monoSneak.valLabel.Text = "-" .. tostring(n) end
    monoSneakSave()
    if monoSneak.on and monoSneak.root and monoSneak.root.Parent then
        if monoSneak.busy then
            monoSneak.toY = -n
        else
            monoSneakDestroyPlatform()
            monoSneakStartSlide(true)
        end
    end
end

function monoSneakPanelOpen()
    for i = #monoPanelCols, 1, -1 do
        if monoPanelCols[i].name == "sneak" then return true end
    end
    return false
end

function monoSneakKeySet(name)
    monoSneak.key = name
    if name then
        for k, v in pairs(monoCmdBinds) do
            if v == name then monoCmdBindSet(k, nil) end
        end
        if toggleUIKeyName == name then Window:ClearToggleKeyName() end
        if type(monoTermKeyName) == "function" and monoTermKeyName() == name then monoTermUnbindKey() end
        if type(monoFly) == "table" and monoFly.key == name then monoFlyKeySet(nil) end
        if type(monoFreeCam) == "table" and monoFreeCam.key == name then monoFreeCamKeySet(nil) end
    end
    monoSneakSave()
    if type(monoCmdRefresh) == "function" then monoCmdRefresh() end
    monoSneakKeyConnect()
    monoSneakPaint()
end

function monoSneakKeyDisconnect()
    if monoSneak.keyConn then
        pcall(function() monoSneak.keyConn:Disconnect() end)
        monoSneak.keyConn = nil
    end
end

function monoSneakKeyConnect()
    monoSneakKeyDisconnect()
    if not monoSneak.key then return end
    monoSneak.keyConn = UserInputService.InputBegan:Connect(function(input, gameProcessed)
        if gameProcessed or monoBindCapturing or monoBindSwallow then return end
        if input.UserInputType ~= Enum.UserInputType.Keyboard then return end
        local kn = input.KeyCode.Name
        if kn == "Unknown" or kn ~= monoSneak.key then return end
        monoSneakSet(not monoSneak.on)
    end)
end

function monoSneakDetach()
    if monoSneak.moveConn then pcall(function() monoSneak.moveConn:Disconnect() end) ;monoSneak.moveConn = nil end
    if monoSneak.endConn then pcall(function() monoSneak.endConn:Disconnect() end) ;monoSneak.endConn = nil end
    monoSneak.fill = nil
    monoSneak.knob = nil
    monoSneak.track = nil
    monoSneak.valLabel = nil
    monoSneak.dragging = false
end

function monoSneakBuildPanel()
    local entry = monoPanelOpen("sneak", "Sneak", 110, function()
        monoSneakKeyDisconnect()
        monoSneakDetach()
        monoSneakSet(false, true)
        monoPanelDrop("sneak")
        monoSneak.btn = nil
        monoSneak.bindBtn = nil
    end)
    if not entry then return end
    monoSneakSet(false, true)
    monoSneakDetach()
    monoSneakKeyConnect()

    local btnSec = monoPanelSection(entry.content, 1)
    local sneakBtn = monoPanelBtn(btnSec, monoSneak.on and "Return" or "Sneak", nil, 142,
        UDim2.new(0, 18, 0.5, -12))
    local bindBtn = monoPanelBtn(btnSec, monoCmdBindShort(monoSneak.key), nil, 52,
        UDim2.new(1, -58, 0.5, -12))
    monoSneak.btn = sneakBtn
    monoSneak.bindBtn = bindBtn
    monoSneakPaint()

    sneakBtn.MouseButton1Click:Connect(function() monoSneakSet(not monoSneak.on) end)

    bindBtn.MouseButton1Click:Connect(function()
        if monoBindCapturing then
            monoBindEndCapture()
            monoSneakKeySet(nil)
            monoSneakPaint()
            return
        end
        bindBtn.Text = "..."
        bindBtn.TextColor3 = C.accent
        monoBindCapture(function(input)
            monoSneakKeySet(input.KeyCode.Name)
            monoSneakPaint()
        end, function()
            monoSneakPaint()
        end)
    end)

    monoBuildPanelSlider(entry.content, {
        state = monoSneak, value = monoSneak.depth, label = "Depth",
        min = monoSneakMin, max = monoSneakMax, reset = monoSneakReset,
        format = function(n) return "-" .. tostring(n) end,
        onSet = monoSneakDepthSet,
    })
end

monoCmdOnDestroy("sneak", function()
    monoSneakKeyDisconnect()
    monoSneakDetach()
    monoSneakHardStop()
end)

local function monoSneakPanelToggle(auto)
    if not monoSneakPanelOpen() then
        monoSneakBuildPanel()
        return monoSneak.on
    end
    monoSneakSet(false, true)
    monoSneakKeyDisconnect()
    monoSneakDetach()
    monoPanelDrop("sneak")
    monoSneak.btn = nil
    monoSneak.bindBtn = nil
    return monoSneak.on
end

registerMonoCommand("sneak", function(auto)
    return monoSneakPanelToggle(auto)
end)

registerMonoCommand("trip", function()
    monoGlobalTripPlayer(LocalPlayer)
end)

function monoJkFind()
    local pack = LocalPlayer:FindFirstChildOfClass("Backpack")
    local t = pack and pack:FindFirstChild("Jerk Off")
    if t then return t end
    local char = LocalPlayer.Character
    return char and char:FindFirstChild("Jerk Off") or nil
end

monoJkGen = 0
monoJkActive = false
monoJkConn = nil

function monoJkStop()
    monoJkActive = false
    monoJkGen = monoJkGen + 1
    if monoJkConn then pcall(function() monoJkConn:Disconnect() end) ;monoJkConn = nil end
    local t = monoJkFind()
    if t then pcall(function() t:Destroy() end) end
end

function monoJkRespawn()
    local b = LocalPlayer:WaitForChild("Backpack", 10)
    local c = LocalPlayer.Character
    if c and not c:FindFirstChildOfClass("Humanoid") then c:WaitForChild("Humanoid", 10) end
    if not monoJkActive then return end
    local t = monoJkFind()
    if t then pcall(function() t:Destroy() end) end
    monoJkGen = monoJkGen + 1
    if b then monoJkStart() end
end

function monoJkStart()
    if monoJkFind() then return false end
    local char = LocalPlayer.Character
    if not char then return false end
    local humanoid = char:FindFirstChildOfClass("Humanoid")
    if not humanoid then
        humanoid = char:WaitForChild("Humanoid", 10)
        if not humanoid then return false end
    end
    local backpack = LocalPlayer:FindFirstChildOfClass("Backpack")
    if not backpack then
        backpack = LocalPlayer:WaitForChild("Backpack", 10)
        if not backpack then return false end
    end

    local tool = Instance.new("Tool")
    tool.Name = "Jerk Off"
    tool.ToolTip = "Equip to jerk"
    tool.RequiresHandle = false
    tool.Parent = backpack

    local jorkin = false
    local track = nil

    local function stopTomfoolery()
        jorkin = false
        if track then
            track:Stop()
            track = nil
        end
    end

    tool.Equipped:Connect(function() jorkin = true end)
    tool.Unequipped:Connect(stopTomfoolery)
    humanoid.Died:Connect(stopTomfoolery)

    monoJkGen = monoJkGen + 1
    local myGen = monoJkGen
    task.spawn(function()
        while task.wait() do
            if monoJkGen ~= myGen then return end
            if not jorkin then continue end
            local isR15 = humanoid.RigType == Enum.HumanoidRigType.R15
            if not track then
                local anim = Instance.new("Animation")
                anim.AnimationId = not isR15 and "rbxassetid://72042024" or "rbxassetid://698251653"
                track = humanoid:LoadAnimation(anim)
            end
            track:Play()
            track:AdjustSpeed(isR15 and 0.7 or 0.65)
            track.TimePosition = 0.6
            task.wait(0.1)
            while track and track.TimePosition < (not isR15 and 0.65 or 0.7) do task.wait(0.1) end
            if track then
                track:Stop()
                track = nil
            end
        end
    end)
    return true
end

monoCmdOnDestroy("jerk", monoJkStop)

registerMonoCommand("jerk", function()
    if monoJkActive then
        monoJkStop()
        return
    end
    if not monoJkStart() then return end
    monoJkActive = true
    if monoJkConn then pcall(function() monoJkConn:Disconnect() end) end
    monoJkConn = trackConn(LocalPlayer.CharacterAdded:Connect(function()
        task.spawn(monoJkRespawn)
    end))
end)

monoNcOn = false
monoNcParts = nil
monoNcSaved = {}
monoNcConn = nil
monoNcCharConn = nil
monoNcScanAt = 0

function monoNcRefresh()
    monoNcParts = {}
    local char = LocalPlayer.Character
    if not char then return end
    for _, d in ipairs(char:GetDescendants()) do
        if d:IsA("BasePart") then
            monoNcParts[#monoNcParts + 1] = d
            if monoNcSaved[d] == nil then monoNcSaved[d] = d.CanCollide end
        end
    end
end

function monoNcApply()
    local parts = monoNcParts
    for i = 1, #parts do
        parts[i].CanCollide = false
    end
end

function monoNcStop()
    monoNcOn = false
    if monoNcConn then pcall(function() monoNcConn:Disconnect() end) ;monoNcConn = nil end
    if monoNcCharConn then pcall(function() monoNcCharConn:Disconnect() end) ;monoNcCharConn = nil end
    for part, was in pairs(monoNcSaved) do
        pcall(function() part.CanCollide = was end)
    end
    monoNcSaved = {}
    monoNcParts = nil
end

function monoNcStart()
    if monoNcConn then return end
    monoNcOn = true
    monoNcSaved = {}
    monoNcParts = nil
    monoNcScanAt = 0
    monoNcRefresh()
    monoNcConn = trackConn(RunService.Stepped:Connect(function()
        if not monoNcOn then return end
        local now = os.clock()
        if not monoNcParts or now - monoNcScanAt >= 2 then
            monoNcScanAt = now
            monoNcRefresh()
        end
        if not monoNcParts then return end
        if not pcall(monoNcApply) then
            monoNcParts = nil
            monoNcRefresh()
        end
    end))
    monoNcCharConn = trackConn(LocalPlayer.CharacterAdded:Connect(function()
        if not monoNcOn then return end
        monoNcSaved = {}
        monoNcParts = nil
        monoNcScanAt = 0
    end))
end

monoCmdOnDestroy("noclip", monoNcStop)

registerMonoCommand("noclip", function(auto)
    if auto then monoNcOn = true else monoNcOn = not monoNcOn end
    if monoNcOn then monoNcStart() else monoNcStop() end
    if type(setData) == "table" then
        setData.noClip = monoNcOn
        if type(setSave) == "function" then setSave() end
    end
    notify("Monochrome", "Noclip " .. (monoNcOn and "enabled" or "disabled"), 3)
end)

monoBpOn = false
monoBpConn = nil
monoBpFolder = nil
monoBpTiles = {}
monoBpQueue = {}
monoBpCx = nil
monoBpCz = nil
monoBpBaseY = 0
monoBpBaseYSet = false
monoBpTileSize = 256
monoBpSink = 0.01
monoBpRadius = 8
monoBpPerFrame = 8
monoBpColorDefault = Color3.fromRGB(115, 231, 117)
monoBpColor = Color3.fromRGB(115, 231, 117)
monoBpDefaultColor = nil
monoBpMaterial = Enum.Material.Grass

monoBpTilePreset = {
    name = "baseplate",
    size = Vector3.new(monoBpTileSize, 16, monoBpTileSize),
    cframe = CFrame.identity,
}

function monoBpPresetFor(cx, cz)
    return monoBpTilePreset
end

function monoBpFolderGet()
    if monoBpFolder then
        local ok, live = pcall(function() return monoBpFolder.Parent end)
        if ok and live then return monoBpFolder end
    end
    local f = Instance.new("Folder")
    f.Name = "MonoBaseplateFolder"
    f.Parent = workspace
    monoBpFolder = f
    return f
end

function monoBpAdd(cx, cz)
    local row = monoBpTiles[cx]
    if row and typeof(row[cz]) == "Instance" then return end
    local preset = monoBpPresetFor(cx, cz)
    local part = Instance.new("Part")
    part.Name = preset.name
    part.Anchored = true
    part.Locked = true
    part.CanCollide = true
    part.Size = preset.size
    part.CFrame = preset.cframe + Vector3.new(
        cx * monoBpTileSize,
        monoBpBaseY - preset.size.Y * 0.5 - monoBpSink,
        cz * monoBpTileSize)
    part.Material = monoBpMaterial
    part.Color = monoBpColor
    part.TopSurface = Enum.SurfaceType.Smooth
    part.BottomSurface = Enum.SurfaceType.Smooth
    part.Parent = monoBpFolderGet()
    if not row then row = {}; monoBpTiles[cx] = row end
    row[cz] = part
end

function monoBpDrop(cx, cz)
    local row = monoBpTiles[cx]
    if not row then return end
    local part = row[cz]
    row[cz] = nil
    if typeof(part) == "Instance" then pcall(function() part:Destroy() end) end
end

function monoBpScan(root)
    local cx = math.floor(root.Position.X / monoBpTileSize)
    local cz = math.floor(root.Position.Z / monoBpTileSize)
    if cx == monoBpCx and cz == monoBpCz then return end
    monoBpCx, monoBpCz = cx, cz
    for x = cx - monoBpRadius, cx + monoBpRadius do
        for z = cz - monoBpRadius, cz + monoBpRadius do
            local row = monoBpTiles[x]
            if not row then row = {}; monoBpTiles[x] = row end
            if row[z] == nil then
                row[z] = true
                monoBpQueue[#monoBpQueue + 1] = x
                monoBpQueue[#monoBpQueue + 1] = z
            end
        end
    end
    for x, row in pairs(monoBpTiles) do
        if math.abs(x - cx) > monoBpRadius then
            for z in pairs(row) do monoBpDrop(x, z) end
            monoBpTiles[x] = nil
        else
            for z in pairs(row) do
                if math.abs(z - cz) > monoBpRadius then monoBpDrop(x, z) end
            end
        end
    end
end

function monoBpPump()
    local made = 0
    while made < monoBpPerFrame and #monoBpQueue >= 2 do
        local z = monoBpQueue[#monoBpQueue]
        monoBpQueue[#monoBpQueue] = nil
        local x = monoBpQueue[#monoBpQueue]
        monoBpQueue[#monoBpQueue] = nil
        monoBpAdd(x, z)
        made = made + 1
    end
    return made
end

function monoBpStop()
    monoBpOn = false
    monoBpGameRestoreColor()
    if monoBpConn then pcall(function() monoBpConn:Disconnect() end) ;monoBpConn = nil end
    if monoBpFolder then pcall(function() monoBpFolder:Destroy() end) ;monoBpFolder = nil end
    monoBpTiles = {}
    monoBpQueue = {}
    monoBpCx = nil
    monoBpCz = nil
    monoBpBaseYSet = false
end

function monoBpStart()
    if monoBpConn then return end
    monoBpOn = true
    monoBpGameApplyColor()
    monoBpConn = trackConn(RunService.Heartbeat:Connect(function()
        if not monoBpOn then return end
        local char = LocalPlayer.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        if not root or not root.Parent then return end
        if not monoBpBaseYSet then
            local hum = char:FindFirstChildOfClass("Humanoid")
            local params = RaycastParams.new()
            params.FilterDescendantsInstances = { char }
            params.FilterType = Enum.RaycastFilterType.Exclude
            local ok, hit = pcall(function()
                return workspace:Raycast(root.Position, Vector3.new(0, -50, 0), params)
            end)
            local n = nil
            if ok and hit then
                n = tonumber(hit.Position.Y)
            end
            if n and n == n then
                monoBpBaseY = n
                monoBpBaseYSet = true
            end
            if not monoBpBaseYSet then
                local hipH = hum and hum.HipHeight or 2.3
                monoBpBaseY = root.Position.Y - root.Size.Y * 0.5 - hipH
                monoBpBaseYSet = true
            end
        end
        monoBpScan(root)
        monoBpPump()
    end))
end

monoBpGameSavedColors = monoBpGameSavedColors or {}

monoBpGamePartCache = nil
monoBpGamePartCacheAt = 0

function monoBpGameParts()
    local now = tick()
    if monoBpGamePartCache and (now - monoBpGamePartCacheAt) < 5 then
        return monoBpGamePartCache
    end
    local out = {}
    pcall(function()
        for _, d in ipairs(workspace:GetDescendants()) do
            if not d:FindFirstAncestor("MonoBaseplateFolder") then
                local n = string.lower(tostring(d.Name or ""))
                local isFloor = (n:find("baseplate", 1, true) ~= nil
                    or n:find("base plate", 1, true) ~= nil
                    or n:find("platform", 1, true) ~= nil)
                if not isFloor then
                    local anc = d.Parent
                    while anc do
                        local an = string.lower(tostring(anc.Name or ""))
                        if an == "monobaseplatefolder" then break end
                        if an:find("baseplate", 1, true) or an:find("extra_room", 1, true) then
                            isFloor = true
                            break
                        end
                        anc = anc.Parent
                    end
                end
                if isFloor then
                    local okColor = pcall(function() return d.Color end)
                    if okColor then
                        out[#out + 1] = d
                    end
                end
            end
        end
    end)
    monoBpGamePartCache = out
    monoBpGamePartCacheAt = now
    return out
end

function monoBpCaptureDefault()
    if monoBpDefaultColor then return monoBpDefaultColor end
    for _, part in ipairs(monoBpGameParts()) do
        local ok, c = pcall(function() return part.Color end)
        if ok and c then
            monoBpDefaultColor = Color3.new(c.R, c.G, c.B)
            break
        end
    end
    return monoBpDefaultColor
end

function monoBpGameApplyColor()
    local parts = monoBpGameParts()
    monoBpCaptureDefault()
    for _, part in ipairs(parts) do
        if monoBpGameSavedColors[part] == nil then
            local ok, c = pcall(function() return part.Color end)
            if ok and c then monoBpGameSavedColors[part] = c end
        end
        pcall(function() part.Color = monoBpColor end)
    end
end

function monoBpGameRestoreColor()
    for part, c in pairs(monoBpGameSavedColors) do
        if part and part.Parent then
            pcall(function() part.Color = c end)
        end
    end
    table.clear(monoBpGameSavedColors)
    monoBpGamePartCache = nil
end

function monoBpApplyColor()
    for cx, row in pairs(monoBpTiles) do
        for cz, part in pairs(row) do
            if typeof(part) == "Instance" then
                pcall(function() part.Color = monoBpColor end)
            end
        end
    end
    if monoBpOn then
        monoBpGameApplyColor()
    end
end

local monoBpGameEnforceAcc = 0
trackConn(RunService.Heartbeat:Connect(function(dt)
    if not monoBpOn then return end
    monoBpGameEnforceAcc += dt
    if not next(monoBpGameSavedColors) then
        if monoBpGameEnforceAcc >= 2 then
            monoBpGameEnforceAcc = 0
            monoBpGameApplyColor()
        end
        return
    end
    if monoBpGameEnforceAcc < 0.1 then return end
    monoBpGameEnforceAcc = 0
    for part in pairs(monoBpGameSavedColors) do
        if part and part.Parent then
            local ok, c = pcall(function() return part.Color end)
            if ok and c ~= monoBpColor then
                pcall(function() part.Color = monoBpColor end)
            end
        end
    end
end))

function monoBpColorSave()
    if type(setData) ~= "table" then return end
    setData.infiniteBaseplateColor = {
        math.floor(monoBpColor.R * 255 + 0.5),
        math.floor(monoBpColor.G * 255 + 0.5),
        math.floor(monoBpColor.B * 255 + 0.5),
    }
    if type(setSave) == "function" then setSave() end
end

function monoBpLoadColor()
    local c = type(setData) == "table" and setData.infiniteBaseplateColor or nil
    if type(c) ~= "table" then return end
    monoBpColor = Color3.fromRGB(
        math.clamp(math.floor((tonumber(c[1]) or 115) + 0.5), 0, 255),
        math.clamp(math.floor((tonumber(c[2]) or 231) + 0.5), 0, 255),
        math.clamp(math.floor((tonumber(c[3]) or 117) + 0.5), 0, 255))
end

function monoBpColorSet(r, g, b)
    monoBpColor = Color3.fromRGB(
        math.clamp(math.floor((tonumber(r) or 0) + 0.5), 0, 255),
        math.clamp(math.floor((tonumber(g) or 0) + 0.5), 0, 255),
        math.clamp(math.floor((tonumber(b) or 0) + 0.5), 0, 255))
    monoBpApplyColor()
    monoBpColorSave()
    if type(monoBpPaint) == "function" then pcall(monoBpPaint) end
end

function monoBpSetEnabled(on, silent)
    on = on and true or false
    if on == monoBpOn then
        if type(monoBpPaint) == "function" then pcall(monoBpPaint) end
        return monoBpOn
    end
    if on then monoBpStart() else monoBpStop() end
    if type(setData) == "table" then
        setData.infiniteBaseplate = monoBpOn
        if type(setSave) == "function" then setSave() end
    end
    if not silent then
        notify("Monochrome", "Infinite baseplate " .. (monoBpOn and "enabled" or "disabled"), 3)
    end
    if type(monoBpPaint) == "function" then pcall(monoBpPaint) end
    return monoBpOn
end

function monoBpPanelOpen()
    for i = #monoPanelCols, 1, -1 do
        if monoPanelCols[i].name == "baseplate" then return true end
    end
    return false
end

function monoBpDetachColor()
    for _, rec in pairs(monoBpColorRows or {}) do
        rec.alive = false
    end
    monoBpColorRows = {}
    monoBpPaint = nil
end

function monoBpColorRow(parent, order, labelText, value, onSet, channel, fallbackDefault)
    local sec = monoPanelSection(parent, order)
    sec.Size = UDim2.new(1, 0, 0, 52)
    create("UIPadding", { PaddingTop = UDim.new(0, 5), PaddingBottom = UDim.new(0, 5) }, sec)
    create("UIListLayout", { Padding = UDim.new(0, 2), SortOrder = Enum.SortOrder.LayoutOrder }, sec)

    local labelRow = create("Frame", {
        Size = UDim2.new(1, 0, 0, 20), BackgroundTransparency = 1, LayoutOrder = 1,
    }, sec)
    create("UIPadding", { PaddingLeft = UDim.new(0, 12), PaddingRight = UDim.new(0, 12) }, labelRow)
    create("TextLabel", {
        Size = UDim2.new(1, -60, 1, 0), BackgroundTransparency = 1,
        Text = labelText, TextColor3 = C.text, TextSize = 12,
        Font = Enum.Font.Gotham, TextXAlignment = Enum.TextXAlignment.Left,
    }, labelRow)
    local valLabel = create("TextLabel", {
        Size = UDim2.new(0, 55, 1, 0), Position = UDim2.new(1, -55, 0, 0),
        BackgroundTransparency = 1, Text = tostring(value),
        TextColor3 = C.textMut, TextSize = 11, Font = Enum.Font.Gotham,
        TextXAlignment = Enum.TextXAlignment.Right,
    }, labelRow)

    local sliderRow = create("Frame", {
        Size = UDim2.new(1, 0, 0, 18), BackgroundTransparency = 1, LayoutOrder = 2,
    }, sec)
    create("UIPadding", { PaddingLeft = UDim.new(0, 12), PaddingRight = UDim.new(0, 12) }, sliderRow)
    local track = create("Frame", {
        Size = UDim2.new(1, 0, 0, 6), Position = UDim2.new(0, 0, 0.5, -3),
        BackgroundColor3 = C.input, BorderSizePixel = 0, Active = true,
    }, sliderRow)
    corner(track, 999)
    local scale = math.clamp(value / 255, 0, 1)
    local fill = create("Frame", {
        Size = UDim2.new(scale, 0, 1, 0), BackgroundColor3 = C.accent, BorderSizePixel = 0,
    }, track)
    corner(fill, 999)
    local knob = create("Frame", {
        Size = UDim2.new(0, 14, 0, 14), Position = UDim2.new(scale, 0, 0.5, 0),
        AnchorPoint = Vector2.new(0.5, 0.5), BackgroundColor3 = C.text,
        BorderSizePixel = 0, ZIndex = 3,
    }, track)
    corner(knob, 999)

    local rec = { fill = fill, knob = knob, label = valLabel, alive = true }
    local dragging = false
    local lastClick = 0
    local function setVal(v)
        if not rec.alive then return end
        v = math.clamp(math.floor(v + 0.5), 0, 255)
        local rel = v / 255
        fill.Size = UDim2.new(rel, 0, 1, 0)
        knob.Position = UDim2.new(rel, 0, 0.5, 0)
        valLabel.Text = tostring(v)
        onSet(v)
    end
    local function defaultVal()
        local c = monoBpDefaultColor or monoBpCaptureDefault()
        if c and channel then
            local ch = string.lower(channel)
            local comp = ch == "r" and c.R or (ch == "g" and c.G or c.B)
            return math.floor(comp * 255 + 0.5)
        end
        return fallbackDefault or value
    end
    local function slideTo(input)
        if not rec.alive then return end
        local w = math.max(1, track.AbsoluteSize.X)
        local rel = math.clamp((input.Position.X - track.AbsolutePosition.X) / w, 0, 1)
        setVal(rel * 255)
    end
    knob.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
        or input.UserInputType == Enum.UserInputType.Touch then
            dragging = true
        end
    end)
    track.InputBegan:Connect(function(input)
        if input.UserInputType ~= Enum.UserInputType.MouseButton1
        and input.UserInputType ~= Enum.UserInputType.Touch then return end
        local now = tick()
        if now - lastClick < 0.3 then
            lastClick = 0
            dragging = false
            setVal(defaultVal())
            return
        end
        lastClick = now
        dragging = true
        slideTo(input)
    end)
    trackConn(UserInputService.InputChanged:Connect(function(input)
        if not dragging or not rec.alive then return end
        if input.UserInputType == Enum.UserInputType.MouseMovement
        or input.UserInputType == Enum.UserInputType.Touch then
            slideTo(input)
        end
    end))
    trackConn(UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
        or input.UserInputType == Enum.UserInputType.Touch then
            dragging = false
        end
    end))
    return rec
end

function monoBpBuildPanel()
    monoBpCaptureDefault()
    local entry = monoPanelOpen("baseplate", "Infinite Baseplate", 226, function()
        monoBpSetEnabled(false, true)
        monoBpDetachColor()
        monoPanelDrop("baseplate")
    end)
    if not entry then return end

    local toggleSec = monoPanelSection(entry.content, 1)
    create("TextLabel", {
        Size = UDim2.new(1, -100, 1, 0), Position = UDim2.new(0, 12, 0, 0),
        BackgroundTransparency = 1, Text = "Infinite Baseplate", TextColor3 = C.text,
        TextSize = 12, Font = Enum.Font.Gotham, TextXAlignment = Enum.TextXAlignment.Left,
    }, toggleSec)
    local preview = create("Frame", {
        Size = UDim2.new(0, 28, 0, 18), Position = UDim2.new(1, -96, 0.5, -9),
        BackgroundColor3 = monoBpColor, BorderSizePixel = 0,
    }, toggleSec)
    corner(preview, 5); stroke(preview, C.borderSoft, 1, 0.4)

    local paint = monoPanelPill(toggleSec, monoBpOn)
    monoPanelPillHit(toggleSec, function() monoBpSetEnabled(not monoBpOn) end)

    local bpDefR = math.floor(monoBpColorDefault.R * 255 + 0.5)
    local bpDefG = math.floor(monoBpColorDefault.G * 255 + 0.5)
    local bpDefB = math.floor(monoBpColorDefault.B * 255 + 0.5)
    monoBpColorRows = {
        R = monoBpColorRow(entry.content, 2, "Red", math.floor(monoBpColor.R * 255 + 0.5),
            function(v) monoBpColorSet(v, monoBpColor.G * 255, monoBpColor.B * 255) end, "R", bpDefR),
        G = monoBpColorRow(entry.content, 3, "Green", math.floor(monoBpColor.G * 255 + 0.5),
            function(v) monoBpColorSet(monoBpColor.R * 255, v, monoBpColor.B * 255) end, "G", bpDefG),
        B = monoBpColorRow(entry.content, 4, "Blue", math.floor(monoBpColor.B * 255 + 0.5),
            function(v) monoBpColorSet(monoBpColor.R * 255, monoBpColor.G * 255, v) end, "B", bpDefB),
    }
    monoBpPaint = function()
        pcall(function()
            paint(monoBpOn)
            preview.BackgroundColor3 = monoBpColor
        end)
    end
    monoBpPaint()
end

monoCmdOnDestroy("infinitebaseplate", function()
    monoBpStop()
    monoBpDetachColor()
end)

registerMonoCommand("infinitebaseplate", function(auto)
    if auto then
        monoBpSetEnabled(true, true)
        return monoBpOn
    end
    if not monoBpPanelOpen() then
        monoBpSetEnabled(true)
        monoBpBuildPanel()
    else
        monoBpSetEnabled(false)
        monoPanelDrop("baseplate")
        monoBpDetachColor()
    end
    return monoBpOn
end)

monoAiVec = { text = "", size = 5, x = 0, y = 0, z = 0 }
monoAiVecSliderSetters = {}

local function monoAiVecPanelOpen()
    for _, e in ipairs(monoPanelCols or {}) do
        if e.name == "aitools" then return true end
    end
    return false
end

local function monoAiVecCustomTool()
    local char = LocalPlayer and LocalPlayer.Character
    local tool = char and char:FindFirstChild("custom tool")
    if tool and tool:IsA("Tool") then return tool end
    local bp = LocalPlayer and LocalPlayer:FindFirstChildOfClass("Backpack")
    local bpTool = bp and bp:FindFirstChild("custom tool")
    if bpTool and bpTool:IsA("Tool") then return bpTool end
    return nil
end
local function monoAiVecDisableToolClick()
    local tool = monoAiVecCustomTool()
    if not tool then return end
    pcall(function() tool.Enabled = false end)
    if type(getconnections) ~= "function" then return end
    pcall(function()
        local ok, conns = getconnections(tool.Activated)
        if ok and type(conns) == "table" then
            for _, conn in ipairs(conns) do
                pcall(function() conn:Disconnect() end)
            end
        end
    end)
end
local monoAiVecSliderRefreshing = false
local function monoAiVecSliderRefreshTool()
    if monoAiVecSliderRefreshing then return end
    local tool = monoAiVecCustomTool()
    if not tool or not tool:IsA("Tool") then return end
    local char = tool.Parent
    local humanoid = char and char:FindFirstChildOfClass("Humanoid")
    if not humanoid then return end
    monoAiVecSliderRefreshing = true
    task.spawn(function()
        pcall(function() humanoid:UnequipTools() end)
        task.wait(0.05)
        if tool.Parent then
            pcall(function() humanoid:EquipTool(tool) end)
        end
        monoAiVecSliderRefreshing = false
    end)
end
local function monoAiVecApplyGrip()
    local tool = monoAiVecCustomTool()
    if not tool then return end
    pcall(function()
        local grip = tool.Grip
        local rotation = grip - grip.Position
        tool.Grip = CFrame.new(monoAiVec.x, monoAiVec.y, monoAiVec.z) * rotation
    end)
end

local function monoAiVecSubmit()
    local word = tostring(monoAiVec.text or "")
    local size = monoAiVec.size
    local ok, err = pcall(function()
        local ev = game:GetService("ReplicatedStorage"):WaitForChild("event_generation", 5)
        if not ev or typeof(ev.FireServer) ~= "function" then error("event_generation unavailable") end
        ev:FireServer(word, Vector3.new(size, size, size))
    end)
    if ok then
        notify("Monochrome", "Fired " .. word .. " (size " .. tostring(size) .. ")", 2)
    else
        notify("Monochrome", "Ai Tools failed: " .. tostring(err), 3)
    end
    return ok
end

local function monoAiVecSlider(parent, order, labelText, key, min, max, onChanged)
    local sec = monoPanelSection(parent, order)
    sec.Size = UDim2.new(1, 0, 0, 52)
    create("UIPadding", {
        PaddingTop = UDim.new(0, 5), PaddingBottom = UDim.new(0, 5),
    }, sec)
    create("UIListLayout", {
        Padding = UDim.new(0, 2), SortOrder = Enum.SortOrder.LayoutOrder,
    }, sec)

    local labelRow = create("Frame", {
        Size = UDim2.new(1, 0, 0, 20), BackgroundTransparency = 1, LayoutOrder = 1,
    }, sec)
    create("UIPadding", {
        PaddingLeft = UDim.new(0, 12), PaddingRight = UDim.new(0, 12),
    }, labelRow)
    create("TextLabel", {
        Size = UDim2.new(1, -60, 1, 0), BackgroundTransparency = 1,
        Text = labelText, TextColor3 = C.text, TextSize = 12,
        Font = Enum.Font.Gotham, TextXAlignment = Enum.TextXAlignment.Left,
    }, labelRow)
    local valLabel = create("TextLabel", {
        Size = UDim2.new(0, 55, 1, 0), Position = UDim2.new(1, -55, 0, 0),
        BackgroundTransparency = 1, Text = tostring(monoAiVec[key]),
        TextColor3 = C.textMut, TextSize = 11, Font = Enum.Font.Gotham,
        TextXAlignment = Enum.TextXAlignment.Right,
    }, labelRow)

    local sliderRow = create("Frame", {
        Size = UDim2.new(1, 0, 0, 18), BackgroundTransparency = 1, LayoutOrder = 2,
    }, sec)
    create("UIPadding", {
        PaddingLeft = UDim.new(0, 12), PaddingRight = UDim.new(0, 12),
    }, sliderRow)
    local track = create("Frame", {
        Size = UDim2.new(1, 0, 0, 6), Position = UDim2.new(0, 0, 0.5, -3),
        BackgroundColor3 = C.input, BorderSizePixel = 0, Active = true,
    }, sliderRow)
    corner(track, 999)
    local rel = math.clamp((monoAiVec[key] - min) / (max - min), 0, 1)
    local fill = create("Frame", {
        Size = UDim2.new(rel, 0, 1, 0), BackgroundColor3 = C.accent, BorderSizePixel = 0,
    }, track)
    corner(fill, 999)
    local knob = create("Frame", {
        Size = UDim2.new(0, 14, 0, 14), Position = UDim2.new(rel, 0, 0.5, 0),
        AnchorPoint = Vector2.new(0.5, 0.5), BackgroundColor3 = C.text,
        BorderSizePixel = 0, ZIndex = 3,
    }, track)
    corner(knob, 999)

    local dragging = false
    local lastClick = 0
    local function apply(v)
        v = math.clamp(math.floor(v + 0.5), min, max)
        monoAiVec[key] = v
        local r = (v - min) / (max - min)
        fill.Size = UDim2.new(r, 0, 1, 0)
        knob.Position = UDim2.new(r, 0, 0.5, 0)
        valLabel.Text = tostring(v)
        if onChanged then onChanged(v) end
    end
    monoAiVecSliderSetters[key] = apply
    local function slideTo(input)
        local w = math.max(1, track.AbsoluteSize.X)
        local r = math.clamp((input.Position.X - track.AbsolutePosition.X) / w, 0, 1)
        apply(min + r * (max - min))
    end
    knob.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
        or input.UserInputType == Enum.UserInputType.Touch then
            dragging = true
        end
    end)
    track.InputBegan:Connect(function(input)
        if input.UserInputType ~= Enum.UserInputType.MouseButton1
        and input.UserInputType ~= Enum.UserInputType.Touch then return end
        local now = tick()
        if now - lastClick < 0.3 then
            lastClick = 0
            dragging = false
            apply(min < 0 and 0 or 5)
        else
            lastClick = now
            dragging = true
            slideTo(input)
        end
    end)
    trackConn(UserInputService.InputChanged:Connect(function(input)
        if not dragging then return end
        if input.UserInputType == Enum.UserInputType.MouseMovement
        or input.UserInputType == Enum.UserInputType.Touch then slideTo(input) end
    end))
    trackConn(UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
        or input.UserInputType == Enum.UserInputType.Touch then
            local wasDragging = dragging
            dragging = false
            if wasDragging and key ~= "size" then monoAiVecSliderRefreshTool() end
        end
    end))
end

function monoAiVecBuildPanel()
    monoAiVecSliderSetters = {}
    local box = nil
    local entry = monoPanelOpen("aitools", "Ai Tools", 324, function()
        monoAiVec.text = ""
        if box and box.Parent then pcall(function() box.Text = "" end) end
        monoPanelDrop("aitools")
    end)
