        Size = UDim2.new(1, -16, 0, 26), Position = UDim2.new(0, 8, 0, 5),
        BackgroundColor3 = C.surface, BackgroundTransparency = 0.4, BorderSizePixel = 0,
        Text = monoAiVec.text, PlaceholderText = "what to generate", PlaceholderColor3 = C.textMut,
        TextColor3 = C.text, TextSize = 11, Font = Enum.Font.Gotham,
