local monoAiVecStatusAt = 0
trackConn(RunService.Heartbeat:Connect(function()
    local now = tick()
    if now - monoAiVecStatusAt < 0.2 then return end
    monoAiVecStatusAt = now
    pcall(monoAiVecApplyGrip)
    pcall(monoAiVecDisableToolClick)
end))

local monoAiVecHooked = false
local function monoAiVecUpvalue(fn, index)
    if type(getupvalue) == "function" then
        local ok, name, value = pcall(getupvalue, fn, index)
        if ok then return name, value end
    end
    if type(debug) == "table" and type(debug.getupvalue) == "function" then
        return debug.getupvalue(fn, index)
    end
    return nil, nil
end
local function monoAiVecSetUpvalue(fn, index, value)
    if type(setupvalue) == "function" then return setupvalue(fn, index, value) end
    if type(debug) == "table" and type(debug.setupvalue) == "function" then
        return debug.setupvalue(fn, index, value)
    end
    return nil
end
local function monoAiVecResetGenerated(fn)
    pcall(function()
        for index = 1, 16 do
            local name, value = monoAiVecUpvalue(fn, index)
            if not name then break end
            if type(value) == "boolean" then
                monoAiVecSetUpvalue(fn, index, false)
            elseif type(value) == "table" then
                for key, item in pairs(value) do
                    if type(typeof) == "function" and typeof(item) == "Instance"
                        and item.Parent == nil then
                        value[key] = nil
                        pcall(function() item:Destroy() end)
                    end
                end
            end
        end
    end)
end
local function monoAiVecFindGenerateFn()
    if type(getconnections) ~= "function" then return nil end
    local roots = {}
    local pg = LocalPlayer and LocalPlayer:FindFirstChildOfClass("PlayerGui")
    if pg then roots[#roots + 1] = pg end
    roots[#roots + 1] = game:GetService("ReplicatedStorage")
    for _, root in ipairs(roots) do
        local objects = { root }
        for _, descendant in ipairs(root:GetDescendants()) do
            objects[#objects + 1] = descendant
        end
        for _, object in ipairs(objects) do
            local signal = nil
            if object:IsA("BindableEvent") then signal = object.Event
            elseif object:IsA("RemoteEvent") then signal = object.OnClientEvent
            elseif object:IsA("BindableFunction") then signal = object.OnInvoke end
            if signal then
                local ok, conns = pcall(getconnections, signal)
                if ok and type(conns) == "table" then
                    for _, conn in ipairs(conns) do
                        local fn = conn.Function or conn.fn
                        local okInfo, info = pcall(function()
                            if type(getinfo) == "function" then return getinfo(fn) end
                            if type(debug) == "table" and type(debug.getinfo) == "function" then
                                return debug.getinfo(fn)
                            end
                            return nil
                        end)
                        if okInfo and type(info) == "table" and type(info.Source) == "string"
                            and info.Source:find("hub.bg.generation.generate", 1, true) then
                            return fn
                        end
                    end
                end
            end
        end
    end
    return nil
end
task.spawn(function()
    local fn = nil
    for _ = 1, 40 do
        fn = monoAiVecFindGenerateFn()
        if fn then break end
        task.wait(0.5)
    end
    if not fn or monoAiVecHooked or type(hookfunction) ~= "function" then return end
    local original = nil
    local ok = pcall(function()
        original = hookfunction(fn, function(...)
            local packed = table.pack(...)
            local results = nil
            pcall(function()
                results = table.pack(original(table.unpack(packed, 1, packed.n)))
            end)
            pcall(monoAiVecResetGenerated, original or fn)
            if results then return table.unpack(results, 1, results.n) end
            return nil
        end)
    end)
    if ok and original then monoAiVecHooked = true end
end)

monoIzOn = false
monoIzConn = nil
monoIzDefault = nil

pcall(function()
    local v = tonumber(LocalPlayer.CameraMaxZoomDistance)
    if v and v == v and v < math.huge then monoIzDefault = v end
end)

function monoIzStop()
    monoIzOn = false
    if monoIzConn then pcall(function() monoIzConn:Disconnect() end) ;monoIzConn = nil end
    local d = monoIzDefault or 128
    pcall(function() LocalPlayer.CameraMaxZoomDistance = d end)
end

function monoIzStart()
    if monoIzConn then return end
    monoIzOn = true
    pcall(function() LocalPlayer.CameraMaxZoomDistance = math.huge end)
    monoIzConn = trackConn(RunService.Heartbeat:Connect(function()
        if not monoIzOn then return end
        local ok, v = pcall(function() return LocalPlayer.CameraMaxZoomDistance end)
        if ok and v ~= math.huge then
            pcall(function() LocalPlayer.CameraMaxZoomDistance = math.huge end)
        end
    end))
end

monoCmdOnDestroy("infinitezoom", monoIzStop)

registerMonoCommand("infinitezoom", function(auto)
    if auto then monoIzOn = true else monoIzOn = not monoIzOn end
    if monoIzOn then monoIzStart() else monoIzStop() end
    if type(setData) == "table" then
        setData.infiniteZoom = monoIzOn
        if type(setSave) == "function" then setSave() end
    end
    notify("Monochrome", "Infinite zoom " .. (monoIzOn and "enabled" or "disabled"), 3)
end)

monoPanelW = 239
monoPanelGap = 10
monoPanelPadX = 8
monoPanelPadY = 0
monoPanelSlide = 0.2
monoPanelHeadH = 36
monoPanelSecH = 36
monoPanelBtnW = 62
monoPanelBtnH = 24
monoPanelCols = {}
monoPanelAnchor = nil
monoPanelLive = {}
monoPanelOnClose = {}
monoPanelMin = {}
pcall(function()
    if readfile and isfile and isfile("Monochrome/panelMin.json") then
        local d = HttpService:JSONDecode(readfile("Monochrome/panelMin.json"))
        if type(d) == "table" then
            for k, v in pairs(d) do
                if v == true then monoPanelMin[tostring(k)] = true end
            end
        end
    end
end)

function monoPanelBgSync(entry)
    if type(entry) ~= "table" or not entry.bg then return nil end
    local on = (monoBgImage
        and typeof(monoBgImage) == "Instance"
        and monoBgImage.Parent ~= nil
        and monoBgImage.Visible == true
        and monoBgImage.Image ~= "") and true or false
    entry.bg.Visible = on
    entry.bg.Image = on and monoBgImage.Image or ""
    entry.bg.ImageTransparency = on and monoCustomBgTransparency() or 0
    local dim = setData and setData.bgDim or 55
    if on then
        entry.bgShade.BackgroundTransparency = dim / 100
        entry.frame.BackgroundTransparency = 1
        return 1
    end
    local target = monoUiPanelTransparency()
    tween(entry.bgShade, { BackgroundTransparency = 1 }, 0.25)
    tween(entry.frame, { BackgroundTransparency = target }, 0.25)
    return target
end

function monoPanelBgSyncAll()
    for _, entry in pairs(monoPanelLive) do monoPanelBgSync(entry) end
end

function monoPanelColH()
    if monoPanelAnchor then return monoPanelAnchor.AbsoluteSize.Y end
    if Window and Window._winH then return Window._winH end
    return 370
end

function monoPanelLayout(animate)
    local h = monoPanelColH()
    local top = h - monoPanelPadY
    local col = 0
    local half = monoPanelSlide * 0.5
    for i = 1, #monoPanelCols do
        local p = monoPanelCols[i]
        if p.free or p.dragging then continue end
        if top - p.h < 0 then
            col = col + 1
            top = h - monoPanelPadY
        end
        local xOff = monoPanelPadX + col * (monoPanelW + monoPanelGap)
        local yPos = top - p.h
        local target = UDim2.new(1, xOff, 0, yPos)
        p.layGen = (p.layGen or 0) + 1
        local gen = p.layGen
        if animate then
            local cx = p.frame.Position.X.Offset
            local cy = p.frame.Position.Y.Offset
            if cx ~= xOff and cy ~= yPos then
                local mid = UDim2.new(1, xOff, 0, cy)
                if xOff < cx then mid = UDim2.new(1, cx, 0, yPos) end
                tween(p.frame, { Position = mid }, half,
                    Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
                task.delay(half, function()
                    if p.layGen ~= gen then return end
                    if not p.frame or not p.frame.Parent then return end
                    tween(p.frame, { Position = target }, half,
                        Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
                end)
            else
                tween(p.frame, { Position = target }, monoPanelSlide,
                    Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
            end
        else
            p.frame.Position = target
        end
        top = top - p.h - monoPanelGap
    end
end

function monoPanelRemove(name, instant)
    for i = #monoPanelCols, 1, -1 do
        if monoPanelCols[i].name == name then
            local p = table.remove(monoPanelCols, i)
            if p.frame then
                monoPanelLive[p.frame] = nil
                local f = p.frame
                if instant then
                    pcall(function() f:Destroy() end)
                else
                    tween(f, { BackgroundTransparency = 1 }, 0.18)
                    if p.fade then tween(p.fade, { GroupTransparency = 1 }, 0.18) end
                    if p.border then tween(p.border, { Transparency = 1 }, 0.18) end
                    task.delay(0.18, function() pcall(function() f:Destroy() end) end)
                end
            end
        end
    end
    monoPanelLayout()
end

function monoPanelMinSave()
    local t = {}
    for k, v in pairs(monoPanelMin) do
        if v == true then t[k] = true end
    end
    if type(setData) == "table" then
        setData.panelMin = t
        if type(setSave) == "function" then setSave() end
    end
    pcall(function()
        if writefile then
            ensureFolder("Monochrome")
            writefile("Monochrome/panelMin.json", HttpService:JSONEncode(t))
        end
    end)
end

function monoPanelDrop(name)
    monoPanelRemove(name, false)
    monoPanelMinSave()
end

function monoPanelClose(name)
    local fn = monoPanelOnClose[name]
    if fn then pcall(fn) end
end

function monoPanelIcon(parent, text, xoff)
    local b = create("TextButton", {
        Size = UDim2.new(0, 24, 0, 24), Position = UDim2.new(1, xoff, 0.5, -12),
        BackgroundColor3 = C.surface, BackgroundTransparency = 0.4, BorderSizePixel = 0,
        Text = text, TextColor3 = C.textMut, TextSize = 13, Font = Enum.Font.GothamBold,
        AutoButtonColor = false,
    }, parent)
    corner(b, 7); stroke(b, C.borderSoft, 1, 0.6)
    b.MouseEnter:Connect(function()
        tween(b, { BackgroundColor3 = C.surfaceHi, BackgroundTransparency = 0.15 }, 0.15)
        b.TextColor3 = C.accent
    end)
    b.MouseLeave:Connect(function()
        tween(b, { BackgroundColor3 = C.surface, BackgroundTransparency = 0.4 }, 0.15)
        b.TextColor3 = C.textMut
    end)
    return b
end

function monoPanelHead(entry, parent, titleText, onClose)
    local row = create("Frame", {
        Size = UDim2.new(1, 0, 0, monoPanelHeadH),
        BackgroundTransparency = 1,
    }, parent)
    create("TextLabel", {
        Size = UDim2.new(1, -80, 1, 0), Position = UDim2.new(0, 14, 0, 0),
        BackgroundTransparency = 1, Text = titleText or "",
        TextColor3 = C.text, TextSize = 13, Font = Enum.Font.GothamBold,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextTruncate = Enum.TextTruncate.AtEnd,
    }, row)
    local minBtn = monoPanelIcon(row, "-", -52)
    local closeBtn = monoPanelIcon(row, "X", -26)
    entry.minBtn = minBtn
    for _, btn in ipairs({ minBtn, closeBtn }) do
        btn.InputBegan:Connect(function() entry._btnPressed = true end)
        btn.InputEnded:Connect(function() entry._btnPressed = false end)
    end
    minBtn.MouseButton1Click:Connect(function() monoPanelMinimize(entry) end)
    closeBtn.MouseButton1Click:Connect(function()
        if onClose then pcall(onClose) end
    end)
    return row
end

function monoPanelMinimize(entry)
    entry.min = not entry.min
    monoPanelMin[entry.name] = entry.min
    monoPanelMinSave()
    local oldH = entry.h
    local targetH = entry.min and monoPanelHeadH or entry.fullH
    local delta = targetH - oldH
    if entry.minBtn then entry.minBtn.Text = entry.min and "+" or "-" end

    if entry.min then
        if entry.contentFade then
            tween(entry.contentFade, { GroupTransparency = 1 }, monoPanelSlide * 0.75)
        end
        task.delay(monoPanelSlide, function()
            if entry.min and entry.content then entry.content.Visible = false end
        end)
    else
        entry.content.Visible = true
        if entry.contentFade then
            tween(entry.contentFade, { GroupTransparency = 0 }, monoPanelSlide)
        end
    end

    entry.h = targetH
    tween(entry.frame, { Size = UDim2.new(0, monoPanelW, 0, targetH) }, monoPanelSlide,
        Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
    local baseY = entry.frame.Position.Y.Offset
    local baseX = entry.frame.Position.X.Offset
    local entryW = entry.frame.AbsoluteSize.X
    local oldBottom = baseY + oldH
    local newBottom = baseY + targetH
    local _gap = monoPanelGap
    local candidates = {}
    for _, other in ipairs(monoPanelCols) do
        if other == entry then continue end
        local of = other.frame
        if not of or not of.Parent then continue end
        local ox, ow = of.Position.X.Offset, of.AbsoluteSize.X
        local xOverlap = baseX < ox + ow and baseX + entryW > ox
        local otherY = other.targetY or of.Position.Y.Offset
        if xOverlap and otherY >= oldBottom - 2 then
            table.insert(candidates, other)
        end
    end
    table.sort(candidates, function(a, b)
        return (a.targetY or a.frame.Position.Y.Offset) < (b.targetY or b.frame.Position.Y.Offset)
    end)
    if delta > 0 then
        local pushed = {}
        local cursor = newBottom
        for _, other in ipairs(candidates) do
            local of = other.frame
            local otherY = other.targetY or of.Position.Y.Offset
            if otherY < cursor then
                other._prevTargetY = otherY
                other.targetY = cursor
                tween(of, { Position = UDim2.new(0, of.Position.X.Offset, 0, cursor) }, monoPanelSlide,
                    Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
                monoPanelPosSave(other.name, UDim2.new(0, of.Position.X.Offset, 0, cursor))
                table.insert(pushed, other)
                cursor = cursor + other.h
            else
                cursor = math.max(cursor, otherY + other.h)
            end
        end
        entry._pushed = pushed
    else
        for _, other in ipairs(candidates) do
            local of = other.frame
            if not of or not of.Parent then continue end
            local otherY = other.targetY or of.Position.Y.Offset
            local newTarget = otherY + delta
            other.targetY = newTarget
            other._prevTargetY = nil
            tween(of, { Position = UDim2.new(0, of.Position.X.Offset, 0, newTarget) }, monoPanelSlide,
                Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
            monoPanelPosSave(other.name, UDim2.new(0, of.Position.X.Offset, 0, newTarget))
        end
        entry._pushed = nil
    end
end

function monoPanelSection(parent, order)
    local sec = create("Frame", {
        Size = UDim2.new(1, 0, 0, monoPanelSecH),
        BackgroundColor3 = C.card, BackgroundTransparency = 0.4,
        BorderSizePixel = 0, LayoutOrder = order,
    }, parent)
    corner(sec, 10)
    return sec
end

function monoPanelPill(parent, on, onChange)
    local pill = create("Frame", {
        Size = UDim2.new(0, 38, 0, 20), Position = UDim2.new(1, -52, 0.5, -10),
        BackgroundColor3 = on and C.accent or C.input, BorderSizePixel = 0,
    }, parent)
    corner(pill, 999); stroke(pill, C.borderSoft, 1, 0.55)
    local track = pill
    local knob = create("Frame", {
        Size = UDim2.new(0, 14, 0, 14),
        Position = on and UDim2.new(1, -17, 0.5, -7) or UDim2.new(0, 3, 0.5, -7),
        BackgroundColor3 = on and C.bg or C.text, BorderSizePixel = 0,
    }, track)
    corner(knob, 999)
    local cur = on and true or false
    local function paint(v)
        tween(track, { BackgroundColor3 = v and C.accent or C.input }, 0.2)
        tween(knob, {
            BackgroundColor3 = v and C.bg or C.text,
            Position = v and UDim2.new(1, -17, 0.5, -7) or UDim2.new(0, 3, 0.5, -7),
        }, 0.22)
    end
    local setter = function(v)
        cur = v and true or false
        paint(cur)
    end
    return setter
end

function monoPanelPillHit(parent, onChange)
    local hit = create("TextButton", {
        Size = UDim2.new(0, 52, 1, 0), Position = UDim2.new(1, -56, 0, 0),
        BackgroundTransparency = 1, Text = "", AutoButtonColor = false,
    }, parent)
    hit.MouseButton1Click:Connect(function()
        if onChange then onChange() end
    end)
    return hit
end

function monoPanelPress(b)
    tween(b, { BackgroundTransparency = 0 }, 0.08)
    task.delay(0.1, function() tween(b, { BackgroundTransparency = 0.4 }, 0.15) end)
end

function monoPanelBtn(parent, text, order, w, pos)
    local props = {
        BackgroundColor3 = C.surface, BackgroundTransparency = 0.4, BorderSizePixel = 0,
        Text = text, TextColor3 = C.text, TextSize = 11,
        Font = Enum.Font.GothamBold, AutoButtonColor = false,
    }
    if w then
        props.Size = UDim2.new(0, w, 0, monoPanelBtnH)
        props.Position = pos
    else
        props.Size = UDim2.new(0, monoPanelBtnW, 0, monoPanelBtnH)
        props.LayoutOrder = order
    end
    local b = create("TextButton", props, parent)
    corner(b, 6); stroke(b, C.borderSoft, 1, 0.55)
    b.MouseEnter:Connect(function()
        tween(b, { BackgroundTransparency = 0.15 }, 0.15)
    end)
    b.MouseLeave:Connect(function()
        tween(b, { BackgroundTransparency = 0.4 }, 0.15)
    end)
    b.MouseButton1Down:Connect(function() monoPanelPress(b) end)
    return b
end

function _monoPanelEnsure()
    if not monoPanelHost and Window and Window._win then
        local found = nil
        for _, c in ipairs(Window._win:GetChildren()) do
            if c.Name == "MonoPanels" then found = c end
        end
        monoPanelHost = found or create("Frame", {
            Name = "MonoPanels", Size = UDim2.new(0, 0, 1, 0),
            Position = UDim2.new(1, monoPanelPadX, 0, 0),
            BackgroundTransparency = 1, BorderSizePixel = 0,
        }, Window._win)
        for _, c in ipairs(monoPanelHost:GetChildren()) do
            pcall(function() c:Destroy() end)
        end
        monoPanelAnchor = Window._win
        trackConn(monoPanelAnchor:GetPropertyChangedSignal("AbsoluteSize"):Connect(monoPanelLayout))
    end
    if monoPanelHost then monoPanelHost.Visible = false end
    return monoPanelHost
end

function monoPanelReveal(host, entry, bgTarget)
    while not monoLoadDone do task.wait(0.1) end
    RunService.RenderStepped:Wait()
    if not host or not host.Parent then return end
    if host:IsA("ScreenGui") then
        host.Enabled = monoPanelVisible and true or false
    else
        host.Visible = monoPanelVisible and true or false
    end
    local frame = entry.frame
    if not frame or not frame.Parent then return end
    frame.BackgroundTransparency = 1
    if entry.fade then entry.fade.GroupTransparency = 1 end
    task.wait(0.05)
    if entry.fade then tween(entry.fade, { GroupTransparency = 0 }, 0.5) end
    if entry.border then
        entry.border.Transparency = 1
        tween(entry.border, { Transparency = 0.2 }, 0.5)
    end
    if bgTarget and bgTarget < 1 then
        tween(frame, { BackgroundTransparency = bgTarget }, 0.5)
    else
        tween(frame, { BackgroundTransparency = monoUiPanelTransparency() }, 0.5)
    end
end

monoPanelExtGui = nil
task.spawn(function()
    while not monoLoadDone do task.wait(0.1) end
    if monoPanelExtGui then pcall(function() monoPanelExtGui.Enabled = true end) end
end)
function monoPanelExternalHost()
    if not monoPanelExtGui then
        local gui = create("ScreenGui", {
            Name = "MonochromePanelsExt", ResetOnSpawn = false,
            IgnoreGuiInset = true, ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
        })
        monoGuiParent(gui)
        applyDisplayOrder(gui, MONO_ORDER.UI, MONO_ORDER_OLD.UI)
        gui.Enabled = monoLoadDone and true or false
        monoPanelExtGui = gui
    end
    if monoPanelExtGui and not monoLoadDone then
        monoPanelExtGui.Enabled = false
    end
    return monoPanelExtGui
end

monoPanelPosFile = "Monochrome/panelPositions.json"
monoPanelPositions = monoPanelPositions or {}
pcall(function()
    if readfile and isfile and isfile(monoPanelPosFile) then
        local d = HttpService:JSONDecode(readfile(monoPanelPosFile))
        if type(d) == "table" then monoPanelPositions = d end
    end
end)

function monoPanelPosSave(name, pos)
    monoPanelPositions[name] = { X = pos.X.Offset, Y = pos.Y.Offset }
    pcall(function()
        if writefile then
            ensureFolder("Monochrome")
            writefile(monoPanelPosFile, HttpService:JSONEncode(monoPanelPositions))
        end
    end)
end

function monoPanelPosLoad(name)
    local d = monoPanelPositions[name]
    if type(d) == "table" then
        return UDim2.new(0, tonumber(d.X) or 0, 0, tonumber(d.Y) or 0)
    end
    return nil
end

function monoPanelOpen(name, titleText, contentH, onClose)
    local host = monoPanelExternalHost()
    if not host then return nil end
    monoPanelRemove(name, true)
    local min = monoPanelMin[name] and true or false
    local fullH = monoPanelHeadH + (contentH or 0)
    local h = min and monoPanelHeadH or fullH
    local frame = create("Frame", {
        Name = "MonoPanel_" .. name,
        Size = UDim2.new(0, monoPanelW, 0, h),
        BackgroundColor3 = C.bg, BackgroundTransparency = monoUiPanelTransparency(),
        BorderSizePixel = 0,
    }, host)
    corner(frame, 14)
    local border = stroke(frame, C.border, 1, 1)
    local fade = create("CanvasGroup", {
        Name = "Fade", Size = UDim2.new(1, 0, 1, 0),
        BackgroundTransparency = 1, BorderSizePixel = 0, GroupTransparency = 1,
    }, frame)
    local bgClip = create("Frame", {
        Name = "BgClip", Size = UDim2.new(1, 0, 1, 0),
        BackgroundTransparency = 1, BorderSizePixel = 0, ClipsDescendants = true,
    }, fade)
    corner(bgClip, 14)
    local bgBack = create("ImageLabel", {
        Name = "Bg", Size = UDim2.new(1, 0, 1, 0),
        BackgroundTransparency = 1, BorderSizePixel = 0,
        Image = "", ScaleType = Enum.ScaleType.Crop, Visible = false,
    }, bgClip)
    corner(bgBack, 14)
    local bgShade = create("Frame", {
        Name = "BgShade", Size = UDim2.new(1, 0, 1, 0),
        BackgroundColor3 = C.bg, BackgroundTransparency = 1, BorderSizePixel = 0,
    }, bgClip)
    corner(bgShade, 14)
    local contentFade = create("CanvasGroup", {
        Name = "ContentFade", Size = UDim2.new(1, 0, 1, 0),
        BackgroundTransparency = 1, BorderSizePixel = 0, GroupTransparency = min and 1 or 0,
    }, fade)
    local content = create("Frame", {
        Size = UDim2.new(1, 0, 1, -monoPanelHeadH), Position = UDim2.new(0, 0, 0, monoPanelHeadH),
        BackgroundTransparency = 1, ClipsDescendants = true, Visible = not min,
    }, contentFade)
    create("UIPadding", {
        PaddingTop = UDim.new(0, 4), PaddingBottom = UDim.new(0, 12),
        PaddingLeft = UDim.new(0, 8), PaddingRight = UDim.new(0, 8),
    }, content)
    create("UIListLayout", {
        Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder,
    }, content)
    local entry = {
        name = name, frame = frame, fade = fade, contentFade = contentFade, border = border, content = content,
        h = h, fullH = fullH, min = min, bg = bgBack, bgShade = bgShade, layGen = 0, free = true, dragging = false,
        minBtn = nil, _btnPressed = nil, headRow = nil, targetY = nil, _dragConns = nil, _prevTargetY = nil,
    }
    entry.headRow = monoPanelHead(entry, fade, titleText, function() monoPanelClose(name) end)
    if min and entry.minBtn then entry.minBtn.Text = "+" end
    if onClose then monoPanelOnClose[name] = onClose end
    table.insert(monoPanelCols, entry)
    monoPanelLive[frame] = entry
    local bgTarget = monoPanelBgSync(entry) or entry.frame.BackgroundTransparency
    frame.BackgroundTransparency = 1
    local savedPos = monoPanelPosLoad(name)
    if savedPos then
        frame.Position = savedPos
    else
        local cascade = (#monoPanelCols) * 30
        frame.Position = UDim2.new(0, 40 + cascade, 0, 40 + cascade)
    end
    monoPanelLayout()
    entry.targetY = frame.Position.Y.Offset
    task.spawn(monoPanelReveal, host, entry, bgTarget)

    entry.free = true
    entry.dragging = false
    local dragStart, startPos = nil, nil
    local lastInputPos = nil
    local curX, curY = nil, nil
    local function beginDrag(input)
        if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then return end
        if entry._btnPressed then return end
        entry.dragging = true
        entry._prevTargetY = nil
        if frame.Parent ~= monoPanelExternalHost() then
            local absPos = frame.AbsolutePosition
            frame.Parent = monoPanelExternalHost()
            frame.Position = UDim2.new(0, absPos.X, 0, absPos.Y)
        end
        dragStart = input.Position
        startPos = frame.Position
        curX = frame.Position.X.Offset
        curY = frame.Position.Y.Offset
        lastInputPos = input.Position
        entry.free = true
        monoPanelLayout()
    end
    if entry.headRow then
        entry.headRow.InputBegan:Connect(beginDrag)
    end
    local changedConn = UserInputService.InputChanged:Connect(function(input)
        if not entry.dragging then return end
        if input.UserInputType ~= Enum.UserInputType.MouseMovement and input.UserInputType ~= Enum.UserInputType.Touch then return end
        if not dragStart or not startPos then return end
        local _delta = input.Position - dragStart
        local cam = workspace.CurrentCamera
        local vs = cam and cam.ViewportSize or Vector2.new(1920, 1080)
        local w = monoPanelW
        local h = entry.h
        local dx = input.Position.X - lastInputPos.X
        local dy = input.Position.Y - lastInputPos.Y
        lastInputPos = input.Position
        local x = curX
        local y = curY
        local steps = math.max(1, math.ceil(math.max(math.abs(dx), math.abs(dy)) / 8))
        for _ = 1, steps do
            x = x + dx / steps
            y = y + dy / steps
            for _ = 1, 8 do
                local moved = false
                for _, other in ipairs(monoPanelCols) do
                    if other == entry then continue end
                    local of = other.frame
                    if not of or not of.Parent then continue end
                    local ox, oy = of.Position.X.Offset, of.Position.Y.Offset
                    local ow, oh = of.AbsoluteSize.X, of.AbsoluteSize.Y
                    if ow < 1 then ow = monoPanelW end
                    if oh < 1 then oh = other.h end
                    if x < ox + ow and x + w > ox and y < oy + oh and y + h > oy then
                        local overlapX = math.min(x + w, ox + ow) - math.max(x, ox)
                        local overlapY = math.min(y + h, oy + oh) - math.max(y, oy)
                        if overlapX < overlapY then
                            if x + w * 0.5 < ox + ow * 0.5 then
                                x = ox - w
                            else
                                x = ox + ow
                            end
                        else
                            if y + h * 0.5 < oy + oh * 0.5 then
                                y = oy - h
                            else
                                y = oy + oh
                            end
                        end
                        moved = true
                    end
                end
                if not moved then break end
            end
        end
        x = math.clamp(x, 0, math.max(0, vs.X - w))
        y = math.clamp(y, 0, math.max(0, vs.Y - h))
        curX = x
        curY = y
        frame.Position = UDim2.new(0, x, 0, y)
    end)
    local endedConn = UserInputService.InputEnded:Connect(function(input)
        if not entry.dragging then return end
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            entry.dragging = false
            monoPanelPosSave(entry.name, frame.Position)
            entry.targetY = frame.Position.Y.Offset
            dragStart = nil
            startPos = nil
        end
    end)
    entry._dragConns = { changedConn, endedConn }

    return entry
end

monoWoa = {
    enabled = false, platform = nil, tiles = {}, queue = {},
    baseY = 0, appliedY = 0, startY = nil,
    up = false, down = false, renderConn = nil,
}
monoWoaTile = 256
monoWoaThick = 16
monoWoaSink = 0.01
monoWoaRadius = 8
monoWoaPerFrame = 8
monoWoaCx = nil
monoWoaCz = nil
monoWoaHit = nil
monoWoaFolderName = "MonoWalkAirPlatform"
monoWoaPaint = nil

function monoWoaGetHR()
    local char = LocalPlayer.Character
    if not char then return nil, nil end
    return char:FindFirstChildOfClass("Humanoid"), char:FindFirstChild("HumanoidRootPart")
end

function monoWoaFootY(h, root)
    local char = LocalPlayer.Character
    local hipH = h and h.HipHeight or 2.3
    local params = RaycastParams.new()
    params.FilterDescendantsInstances = char and { char } or {}
    params.FilterType = Enum.RaycastFilterType.Exclude
    local ok, hit = pcall(function()
        return workspace:Raycast(root.Position, Vector3.new(0, -50, 0), params)
    end)
    if ok and hit then
        local y = tonumber(hit.Position.Y)
        if y and y == y then return y end
    end

    return root.Position.Y - root.Size.Y * 0.5 - hipH
end

function monoWoaPartY()
    return monoWoa.baseY - monoWoaThick * 0.5 - monoWoaSink
end

function monoWoaFolderGet()
    if monoWoa.platform then
        local ok, live = pcall(function() return monoWoa.platform.Parent end)
        if ok and live then return monoWoa.platform end
    end
    local f = Instance.new("Folder")
    f.Name = monoWoaFolderName
    f.Parent = workspace
    monoWoa.platform = f
    return f
end

function monoWoaAdd(cx, cz)
    local row = monoWoa.tiles[cx]
    if row and typeof(row[cz]) == "Instance" then return end
    local part = Instance.new("Part")
    part.Name = "MonoWalkAirTile"
    part.Anchored = true
    part.Locked = true
    part.CanCollide = true
    part.Size = Vector3.new(monoWoaTile, monoWoaThick, monoWoaTile)
    part.Position = Vector3.new(cx * monoWoaTile, monoWoaPartY(), cz * monoWoaTile)
    part.Material = Enum.Material.SmoothPlastic
    part.Transparency = 1
    part.CastShadow = false
    part.TopSurface = Enum.SurfaceType.Smooth
    part.BottomSurface = Enum.SurfaceType.Smooth
    part.Parent = monoWoaFolderGet()
    if not row then row = {}; monoWoa.tiles[cx] = row end
    row[cz] = part
end

function monoWoaDrop(cx, cz)
    local row = monoWoa.tiles[cx]
    if not row then return end
    local part = row[cz]
    row[cz] = nil
    if typeof(part) == "Instance" then pcall(function() part:Destroy() end) end
end

function monoWoaScan(root)
    local cx = math.floor(root.Position.X / monoWoaTile)
    local cz = math.floor(root.Position.Z / monoWoaTile)
    if cx == monoWoaCx and cz == monoWoaCz then return end
    monoWoaCx, monoWoaCz = cx, cz
    for x = cx - monoWoaRadius, cx + monoWoaRadius do
        for z = cz - monoWoaRadius, cz + monoWoaRadius do
            local row = monoWoa.tiles[x]
            if not row then row = {}; monoWoa.tiles[x] = row end
            if row[z] == nil then
                row[z] = true
                monoWoa.queue[#monoWoa.queue + 1] = x
                monoWoa.queue[#monoWoa.queue + 1] = z
            end
        end
    end
    for x, row in pairs(monoWoa.tiles) do
        if math.abs(x - cx) > monoWoaRadius then
            for z in pairs(row) do monoWoaDrop(x, z) end
            monoWoa.tiles[x] = nil
        else
            for z in pairs(row) do
                if math.abs(z - cz) > monoWoaRadius then monoWoaDrop(x, z) end
            end
        end
    end
end

function monoWoaPump()
    local made = 0
    while made < monoWoaPerFrame and #monoWoa.queue >= 2 do
        local z = monoWoa.queue[#monoWoa.queue]
        monoWoa.queue[#monoWoa.queue] = nil
        local x = monoWoa.queue[#monoWoa.queue]
        monoWoa.queue[#monoWoa.queue] = nil
        monoWoaAdd(x, z)
        made = made + 1
    end
    return made
end

function monoWoaDestroy()
    if monoWoa.renderConn then
        pcall(function() monoWoa.renderConn:Disconnect() end)
        monoWoa.renderConn = nil
    end
    if monoWoa.platform then
        pcall(function() monoWoa.platform:Destroy() end)
        monoWoa.platform = nil
    end
    local stray = workspace:FindFirstChild(monoWoaFolderName)
    if stray then pcall(function() stray:Destroy() end) end
    monoWoa.tiles = {}
    monoWoa.queue = {}
    monoWoaCx = nil
    monoWoaCz = nil
    monoWoa.enabled = false
    monoWoa.up = false
    monoWoa.down = false
end

function monoWoaCreate()
    local h, root = monoWoaGetHR()
    if not root then return false end
    monoWoaDestroy()
    local footY = monoWoaFootY(h, root)
    if not footY then return false end
    monoWoa.enabled = true
    monoWoa.startY = footY
    monoWoa.baseY = footY
    monoWoa.appliedY = monoWoaPartY()

    monoWoa.renderConn = RunService.Heartbeat:Connect(function()
        if not monoWoa.enabled then return end
        local _, r = monoWoaGetHR()
        if not r then return end

        if monoWoa.up then monoWoa.baseY = monoWoa.baseY + 0.2 end
        if monoWoa.down then monoWoa.baseY = monoWoa.baseY - 0.2 end

        if monoWoa.baseY ~= monoWoa.appliedY then
            monoWoa.appliedY = monoWoa.baseY
            for x, row in pairs(monoWoa.tiles) do
                for _, part in pairs(row) do
                    if typeof(part) == "Instance" then
                        part.Position = Vector3.new(part.Position.X, monoWoaPartY(), part.Position.Z)
                    end
                end
            end
        end

        monoWoaScan(r)
        monoWoaPump()
    end)
    return true
end

function monoWoaBuildPanel()
    local entry = monoPanelOpen("walkonair", "Walk On Air", 94, function()
        monoWoaSetEnabled(false, true)
        monoPanelDrop("walkonair")
        monoWoaPaint = nil
        monoWoaHit = nil
    end)
    if not entry then return end

    local toggleSec = monoPanelSection(entry.content, 1)
    create("TextLabel", {
        Size = UDim2.new(1, -100, 1, 0), Position = UDim2.new(0, 12, 0, 0),
        BackgroundTransparency = 1, Text = "Walk On Air", TextColor3 = C.text,
        TextSize = 12, Font = Enum.Font.Gotham, TextXAlignment = Enum.TextXAlignment.Left,
    }, toggleSec)
    monoWoaPaint = monoPanelPill(toggleSec, monoWoa.enabled)
    monoWoaHit = monoPanelPillHit(toggleSec, function()
        monoWoaSetEnabled(not monoWoa.enabled, true)
    end)

    local btnSec = monoPanelSection(entry.content, 2)
    create("UIListLayout", {
        Padding = UDim.new(0, 6), FillDirection = Enum.FillDirection.Horizontal,
        HorizontalAlignment = Enum.HorizontalAlignment.Center,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        SortOrder = Enum.SortOrder.LayoutOrder,
    }, btnSec)
    local upBtn = monoPanelBtn(btnSec, "Up", 1)
    local resetBtn = monoPanelBtn(btnSec, "Reset", 2)
    local downBtn = monoPanelBtn(btnSec, "Down", 3)

    upBtn.MouseButton1Down:Connect(function() monoWoa.up = true end)
    upBtn.MouseButton1Up:Connect(function() monoWoa.up = false end)
    upBtn.MouseLeave:Connect(function() monoWoa.up = false end)
    downBtn.MouseButton1Down:Connect(function() monoWoa.down = true end)
    downBtn.MouseButton1Up:Connect(function() monoWoa.down = false end)
    downBtn.MouseLeave:Connect(function() monoWoa.down = false end)
    resetBtn.MouseButton1Click:Connect(function()
        if monoWoa.enabled and monoWoa.startY ~= nil then monoWoa.baseY = monoWoa.startY end
    end)
end

function monoWoaSetEnabled(on, silent)
    on = on and true or false
    if on ~= monoWoa.enabled then
        if on then
            if not monoWoaCreate() then
                if monoWoaPaint then monoWoaPaint(false) end
                if not silent then notify("Monochrome", "Walk on air needs a character", 3) end
                return false
            end
        else
            monoWoaDestroy()
        end
        if type(setData) == "table" then
            setData.walkOnAir = monoWoa.enabled
            if type(setSave) == "function" then setSave() end
        end
        if not silent then
            notify("Monochrome", "Walk on air " .. (monoWoa.enabled and "enabled" or "disabled"), 3)
        end
    end
    if monoWoaPaint then monoWoaPaint(monoWoa.enabled) end
    return monoWoa.enabled
end

monoCmdOnDestroy("walkonair", monoWoaDestroy)

registerMonoCommand("walkonair", function(auto)
    local open = false
    for i = #monoPanelCols, 1, -1 do
        if monoPanelCols[i].name == "walkonair" then open = true end
    end
    if not open then
        monoWoaBuildPanel()
        if auto and setData.walkOnAir then monoWoaSetEnabled(true, true) end
        return monoWoa.enabled
    end
    if not auto then monoWoaSetEnabled(false, true) end
    monoPanelDrop("walkonair")
    monoWoaPaint = nil
    monoWoaHit = nil
    return monoWoa.enabled
end)

monoFov = {
    value = 70, game = 70, charConn = nil,
    fill = nil, knob = nil, track = nil, valLabel = nil,
    dragging = false, lastClick = 0, moveConn = nil, endConn = nil,
}
monoFovMin = 1
monoFovMax = 120
monoFovReset = 70
monoFovSaveToken = 0

function monoFovGameDefault()
    local cam = workspace.CurrentCamera
    local v = cam and cam.FieldOfView or monoFovReset
    if type(v) ~= "number" or v ~= v then v = monoFovReset end
    return math.clamp(v, monoFovMin, monoFovMax)
end

function monoFovSave()
    monoFovSaveToken = monoFovSaveToken + 1
    local mine = monoFovSaveToken
    task.delay(0.25, function()
        if mine ~= monoFovSaveToken then return end
        if type(setData) == "table" and type(setSave) == "function" then setSave() end
    end)
end

function monoFovApply(v)
    local n = math.clamp(math.floor(v + 0.5), monoFovMin, monoFovMax)
    monoFov.value = n
    local scale = (n - monoFovMin) / (monoFovMax - monoFovMin)
    if monoFov.fill then monoFov.fill.Size = UDim2.new(scale, 0, 1, 0) end
    if monoFov.knob then monoFov.knob.Position = UDim2.new(scale, 0, 0.5, 0) end
    if monoFov.valLabel then monoFov.valLabel.Text = tostring(n) end
    local cam = workspace.CurrentCamera
    if cam then pcall(function() cam.FieldOfView = n end) end
    if type(setData) == "table" then
        setData.fov = n
        monoFovSave()
    end
end

function monoFovDetach()
    if monoFov.moveConn then pcall(function() monoFov.moveConn:Disconnect() end) ;monoFov.moveConn = nil end
    if monoFov.endConn then pcall(function() monoFov.endConn:Disconnect() end) ;monoFov.endConn = nil end
    monoFov.fill = nil
    monoFov.knob = nil
    monoFov.track = nil
    monoFov.valLabel = nil
    monoFov.dragging = false
end

function monoFovStop()
    monoFovDetach()
    if monoFov.charConn then
        pcall(function() monoFov.charConn:Disconnect() end)
        monoFov.charConn = nil
    end
    local cam = workspace.CurrentCamera
    if cam then pcall(function() cam.FieldOfView = monoFov.game or monoFovReset end) end
end

function monoFovLoad()
    monoFov.game = monoFovGameDefault()
    local raw = type(setData) == "table" and setData.fov or nil
    if raw ~= nil then
        monoFov.value = math.clamp(math.floor((tonumber(raw) or monoFovReset) + 0.5), monoFovMin, monoFovMax)
    end
end

function monoSpeedLoad()
    local hum = monoSpeedHum()
    local g = hum and tonumber(hum.WalkSpeed) or 16
    if type(g) ~= "number" or g ~= g then g = 16 end
    monoSpeed.game = g
    local raw = type(setData) == "table" and setData.walkSpeed or nil
    if raw ~= nil then
        monoSpeed.value = math.clamp(math.floor((tonumber(raw) or g) + 0.5), monoSpeedMin, monoSpeedMax)
    end
    local craw = type(setData) == "table" and setData.cframeSpeed or nil
    if craw ~= nil then
        monoSpeed.cframe = math.clamp(math.floor((tonumber(craw) or 0) + 0.5), monoSpeedCMin, monoSpeedCMax)
    end
end

function monoJumpLoad()
    local hum = monoJumpHum()
    local jp = hum and tonumber(hum.JumpPower) or monoJumpReset
    if type(jp) ~= "number" or jp ~= jp then jp = monoJumpReset end
    monoJump.game = math.clamp(jp, 0, monoJumpMax)
    local usePower = true
    if hum then pcall(function() usePower = hum.UseJumpPower end) end
    monoJump.gameUsePower = usePower and true or false
    local raw = type(setData) == "table" and setData.jumpPower or nil
    if raw ~= nil then
        monoJump.power = math.clamp(math.floor((tonumber(raw) or monoJumpReset) + 0.5), monoJumpMin, monoJumpMax)
    end
end

function monoFovBuildPanel()
    local entry = monoPanelOpen("fov", "Field Of View", 68, function()
        monoFovStop()
        monoPanelDrop("fov")
    end)
    if not entry then return end

    local scale = (monoFov.value - monoFovMin) / (monoFovMax - monoFovMin)

    local sec = monoPanelSection(entry.content, 1)
    sec.Size = UDim2.new(1, 0, 0, 52)
    create("UIPadding", {
        PaddingTop = UDim.new(0, 5), PaddingBottom = UDim.new(0, 5),
    }, sec)
    create("UIListLayout", {
        Padding = UDim.new(0, 2), SortOrder = Enum.SortOrder.LayoutOrder,
    }, sec)

    local labelRow = create("Frame", {
        Size = UDim2.new(1, 0, 0, 20), BackgroundTransparency = 1, LayoutOrder = 1,
    }, sec)
    create("UIPadding", {
        PaddingLeft = UDim.new(0, 12), PaddingRight = UDim.new(0, 12),
    }, labelRow)
    create("TextLabel", {
        Size = UDim2.new(1, -60, 1, 0), BackgroundTransparency = 1,
        Text = "Field of View", TextColor3 = C.text, TextSize = 12,
        Font = Enum.Font.Gotham, TextXAlignment = Enum.TextXAlignment.Left,
    }, labelRow)
    local valLabel = create("TextLabel", {
        Size = UDim2.new(0, 55, 1, 0), Position = UDim2.new(1, -55, 0, 0),
        BackgroundTransparency = 1, Text = tostring(monoFov.value),
        TextColor3 = C.textMut, TextSize = 11, Font = Enum.Font.Gotham,
        TextXAlignment = Enum.TextXAlignment.Right,
    }, labelRow)

    local sliderRow = create("Frame", {
        Size = UDim2.new(1, 0, 0, 18), BackgroundTransparency = 1, LayoutOrder = 2,
    }, sec)
    create("UIPadding", {
        PaddingLeft = UDim.new(0, 12), PaddingRight = UDim.new(0, 12),
    }, sliderRow)
    local track = create("Frame", {
        Size = UDim2.new(1, 0, 0, 6), Position = UDim2.new(0, 0, 0.5, -3),
        BackgroundColor3 = C.input, BorderSizePixel = 0, Active = true,
    }, sliderRow)
    corner(track, 999)
    local fill = create("Frame", {
        Size = UDim2.new(scale, 0, 1, 0), BackgroundColor3 = C.accent, BorderSizePixel = 0,
    }, track)
    corner(fill, 999)
    local knob = create("Frame", {
        Size = UDim2.new(0, 14, 0, 14), Position = UDim2.new(scale, 0, 0.5, 0),
        AnchorPoint = Vector2.new(0.5, 0.5), BackgroundColor3 = C.text,
        BorderSizePixel = 0, ZIndex = 3,
    }, track)
    corner(knob, 999)

    monoFov.fill = fill
    monoFov.knob = knob
    monoFov.track = track
    monoFov.valLabel = valLabel
    monoFov.dragging = false

    local function slideTo(input)
        local w = math.max(1, track.AbsoluteSize.X)
        local rel = math.clamp((input.Position.X - track.AbsolutePosition.X) / w, 0, 1)
        monoFovApply(monoFovMin + rel * (monoFovMax - monoFovMin))
    end

    knob.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
        or input.UserInputType == Enum.UserInputType.Touch then
            monoFov.dragging = true
        end
    end)

    track.InputBegan:Connect(function(input)
        if input.UserInputType ~= Enum.UserInputType.MouseButton1
        and input.UserInputType ~= Enum.UserInputType.Touch then return end
        local now = tick()
        if now - monoFov.lastClick < 0.3 then
            monoFov.lastClick = 0
            monoFov.dragging = false
            monoFovApply(monoFovReset)
        else
            monoFov.lastClick = now
            monoFov.dragging = true
            slideTo(input)
        end
    end)

    monoFov.moveConn = trackConn(UserInputService.InputChanged:Connect(function(input)
        if not monoFov.dragging then return end
        if input.UserInputType ~= Enum.UserInputType.MouseMovement
        and input.UserInputType ~= Enum.UserInputType.Touch then return end
        slideTo(input)
    end))

    monoFov.endConn = trackConn(UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
        or input.UserInputType == Enum.UserInputType.Touch then
            monoFov.dragging = false
        end
    end))

    if monoFov.charConn then pcall(function() monoFov.charConn:Disconnect() end) end
    monoFov.charConn = trackConn(LocalPlayer.CharacterAdded:Connect(function()
        task.wait(0.5)
        local cam = workspace.CurrentCamera
        if cam then pcall(function() cam.FieldOfView = monoFov.value end) end
    end))

    monoFovApply(monoFov.value)
end

monoCmdOnDestroy("fov", monoFovStop)

registerMonoCommand("fov", function(auto)
    local open = false
    for i = #monoPanelCols, 1, -1 do
        if monoPanelCols[i].name == "fov" then open = true end
    end
    if not open then
        monoFovBuildPanel()
        return monoFov.value
    end
    if not auto then monoFovStop() end
    monoPanelDrop("fov")
    monoFovDetach()
    return monoFov.value
end)

