monoCmdOnDestroy("infinitejump", monoIjStop)

registerMonoCommand("infinitejump", function()
    if monoIjConn then
        monoIjStop()
        notify("Monochrome", "Infinite jump disabled", 3)
        return false
    end
    monoIjDebounce = false
    monoIjConn = trackConn(UserInputService.JumpRequest:Connect(function()
        if monoIjDebounce then return end
        monoIjDebounce = true
        local char = LocalPlayer.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if hum then pcall(function() hum:ChangeState(Enum.HumanoidStateType.Jumping) end) end
        task.wait()
        monoIjDebounce = false
    end))
    notify("Monochrome", "Infinite jump enabled", 3)
    return true
end)

monoSpeed = {
    value = 16, game = 16, cframe = 0,
    bv = nil, mdConn = nil, mdHum = nil,
    cFill = nil, cKnob = nil, cTrack = nil, cValLabel = nil, cDragging = false, cLastClick = 0,
    fill = nil, knob = nil, track = nil, valLabel = nil,
    dragging = false, lastClick = 0, moveConn = nil, endConn = nil, charConn = nil,
}
monoSpeedMin = 0
monoSpeedMax = 500
monoSpeedCMin = 0
monoSpeedCMax = 100

function monoSpeedHum()
    local char = LocalPlayer.Character
    return char and char:FindFirstChildOfClass("Humanoid")
end

function monoSpeedSave()
    if type(setData) == "table" then
        setData.walkSpeed = monoSpeed.value
        setData.cframeSpeed = monoSpeed.cframe
        if type(setSave) == "function" then setSave() end
    end
end

function monoSpeedCStop()
    if monoSpeed.mdConn then
        pcall(function() monoSpeed.mdConn:Disconnect() end)
        monoSpeed.mdConn = nil
    end
    monoSpeed.mdHum = nil
    if monoSpeed.bv then
        pcall(function() monoSpeed.bv:Destroy() end)
        monoSpeed.bv = nil
    end
end

function monoSpeedCVel()
    local bv = monoSpeed.bv
    if not bv or not bv.Parent then return end
    local hum = monoSpeedHum()
    if not hum then return end
    local md = hum.MoveDirection
    if md.Magnitude <= 0 or monoSpeed.cframe <= 0 then
        bv.Velocity = Vector3.zero
        return
    end
    local u = md.Unit
    bv.Velocity = Vector3.new(u.X * monoSpeed.cframe, 0, u.Z * monoSpeed.cframe)
end

function monoSpeedCApply()
    local hum = monoSpeedHum()
    if not hum or monoSpeed.cframe <= 0 then
        monoSpeedCStop()
        return
    end
    local root = hum.Parent and hum.Parent:FindFirstChild("HumanoidRootPart")
    if not root then return end
    if not monoSpeed.bv or not monoSpeed.bv.Parent then
        monoSpeed.bv = Instance.new("BodyVelocity")
        monoSpeed.bv.Name = "MonoSpeedBV"
        monoSpeed.bv.Velocity = Vector3.zero
        monoSpeed.bv.Parent = root
    end
    monoSpeed.bv.MaxForce = Vector3.new(1e9, 0, 1e9)
    if monoSpeed.mdHum ~= hum then
        if monoSpeed.mdConn then pcall(function() monoSpeed.mdConn:Disconnect() end) end
        monoSpeed.mdConn = trackConn(hum:GetPropertyChangedSignal("MoveDirection"):Connect(monoSpeedCVel))
        monoSpeed.mdHum = hum
    end
    monoSpeedCVel()
end

function monoSpeedCSet(v)
    local n = math.clamp(math.floor(v + 0.5), monoSpeedCMin, monoSpeedCMax)
    monoSpeed.cframe = n
    local scale = (n - monoSpeedCMin) / (monoSpeedCMax - monoSpeedCMin)
    if monoSpeed.cFill then monoSpeed.cFill.Size = UDim2.new(scale, 0, 1, 0) end
    if monoSpeed.cKnob then monoSpeed.cKnob.Position = UDim2.new(scale, 0, 0.5, 0) end
    if monoSpeed.cValLabel then monoSpeed.cValLabel.Text = tostring(n) end
    monoSpeedCApply()
    monoSpeedSave()
end

function monoSpeedDetach()
    if monoSpeed.moveConn then pcall(function() monoSpeed.moveConn:Disconnect() end) ;monoSpeed.moveConn = nil end
    if monoSpeed.endConn then pcall(function() monoSpeed.endConn:Disconnect() end) ;monoSpeed.endConn = nil end
    if monoSpeed.cMoveConn then pcall(function() monoSpeed.cMoveConn:Disconnect() end) ;monoSpeed.cMoveConn = nil end
    if monoSpeed.cEndConn then pcall(function() monoSpeed.cEndConn:Disconnect() end) ;monoSpeed.cEndConn = nil end
    monoSpeed.fill = nil
    monoSpeed.knob = nil
    monoSpeed.track = nil
    monoSpeed.valLabel = nil
    monoSpeed.cFill = nil
    monoSpeed.cKnob = nil
    monoSpeed.cTrack = nil
    monoSpeed.cValLabel = nil
    monoSpeed.dragging = false
    monoSpeed.cDragging = false
end

function monoSpeedStop()
    monoSpeedDetach()
    monoSpeedCStop()
    if monoSpeed.charConn then
        pcall(function() monoSpeed.charConn:Disconnect() end)
        monoSpeed.charConn = nil
    end
    local hum = monoSpeedHum()
    if hum then pcall(function() hum.WalkSpeed = monoSpeed.game or 16 end) end
end

function monoSpeedApply(v)
    local n = math.clamp(math.floor(v + 0.5), monoSpeedMin, monoSpeedMax)
    monoSpeed.value = n
    local scale = (n - monoSpeedMin) / (monoSpeedMax - monoSpeedMin)
    if monoSpeed.fill then monoSpeed.fill.Size = UDim2.new(scale, 0, 1, 0) end
    if monoSpeed.knob then monoSpeed.knob.Position = UDim2.new(scale, 0, 0.5, 0) end
    if monoSpeed.valLabel then monoSpeed.valLabel.Text = tostring(n) end
    local hum = monoSpeedHum()
    if hum then pcall(function() hum.WalkSpeed = n end) end
    monoSpeedSave()
end

