    }, sec)
    create("UIPadding", {
        PaddingLeft = UDim.new(0, 12), PaddingRight = UDim.new(0, 12),
    }, sliderRow)
    local track = create("Frame", {
        Size = UDim2.new(1, 0, 0, 6), Position = UDim2.new(0, 0, 0.5, -3),
        BackgroundColor3 = C.input, BorderSizePixel = 0, Active = true,
    }, sliderRow)
    corner(track, 999)
    local fill = create("Frame", {
        Size = UDim2.new(scale, 0, 1, 0), BackgroundColor3 = C.accent, BorderSizePixel = 0,
    }, track)
    corner(fill, 999)
    local knob = create("Frame", {
        Size = UDim2.new(0, 14, 0, 14), Position = UDim2.new(scale, 0, 0.5, 0),
        AnchorPoint = Vector2.new(0.5, 0.5), BackgroundColor3 = C.text,
        BorderSizePixel = 0, ZIndex = 3,
    }, track)
    corner(knob, 999)

    monoJump.fill = fill
    monoJump.knob = knob
    monoJump.track = track
    monoJump.valLabel = valLabel
    monoJump.dragging = false

    local function slideTo(input)
        local w = math.max(1, track.AbsoluteSize.X)
        local rel = math.clamp((input.Position.X - track.AbsolutePosition.X) / w, 0, 1)
        monoJumpPower(monoJumpMin + rel * (monoJumpMax - monoJumpMin))
    end

    knob.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
        or input.UserInputType == Enum.UserInputType.Touch then
            monoJump.dragging = true
        end
    end)

    track.InputBegan:Connect(function(input)
        if input.UserInputType ~= Enum.UserInputType.MouseButton1
        and input.UserInputType ~= Enum.UserInputType.Touch then return end
        local now = tick()
        if now - monoJump.lastClick < 0.3 then
            monoJump.lastClick = 0
            monoJump.dragging = false
            monoJumpPower(monoJumpReset)
        else
            monoJump.lastClick = now
            monoJump.dragging = true
            slideTo(input)
        end
    end)

    monoJump.moveConn = trackConn(UserInputService.InputChanged:Connect(function(input)
        if not monoJump.dragging then return end
        if input.UserInputType ~= Enum.UserInputType.MouseMovement
        and input.UserInputType ~= Enum.UserInputType.Touch then return end
        slideTo(input)
    end))

    monoJump.endConn = trackConn(UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
        or input.UserInputType == Enum.UserInputType.Touch then
            monoJump.dragging = false
        end
    end))

    if monoJump.charConn then pcall(function() monoJump.charConn:Disconnect() end) end
    monoJump.charConn = trackConn(LocalPlayer.CharacterAdded:Connect(function()
        task.wait(0.5)
        monoJumpPower(monoJump.power)
    end))

    monoJumpPower(monoJump.power)
end

registerMonoCommand("jump", function()
    local open = false
    for i = #monoPanelCols, 1, -1 do
        if monoPanelCols[i].name == "jump" then open = true end
    end
    if not open then
        monoJumpBuildPanel()
        return monoJump.power
    end
    monoJumpStop()
    monoPanelDrop("jump")
    monoJumpDetach()
    return monoJump.power
end)

monoFly = {
    on = false, speed = 50, qe = false, btn = nil,
    key = nil, keyConn = nil,
    conn = nil, bv = nil, bg = nil, anim = nil,
    charConn = nil, descConn = nil, footstep = {},
    qePaint = nil, bindBtn = nil,
    fill = nil, knob = nil, track = nil, valLabel = nil,
    dragging = false, lastClick = 0, moveConn = nil, endConn = nil,
}
monoFlyMin = 0
monoFlyMax = 500
monoFlyReset = 50
monoFlyAnim = "rbxassetid://132783162476851"

function monoFlyHum()
    local char = LocalPlayer.Character
    return char and char:FindFirstChildOfClass("Humanoid")
end

function monoFlySave()
    if type(setData) == "table" then
        setData.flySpeed = monoFly.speed
        setData.flyQE = monoFly.qe
        setData.flyBind = monoFly.key or false
        if type(setSave) == "function" then setSave() end
    end
end

function monoFlyDetach()
    if monoFly.moveConn then pcall(function() monoFly.moveConn:Disconnect() end) ;monoFly.moveConn = nil end
    if monoFly.endConn then pcall(function() monoFly.endConn:Disconnect() end) ;monoFly.endConn = nil end
    monoFly.fill = nil
    monoFly.knob = nil
    monoFly.track = nil
    monoFly.valLabel = nil
    monoFly.dragging = false
end

function monoFlyMute()
    local char = LocalPlayer.Character
    if not char then return end
    for _, obj in ipairs(char:GetDescendants()) do
        if obj:IsA("Sound") then
            local n = obj.Name:lower()
            if n:find("footstep") or n:find("running") or n:find("walk") then
                if monoFly.footstep[obj] == nil then monoFly.footstep[obj] = obj.Volume end
                obj.Volume = 0
            end
        end
    end
    if monoFly.descConn then pcall(function() monoFly.descConn:Disconnect() end) ;monoFly.descConn = nil end
    monoFly.descConn = trackConn(char.DescendantAdded:Connect(function(obj)
        if not monoFly.on or not obj:IsA("Sound") then return end
        local n = obj.Name:lower()
        if n:find("footstep") or n:find("running") or n:find("walk") then
            if monoFly.footstep[obj] == nil then monoFly.footstep[obj] = obj.Volume end
            obj.Volume = 0
        end
    end))
end

function monoFlyUnmute()
    if monoFly.descConn then pcall(function() monoFly.descConn:Disconnect() end) ;monoFly.descConn = nil end
    for snd, vol in pairs(monoFly.footstep) do
        pcall(function() if snd then snd.Volume = vol end end)
    end
    monoFly.footstep = {}
end

function monoFlyStop()
    monoFly.on = false
    monoFlyUnmute()
    if monoFly.conn then pcall(function() monoFly.conn:Disconnect() end) ;monoFly.conn = nil end
    if monoFly.bv then pcall(function() monoFly.bv:Destroy() end) ;monoFly.bv = nil end
    if monoFly.bg then pcall(function() monoFly.bg:Destroy() end) ;monoFly.bg = nil end
    if monoFly.anim then pcall(function() monoFly.anim:Stop() end) ;monoFly.anim = nil end
    local hum = monoFlyHum()
    if hum then
        pcall(function() hum.PlatformStand = false end)
        pcall(function() hum:ChangeState(Enum.HumanoidStateType.GettingUp) end)
    end
end

function monoFlyBody(root)
    if not monoFly.bv or not monoFly.bv.Parent then
        monoFly.bv = Instance.new("BodyVelocity")
        monoFly.bv.MaxForce = Vector3.new(400000, 400000, 400000)
        monoFly.bv.Velocity = Vector3.zero
        monoFly.bv.Parent = root
    else
        monoFly.bv.MaxForce = Vector3.new(400000, 400000, 400000)
    end
    if not monoFly.bg or not monoFly.bg.Parent then
        monoFly.bg = Instance.new("BodyGyro")
        monoFly.bg.MaxTorque = Vector3.new(400000, 400000, 400000)
        monoFly.bg.P = 90000
        monoFly.bg.CFrame = root.CFrame
        monoFly.bg.Parent = root
    else
        monoFly.bg.MaxTorque = Vector3.new(400000, 400000, 400000)
    end
end

function monoFlyStart()
    local char = LocalPlayer.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    local root = char and char:FindFirstChild("HumanoidRootPart")
    if not hum or not root then return false end

    monoFlyMute()

    local anim = Instance.new("Animation")
    anim.AnimationId = monoFlyAnim
    local animator = hum:FindFirstChildOfClass("Animator")
    local track = nil
    pcall(function()
        track = animator and animator:LoadAnimation(anim) or hum:LoadAnimation(anim)
        if track then
            track.Priority = Enum.AnimationPriority.Action
            track:Play()
        end
    end)
    monoFly.anim = track

    pcall(function() hum.PlatformStand = true end)
    monoFlyBody(root)
    monoFly.on = true

    if monoFly.conn then pcall(function() monoFly.conn:Disconnect() end) ;monoFly.conn = nil end
    monoFly.conn = trackConn(RunService.RenderStepped:Connect(function()
        if not monoFly.on then return end
        local c = LocalPlayer.Character
        local r = c and c:FindFirstChild("HumanoidRootPart")
        local cam = workspace.CurrentCamera
        if not r or not cam then return end
        monoFlyBody(r)
        local dir = Vector3.zero
        if UserInputService:IsKeyDown(Enum.KeyCode.W) then dir = dir + cam.CFrame.LookVector end
        if UserInputService:IsKeyDown(Enum.KeyCode.S) then dir = dir - cam.CFrame.LookVector end
        if UserInputService:IsKeyDown(Enum.KeyCode.A) then dir = dir - cam.CFrame.RightVector end
        if UserInputService:IsKeyDown(Enum.KeyCode.D) then dir = dir + cam.CFrame.RightVector end
        if monoFly.qe then
            if UserInputService:IsKeyDown(Enum.KeyCode.E) then dir = dir + Vector3.new(0, 1, 0) end
            if UserInputService:IsKeyDown(Enum.KeyCode.Q) then dir = dir - Vector3.new(0, 1, 0) end
        end
        if dir.Magnitude > 0 then dir = dir.Unit * monoFly.speed end
        monoFly.bv.Velocity = dir
        monoFly.bg.CFrame = cam.CFrame
    end))
    return true
end

function monoFlySet(on, silent)
    on = on and true or false
    if on == monoFly.on then return monoFly.on end
    if on then
        if not monoFlyStart() then
            if not silent then notify("Monochrome", "Fly needs a character", 3) end
            return false
        end
    else
        monoFlyStop()
    end
    if monoFly.btn then pcall(function() monoFly.btn.Text = monoFly.on and "Stop" or "Fly" end) end
    return monoFly.on
end

function monoFlySpeed(v)
    local n = math.clamp(math.floor(v + 0.5), monoFlyMin, monoFlyMax)
    monoFly.speed = n
    local scale = (n - monoFlyMin) / (monoFlyMax - monoFlyMin)
    if monoFly.fill then monoFly.fill.Size = UDim2.new(scale, 0, 1, 0) end
    if monoFly.knob then monoFly.knob.Position = UDim2.new(scale, 0, 0.5, 0) end
    if monoFly.valLabel then monoFly.valLabel.Text = tostring(n) end
    monoFlySave()
end

function monoFlyQE(on)
    monoFly.qe = on and true or false
    if monoFly.qePaint then monoFly.qePaint(monoFly.qe) end
    monoFlySave()
end

function monoFlyLoad()
    if type(setData) ~= "table" then return end
    local raw = setData.flySpeed
    if raw ~= nil then
        monoFly.speed = math.clamp(math.floor((tonumber(raw) or monoFlyReset) + 0.5), monoFlyMin, monoFlyMax)
    end
    monoFly.qe = setData.flyQE == true
    if type(setData.flyBind) == "string" and setData.flyBind ~= "" then
        monoFly.key = setData.flyBind
    end
end

function monoFlyKeySet(name)
    monoFly.key = name
    if name then
        for k, v in pairs(monoCmdBinds) do
            if v == name then monoCmdBindSet(k, nil) end
        end
        if type(monoSneak) == "table" and monoSneak.key == name then monoSneakKeySet(nil) end
    end
    monoFlySave()
    monoCmdRefresh()
    monoFlyKeyConnect()
end

function monoFlyKeyDisconnect()
    if monoFly.keyConn then
        pcall(function() monoFly.keyConn:Disconnect() end)
        monoFly.keyConn = nil
    end
end

function monoFlyKeyConnect()
    monoFlyKeyDisconnect()
    if not monoFly.key then return end
    monoFly.keyConn = UserInputService.InputBegan:Connect(function(input, gameProcessed)
        if gameProcessed or monoBindCapturing or monoBindSwallow then return end
        if input.UserInputType ~= Enum.UserInputType.Keyboard then return end
        local kn = input.KeyCode.Name
        if kn == "Unknown" or kn ~= monoFly.key then return end
        monoFlySet(not monoFly.on)
    end)
end

function monoFlyBuildPanel()
    local entry = monoPanelOpen("fly", "Fly", 148, function()
        monoFlyKeyDisconnect()
        monoFlySet(false, true)
        monoPanelDrop("fly")
        monoFly.btn = nil
        monoFly.bindBtn = nil
        monoFly.qePaint = nil
    end)
    if not entry then return end
    monoFlyKeyConnect()

    local btnSec = monoPanelSection(entry.content, 1)

    local flyBtn = monoPanelBtn(btnSec, monoFly.on and "Stop" or "Fly", nil, 142,
        UDim2.new(0, 18, 0.5, -12))
    local bindBtn = monoPanelBtn(btnSec, monoCmdBindShort(monoFly.key), nil, 52,
        UDim2.new(1, -58, 0.5, -12))

    monoFly.btn = flyBtn
    monoFly.bindBtn = bindBtn

    local function bindPaint()
        pcall(function()
            bindBtn.Text = monoCmdBindShort(monoFly.key)
            bindBtn.TextColor3 = monoFly.key and C.accent or C.textDim
        end)
    end
    bindPaint()

    flyBtn.MouseButton1Click:Connect(function() monoFlySet(not monoFly.on) end)

    bindBtn.MouseButton1Click:Connect(function()
        if monoBindCapturing then
            monoBindEndCapture()
            local had = monoFly.key
            monoFlyKeySet(nil)
            bindPaint()
            if had then notify("Monochrome", "fly keybind cleared", 2) end
            return
        end
        bindBtn.Text = "..."
        bindBtn.TextColor3 = C.accent
        monoBindCapture(function(input)
            monoFlyKeySet(input.KeyCode.Name)
            bindPaint()
            notify("Monochrome", "fly bound to " .. input.KeyCode.Name, 2)
        end, function()
            bindPaint()
        end)
    end)

    local qeRow = monoPanelSection(entry.content, 2)
    qeRow.Size = UDim2.new(1, 0, 0, 32)
    create("TextLabel", {
        Size = UDim2.new(1, -100, 1, 0), Position = UDim2.new(0, 12, 0, 0),
        BackgroundTransparency = 1, Text = "E Up / Q Down", TextColor3 = C.text,
        TextSize = 12, Font = Enum.Font.Gotham, TextXAlignment = Enum.TextXAlignment.Left,
    }, qeRow)
    monoFly.qePaint = monoPanelPill(qeRow, monoFly.qe)
    monoPanelPillHit(qeRow, function() monoFlyQE(not monoFly.qe) end)

    local sec = monoPanelSection(entry.content, 3)
    sec.Size = UDim2.new(1, 0, 0, 52)
    create("UIPadding", {
        PaddingTop = UDim.new(0, 5), PaddingBottom = UDim.new(0, 5),
    }, sec)
    create("UIListLayout", {
        Padding = UDim.new(0, 2), SortOrder = Enum.SortOrder.LayoutOrder,
    }, sec)

    local labelRow = create("Frame", {
        Size = UDim2.new(1, 0, 0, 20), BackgroundTransparency = 1, LayoutOrder = 1,
    }, sec)
    create("UIPadding", {
        PaddingLeft = UDim.new(0, 12), PaddingRight = UDim.new(0, 12),
    }, labelRow)
    create("TextLabel", {
        Size = UDim2.new(1, -60, 1, 0), BackgroundTransparency = 1,
        Text = "Speed", TextColor3 = C.text, TextSize = 12,
        Font = Enum.Font.Gotham, TextXAlignment = Enum.TextXAlignment.Left,
    }, labelRow)
    local valLabel = create("TextLabel", {
        Size = UDim2.new(0, 55, 1, 0), Position = UDim2.new(1, -55, 0, 0),
        BackgroundTransparency = 1, Text = tostring(monoFly.speed),
        TextColor3 = C.textMut, TextSize = 11, Font = Enum.Font.Gotham,
        TextXAlignment = Enum.TextXAlignment.Right,
    }, labelRow)

    local sliderRow = create("Frame", {
        Size = UDim2.new(1, 0, 0, 18), BackgroundTransparency = 1, LayoutOrder = 2,
    }, sec)
    create("UIPadding", {
        PaddingLeft = UDim.new(0, 12), PaddingRight = UDim.new(0, 12),
    }, sliderRow)
    local track = create("Frame", {
        Size = UDim2.new(1, 0, 0, 6), Position = UDim2.new(0, 0, 0.5, -3),
        BackgroundColor3 = C.input, BorderSizePixel = 0, Active = true,
    }, sliderRow)
    corner(track, 999)
    local fill = create("Frame", {
        Size = UDim2.new((monoFly.speed - monoFlyMin) / (monoFlyMax - monoFlyMin), 0, 1, 0),
        BackgroundColor3 = C.accent, BorderSizePixel = 0,
    }, track)
    corner(fill, 999)
    local knob = create("Frame", {
        Size = UDim2.new(0, 14, 0, 14),
        Position = UDim2.new((monoFly.speed - monoFlyMin) / (monoFlyMax - monoFlyMin), 0, 0.5, 0),
        AnchorPoint = Vector2.new(0.5, 0.5), BackgroundColor3 = C.text,
        BorderSizePixel = 0, ZIndex = 3,
    }, track)
    corner(knob, 999)

    monoFly.fill = fill
    monoFly.knob = knob
    monoFly.track = track
    monoFly.valLabel = valLabel
    monoFly.dragging = false

    local function slideTo(input)
        local w = math.max(1, track.AbsoluteSize.X)
        local rel = math.clamp((input.Position.X - track.AbsolutePosition.X) / w, 0, 1)
        monoFlySpeed(monoFlyMin + rel * (monoFlyMax - monoFlyMin))
    end

    knob.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
        or input.UserInputType == Enum.UserInputType.Touch then
            monoFly.dragging = true
        end
    end)

    track.InputBegan:Connect(function(input)
        if input.UserInputType ~= Enum.UserInputType.MouseButton1
        and input.UserInputType ~= Enum.UserInputType.Touch then return end
        local now = tick()
        if now - monoFly.lastClick < 0.3 then
            monoFly.lastClick = 0
            monoFly.dragging = false
            monoFlySpeed(monoFlyReset)
        else
            monoFly.lastClick = now
            monoFly.dragging = true
            slideTo(input)
        end
    end)

    monoFly.moveConn = trackConn(UserInputService.InputChanged:Connect(function(input)
        if not monoFly.dragging then return end
        if input.UserInputType ~= Enum.UserInputType.MouseMovement
        and input.UserInputType ~= Enum.UserInputType.Touch then return end
        slideTo(input)
    end))

    monoFly.endConn = trackConn(UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
        or input.UserInputType == Enum.UserInputType.Touch then
            monoFly.dragging = false
        end
    end))

    if monoFly.charConn then pcall(function() monoFly.charConn:Disconnect() end) ;monoFly.charConn = nil end
    monoFly.charConn = trackConn(LocalPlayer.CharacterAdded:Connect(function()
        task.wait(0.5)
        if not monoFly.on then return end
        monoFlyStop()
        monoFlySet(true, true)
    end))

    monoFlySpeed(monoFly.speed)
end

function monoFlyPanelOpen()
    for i = #monoPanelCols, 1, -1 do
        if monoPanelCols[i].name == "fly" then return true end
    end
    return false
end

registerMonoCommand("fly", function(auto)
    if not monoFlyPanelOpen() then
        monoFlyBuildPanel()
        return monoFly.on
    end
    if not auto then monoFlySet(false, true) end
    monoFlyKeyDisconnect()
    monoPanelDrop("fly")
    monoFlyDetach()
    monoFly.btn = nil
    monoFly.bindBtn = nil
    monoFly.qePaint = nil
    return monoFly.on
end)

monoCmdOnDestroy("speed", monoSpeedStop)
monoCmdOnDestroy("jump", monoJumpStop)
monoCmdOnDestroy("fly", function()
    monoFlyKeyDisconnect()
    monoFlyStop()
end)

monoShBusy = false

function monoShCandidates(sortOrder)
    local ok, result = pcall(function()
        return HttpService:JSONDecode(game:HttpGet(
            "https://games.roblox.com/v1/games/" .. game.PlaceId
            .. "/servers/Public?sortOrder=" .. sortOrder
            .. "&limit=100&excludeFullGames=true", true))
    end)
    if not ok or type(result) ~= "table" or type(result.data) ~= "table" then return nil end
    local out = {}
    for _, server in ipairs(result.data) do
        local playing = server.playing or 0
        local maxPlayers = server.maxPlayers or 0
        if type(server.id) == "string" and server.id ~= game.JobId
            and maxPlayers > 0 and playing < maxPlayers then
            out[#out + 1] = server
        end
    end
    return out
end

function monoShBest(list, score)
    local best = nil
    local bestScore = math.huge
    for _, server in ipairs(list) do
        local v = score(server)
        if type(v) == "number" and v < bestScore then
            bestScore = v
            best = server
        end
    end
    return best
end

function monoShRun(sortOrder, pick)
    if monoShBusy then return end
    monoShBusy = true
    task.spawn(function()
        local list = monoShCandidates(sortOrder)
        local server = nil
        if list and #list > 0 then server = pick(list) end
        monoShBusy = false
        if not server then return end
        TeleportService:TeleportToPlaceInstance(game.PlaceId, server.id, LocalPlayer)
    end)
end

registerMonoCommand("rejoin", function()
    if #Players:GetPlayers() <= 1 then
        LocalPlayer:Kick("Rejoining...")
        task.wait(0.3)
        TeleportService:Teleport(game.PlaceId, LocalPlayer)
    else
        TeleportService:TeleportToPlaceInstance(game.PlaceId, game.JobId, LocalPlayer)
    end
end)

registerMonoCommand("serverhop", function()
    monoShRun("Desc", function(list)
        return list[math.random(1, #list)]
    end)
end)

registerMonoCommand("serverhopmost", function()
    monoShRun("Desc", function(list)
        return monoShBest(list, function(s) return -(s.playing or 0) end)
    end)
end)

registerMonoCommand("serverhopping", function()
    monoShRun("Asc", function(list)
        return monoShBest(list, function(s) return s.ping or math.huge end)
    end)
end)

registerMonoCommand("serverhopfew", function()
    monoShRun("Asc", function(list)
        return monoShBest(list, function(s) return s.playing or 0 end)
    end)
end)

monoCmdRefresh()

Target = Window:Tab({ Name = "Target" })
tp = Target._page

T = {
    Player = nil,
    Viewing = false, Headsitting = false, Backpacking = false,
    _viewConn = nil, _headsitConn = nil, _backConn = nil,
    Resume = nil,
    LastTargetId = nil, LastTargetName = nil,
}
ActionBtns = {}

function tRootOf(p) local c = p and p.Character; return c and c:FindFirstChild("HumanoidRootPart") end
function tHumOf(p) local c = p and p.Character; return c and c:FindFirstChildOfClass("Humanoid") end
function MyRoot() return tRootOf(LocalPlayer) end
function MyHum() return tHumOf(LocalPlayer) end

function BV(root)
    local existing = root:FindFirstChild("MonoTargBV")
    if existing then return existing end
    local bv = Instance.new("BodyVelocity")
    bv.Name = "MonoTargBV"
    bv.MaxForce = Vector3.new(1e9, 1e9, 1e9)
    bv.Velocity = Vector3.zero
    bv.Parent = root
    return bv
end
function RemoveBV(root)
    if root then
        local b = root:FindFirstChild("MonoTargBV")
        if b then b:Destroy() end
    end
end

function SetBtnActive(key, active)
    local b = ActionBtns[key]
    if not b then return end
    tween(b, {
        BackgroundColor3 = active and C.surfaceHi or C.surface,
        BackgroundTransparency = active and 0.15 or 0.4,
        TextColor3 = active and C.accent or C.text,
    }, 0.15)
    local s = b:FindFirstChildOfClass("UIStroke")
    if s then
        s.Color = active and C.border or C.borderSoft
        s.Transparency = active and 0.15 or 0.55
    end
end

function StopAll()
    local wasViewing, wasHeadsit, wasBackpack = T.Viewing, T.Headsitting, T.Backpacking
    for _, key in ipairs({ "_viewConn", "_headsitConn", "_backConn" }) do
        if T[key] then pcall(function() T[key]:Disconnect() end); T[key] = nil end
    end
    T.Viewing, T.Headsitting, T.Backpacking = false, false, false
    for key in pairs(ActionBtns) do SetBtnActive(key, false) end
    local h = MyHum()
    if wasHeadsit or wasBackpack then
        RemoveBV(MyRoot())
        if h then
            h.Sit = false
            h.AutoRotate = true
        end
        monoAntiSitPause(false)
    end
    if wasViewing and h then
        local cam = workspace.CurrentCamera
        if cam then cam.CameraSubject = h end
    end
end

function StartExclusive(stateKey)
    T.Resume = nil
    if T[stateKey] then StopAll(); return false end
    StopAll()
    return true
end

