function UpdateListSize()
    if not tgListScroll or not tgListScroll.Parent then return false end
    if not tgActRow or not tgActRow.Parent then return false end
    if not tp or not tp.Parent then return false end
    local pageH = tp.AbsoluteSize.Y
    if pageH <= 0 then return false end
    local rowH = tgActRow.AbsoluteSize.Y
    if rowH <= 0 then return false end
    local listRel = tgListScroll.AbsolutePosition.Y - tp.AbsolutePosition.Y
    local avail = pageH - (listRel + 6) - rowH
    if avail > 40 then
        tgListScroll.Size = UDim2.new(1, 0, 0, math.floor(avail))
    end
    return true
end

function AssignOrders()
    local sorted = {}
    for uid, data in pairs(playerCache) do
        if data.player and data.player.Parent then table.insert(sorted, data) end
    end
    table.sort(sorted, function(a, b)
        local aF, bF = a.isFriend == true, b.isFriend == true
        if aF ~= bF then return aF end
        return string.lower(a.player.Name) < string.lower(b.player.Name)
    end)
    for order, data in ipairs(sorted) do
        local row = playerBtns[data.player.UserId]
        if row then row.LayoutOrder = order end
    end
end

    RefreshHighlights = function()
    for uid, row in pairs(playerBtns) do
        if row and row.Parent then
            local data = playerCache[uid]
            local selected = data and data.player == T.Player
            tween(row, {
                BackgroundColor3 = selected and C.surfaceHi or C.surface,
                BackgroundTransparency = selected and 0.15 or 0.4,
            }, 0.15)
            local s = row:FindFirstChildOfClass("UIStroke")
            if s then tween(s, { Color = selected and C.border or C.borderSoft, Transparency = selected and 0.15 or 0.55 }, 0.15) end
            local dn = row:FindFirstChild("DisplayName")
            if dn then tween(dn, { TextColor3 = selected and C.accent or C.text }, 0.15) end
        end
    end
end

function MakePlayerRow(plr)
    local uid = plr.UserId
    local selected = plr == T.Player
    local row = create("Frame", {
        Name = tostring(uid), Size = UDim2.new(1, 0, 0, TG_ROW_H),
        BackgroundColor3 = selected and C.surfaceHi or C.surface, BackgroundTransparency = selected and 0.15 or 0.4,
