        BackgroundTransparency = 1, Text = plr.DisplayName,
        TextColor3 = selected and C.accent or C.text, TextSize = 11, Font = Enum.Font.GothamMedium,
        TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd,
    }, row)
    create("TextLabel", {
        Name = "UserLabel",
        Size = UDim2.new(1, -52, 0, 12), Position = UDim2.new(0, 42, 0, 20),
        BackgroundTransparency = 1, Text = "@" .. plr.Name,
        TextColor3 = C.textMut, TextSize = 9, Font = Enum.Font.Gotham,
        TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd,
    }, row)

    local hit = create("TextButton", {
        Size = UDim2.new(1, 0, 1, 0), BackgroundTransparency = 1, Text = "",
    }, row)
    hit.MouseEnter:Connect(function()
        if T.Player ~= plr then tween(row, { BackgroundColor3 = C.surface, BackgroundTransparency = 0.15 }, 0.15) end
    end)
    hit.MouseLeave:Connect(function()
        if T.Player ~= plr then tween(row, { BackgroundColor3 = C.surface, BackgroundTransparency = 0.4 }, 0.15) end
    end)
    hit.MouseButton1Click:Connect(function()
        if T.Player == plr then
            T.LastTargetId, T.LastTargetName = nil, nil
            SetTarget(nil)
        else
            SetTarget(plr)
        end
    end)

    playerBtns[uid] = row
end

function AddPlayer(plr)
    if plr == LocalPlayer or playerBtns[plr.UserId] then return end
    playerCache[plr.UserId] = { player = plr, isFriend = nil }
    MakePlayerRow(plr)
    ApplyFilter()
    task.spawn(function()
        local ok, isFriend = pcall(function() return LocalPlayer:IsFriendsWith(plr.UserId) end)
        if playerCache[plr.UserId] then
            playerCache[plr.UserId].isFriend = (ok and isFriend) or false
            AssignOrders()
        end
    end)
end

function RemovePlayer(plr)
    local row = playerBtns[plr.UserId]
    if row then row:Destroy(); playerBtns[plr.UserId] = nil end
    playerCache[plr.UserId] = nil
    if T.Player == plr then SetTarget(nil) end
    AssignOrders()
    UpdateListSize()
end

function ApplyFilter()
    local raw = string.lower(tgSearch.Text or ""):gsub("^@", "")
    for uid, row in pairs(playerBtns) do
        local data = playerCache[uid]
        if data and data.player and data.player.Parent then
            local n = string.lower(data.player.Name)
            local dn = string.lower(data.player.DisplayName or "")
            row.Visible = raw == ""
                or n:find(raw, 1, true) ~= nil
                or dn:find(raw, 1, true) ~= nil
        end
    end
    UpdateListSize()
end
