UpdateInfoCard = function(plr)
    if not plr then
        tgThumb.Image = ""
        tgNoTarg.Visible = true
        tgName.Text, tgUser.Text, tgId.Text = "", "", ""
        tgAge.Text, tgJoined.Text = "", ""
        return
    end
    tgNoTarg.Visible = false
    tgThumb.Image = ""
    task.spawn(function()
        local ok, img = pcall(function()
            return Players:GetUserThumbnailAsync(plr.UserId, Enum.ThumbnailType.HeadShot, Enum.ThumbnailSize.Size100x100)
        end)
        if ok and tgThumb and tgThumb.Parent then tgThumb.Image = img end
    end)

    tgName.Text = plr.DisplayName
    tgUser.Text = "@" .. plr.Name
    tgId.Text = "ID: " .. tostring(plr.UserId)

    local days = plr.AccountAge or 0
    local joined = os.time() - days * 86400
    local nowT = os.date("*t", os.time())
    local joinT = os.date("*t", joined)
    local years = nowT.year - joinT.year
    local months = nowT.month - joinT.month
    local dayDiff = nowT.day - joinT.day
    if dayDiff < 0 then
        months = months - 1
        local prevMonth = nowT.month - 1
        local prevYear = nowT.year
        if prevMonth == 0 then prevMonth = 12; prevYear = prevYear - 1 end
        local daysInPrev = os.date("*t", os.time({ year = prevYear, month = prevMonth + 1, day = 0 })).day
        dayDiff = dayDiff + daysInPrev
    end
    if months < 0 then years = years - 1; months = months + 12 end
    tgAge.Text = "Age: " .. ((years > 0 and years .. "y " or "") .. (months > 0 and months .. "m " or "") .. dayDiff .. "d")
    tgJoined.Text = "Joined: " .. os.date("%d-%m-%Y", joined)
end

