SetTarget = function(plr)
    if T.Player ~= plr then StopAll() end
    T.Player = plr
    if plr then
        T.LastTargetId, T.LastTargetName = plr.UserId, plr.DisplayName
    end
    if plr and tgSearch.Text ~= "" then
        tgSearch.Text = ""
        ApplyFilter()
    end
    UpdateInfoCard(plr)
    RefreshHighlights()
end

tgTeleportBtn, tgViewBtn, tgHeadsitBtn, tgBackpackBtn =
    ActionBtns.teleport, ActionBtns.view, ActionBtns.headsit, ActionBtns.backpack

function StartView()
    T.Viewing = true
    SetBtnActive("view", true)
    T._viewConn = trackConn(RunService.Heartbeat:Connect(function()
        if not tp.Parent or not T.Player then StopAll(); return end
        local h = tHumOf(T.Player)
        local cam = workspace.CurrentCamera
        if h and cam then cam.CameraSubject = h end
    end))
end

function StartHeadsit()
    T.Headsitting = true
    SetBtnActive("headsit", true)
    monoAntiSitPause(true)
    T._headsitConn = trackConn(RunService.Heartbeat:Connect(function()
        if not tp.Parent or not T.Player then StopAll(); return end
        pcall(function()
            local r = MyRoot()
            if not r then return end
            local hum = MyHum()
            if hum then hum.Sit = true end
            BV(r).Velocity = Vector3.zero
            local head = T.Player.Character and T.Player.Character:FindFirstChild("Head")
            if head then r.CFrame = head.CFrame * CFrame.new(0, 2, 0) end
        end)
    end))
end

function StartBackpack()
    T.Backpacking = true
    SetBtnActive("backpack", true)
    monoAntiSitPause(true)
    T._backConn = trackConn(RunService.Heartbeat:Connect(function()
        if not tp.Parent or not T.Player then StopAll(); return end
        pcall(function()
            local r = MyRoot()
            if not r then return end
            local hum = MyHum()
            if hum then
                hum.Sit = true
                hum.AutoRotate = false
            end
            BV(r).Velocity = Vector3.zero
            local tRoot = tRootOf(T.Player)
            if tRoot then
                r.CFrame = tRoot.CFrame * CFrame.new(0, 0, 1.2) * CFrame.Angles(0, -math.pi, 0)
            end
        end)
    end))
end

tgTeleportBtn.MouseButton1Click:Connect(function()
    if not T.Player then return end
    local myRoot, tRoot = MyRoot(), tRootOf(T.Player)
    if not myRoot or not tRoot then return end
    myRoot.CFrame = tRoot.CFrame
end)

tgViewBtn.MouseButton1Click:Connect(function()
    if not T.Player then return end
    if not StartExclusive("Viewing") then return end
    StartView()
end)

tgHeadsitBtn.MouseButton1Click:Connect(function()
    if not T.Player then return end
    if not StartExclusive("Headsitting") then return end
    StartHeadsit()
end)

tgBackpackBtn.MouseButton1Click:Connect(function()
