local monoVoiceService

function monoMuteSubscribe(plr, paused)
    if not plr then return false end
    if monoVoiceService == nil then
        local ok, vc = pcall(function()
            return game:GetService("VoiceChatInternal")
        end)
        monoVoiceService = (ok and vc) or false
    end
    if not monoVoiceService then return false end
    return pcall(function()
        monoVoiceService:SubscribePause(plr.UserId, paused and true or false)
    end)
end

function monoSetLocalTransparency(inst, value)
    return pcall(function()
        inst.LocalTransparencyModifier = value
    end)
end

_G.MONO_MUTED = _G.MONO_MUTED or monoMutedPlayers or {}
monoMutedPlayers = _G.MONO_MUTED
_G.MONO_MUTED_USER_IDS = _G.MONO_MUTED_USER_IDS or monoMutedUserIds or {}
monoMutedUserIds = _G.MONO_MUTED_USER_IDS
monoMuteEnforceConn = nil
monoMutePlayerAddedConn = nil
monoMuteVoiceConns = {}



function monoMuteDevice(p, muted, propName)
    if not p then return false, nil end
    local adi = monoMuteAdi(p)
    if not adi then return false, nil end
    local candidates = propName and { propName } or { "MutedByLocalUser", "Muted" }
    for _, name in ipairs(candidates) do
        local okType, kind = pcall(function() return type(adi[name]) end)
        if okType and kind == "boolean" then
            local okSet = pcall(function() adi[name] = muted end)
            local okRead, cur = pcall(function() return adi[name] end)
            if okSet and okRead and cur == muted then return true, name end
        end
    end
    return false, nil
end

function monoMuteEnsureEnforce()
    if monoMuteEnforceConn then return end

    
    
    
    local acc = 0
    monoMuteEnforceConn = trackConn(RunService.Heartbeat:Connect(function(dt)
        if not monoAlive then return end
        acc = acc + dt
        if acc < 0.5 then return end
        acc = 0
        for uid, entry in pairs(monoMutedPlayers or {}) do
            if not entry.manuallyUnmuted then
                local p = Players:GetPlayerByUserId(uid)
                if p then pcall(monoMuteApply, p, true) end
            end
        end
    end))

    
    if monoVoiceService == nil then
        pcall(function() monoVoiceService = game:GetService("VoiceChatInternal") end)
    end
    if monoVoiceService then
        local function reassert()
            for uid, entry in pairs(monoMutedPlayers or {}) do
                if not entry.manuallyUnmuted then
                    local p = Players:GetPlayerByUserId(uid)
                    if p then pcall(monoMuteApply, p, true) end
                end
            end
        end
        for _, name in ipairs({ "StateChanged", "ParticipantsStateChanged", "PlayerMicActivitySignalChange" }) do
            local sig = monoVoiceService[name]
            if typeof(sig) == "RBXScriptSignal" then
                monoMuteVoiceConns[#monoMuteVoiceConns + 1] = trackConn(sig:Connect(reassert))
            end
        end
    end
end

function monoMuteEnsurePlayerAdded()
    if monoMutePlayerAddedConn then return end
    monoMutePlayerAddedConn = trackConn(Players.PlayerAdded:Connect(function(p)
        if p == LocalPlayer then return end
        if not monoMutedUserIds[p.UserId] then return end
        monoMuteTrack(p)
    end))
end

function monoMuteTrack(p, force)
    if not p or p == LocalPlayer then return end
    local existing = monoMutedPlayers[p.UserId]
    local manuallyUnmuted = (not force) and existing and existing.manuallyUnmuted == true
    if existing then
        if existing.conn then pcall(function() existing.conn:Disconnect() end) end
        if existing.adiConn then pcall(function() existing.adiConn:Disconnect() end) end
    end
    local entry = existing or { manuallyUnmuted = false }
    entry.manuallyUnmuted = manuallyUnmuted
    entry.conn = nil
    entry.adiConn = nil
    monoMutedPlayers[p.UserId] = entry
    monoMutedUserIds[p.UserId] = true
    local ok = true
    if not entry.manuallyUnmuted then
        ok = monoMuteApply(p, true)
    end
    monoMuteEnsureEnforce()
    monoMuteEnsurePlayerAdded()

    entry.adiConn = p.ChildAdded:Connect(function(child)
        if not child:IsA("AudioDeviceInput") then return end
        local cur = monoMutedPlayers[p.UserId]
        if not cur or cur.manuallyUnmuted then return end
        monoMuteCacheAdi(p)
        monoMuteApply(p, true)
    end)
    entry.conn = p.CharacterAdded:Connect(function()
        task.wait(0.1)
        local cur = monoMutedPlayers[p.UserId]
        if not cur or cur.manuallyUnmuted then return end
        monoMuteCacheAdi(p)
        monoMuteApply(p, true)
    end)
    return ok
end

monoMuteAdiCache = monoMuteAdiCache or {}



local function _monoFindAdi(plr)
    if not plr then return nil end
    local found = nil
    pcall(function() found = plr:FindFirstChildWhichIsA("AudioDeviceInput", true) end)
    if not found then
        pcall(function()
            local char = plr.Character
            if char then found = char:FindFirstChildWhichIsA("AudioDeviceInput", true) end
        end)
    end
    return found
end

function monoMuteCacheAdi(plr)
    if not plr then return nil end
    local cached = monoMuteAdiCache[plr.UserId]
    if cached and cached.Parent then return cached end
    local adi = _monoFindAdi(plr)
    if adi then monoMuteAdiCache[plr.UserId] = adi end
    return adi
end

function monoMuteAdi(plr)
    return monoMuteCacheAdi(plr)
end

function monoMuteApply(plr, muted)
    if not plr then return false end
    local deviceOk = false
    local adi = monoMuteAdi(plr)
    if adi then
        if muted then
            deviceOk = monoMuteDevice(plr, true)
            
            pcall(function() adi.Muted = true end)
        else
            local selfMuted = not adi.Active
            pcall(function() adi.Muted = false end)
            monoMuteDevice(plr, false)
            if not selfMuted then pcall(function() adi.Active = true end) end
            deviceOk = true
        end
    end

    if monoVc and monoVcMuteVoiceTree then
        pcall(monoVcMuteVoiceTree, plr, muted)
    end
    local subscribed = monoMuteSubscribe(plr, muted)
    return deviceOk or subscribed
end

function monoFindPlayer(name)
    local q = name:lower()
    for _, p in ipairs(Players:GetPlayers()) do
        if p ~= LocalPlayer then
            if p.Name:lower() == q or p.DisplayName:lower() == q then return p end
        end
    end
    for _, p in ipairs(Players:GetPlayers()) do
        if p ~= LocalPlayer then
            if p.Name:lower():find(q, 1, true) or p.DisplayName:lower():find(q, 1, true) then return p end
        end
    end
    return nil
end

function monoTargetFrom(args)
    if args and args[1] then
        local found = monoFindPlayer(args[1])
        if found then return found end
        notify("Monochrome", "No player matching " .. args[1], 3)
        return nil
    end
    if not T.Player then
        notify("Monochrome", "Select a player in the Target tab first", 3)
        return nil
    end
    return T.Player
end

function monoMuteAllOff()
    if monoMuteEnforceConn then
        pcall(function() monoMuteEnforceConn:Disconnect() end)
        monoMuteEnforceConn = nil
    end
    if monoMutePlayerAddedConn then
        pcall(function() monoMutePlayerAddedConn:Disconnect() end)
        monoMutePlayerAddedConn = nil
    end
    for uid, entry in pairs(monoMutedPlayers) do
        if entry and entry.conn then pcall(function() entry.conn:Disconnect() end) end
        if entry and entry.adiConn then pcall(function() entry.adiConn:Disconnect() end) end
        local p = Players:GetPlayerByUserId(uid)
        if p then monoMuteApply(p, false) end
        if monoVcClearVoiceMute then pcall(monoVcClearVoiceMute, uid) end
    end
    table.clear(monoMutedPlayers)
    table.clear(monoMutedUserIds)
end

registerMonoCommand("mute", function(auto, args)
    local target = monoTargetFrom(args)
    if not target then return end
    if not monoMuteTrack(target, true) then
        notify("Monochrome", target.Name .. "'s mic isn't reachable", 3)
        return
    end
    notify("Monochrome", "Muted " .. target.Name, 2)
end)

registerMonoCommand("unmute", function(auto, args)
    local target = monoTargetFrom(args)
    if not target then return end
    if not monoMuteApply(target, false) then
        notify("Monochrome", target.Name .. "'s mic isn't reachable", 3)
        return
    end
    local entry = monoMutedPlayers[target.UserId]
    if entry then entry.manuallyUnmuted = true end
end)

registerMonoCommand("muteall", function()
    monoMuteEnsurePlayerAdded()
    monoMuteEnsureEnforce()
    for _, p in ipairs(Players:GetPlayers()) do
        if p ~= LocalPlayer then
            monoMutedUserIds[p.UserId] = true
            monoMuteTrack(p, true)
        end
    end
end)

registerMonoCommand("unmuteall", function() monoMuteAllOff() end)

monoCmdOnDestroy("muteall", monoMuteAllOff)

monoToPin = nil
monoToPinFrames = 12

function monoToStopPin()
    if monoToPin then
        pcall(function() monoToPin:Disconnect() end)
        monoToPin = nil
    end
end

function monoToPlace(target)
    local myRoot, tRoot = MyRoot(), tRootOf(target)
    if not myRoot or not tRoot then return end
    myRoot.CFrame = tRoot.CFrame
    pcall(function()
        myRoot.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
        myRoot.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
    end)
    monoToStopPin()
    local frames = 0
    local limit = monoToPinFrames
    monoToPin = trackConn(RunService.Heartbeat:Connect(function()
        frames = frames + 1
        if frames > limit or not myRoot.Parent or not tRoot.Parent then
            monoToStopPin()
            return
        end
        pcall(function() myRoot.CFrame = tRoot.CFrame end)
    end))
end

registerMonoCommand("to", function(auto, args)
    local target = monoTargetFrom(args)
    if not target then return end
    monoToPlace(target)
end)

