_G.MONO_HIDDEN = _G.MONO_HIDDEN or monoHiddenPlayers or {}
monoHiddenPlayers = _G.MONO_HIDDEN

function monoHideNew(state, desc)

    local isBubble = false
    pcall(function()
        if desc:IsA("BillboardGui") or desc:IsA("SurfaceGui") then
            local low = string.lower(desc.Name or "")
            if string.find(low, "bubble", 1, true) then isBubble = true end
        end
    end)
    if isBubble then
        pcall(function()
            if not state.bubbles then state.bubbles = {} end
            if state.bubbles[desc] == nil then
                state.bubbles[desc] = { enabled = desc.Enabled, maxDistance = desc.MaxDistance }
            end
            desc.MaxDistance = 0
            desc.Enabled = false
        end)
        return
    end
    if desc:IsA("BillboardGui") or desc:IsA("SurfaceGui") then
        pcall(function()
            if state.guis[desc] == nil then state.guis[desc] = desc.Enabled end
            desc.Enabled = false
        end)
    elseif desc:IsA("ParticleEmitter") or desc:IsA("Fire")
        or desc:IsA("Sparkles") or desc:IsA("Smoke") then
        pcall(function()
            if state.particles[desc] == nil then state.particles[desc] = desc.Enabled end
            desc.Enabled = false
        end)
    elseif desc:IsA("Beam") or desc:IsA("Trail") then
        pcall(function()
            if state.beams[desc] == nil then state.beams[desc] = desc.Enabled end
            desc.Enabled = false
        end)
    elseif desc:IsA("Sound") then
        pcall(function()
            if state.sounds[desc] == nil then state.sounds[desc] = desc.Volume end
            desc.Volume = 0
        end)
    elseif desc:IsA("PointLight") or desc:IsA("SpotLight") or desc:IsA("SurfaceLight") then
        pcall(function()
            if state.lights[desc] == nil then state.lights[desc] = desc.Brightness end
            desc.Brightness = 0
        end)
    elseif desc:IsA("BasePart") or desc:IsA("Decal") or desc:IsA("Texture") then

        pcall(function()
            if monoSetLocalTransparency(desc, 1) then
                if not state.localTransparency then state.localTransparency = {} end
                state.localTransparency[desc] = true
            end
        end)
    end
end

function monoHideApply(char)
    if not char then return nil end
    local state = { parts = {}, localTransparency = {}, guis = {}, particles = {}, beams = {}, sounds = {}, lights = {}, hum = {}, bubbles = {} }
    local hum = char:FindFirstChildOfClass("Humanoid")
    if hum then
        pcall(function()
            state.hum.displayDistType = hum.DisplayDistanceType
            state.hum.healthDist = hum.HealthDisplayDistance
            state.hum.nameDist = hum.NameDisplayDistance
            hum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
            hum.HealthDisplayDistance = 0
            hum.NameDisplayDistance = 0
        end)
    end
    for _, desc in ipairs(char:GetDescendants()) do
        monoHideNew(state, desc)
    end
    return state
end

function monoHideWatch(entry, char)

    if entry.descendantConn then
        pcall(function() entry.descendantConn:Disconnect() end)
        entry.descendantConn = nil
    end
    if entry.bubbleConns then
        for _, c in ipairs(entry.bubbleConns) do pcall(function() c:Disconnect() end) end
        entry.bubbleConns = nil
    end
    
    
    entry.descendantConn = char.DescendantAdded:Connect(function(obj)
        if not entry.saved then return end
        pcall(monoHideNew, entry.saved, obj)
    end)

    entry.bubbleConns = {}
    for _, partName in ipairs({ "Head", "HumanoidRootPart" }) do
        local part = char:FindFirstChild(partName)
        if part then
            local conn = part.ChildAdded:Connect(function(child)
                if not entry.saved then return end
                pcall(function()
                    monoHideNew(entry.saved, child)
                    for _, d in ipairs(child:GetDescendants()) do
                        monoHideNew(entry.saved, d)
                    end
                end)
            end)
            entry.bubbleConns[#entry.bubbleConns + 1] = conn
            pcall(function() monoHideNew(entry.saved, part) end)
            for _, d in ipairs(part:GetDescendants()) do
                local low = ""
                pcall(function() low = string.lower(d.Name or "") end)
                if string.find(low, "bubble", 1, true) then
                    pcall(function() monoHideNew(entry.saved, d) end)
                end
            end
        end
    end
end

monoHideBubbleWatch = nil
function monoHideEnsureBubbleWatch()
    if monoHideBubbleWatch then return end
    local function onDesc(desc)
        if not desc:IsA("BillboardGui") and not desc:IsA("SurfaceGui") then return end
        local low = string.lower(desc.Name or "")
        if not string.find(low, "bubble", 1, true) then return end
        local adornee = desc.Adornee
        local model = adornee and adornee:FindFirstAncestorOfClass("Model")
        local plr = model and Players:GetPlayerFromCharacter(model)
        if not plr then return end
        local entry = monoHiddenPlayers[plr.UserId]
        if not entry or not entry.saved then return end
        pcall(function() monoHideNew(entry.saved, desc) end)
    end
    monoHideBubbleWatch = {}
    local hosts = { PlayerGui, CoreGui }
    for _, host in ipairs(hosts) do
        if host then
            pcall(function()
                monoHideBubbleWatch[#monoHideBubbleWatch + 1] = host.DescendantAdded:Connect(onDesc)
            end)
        end
    end
    local root = monoGuiRoot()
    if root and root ~= PlayerGui and root ~= CoreGui then
        pcall(function()
            monoHideBubbleWatch[#monoHideBubbleWatch + 1] = root.DescendantAdded:Connect(onDesc)
        end)
    end
end

function monoHideScanBubbles(uid, state)
    if not uid or not state then return end
    local hosts = {}
    local function add(h)
        if h and typeof(h) == "Instance" then
            for _, c in ipairs(hosts) do if c == h then return end end
            hosts[#hosts + 1] = h
        end
    end
    add(PlayerGui)
    add(CoreGui)
    add(monoGuiRoot())
    for _, host in ipairs(hosts) do
        for _, d in ipairs(host:GetDescendants()) do
            if d:IsA("BillboardGui") or d:IsA("SurfaceGui") then
                local low = string.lower(d.Name or "")
                if string.find(low, "bubble", 1, true) then
                    local adornee = d.Adornee
                    local model = adornee and adornee:FindFirstAncestorOfClass("Model")
                    local plr = model and Players:GetPlayerFromCharacter(model)
                    if plr and plr.UserId == uid then
                        pcall(function() monoHideNew(state, d) end)
                    end
                end
            end
        end
    end
end

_G.MONO_HIDDEN_SAFETY = _G.MONO_HIDDEN_SAFETY or {}

local function monoHideStartSafety(entry, p)
    if not entry or not entry.saved then return end
    local char = entry.char or (p and p.Character)
    if not char or not char.Parent then return end
    
    
    for _, d in ipairs(char:GetDescendants()) do
        pcall(monoHideNew, entry.saved, d)
    end
    if p then pcall(monoHideScanBubbles, p.UserId, entry.saved) end
end

_G.MONO_HIDDEN_USER_IDS = _G.MONO_HIDDEN_USER_IDS or monoHiddenUserIds or {}
monoHiddenUserIds = _G.MONO_HIDDEN_USER_IDS
monoHideEnforceConn = nil
monoHidePlayerAddedConn = nil

function _monoHideEnforceChar(char, state)
    if not char or not state then return end
    state.localTransparency = state.localTransparency or {}

    local hum = char:FindFirstChildOfClass("Humanoid")
    if hum then
        pcall(function()
            if hum.DisplayDistanceType ~= Enum.HumanoidDisplayDistanceType.None then
                hum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
            end
            if hum.HealthDisplayDistance ~= 0 then hum.HealthDisplayDistance = 0 end
            if hum.NameDisplayDistance ~= 0 then hum.NameDisplayDistance = 0 end
        end)
    end

    for desc in pairs(state.localTransparency) do
        if desc and desc.Parent then
            pcall(function()
                if desc.LocalTransparencyModifier ~= 1 then
                    desc.LocalTransparencyModifier = 1
                end
            end)
        end
    end
    for desc in pairs(state.guis or {}) do
        if desc and desc.Parent then
            pcall(function()
                if desc.Enabled then desc.Enabled = false end
            end)
        end
    end
    for desc in pairs(state.particles or {}) do
        if desc and desc.Parent then
            pcall(function()
                if desc.Enabled then desc.Enabled = false end
            end)
        end
    end
    for desc in pairs(state.beams or {}) do
        if desc and desc.Parent then
            pcall(function()
                if desc.Enabled then desc.Enabled = false end
            end)
        end
    end
    for desc in pairs(state.sounds or {}) do
        if desc and desc.Parent then
            pcall(function()
                if desc.Volume ~= 0 then desc.Volume = 0 end
            end)
        end
    end
    for desc in pairs(state.lights or {}) do
        if desc and desc.Parent then
            pcall(function()
                if desc.Brightness ~= 0 then desc.Brightness = 0 end
            end)
        end
    end
    
    
    for desc, saved in pairs(state.bubbles or {}) do
        if desc and desc.Parent then
            pcall(function()
                if desc.MaxDistance ~= 0 then desc.MaxDistance = 0 end
                if desc.Enabled then desc.Enabled = false end
            end)
        end
    end

end

function monoHideEnsureEnforce()
    if monoHideEnforceConn then return end

    
    
    
    
    local acc = 0
    monoHideEnforceConn = trackConn(RunService.Heartbeat:Connect(function(dt)
        if not monoAlive then return end
        acc = acc + dt
        if acc < 0.25 then return end
        acc = 0
        for uid, entry in pairs(monoHiddenPlayers or {}) do
            local p = Players:GetPlayerByUserId(uid)
            if p then
                local char = p.Character
                if char and char.Parent and entry.saved then
                    pcall(_monoHideEnforceChar, char, entry.saved)
                end
            end
        end
    end))
end

function monoHideEnsurePlayerAdded()
    if monoHidePlayerAddedConn then return end
    monoHidePlayerAddedConn = trackConn(Players.PlayerAdded:Connect(function(p)
        if p == LocalPlayer then return end
        if not monoHiddenUserIds[p.UserId] then return end
        monoHideTrack(p)
    end))
end

function monoHideTrack(p)
    if not p or p == LocalPlayer then return end
    local entry = monoHiddenPlayers[p.UserId]
    local reapply = (not entry) or (entry.char ~= p.Character)
    if not entry then
        entry = { saved = nil, conn = nil, descendantConn = nil, bubbleConns = nil, adi = nil, char = nil }
        monoHiddenPlayers[p.UserId] = entry
    end
    monoHiddenUserIds[p.UserId] = true
    monoHideEnsureEnforce()
    monoHideEnsurePlayerAdded()
    monoHideEnsureBubbleWatch()
    if entry.conn then pcall(function() entry.conn:Disconnect() end); entry.conn = nil end
    if entry.descendantConn then pcall(function() entry.descendantConn:Disconnect() end); entry.descendantConn = nil end
    if entry.bubbleConns then
        for _, c in ipairs(entry.bubbleConns) do pcall(function() c:Disconnect() end) end
        entry.bubbleConns = nil
    end
    if monoVcHideOverlay then monoVcHideOverlay(p.UserId) end
    local voiceOk = monoMuteSubscribe(p, true)
    if not voiceOk and not entry.adi then
        entry.adi = monoMuteAdi(p)
        if entry.adi then pcall(function() entry.adi.Muted = true end) end
    end
    if reapply then
        local char = p.Character
        if char then
            entry.saved = monoHideApply(char)
            monoHideWatch(entry, char)
            monoHideScanBubbles(p.UserId, entry.saved)
            entry.char = char
            monoHideStartSafety(entry, p)
        end
    end
    entry.conn = p.CharacterAdded:Connect(function(c)
        if entry.descendantConn then pcall(function() entry.descendantConn:Disconnect() end); entry.descendantConn = nil end
        if entry.bubbleConns then
            for _, cc in ipairs(entry.bubbleConns) do pcall(function() cc:Disconnect() end) end
            entry.bubbleConns = nil
        end
        task.spawn(function()
            if not c:WaitForChild("HumanoidRootPart", 10) then return end
            if not c:WaitForChild("Head", 10) then return end
            task.wait(0.1)
            entry.saved = monoHideApply(c)
            monoHideWatch(entry, c)
            monoHideScanBubbles(p.UserId, entry.saved)
            monoHideStartSafety(entry, p)
            entry.char = c
            local voiceOk = monoMuteSubscribe(p, true)
            if not voiceOk then
                local adi = entry.adi or monoMuteAdi(p)
                if adi then
                    entry.adi = adi
                    pcall(function() adi.Muted = true end)
                end
            end
            if monoVcHideOverlay then monoVcHideOverlay(p.UserId) end
        end)
    end)

    if entry.char then
        monoHideWatch(entry, entry.char)
        monoHideStartSafety(entry, p)
    end
end

function monoHideRestore(state)
    if not state then return end
    for desc, _ in pairs(state.localTransparency or {}) do
        monoSetLocalTransparency(desc, 0)
    end
    for desc, orig in pairs(state.guis or {}) do pcall(function() desc.Enabled = orig end) end
    for desc, saved in pairs(state.bubbles or {}) do
        pcall(function()
            desc.MaxDistance = saved.maxDistance
            desc.Enabled = saved.enabled
        end)
    end
    for desc, orig in pairs(state.particles or {}) do pcall(function() desc.Enabled = orig end) end
    for desc, orig in pairs(state.beams or {}) do pcall(function() desc.Enabled = orig end) end
    for desc, orig in pairs(state.sounds or {}) do pcall(function() desc.Volume = orig end) end
    for desc, orig in pairs(state.lights or {}) do pcall(function() desc.Brightness = orig end) end
end

function monoHideOff(p)
    local entry = monoHiddenPlayers[p.UserId]
    if not entry then
        monoHiddenUserIds[p.UserId] = nil
        return
    end
    if entry.conn then pcall(function() entry.conn:Disconnect() end) end
    if entry.descendantConn then pcall(function() entry.descendantConn:Disconnect() end) end
    if entry.bubbleConns then
        for _, c in ipairs(entry.bubbleConns) do pcall(function() c:Disconnect() end) end
        entry.bubbleConns = nil
    end
    if entry.adiConn then pcall(function() entry.adiConn:Disconnect() end) end
    monoHiddenPlayers[p.UserId] = nil
    monoHiddenUserIds[p.UserId] = nil
    local safety = _G.MONO_HIDDEN_SAFETY and _G.MONO_HIDDEN_SAFETY[p.UserId]
    if safety then
        _G.MONO_HIDDEN_SAFETY[p.UserId] = nil
        pcall(function() safety:Disconnect() end)
    end

    local char = p.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    local savedHum = entry.saved and entry.saved.hum
    if hum then
        pcall(function()
            hum.DisplayDistanceType = (savedHum and savedHum.displayDistType)
                or Enum.HumanoidDisplayDistanceType.Viewer
            hum.HealthDisplayDistance = (savedHum and savedHum.healthDist) or 100
            hum.NameDisplayDistance = (savedHum and savedHum.nameDist) or 100
        end)
    end

    monoHideRestore(entry.saved)
    monoMuteSubscribe(p, false)

    if entry.adi then
        pcall(function()
            entry.adi.Muted = false
        end)
    end
    if monoMuteAdiCache then monoMuteAdiCache[p.UserId] = nil end

    if monoVcRestoreOverlay then monoVcRestoreOverlay(p) end
end

task.spawn(function()
    task.wait(1)
    for uid in pairs(monoHiddenPlayers or {}) do
        local plr = Players:GetPlayerByUserId(uid)
        if plr and plr ~= LocalPlayer then
            pcall(function() monoHideTrack(plr) end)
        end
    end
end)

function monoHideAll()
    local uids = {}
    for uid in pairs(monoHiddenPlayers) do uids[#uids + 1] = uid end
    for _, uid in ipairs(uids) do
        local p = Players:GetPlayerByUserId(uid)
        if p then monoHideOff(p) end
    end
    monoHiddenPlayers = _G.MONO_HIDDEN or monoHiddenPlayers or {}
    _G.MONO_HIDDEN = monoHiddenPlayers
end

registerMonoCommand("hide", function(auto, args)
    local target = monoTargetFrom(args)
    if not target then return end
    monoHideTrack(target)
end)

registerMonoCommand("unhide", function(auto, args)
    local target = monoTargetFrom(args)
    if not target then return end
    monoHideOff(target)
end)

monoCmdOnDestroy("hide", monoHideAll)

monoHideAllConn = _G.MONO_HIDE_ALL_CONN

function monoHideEnsureHideAll()
    if _G.MONO_HIDE_ALL ~= true then return end
    if _G.MONO_HIDE_ALL_CONN then
        monoHideAllConn = _G.MONO_HIDE_ALL_CONN
        return
    end
    _G.MONO_HIDE_ALL_CONN = Players.PlayerAdded:Connect(function(p)
        if p ~= LocalPlayer then
            monoHiddenUserIds[p.UserId] = true
            monoHideTrack(p)
        end
    end)
    monoHideAllConn = _G.MONO_HIDE_ALL_CONN
end

function monoHideEveryone()
    _G.MONO_HIDE_ALL = true
    monoHideEnsureEnforce()
    monoHideEnsurePlayerAdded()
    monoHideEnsureHideAll()
    for _, p in ipairs(Players:GetPlayers()) do
        if p ~= LocalPlayer then
            monoHiddenUserIds[p.UserId] = true
            monoHideTrack(p)
        end
    end
end

function monoHideNobody()
    _G.MONO_HIDE_ALL = false
    if _G.MONO_HIDE_ALL_CONN then
        pcall(function() _G.MONO_HIDE_ALL_CONN:Disconnect() end)
        _G.MONO_HIDE_ALL_CONN = nil
        monoHideAllConn = nil
    elseif monoHideAllConn then
        pcall(function() monoHideAllConn:Disconnect() end)
        monoHideAllConn = nil
    end
    if monoHideEnforceConn then
        pcall(function() monoHideEnforceConn:Disconnect() end)
        monoHideEnforceConn = nil
    end
    if monoHidePlayerAddedConn then
        pcall(function() monoHidePlayerAddedConn:Disconnect() end)
        monoHidePlayerAddedConn = nil
    end
    table.clear(monoHiddenUserIds)
    monoHideAll()
end

registerMonoCommand("hideall", function(auto, args)
    monoHideEveryone()
    notify("Monochrome", "Every other player is hidden", 3)
end)

registerMonoCommand("unhideall", function(auto, args)
    monoHideNobody()
    notify("Monochrome", "Every player is visible again", 3)
end)

monoCmdOnDestroy("hide", monoHideNobody)
monoCmdOnDestroy("hideall", monoHideNobody)
monoCmdOnDestroy("unhideall", monoHideNobody)

monoVcMicUnmutedImg = "rbxasset://textures/ui/VoiceChat/MicLight/Unmuted0.png"
monoVcMicMutedImg = "rbxasset://textures/ui/VoiceChat/MicLight/Muted.png"
monoVcSpkMutedImg = "rbxasset://textures/ui/VoiceChat/SpeakerLight/Muted.png"
monoVcSpkLevels = {
