MONO_VC_FLAG = "MonochromeVcLoaded"

function monoVcIsLoaded()
    local ok, v = pcall(function() return LocalPlayer:GetAttribute(MONO_VC_FLAG) end)
    return ok and v == true
end

function monoVcSetLoaded(on)
    pcall(function() LocalPlayer:SetAttribute(MONO_VC_FLAG, on == true) end)
