local monoVcDefaults = {
    active = false,
    built = false,
    starting = false,
    method = "",
    disabled = {},
    addedConn = nil,
    removingConn = nil,
    sizeConn = nil,
    propConn = nil,
    paintConn = nil,
    micBtn = nil,
    micHit = nil,
    micDot = nil,
    micHost = nil,
    micSizeSaved = nil,
    stashedMic = nil,
    selfMuted = false,
    overlays = {},
    talking = {},
    voiceMuteState = {},
    nativeMicIcon = nil,
    nativeMicDot = nil,
}
_G.MONO_VC = _G.MONO_VC or monoVcDefaults
monoVc = _G.MONO_VC
for key, value in pairs(monoVcDefaults) do
    if monoVc[key] == nil then monoVc[key] = value end
end
monoVc.disabled = monoVc.disabled or {}
monoVc.overlays = monoVc.overlays or {}
monoVc.talking = monoVc.talking or {}
monoVc.voiceMuteState = monoVc.voiceMuteState or {}

function monoVcFetch()
    if not monoVcFetched then
        monoVcFetched = true
        local cf = clonefunction or function(...) return ... end
        pcall(function()
            local s = game:GetService("VoiceChatService")
            local cr = cloneref
            if cr then s = cr(s) or s end
            monoVcSvc = s
        end)
        pcall(function()
            local i = game:GetService("VoiceChatInternal")
            local cr = cloneref
            if cr then i = cr(i) or i end
            monoVcInternal = i
        end)
        pcall(function()
            if getconnections then monoVcGetConns = cf(getconnections) end
        end)
    end
    return monoVcSvc, monoVcInternal, monoVcGetConns
end

function monoVcMicPath()
    local top = CoreGui:FindFirstChild("TopBarApp")
    if not top then return nil end
    local inner = top:FindFirstChild("TopBarApp") or top
    local left = inner:FindFirstChild("UnibarLeftFrame")
    if not left then return nil end
    local menu = left:FindFirstChild("UnibarMenu") or left:FindFirstChild("ChromeMenu")
    if not menu then return nil end
    local two = menu:FindFirstChild("2")
    if not two then return nil end
    local host = two:FindFirstChild("Unibar") or two
    local three = host:FindFirstChild("3") or two:FindFirstChild("3")
    if not three then return nil end
    return host, three
end

monoVcPurgeAt = 0

function monoVcPurgeMicButtons()
    local top = CoreGui:FindFirstChild("TopBarApp")
    if not top then return end
    for _, d in ipairs(top:GetDescendants()) do
        if d.Name == "toggle_mic_mute" or d.Name == "toggle_mic_mute_new" then
            if d ~= monoVc.micBtn then pcall(function() d:Destroy() end) end
        end
    end
end

function monoVcMicIcon(button)
    local fr = button and button:FindFirstChild("IntegrationIconFrame", true)
    local ic = fr and fr:FindFirstChild("IntegrationIcon", true)
    if not ic then return nil end
    return ic:FindFirstChild("1", true) or ic:FindFirstChildOfClass("ImageLabel") or ic:FindFirstChildOfClass("ImageButton")
end

function monoVcMicUnmuted()
    local adi = monoMuteAdi(LocalPlayer)
    if adi then
        local okA, active = pcall(function() return adi.Active end)
        local okM, muted = pcall(function() return adi.Muted end)
        if okA and okM and active == true and muted == false then return true end
    end
    local _, three = monoVcMicPath()
    local btn = three and three:FindFirstChild("toggle_mic_mute", true)
    local img = btn and monoVcMicIcon(btn)
    if img then
        local ok, path = pcall(function() return img.Image end)
        if ok and path == monoVcMicUnmutedImg then return true end
    end
    return false
end

function monoVcConnList(fromIndex)
    local out = {}
    local _, internal, getc = monoVcFetch()
    if not internal or not getc then return out end
    local list = nil
    local ok = pcall(function() list = getc(internal.StateChanged) end)
    if not ok or type(list) ~= "table" then return out end
    for i, c in ipairs(list) do
        if not fromIndex or i >= fromIndex then out[#out + 1] = c end
    end
    return out
end

function monoVcCapture(list)
    monoVc.disabled = {}
    local n = 0
    for _, c in ipairs(list or {}) do
        if pcall(function() c:Disable() end) then n = n + 1 end
    end
    monoVc.disabled = list or {}
    return n
end

function monoVcRelease()
    local n = 0
    for _, c in ipairs(monoVc.disabled) do
        if pcall(function() c:Enable() end) then n = n + 1 end
    end
    monoVc.disabled = {}
    return n
end

function monoVcGui()
    if monoVc.gui and monoVc.gui.Parent then return monoVc.gui end
    local h = gethui
    if h then
        local ok, g = pcall(function() return h() end)
        if ok and g then
            monoVc.gui = g
            return g
        end
    end
    monoVc.gui = CoreGui
    return CoreGui
end

local MONO_VC_OVERLAY_PREFIX = "MonoVcOverlay"

function monoVcIsOverlay(inst)
    if not inst or not inst:IsA("BillboardGui") then return false end
    local n = inst.Name
    return n == MONO_VC_OVERLAY_PREFIX or n:sub(1, #MONO_VC_OVERLAY_PREFIX + 1) == MONO_VC_OVERLAY_PREFIX .. "_"
end

function _monoVcOverlayOwner(inst)
    if not monoVcIsOverlay(inst) then return nil end
    local fromAttr = tonumber(inst:GetAttribute("MonoUserId"))
    if fromAttr then return fromAttr end
    local fromName = tonumber(inst.Name:match("^MonoVcOverlay_(%d+)$"))
    if fromName then return fromName end
    local adornee = inst.Adornee
    local model = adornee and adornee:FindFirstAncestorOfClass("Model")
    local owner = model and Players:GetPlayerFromCharacter(model)
    return owner and owner.UserId or nil
end

function monoVcOverlayHosts()
    local hosts, seen = {}, {}
    local function add(host)
        if host and typeof(host) == "Instance" and not seen[host] then
            seen[host] = true
            hosts[#hosts + 1] = host
        end
    end
    add(monoGuiRoot())
    add(CoreGui)
    add(PlayerGui)
    add(monoVcGui())
    return hosts
end

MONO_VC_DEFER_NATIVE = true
monoVc.nativeScan = { at = 0, any = false }

local function monoVcLooksLikeNativeVoice(bill)
	if not bill or not bill:IsA("BillboardGui") then return false end

	if monoVcIsOverlay(bill) then return false end
	local billName = string.lower(tostring(bill.Name or ""))
	
	
	if billName:find("m7voiceoverhead", 1, true) then return false end
	if billName:find("voice", 1, true)
		or billName:find("speaker", 1, true)
		or billName:find("mic", 1, true) then
		return true
	end
	local found = false
	pcall(function()
		for _, d in ipairs(bill:GetDescendants()) do
			local dn = string.lower(tostring(d.Name or ""))
			if dn == "playerbuttons" or dn == "microphonebubble"
				or dn:find("voice", 1, true) or dn:find("speaker", 1, true)
				or (dn:find("mic", 1, true) and not dn:find("mono", 1, true)) then
				found = true
				break
			end
			if d:IsA("ImageLabel") or d:IsA("ImageButton") then
				local img = tostring(d.Image or ""):lower()
				if img:find("voicechat", 1, true) or img:find("miclight", 1, true)
					or img:find("speakerlight", 1, true) or img:find("img_set_1x_5", 1, true)
					or img:find("voice", 1, true) then
					found = true
					break
				end
			end
		end
	end)
	return found
end

function monoVcRefreshNativeScan()
	local now = tick()
	if monoVc.nativeScan and (now - monoVc.nativeScan.at) < 0.4 then return end
	local any = false
	local function consider(bill)
		if monoVcLooksLikeNativeVoice(bill) then
			any = true
		end
	end

	pcall(function()
		local ec = CoreGui:FindFirstChild("ExperienceChat")
		local screen = ec and ec:FindFirstChild("bubbleChat")
		if screen then
			for _, bill in ipairs(screen:GetChildren()) do consider(bill) end
		end
	end)

	if not any then
		for _, host in ipairs(monoVcOverlayHosts()) do
			pcall(function()
				for _, d in ipairs(host:GetDescendants()) do
					if d:IsA("BillboardGui") then consider(d) end
				end
			end)
		end
	end

	monoVc.nativeScan = { at = now, any = any }
end

function monoVcInvalidateNativeScan()
	if monoVc.nativeScan then monoVc.nativeScan.at = 0 end
end

function monoVcNativeSuppressAll()
	if not MONO_VC_DEFER_NATIVE then return false end
	if monoVc.nativeSuppressedAll == true then return true end
	monoVcRefreshNativeScan()
	if monoVc.nativeScan.any == true then
		monoVc.nativeSuppressedAll = true
		return true
	end
	return false
end

function monoVcApplyNativeSuppression()
	if not monoVcNativeSuppressAll() then return false end
	if monoVc.nativePurgeDone then return true end
	monoVc.nativePurgeDone = true

	local stray = {}
	for _, host in ipairs(monoVcOverlayHosts()) do
		pcall(function()
			for _, d in ipairs(host:GetDescendants()) do
				if monoVcIsOverlay(d) then stray[#stray + 1] = d end
			end
		end)
	end
	for _, d in ipairs(stray) do
		pcall(function() d:Destroy() end)
	end

	for uid in pairs(monoVc.overlays or {}) do
		monoVcOverlayDropUid(uid)
	end
	return true
end


function monoVcAdoptOverlays()
    local stray = {}
    for _, host in ipairs(monoVcOverlayHosts()) do
        pcall(function()
            for _, d in ipairs(host:GetDescendants()) do
                if monoVcIsOverlay(d) then stray[#stray + 1] = d end
            end
        end)
    end
    for _, d in ipairs(stray) do pcall(function() d:Destroy() end) end
    for uid in pairs(monoVc.overlays or {}) do monoVcOverlayDropUid(uid) end
end

function monoVcPaintMic()
    local img = monoVc.micBtn and monoVcMicIcon(monoVc.micBtn)
    if img then img.Image = monoVc.selfMuted and monoVcMicMutedImg or monoVcMicUnmutedImg end
    if monoVc.micDot then monoVc.micDot.Visible = not monoVc.selfMuted end
end

function monoVcSelfMute(on)
    monoVc.selfMuted = on and true or false
    local _, internal = monoVcFetch()
    if internal then pcall(function() internal:PublishPause(monoVc.selfMuted) end) end
    monoVcPaintMic()
    if monoVcPaintTopbar then pcall(monoVcPaintTopbar) end
end

function monoVcSizeWatch(host)
    if monoVc.sizeConn then return end
    monoVc.sizeConn = RunService.Heartbeat:Connect(function()
        if not monoVc.active then return end
        if not host or not host.Parent then return end
        if host.Size.X.Offset < 140 or host.Size.Y.Offset < 44 then
            pcall(function() host.Size = UDim2.new(0, 140, 0, 44) end)
        end
        if tick() - monoVcPurgeAt > 0.5 then
            monoVcPurgeAt = tick()
            monoVcPurgeMicButtons()
        end
    end)
end

