function monoVcTalkWatch(plr)
    local uid = plr.UserId
    if monoVc.talking[uid] then return end
    local adi = monoMuteAdi(plr)
    if not adi then return end
    local an = adi:FindFirstChild("_M7VoiceAnalyzer")
    if not an or not an:IsA("AudioAnalyzer") then
        local ok, result = pcall(function()
            local audioAnalyzer = Instance.new("AudioAnalyzer")
            audioAnalyzer.Name = "_M7VoiceAnalyzer"
            audioAnalyzer.Parent = adi
            local wire = Instance.new("Wire")
            wire.SourceInstance = adi
            wire.TargetInstance = audioAnalyzer
            wire.Parent = audioAnalyzer
            return audioAnalyzer
        end)
        if not ok or not result then return end
        an = result
    end
    local wr = an:FindFirstChildOfClass("Wire")
    if not wr then
        pcall(function()
            wr = Instance.new("Wire")
            wr.SourceInstance = adi
            wr.TargetInstance = an
            wr.Parent = an
        end)
    end
    monoVc.talking[uid] = { analyzer = an, wire = wr, state = false }
    task.spawn(function()
        pcall(function()
            local muted = adi.Muted
            adi.Muted = true
            task.wait(0.08)
            adi.Muted = muted
        end)
    end)
end

function monoVcTalkDrop(uid)
    local t = monoVc.talking[uid]
    if not t then return end
    if t.wire and t.wire.Parent then pcall(function() t.wire:Destroy() end) end
    if t.analyzer then pcall(function() t.analyzer:Destroy() end) end
    monoVc.talking[uid] = nil
end

function monoVcAdiMuted(plr)
    local adi = monoMuteAdi(plr)
    if not adi then return false end
    for _, name in ipairs({ "Muted", "MutedByLocalUser" }) do
        local ok, v = pcall(function() return adi[name] end)
        if ok and v == true then return true end
    end
    return false
end





local function monoVcIsVoiceSound(inst)
    if not inst or not inst:IsA("Sound") then return false end
    local n = string.lower(tostring(inst.Name or ""))
    return n == "rbxcharactervoice" or n:find("voice", 1, true) ~= nil
end

local function monoVcApplyVoiceVolume(sound, muted, state)
    if not monoVcIsVoiceSound(sound) then return end
    if not muted then
        local vol = state.volumes[sound]
        pcall(function() sound.Volume = vol == nil and 1 or vol end)
        state.volumes[sound] = nil
    else
        if state.volumes[sound] == nil then
            pcall(function() state.volumes[sound] = sound.Volume end)
        end
        pcall(function() sound.Volume = 0 end)
    end
end

function monoVcMuteVoiceTree(plr, muted)
    if not plr or plr == LocalPlayer then return end
    local uid = plr.UserId
    local state = monoVc.voiceMuteState[uid] or {}
    if state.muted == muted and state.char == plr.Character then return end
    if state.descConn then pcall(function() state.descConn:Disconnect() end); state.descConn = nil end
    if state.childConn then pcall(function() state.childConn:Disconnect() end); state.childConn = nil end
    state.muted = muted
    state.char = plr.Character
    state.volumes = state.volumes or {}
    monoVc.voiceMuteState[uid] = state

    local char = plr.Character
    if char then
        for _, d in ipairs(char:GetDescendants()) do
            pcall(monoVcApplyVoiceVolume, d, muted, state)
        end
        if muted then
            state.descConn = char.DescendantAdded:Connect(function(d)
                pcall(monoVcApplyVoiceVolume, d, true, state)
            end)
        end
    end
    if muted then
        state.childConn = plr.ChildAdded:Connect(function(child)
            if child:IsA("AudioDeviceInput") then
                pcall(function() child.Muted = true end)
            end
        end)
    end
end

function monoVcClearVoiceMute(uid)
    local state = monoVc.voiceMuteState[uid]
    if not state then return end
    if state.descConn then pcall(function() state.descConn:Disconnect() end) end
    if state.childConn then pcall(function() state.childConn:Disconnect() end) end
    for sound, vol in pairs(state.volumes or {}) do
        pcall(function() sound.Volume = vol end)
    end
    monoVc.voiceMuteState[uid] = nil
end

function monoVcOverlayDropUid(uid)
    local o = monoVc.overlays[uid]
    if o then
        if o.conn then pcall(function() o.conn:Disconnect() end) end
        if o.charConn then pcall(function() o.charConn:Disconnect() end) end
        if o.bill then pcall(function() o.bill:Destroy() end) end
        monoVc.overlays[uid] = nil
    end
    monoVcTalkDrop(uid)
end

function monoVcOverlayDrop(plr)
    if plr then monoVcOverlayDropUid(plr.UserId) end
end

function monoVcClearOverlays()

end

function monoVcHideOverlay(uid, hidden)

    if hidden == nil then hidden = true end
    hidden = hidden and true or false
    uid = tonumber(uid)
    if not uid then return end
    local entry = monoVc.overlays and monoVc.overlays[uid]
    if entry then
        entry.hidden = hidden
        if entry.bill and entry.bill.Parent then
            pcall(function() entry.bill.Enabled = (not hidden) and not monoVcNativeSuppressAll() end)
        end
    end
end



function monoVcOverlayAdd(plr)
    
    
    if not plr or plr == LocalPlayer then return end
    local uid = plr.UserId
    if monoVc.overlays[uid] then return end
    if monoHiddenPlayers[uid] then return end

    if monoVcApplyNativeSuppression() then return end
    if monoVc.overlays[uid] then return end
    local char = plr.Character
    local root = char and char:FindFirstChild("HumanoidRootPart")
    if not root then return end

    local bill = Instance.new("BillboardGui")
    bill.Name = "MonoVcOverlay_" .. tostring(uid)
    bill:SetAttribute("MonoUserId", uid)
    bill.Size = UDim2.new(0, 30, 0, 30)
    bill.StudsOffsetWorldSpace = Vector3.new(0, monoVcBubbleBaseY, 0)
    bill.Adornee = root
    bill.MaxDistance = math.huge
    bill.AlwaysOnTop = true
    bill.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    bill.LightInfluence = 0
    bill.ResetOnSpawn = false
    bill.Enabled = not monoVcNativeSuppressAll()
    bill.Active = false
    pcall(function() bill.DisplayOrder = MONO_ORDER.Toast end)
    
    
    monoGuiParent(bill)

    local padding = Instance.new("UIPadding")
    padding.Name = "padding"
    padding.Parent = bill
    
    

    local playerButtons = Instance.new("Frame")
    playerButtons.Name = "PlayerButtons"
    playerButtons.Size = UDim2.fromScale(1, 1)
    playerButtons.Position = UDim2.fromScale(0, 0)
    playerButtons.AnchorPoint = Vector2.new(0, 0)
    playerButtons.BackgroundColor3 = Color3.fromRGB(250, 250, 250)
    playerButtons.BackgroundTransparency = 0.1
    playerButtons.Parent = bill
    corner(playerButtons, 8)

    local carat = Instance.new("ImageLabel")
    carat.Name = "Carat"
    carat.Size = UDim2.new(0, 12, 0, 8)
    carat.Position = UDim2.new(0.5, 0, 1, -1)
    carat.AnchorPoint = Vector2.new(0.5, 0)
    carat.BackgroundTransparency = 1
    carat.Image = monoVcCaratImg
    carat.ImageColor3 = Color3.fromRGB(250, 250, 250)
    carat.ImageTransparency = 0.1
    carat.ScaleType = Enum.ScaleType.Stretch
    carat.Visible = false
    carat.Parent = playerButtons
    local caratGradient = Instance.new("UIGradient")
    caratGradient.Name = "CaratGradient"
    caratGradient.Enabled = false
    caratGradient.Parent = carat

    local bubbleGradient = Instance.new("UIGradient")
    bubbleGradient.Name = "BubbleGradient"
    bubbleGradient.Enabled = false
