function monoVcForPlayer(plr)
    
    if not plr or plr == LocalPlayer then return end
    if monoHiddenPlayers[plr.UserId] then return end
    if monoVcNativeSuppressAll() then return end
    task.spawn(function()
        local char = plr.Character
        if not char then char = plr.CharacterAdded:Wait() end
        if not char:WaitForChild("HumanoidRootPart", 10) then return end
        if not char:WaitForChild("Head", 10) then return end
        if not monoVc.active then return end
        monoVcTalkWatch(plr)
        monoVcOverlayAdd(plr)
    end)
end

function monoVcRestoreOverlay(plr)
    if not monoVc.active or not plr or plr == LocalPlayer then return end
    if monoVc.overlays[plr.UserId] then
        monoVcHideOverlay(plr.UserId, false)
        return
    end
    monoVcForPlayer(plr)
end


function monoVcRestoreTopbarMic()
    if monoVc.nativeMicIcon and monoVc.nativeMicIcon.Parent then return end
    local hosts = {}
    pcall(function() hosts[#hosts + 1] = game:GetService("CoreGui") end)
    pcall(function()
        local h = gethui
        local g = h and h()
        if g then hosts[#hosts + 1] = g end
    end)
    for _, host in ipairs(hosts) do
        pcall(function()
            for _, d in ipairs(host:GetDescendants()) do
                if d.Name == "toggle_mic_mute" and not monoVc.nativeMicIcon then
                    local frame = d:FindFirstChild("IntegrationIconFrame")
                    local iconFrame = frame and frame:FindFirstChild("IntegrationIcon")
                    local img = iconFrame and iconFrame:FindFirstChild("1")
                    if img then
                        monoVc.nativeMicIcon = img
                        monoVc.nativeMicDot = iconFrame:FindFirstChild("RedVoiceDot")
                        pcall(function()
                            img.ImageTransparency = 0
                            img.Image = monoVc.selfMuted and monoVcMicMutedImg or monoVcMicUnmutedImg
                        end)
                        for _, c in ipairs(d:GetDescendants()) do
                            if c:IsA("UIGradient") then pcall(function() c.Enabled = false end) end
                            if c.Name == "Highlighter" or c.Name == "SelectedHighlighter" then
                                pcall(function() c.Visible = false end)
                            end
                        end
                    end
                end
            end
        end)
    end
end

function monoVcPaintTopbar()
    local img = monoVc.nativeMicIcon
    if not img or not img.Parent then return end
    local muted = monoVc.selfMuted == true
    pcall(function()
        img.Image = muted and monoVcMicMutedImg or monoVcMicUnmutedImg
        img.ImageTransparency = 0
    end)
    local dot = monoVc.nativeMicDot
    if dot and dot.Parent then pcall(function() dot.Visible = not muted end) end
end

function monoVcPaintAll()
    if not monoVc.active then return end

    if monoVcApplyNativeSuppression() then return end
    local now = tick()
    local myChar = LocalPlayer.Character
    local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
    local myPos = myRoot and myRoot.Position or nil
    for uid, o in pairs(monoVc.overlays) do
        local plr = Players:GetPlayerByUserId(uid)
        if not plr or plr == LocalPlayer then
            
            monoVcOverlayDropUid(uid)
        elseif monoVcNativeSuppressAll() then
            monoVcOverlayDropUid(uid)
        else
            local char = plr.Character
            local root = char and char:FindFirstChild("HumanoidRootPart")
            if root then
                local t = monoVc.talking[uid]
                if t and t.analyzer and t.analyzer.Parent then
                    local okRms, rms = pcall(function() return t.analyzer.RmsLevel end)
                    if okRms and type(rms) == "number" then
                        local th = monoVcTalkThreshold or 0.01
                        if t.state then
                            t.state = rms > th * 0.8
                        else
                            t.state = rms > th * 1.2
                        end
                        if t.state then o.lastTalk = now end
                    end
                    local okPeak, peak = pcall(function() return t.analyzer.PeakLevel end)
                    if okPeak and type(peak) == "number" then
                        local smoothed = t.smoothed or 0
                        if peak > smoothed then
                            smoothed = smoothed * 0.28 + peak * 0.72
                        else
                            smoothed = smoothed * 0.88 + peak * 0.12
                        end
                        t.smoothed = smoothed
                    end
                end

                local tracked = monoMutedPlayers[uid]
                local muted = (tracked and not tracked.manuallyUnmuted) or monoVcAdiMuted(plr)
                local talking = (t and t.state) or false
                local enabled = muted or talking or (now - (o.lastTalk or 0) < 1.0)
                local distanceOk = true
                if myPos then distanceOk = (myPos - root.Position).Magnitude <= 50 end
                local show = enabled and distanceOk and not o.hidden and not monoVcNativeSuppressAll()

                local stacked = monoStackMirrors and monoStackMirrors[uid] ~= nil
                pcall(function()
                    o.bill.Adornee = root
                    o.bill.Enabled = show and not stacked
                    o.bill.Active = show and not stacked
                end)
                if o.playerButtons then o.playerButtons.Visible = distanceOk end
                if o.distant then o.distant.Visible = (not distanceOk) and show end

                
                local vcY = monoVcBubbleY and monoVcBubbleY(uid) or (monoVcBubbleBaseY or 4.6)
                pcall(function()
                    o.bill.StudsOffsetWorldSpace = Vector3.new(0, vcY, 0)
                    if monoNativeOverlap and monoNativeOverlap.vc then
                        monoNativeOverlap.vc[uid] = { active = show, y = vcY }
                    end
                end)

                if o.icon and show then
                    local frame
                    if talking then
                        local fi = (math.floor(now * 20) % #monoVcVoiceFrames) + 1
                        frame = monoVcVoiceFrames[fi]
                    elseif muted then
                        frame = monoVcVoiceMutedFrame
                    else
                        frame = monoVcVoiceTalkFrame
                    end
                    if o.frame ~= frame then
                        o.frame = frame
                        pcall(function() o.icon.ImageRectOffset = frame end)
                    end
                end
                local m = monoStackMirrors and monoStackMirrors[uid]
                if m and m.voice then pcall(function() m.voice.Visible = show end) end
                if m and m.voiceIcon and o.icon then
                    pcall(function() m.voiceIcon.ImageRectOffset = o.icon.ImageRectOffset end)
                end
            end
        end
    end
    monoVcPaintTopbar()
end

function monoVcBuildUI()
    if monoVc.built then return end
    monoVc.built = true
    if not monoVcMakeMicButton() then
        notify("Monochrome", "Bypass is live but the mic button path changed", 4)
    end
    if monoVcRestoreTopbarMic then pcall(monoVcRestoreTopbarMic) end
    monoVcAdoptOverlays()
    for _, p in ipairs(Players:GetPlayers()) do monoVcForPlayer(p) end
    if not monoVc.addedConn then

        monoVc.addedConn = Players.PlayerAdded:Connect(function(p)
            if monoVcNativeSuppressAll() then return end
            monoVcForPlayer(p)
        end)
    end
    if not monoVc.removingConn then
        monoVc.removingConn = Players.PlayerRemoving:Connect(function(p)
            monoVcOverlayDrop(p)
        end)
    end
    if not monoVc.nativeConn then
        monoVc.nativeConn = CoreGui.DescendantAdded:Connect(function(obj)
            local n = obj.Name
            local interesting = n == "bubbleChat" or n == "ExperienceChat"
                or n == "MicrophoneBubble" or n == "PlayerButtons"
                or (obj:IsA("BillboardGui") and n:sub(1, #"BubbleChat_") == "BubbleChat_")
            if interesting then monoVcInvalidateNativeScan() end
        end)
    end
    if not monoVc.paintConn then
        monoVc.paintConn = RunService.Heartbeat:Connect(monoVcPaintAll)
    end
end

function monoVcStashMicButton()
    local _, three = monoVcMicPath()
    if not three then return nil end
    local btn = three:FindFirstChild("toggle_mic_mute", true)
    if not btn then return nil end
    local folder = nil
    pcall(function()
        local rs = game:GetService("RobloxReplicatedStorage")
        folder = rs:FindFirstChild("_MonoVcStash")
        if not folder then
            folder = Instance.new("Folder")
            folder.Name = "_MonoVcStash"
            folder.Parent = rs
        end
    end)
    if folder then pcall(function() btn.Parent = folder end) end
    monoVc.stashedMic = btn
    return btn
end

function monoVcRestoreStash()
    if not monoVc.stashedMic then return end
    local btn = monoVc.stashedMic
    monoVc.stashedMic = nil
    local _, three = monoVcMicPath()
    pcall(function()
        local rs = game:GetService("RobloxReplicatedStorage")
        local folder = rs:FindFirstChild("_MonoVcStash")
        if folder and #folder:GetChildren() == 0 then folder:Destroy() end
    end)
    if not three then return end
    pcall(function()
        btn.Name = "toggle_mic_mute"
        btn.Parent = three
    end)
end

function monoVcRouteMonochrome()
    local svc, internal = monoVcFetch()
    if not svc or not internal then return "no_service" end
    pcall(function() svc:rejoinVoice() end)
    task.wait(0.02)
    monoVcCapture(monoVcConnList())
    return "ok"
end

function monoVcRouteM7()
    local svc, internal = monoVcFetch()
    if not svc or not internal then return "no_service" end
    pcall(function() internal:PublishPause(false) end)
    task.wait(4)
    pcall(function() svc:leaveVoice() end)
    task.wait(2)
    monoVcCapture(monoVcConnList())
    task.wait(1)
    pcall(function() svc:joinVoice() end)
    return "ok"
end

