function monoVcRouteSchwein()
    local svc, internal = monoVcFetch()
    if not svc or not internal then return "no_service" end
    monoVcStashMicButton()
    task.wait(1)
    pcall(function() svc:leaveVoice() end)
    task.wait(2)
    monoVcCapture(monoVcConnList(7))
    task.wait(2)
    local joinDone, joinOk = false, false
    local joinWait = tick()
    task.spawn(function()
        joinOk = pcall(function() svc:joinVoice() end)
        joinDone = true
    end)
    while not joinDone and tick() - joinWait < 8 do task.wait(0.1) end
    task.wait(2)
    local reconnected = false
    local deadline = tick() + 20
    local conn = nil
    pcall(function()
        if internal and internal.StateChanged then
            conn = internal.StateChanged:Connect(function(_, new)
                local n = string.lower(tostring(new and (new.Name or new) or ""))
                if n:find("join", 1, true) or n:find("connect", 1, true)
                    or n:find("ingame", 1, true) or n:find("active", 1, true)
                    or n:find("joined", 1, true) then
                    reconnected = true
                end
            end)
        end
    end)
    while tick() < deadline and not reconnected do
        pcall(function()
            local st = internal and internal.VoiceChatState
            if st then
                local n = string.lower(tostring(st.Name or st))
                if n:find("join", 1, true) or n:find("connect", 1, true)
                    or n:find("ingame", 1, true) or n:find("joined", 1, true) then
                    reconnected = true
                end
            end
        end)
        if not reconnected then
            pcall(function()
                local adi = monoMuteAdi(LocalPlayer)
                if adi and adi.Active ~= nil then reconnected = true end
            end)
        end
        if joinDone and joinOk and tick() > (joinWait + 1.25) then reconnected = true end
        task.wait(0.2)
    end
    if conn then pcall(function() conn:Disconnect() end) end
    return reconnected and "ok" or "ok_quiet"
end

function monoVcRouteVm()
    local svc, internal = monoVcFetch()
    if not svc or not internal then return "no_service" end
    monoVcStashMicButton()

    pcall(function() svc:leaveVoice() end)
    task.wait(2)
    monoVcCapture(monoVcConnList(7))
    task.wait(2)
    pcall(function() svc:joinVoice() end)
    return "ok"
end

function _monoVcStop()
    local restored = monoVcRelease()
    if monoVc.addedConn then
        pcall(function() monoVc.addedConn:Disconnect() end)
        monoVc.addedConn = nil
    end
    if monoVc.removingConn then
        pcall(function() monoVc.removingConn:Disconnect() end)
        monoVc.removingConn = nil
    end
    if monoVc.sizeConn then
        pcall(function() monoVc.sizeConn:Disconnect() end)
        monoVc.sizeConn = nil
    end
    if monoVc.propConn then
        pcall(function() monoVc.propConn:Disconnect() end)
        monoVc.propConn = nil
    end
    if monoVc.paintConn then
        pcall(function() monoVc.paintConn:Disconnect() end)
        monoVc.paintConn = nil
    end
    if monoVc.nativeConn then
        pcall(function() monoVc.nativeConn:Disconnect() end)
        monoVc.nativeConn = nil
    end
    monoVcClearOverlays()
    monoVcClearMic()
    monoVc.selfMuted = false
    local _, internal = monoVcFetch()
    if internal then pcall(function() internal:PublishPause(false) end) end
    local method = monoVc.method
    monoVc.method = ""
    monoVc.active = false
    monoVc.starting = false
    monoVc.built = false
    monoVc.nativeSuppressedAll = false
    monoVc.nativePurgeDone = false
    monoVc.nativeScan = { at = 0, any = false }
    MONO_VC_DEFER_NATIVE = true
    monoVcSetLoaded(false)
    if type(setData) == "table" and setData.vcBypassRan ~= "" then
        setData.vcBypassRan = ""
        if type(setSave) == "function" then setSave() end
    end
    notify("Monochrome", method .. " bypass off, " .. restored .. " connections restored", 3)
end

function monoVcRunBody(method, route)
    local svc, internal, getc = monoVcFetch()
    if not svc then
        notify("Monochrome", "This game has no VoiceChatService", 4)
        monoVc.starting = false
        monoVc.method = ""
        monoVcSetLoaded(false)
        return
    end
    if not internal then
        notify("Monochrome", "This game has no VoiceChatInternal", 4)
        monoVc.starting = false
        monoVc.method = ""
        monoVcSetLoaded(false)
        return
    end
    if not getc then
        notify("Monochrome", "getconnections is unavailable on this executor", 4)
        monoVc.starting = false
        monoVc.method = ""
        monoVcSetLoaded(false)
        return
    end
    if not monoVcMicUnmuted() then
        monoVc.starting = true
        monoVc.method = method
        notify("Monochrome", "Unmute your mic to continue", 3)
        local waited = tick() + 60
        while not monoVcMicUnmuted() and tick() < waited do
            task.wait(0.5)
        end
        monoVc.starting = false
        if not monoVcMicUnmuted() then
            notify("Monochrome", "Mic stayed muted, " .. method .. " cancelled", 4)
            monoVc.starting = false
            monoVc.method = ""
            monoVcSetLoaded(false)
            return
        end
        task.wait(1)
    end
    monoVc.starting = false
    monoVc.active = true
    monoVc.method = method
    notify("Monochrome", "Starting " .. method .. " voice bypass", 3)
    local ok, result = pcall(route)
    if not ok or (result ~= "ok" and result ~= "ok_quiet") then
        monoVc.active = false
        monoVc.method = ""
        monoVcSetLoaded(false)
        monoVcRelease()
        notify("Monochrome", method .. " bypass could not start", 4)
        return
    end
    
    
    
    MONO_VC_DEFER_NATIVE = false
    monoVcInvalidateNativeScan()
    monoVcBuildUI()
    if type(setData) == "table" then
        setData.vcBypassRan = tostring(method or monoVc.method or "")
        if type(setSave) == "function" then setSave() end
    end
    if result == "ok_quiet" then
        notify("Monochrome", method .. " active, voice reconnect not confirmed", 4)
    else
        notify("Monochrome", method .. " voice bypass active", 3)
    end
end

function monoVcRun(method, route)
    if not monoLoadDone then return end
    if monoVcIsLoaded() or monoVc.active or monoVc.starting then
        local current = monoVc.method ~= "" and monoVc.method or "a"
        notify("Monochrome", "Cannot run, " .. current .. " bypass is already loaded", 4)
        return
    end
    monoVc.nativeSuppressedAll = false
    monoVc.nativePurgeDone = false
    monoVc.nativeScan = { at = 0, any = false }
    monoVc.starting = true
    monoVc.method = method
    monoVcSetLoaded(true)
    task.spawn(function()
        pcall(monoVcRunBody, method, route)
    end)
end

