function monoExtRowBtn(parent, text, size, pos, textSize)
    local b = create("TextButton", {
        Size = size, Position = pos,
        BackgroundColor3 = C.surface, BackgroundTransparency = 0.4, BorderSizePixel = 0,
        Text = text, TextColor3 = C.text, TextSize = textSize or 11,
        Font = Enum.Font.GothamBold, AutoButtonColor = false,
        TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd,
        ClipsDescendants = true,
    }, parent)
    corner(b, 6); stroke(b, C.borderSoft, 1, 0.55)
    b.MouseEnter:Connect(function() tween(b, { BackgroundTransparency = 0.15 }, 0.15) end)
    b.MouseLeave:Connect(function() tween(b, { BackgroundTransparency = 0.4 }, 0.15) end)
    b.MouseButton1Down:Connect(function() monoPanelPress(b) end)
    return b
end

function monoExtWindow(opts)
    if not monoLoadDone then return nil end

    local folder = opts.folder
    local extWin = {
        teardown = nil, onClose = nil, close = nil, entry = nil, content = nil, scroll = nil,
        search = nil, status = nil, statusLabel = nil, tabs = nil, chipsRowRef = nil,
        extra = nil, saveExtra = nil, isFav = nil, toggleFav = nil, favs = nil, saveFavs = nil,
        refresh = nil, showTab = nil, getTab = nil, setTabs = nil, setChips = nil, setItems = nil,
    }

    local function shutdown()
        if extWin.teardown then pcall(extWin.teardown) end
        if extWin.onClose then pcall(extWin.onClose) end
    end

    local previous = monoExtLive[opts.panelName]
    if previous then shutdown() end

    local extra = {}
    local extraPath = configPath(folder, "settings")
    if opts.extra then
        extra = opts.extra
    elseif typeof(readfile) == "function" and typeof(isfile) == "function" then
        pcall(function()
            if isfile(extraPath) then
                local okDec, decoded = pcall(function()
                    return HttpService:JSONDecode(readfile(extraPath))
                end)
                if okDec and type(decoded) == "table" then extra = decoded end
            end
        end)
    end

    local function saveExtra()
        if typeof(writefile) ~= "function" then return end
        ensureFolder(folder)
        pcall(function() writefile(extraPath, HttpService:JSONEncode(extra)) end)
    end

    local favs = {}
    local favPath = configPath(folder, "favorites")
    if typeof(readfile) == "function" and typeof(isfile) == "function" then
        pcall(function()
            if isfile(favPath) then
                local okDec, decoded = pcall(function()
                    return HttpService:JSONDecode(readfile(favPath))
                end)
                if okDec and type(decoded) == "table" then favs = decoded end
            end
        end)
    end

    local function saveFavs()
        if typeof(writefile) ~= "function" then return end
        ensureFolder(folder)
        pcall(function() writefile(favPath, HttpService:JSONEncode(favs)) end)
    end

    local function isFav(id) return favs[tostring(id)] == true end

    local function toggleFav(id)
        local key = tostring(id)
        if favs[key] then
            favs[key] = nil
            saveFavs()
            return false
        end
        favs[key] = true
        saveFavs()
        return true
    end

    local entry = monoPanelOpen(opts.panelName, opts.title, opts.contentH, function()
        shutdown()
        monoExtLive[opts.panelName] = nil
        monoPanelDrop(opts.panelName)
    end)
    if not entry then return nil end

    local content = entry.content
    for _, child in ipairs(content:GetChildren()) do
        if child:IsA("UIListLayout") or child:IsA("UIPadding") then
            pcall(function() child:Destroy() end)
        end
    end

    local status = monoPanelSection(content, 0)
    status.Size = UDim2.new(1, -16, 0, 20)
    status.Position = UDim2.new(0, 8, 0, 0)
    local statusLabel = create("TextLabel", {
        Size = UDim2.new(1, -20, 1, 0), Position = UDim2.new(0, 10, 0, 0),
        BackgroundTransparency = 1, Text = opts.statusText,
        TextColor3 = C.text, TextSize = 10, Font = Enum.Font.Gotham,
        TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd,
    }, status)

    local tabBar = create("Frame", {
        Size = UDim2.new(1, -16, 0, 24), Position = UDim2.new(0, 8, 0, 26),
        BackgroundTransparency = 1,
    }, content)
    create("UIListLayout", {
        Padding = UDim.new(0, 3), FillDirection = Enum.FillDirection.Horizontal,
        HorizontalAlignment = Enum.HorizontalAlignment.Center,
        SortOrder = Enum.SortOrder.LayoutOrder,
    }, tabBar)

    local tabButtons = {}
    local currentTab = opts.tabs[1]
    local showTab

    local function renderTabs(list)
        for _, b in pairs(tabButtons) do pcall(function() b:Destroy() end) end
        tabButtons = {}
        for i, tabName in ipairs(list) do
            local tabBtn = monoExtRowBtn(tabBar, "  " .. tabName .. "  ", UDim2.new(0, 0, 1, 0), UDim2.new(0, 0, 0, 0), 10)
            tabBtn.AutomaticSize = Enum.AutomaticSize.X
            tabBtn.ClipsDescendants = false
            tabBtn.TextXAlignment = Enum.TextXAlignment.Center
            tabBtn.LayoutOrder = i
            local function paintTab(on)
                tween(tabBtn, { BackgroundTransparency = on and 0.15 or 0.4 }, 0.15)
                tabBtn.TextColor3 = on and C.text or C.textDim
            end
            paintTab(tabName == currentTab)
            tabBtn.MouseEnter:Connect(function() paintTab(true) end)
            tabBtn.MouseLeave:Connect(function() paintTab(tabName == currentTab) end)
            tabBtn.MouseButton1Click:Connect(function() showTab(tabName) end)
            tabButtons[tabName] = tabBtn
        end
    end

    local chipsRowRef = nil
    local topOffset = 0
    if opts.chips and #opts.chips > 0 then
        chipsRowRef = create("ScrollingFrame", {
            Size = UDim2.new(1, -16, 0, 24), Position = UDim2.new(0, 8, 0, 56),
            BackgroundTransparency = 1, BorderSizePixel = 0,
            ScrollBarThickness = 0, ScrollBarImageTransparency = 1,
            ScrollingDirection = Enum.ScrollingDirection.X,
            CanvasSize = UDim2.new(0, 0, 0, 0),
        }, content)
        pcall(function() chipsRowRef.AutomaticCanvasSize = Enum.AutomaticSize.X end)
        create("UIListLayout", {
            Padding = UDim.new(0, 4), FillDirection = Enum.FillDirection.Horizontal,
            HorizontalAlignment = Enum.HorizontalAlignment.Left,
            VerticalAlignment = Enum.VerticalAlignment.Center,
            SortOrder = Enum.SortOrder.LayoutOrder,
        }, chipsRowRef)
        chipsRowRef.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseWheel then
                local maxX = math.max(chipsRowRef.AbsoluteCanvasSize.X - chipsRowRef.AbsoluteWindowSize.X, 0)
                chipsRowRef.CanvasPosition = Vector2.new(
                    math.clamp(chipsRowRef.CanvasPosition.X - input.Position.Z * 60, 0, maxX), 0)
            end
        end)
        topOffset = 30
    end

    local function renderChips(list)
        if not chipsRowRef then return end
        for _, c in ipairs(chipsRowRef:GetChildren()) do
            if c:IsA("TextButton") then pcall(function() c:Destroy() end) end
        end
        for i, chip in ipairs(list) do
            local cb = monoExtRowBtn(chipsRowRef, "  " .. chip.label .. "  ", UDim2.new(0, 0, 1, 0), UDim2.new(0, 0, 0, 0), 10)
            cb.AutomaticSize = Enum.AutomaticSize.X
            cb.ClipsDescendants = false
            cb.TextXAlignment = Enum.TextXAlignment.Center
            cb.LayoutOrder = i
            cb.TextColor3 = chip.active and C.text or C.textDim
            cb.MouseButton1Click:Connect(function()
                if chip.action then pcall(function() chip.action() end) end
            end)
        end
    end
    renderChips(opts.chips or {})

    local search = create("TextBox", {
        Size = UDim2.new(1, -16, 0, 24), Position = UDim2.new(0, 8, 0, 56 + topOffset),
        BackgroundColor3 = C.input, BackgroundTransparency = 0.4, BorderSizePixel = 0,
        Text = "", PlaceholderText = opts.placeholder, PlaceholderColor3 = C.textDim,
        TextColor3 = C.text, TextSize = 10, Font = Enum.Font.Gotham,
        TextXAlignment = Enum.TextXAlignment.Left, ClearTextOnFocus = false,
    }, content)
    corner(search, 6); stroke(search, C.borderSoft, 1, 0.6)
search.Focused:Connect(function() search.Text = "" end)

    local listBox = create("Frame", {
        Size = UDim2.new(1, -16, 0, opts.listHeight), Position = UDim2.new(0, 8, 0, 86 + topOffset),
        BackgroundTransparency = 1, ClipsDescendants = true,
    }, content)
    create("UIPadding", { PaddingRight = UDim.new(0, 2) }, listBox)

    local scroll = create("ScrollingFrame", {
        Size = UDim2.new(1, 0, 1, 0), BackgroundTransparency = 1, BorderSizePixel = 0,
        ScrollBarThickness = 3, ScrollBarImageColor3 = C.border,
        CanvasSize = UDim2.new(0, 0, 0, 0),
    }, listBox)
    create("UIListLayout", {
        Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder,
    }, scroll)

    local function buildRow(item, index)
        local row = create("Frame", {
            Size = UDim2.new(1, 0, 0, 32), BackgroundTransparency = 1,
            LayoutOrder = index, ClipsDescendants = true,
        })

        local nameBtn = monoExtRowBtn(row, item.name, UDim2.new(1, opts.noFav and 0 or -30, 1, 0), UDim2.new(0, 0, 0, 0))
        nameBtn.MouseButton1Click:Connect(function() opts.onPick(item) end)

        if not opts.noFav then
            local starred = isFav(item.id)
            local star = create("TextButton", {
                Size = UDim2.new(0, 30, 0, 32), Position = UDim2.new(1, -30, 0, 0),
                BackgroundTransparency = 1, BorderSizePixel = 0,
                Text = starred and monoStarOn or monoStarOff,
                TextColor3 = starred and C.accent or C.textDim,
                TextSize = 13, Font = Enum.Font.GothamBold, AutoButtonColor = false, ZIndex = 2,
            }, row)
            star.MouseButton1Click:Connect(function()
                local now = toggleFav(item.id)
                star.Text = now and monoStarOn or monoStarOff
                star.TextColor3 = now and C.accent or C.textDim
                if opts.onFavToggle then pcall(function() opts.onFavToggle(item, now) end) end
            end)
        end

        return row
    end

    local visible = {}
    local loadedRows = {}
    local BATCH_SIZE = 20
    local ROW_HEIGHT = 36
    local isLoading = false

    local function updateVisible(searchTerm)
        visible = {}
        local term = string.lower(searchTerm)
        for i, item in ipairs(opts.items) do
            local matches = term == "" or string.lower(item.name):find(term, 1, true)
            if currentTab == "Favorites" then
                if isFav(item.id) and matches then
                    table.insert(visible, { item = item, index = i })
                end
            elseif matches then
                table.insert(visible, { item = item, index = i })
            end
        end
        for _, row in ipairs(loadedRows) do
            pcall(function() row:Destroy() end)
        end
        loadedRows = {}
        scroll.CanvasSize = UDim2.new(0, 0, 0, 0)
        statusLabel.Text = #visible .. " " .. opts.noun .. " found"
    end

    local function loadBatch(startIdx, count)
        if isLoading then return end
        isLoading = true
        local endIdx = math.min(startIdx + count - 1, #visible)
        for i = startIdx, endIdx do
            local row = visible[i]
            if row then
                local built = buildRow(row.item, row.index)
                built.Parent = scroll
                table.insert(loadedRows, built)
            end
        end
        scroll.CanvasSize = UDim2.new(0, 0, 0, #loadedRows * ROW_HEIGHT)
        isLoading = false
    end

    local function refresh()
        updateVisible(search.Text)
        loadBatch(1, BATCH_SIZE)
        scroll.CanvasPosition = Vector2.new(0, 0)
    end

    local function checkLoadMore()
        if isLoading or #loadedRows >= #visible then return end
        local buffer = ROW_HEIGHT * BATCH_SIZE * 2
        if scroll.CanvasPosition.Y + scroll.AbsoluteWindowSize.Y + buffer > scroll.CanvasSize.Y.Offset then
            loadBatch(#loadedRows + 1, BATCH_SIZE)
        end
    end

    showTab = function(name)
        for tabName, btn in pairs(tabButtons) do
            btn.TextColor3 = tabName == name and C.text or C.textDim
            tween(btn, { BackgroundTransparency = tabName == name and 0.15 or 0.4 }, 0.15)
        end
        currentTab = name
        if opts.onTab then opts.onTab(name, extWin) end
        local skipped = false
        for _, skipName in ipairs(opts.skipTabs or {}) do
            if skipName == name then skipped = true end
        end
        if not skipped then refresh() end
    end

    renderTabs(opts.tabs)

    local searchPending = false
    local searchThread = nil

    search:GetPropertyChangedSignal("Text"):Connect(function()
        if not search.Visible then return end
        searchPending = true
        if searchThread then pcall(function() task.cancel(searchThread) end) end
        searchThread = task.delay(0.3, function()
            if not searchPending then return end
            searchPending = false
            if search.Visible then refresh() end
        end)
    end)

    local scrollConn = RunService.Heartbeat:Connect(function()
        if entry.frame and entry.frame.Parent and scroll.Visible then checkLoadMore() end
    end)

    extWin.entry = entry
    extWin.content = content
    extWin.scroll = scroll
    extWin.search = search
    extWin.status = status
    extWin.statusLabel = statusLabel
    extWin.tabs = tabButtons
    extWin.chipsRowRef = chipsRowRef
    extWin.extra = extra
    extWin.saveExtra = saveExtra
    extWin.isFav = isFav
    extWin.toggleFav = toggleFav
    extWin.favs = favs
    extWin.saveFavs = saveFavs
    extWin.refresh = refresh
    extWin.showTab = showTab
    extWin.getTab = function() return currentTab end
    extWin.setTabs = function(list)
        renderTabs(list)
        for tabName, btn in pairs(tabButtons) do
            btn.TextColor3 = tabName == currentTab and C.text or C.textDim
            btn.BackgroundTransparency = tabName == currentTab and 0.15 or 0.4
        end
    end
    extWin.setChips = function(list) renderChips(list) end
    extWin.setItems = function(list, noun, placeholder, statusText)
        opts.items = list or {}
        if noun then opts.noun = noun end
        if placeholder then search.PlaceholderText = placeholder end
        if statusText then statusLabel.Text = statusText end
        search.Text = ""
        refresh()
    end
    extWin.onClose = opts.onClose
    extWin.close = function() monoPanelClose(opts.panelName) end
    extWin.teardown = function()
        pcall(function() scrollConn:Disconnect() end)
        if searchThread then pcall(function() task.cancel(searchThread) end) end
    end

    trackConn(scrollConn)
    monoExtLive[opts.panelName] = extWin

    updateVisible("")
    loadBatch(1, BATCH_SIZE)
    return extWin
end

monoAnimFolder = "Monochrome/animations"

function monoAnimLoadCache()
    local cache = {}
    if typeof(readfile) ~= "function" or typeof(isfile) ~= "function" then return cache end
    local path = configPath(monoAnimFolder, "cache")
    pcall(function()
        if isfile(path) then
            local okDec, decoded = pcall(function() return HttpService:JSONDecode(readfile(path)) end)
            if okDec and type(decoded) == "table" then cache = decoded end
        end
    end)
    return cache
end

function monoAnimSaveCache(cache)
    if typeof(writefile) ~= "function" then return end
    ensureFolder(monoAnimFolder)
    local path = configPath(monoAnimFolder, "cache")
    pcall(function() writefile(path, HttpService:JSONEncode(cache)) end)
end

function monoAnimWalk(parent, parentPath, mappings)
    for _, child in ipairs(parent:GetChildren()) do
        if child:IsA("Animation") then
            local pathParts = string.split(parentPath .. "." .. child.Name, ".")
            local weights = {}
            for _, wChild in ipairs(child:GetChildren()) do
                if wChild:IsA("NumberValue") and wChild.Name == "Weight" then
                    table.insert(weights, wChild.Value)
                end
            end
            table.insert(mappings, {
                category = pathParts[#pathParts - 1],
                name = pathParts[#pathParts],
                animationId = child.AnimationId,
                weights = weights,
            })
        elseif #child:GetChildren() > 0 then
            monoAnimWalk(child, parentPath .. "." .. child.Name, mappings)
        end
    end
end

function monoAnimResolve(bundledItems)
    local mappings = {}
    for _, assetIds in pairs(bundledItems) do
        for _, assetId in pairs(assetIds) do
            local okGet, objects = pcall(function()
                return game:GetObjects("rbxassetid://" .. assetId)
            end)
            if okGet and objects then
                for _, obj in ipairs(objects) do
                    monoAnimWalk(obj, obj.Name, mappings)
                    obj.Parent = workspace
                    task.delay(1, function() if obj then pcall(function() obj:Destroy() end) end end)
                end
            end
        end
    end
    return mappings
end

function monoAnimMappings(cache, pack)
    if not pack.bundledItems then return {} end
    local cacheKey = tostring(pack.id)
    local mappings = cache[cacheKey]
    if mappings and #mappings > 0 and mappings._version ~= 2 then mappings = nil end
    if not mappings then
        mappings = monoAnimResolve(pack.bundledItems)
        if #mappings > 0 then
            mappings._version = 2
            cache[cacheKey] = mappings
            task.spawn(monoAnimSaveCache, cache)
        end
    end
    return mappings or {}
end

function monoAnimMapOf(mappings, onlyCategory)
    local want = onlyCategory and string.lower(onlyCategory) or nil
    local mappingMap = {}
    for _, m in ipairs(mappings) do
        local cat = string.lower(m.category)
        if not want or cat == want then
            if not mappingMap[cat] then
                mappingMap[cat] = { folderName = m.category, items = {}, count = 0 }
            end
            local slot = mappingMap[cat].items
            if slot[string.lower(m.name)] == nil then
                mappingMap[cat].count = mappingMap[cat].count + 1
            end
            slot[string.lower(m.name)] = m
        end
    end
    return mappingMap
end

function monoAnimTitle(cat)
    return string.upper(string.sub(cat, 1, 1)) .. string.sub(cat, 2)
end

function monoAnimFetchPacks()
    local packs = {}
    local urls = {
        "https://raw.githubusercontent.com/7yd7/sniper-Emote/refs/heads/test/AnimationSniper.json",
        "https://raw.githubusercontent.com/7yd7/sniper-Emote/refs/heads/test/AnimationSniperoffsale.json",
    }
    for _, url in ipairs(urls) do
        local okGet, body = pcall(function() return game:HttpGet(url) end)
        if okGet and body and body ~= "" then
            local okDec, decoded = pcall(function() return HttpService:JSONDecode(body) end)
            if okDec and type(decoded) == "table" and decoded.data then
                for _, pack in ipairs(decoded.data) do
                    table.insert(packs, pack)
                end
            end
        end
    end
    return packs
end



function monoAnimFindAnimateFolder(animate, name)
    if not animate or type(name) ~= "string" or name == "" then return nil end
    local folder = animate:FindFirstChild(name)
    if folder then return folder end
    local lower = string.lower(name)
    folder = animate:FindFirstChild(lower)
    if folder then return folder end
    folder = animate:FindFirstChild(string.upper(string.sub(name, 1, 1)) .. string.sub(name, 2))
    if folder then return folder end
    for _, child in ipairs(animate:GetChildren()) do
        if string.lower(child.Name) == lower then return child end
    end
    return nil
end

local function monoAnimSlotName(folder, index, anims)
    local prefix = "Animation"
    local first = anims[1]
    if first then
        local p = string.match(first.Name, "^(.-)%d+$")
        if p and p ~= "" then prefix = p end
    end
    local name = prefix .. tostring(index)
    if folder:FindFirstChild(name) then name = name .. "_Mono" .. tostring(index) end
    return name
end





function monoAnimWriteSlots(folder, ids, weightsList)
    if not folder or type(ids) ~= "table" or #ids == 0 then return 0 end
    local anims = {}
    for _, child in ipairs(folder:GetChildren()) do
        if child:IsA("Animation") then anims[#anims + 1] = child end
    end
    table.sort(anims, function(a, b) return string.lower(a.Name) < string.lower(b.Name) end)

    local want = #anims
    local isIdle = string.lower(folder.Name) == "idle"
    if isIdle and want < 2 then want = 2 end
    if want < 1 then want = 1 end

    local written = 0
    for i = 1, want do
        local animObj = anims[i]
        if not animObj then
            animObj = create("Animation", { Name = monoAnimSlotName(folder, i, anims) }, nil)
            animObj.Parent = folder
            anims[i] = animObj
        end
        local id = ids[math.min(i, #ids)] or ids[1]
        if type(id) == "string" and id ~= "" then
            pcall(function() animObj.AnimationId = id end)
            local w = weightsList and weightsList[math.min(i, #weightsList)] or (weightsList and weightsList[1] or nil)
            if w ~= nil then
                for _, child in ipairs(animObj:GetChildren()) do
                    if child:IsA("NumberValue") and child.Name == "Weight" then
                        pcall(function() child:Destroy() end)
                    end
                end
                create("NumberValue", { Name = "Weight", Value = w }, animObj)
            end
            written = written + 1
        end
    end

    pcall(function()
        local value = folder.Value
        if type(value) == "string" and value ~= "" and not folder:FindFirstChild(value) then
            folder.Value = anims[1] and anims[1].Name or value
        end
    end)
    return written
end

function monoAnimRestartAnimate(animate)
    if not animate then return end
    
    
    
    pcall(function()
        animate.Disabled = true
        animate.Disabled = false
    end)
end

function monoAnimApply(cache, pack, onlyCategory, onlyName)
    local char = LocalPlayer.Character
    if not char then char = LocalPlayer.CharacterAdded:Wait() end
    local humanoid = char:FindFirstChildOfClass("Humanoid")
    local animate = char:FindFirstChild("Animate")
    if not animate or not humanoid then return end

    if humanoid.RigType == Enum.HumanoidRigType.R6 then
        notify("Monochrome", "Animations require R15", 3)
        return
    end

    local mappings = monoAnimMappings(cache, pack)
    if #mappings == 0 then
        notify("Monochrome", "That pack has no animations", 3)
        return
    end

    local singleName = onlyName and string.lower(onlyName) or nil

    for _, track in ipairs(humanoid:GetPlayingAnimationTracks()) do
        pcall(function() track:Stop() end)
    end

    local mappingMap = monoAnimMapOf(mappings, onlyCategory)
    local applied = 0
    for _, data in pairs(mappingMap) do
        local categoryFolder = monoAnimFindAnimateFolder(animate, data.folderName)
        if categoryFolder then
            if singleName then
                local m = data.items[singleName]
                if m then
                    local foundAnim = false
                    for _, animObj in ipairs(categoryFolder:GetChildren()) do
                        if animObj:IsA("Animation") then
                            pcall(function() animObj.AnimationId = m.animationId end)
                            foundAnim = true
                        end
                    end
                    if not foundAnim then
                        local animObj = create("Animation", { Name = m.name }, nil)
                        pcall(function() animObj.AnimationId = m.animationId end)
                        animObj.Parent = categoryFolder
                    end
                    applied = applied + 1
                end
            else
                local names = {}
                for name in pairs(data.items) do names[#names + 1] = name end
                table.sort(names)
                local ids, weights = {}, {}
                for _, name in ipairs(names) do
                    local m = data.items[name]
                    ids[#ids + 1] = m.animationId
                    if m.weights then
                        for _, value in ipairs(m.weights) do weights[#weights + 1] = value end
                    end
                end
                if #ids > 0 and monoAnimWriteSlots(categoryFolder, ids, weights) > 0 then
                    applied = applied + 1
                end
            end
        end
    end

    monoAnimRestartAnimate(animate)

    if singleName then
        if applied > 0 then
            notify("Monochrome", monoAnimTitle(onlyName), 3)
        else
            notify("Monochrome", "That state does not match your Animate folder", 3)
        end
    elseif onlyCategory then
        if applied > 0 then
            notify("Monochrome", monoAnimTitle(onlyCategory) .. " only", 3)
        else
            notify("Monochrome", "No " .. string.lower(onlyCategory) .. " animations in that pack", 3)
        end
    end
end

local function monoAnimSavedIds(animMap)
    local ids = {}
    if type(animMap) ~= "table" then return ids end
    if #animMap > 0 then
        for i = 1, #animMap do
            local value = animMap[i]
            if type(value) == "string" and value ~= "" then ids[#ids + 1] = value end
        end
        return ids
    end
    local keys = {}
    for key, value in pairs(animMap) do
        if type(key) == "string" and type(value) == "string" and value ~= "" then
            keys[#keys + 1] = key
        end
    end
    table.sort(keys)
    for _, key in ipairs(keys) do ids[#ids + 1] = animMap[key] end
    return ids
end



function monoAnimRestoreLast(opts)
    opts = opts or {}
    if not setData.loadLastAnim then return false end

    local function animateReady(c)
        if not c or not c.Parent then return false end
        local a = c:FindFirstChild("Animate")
        return a ~= nil and a:FindFirstChildWhichIsA("Animation", true) ~= nil
    end
    local char = opts.character
    local waited = 0
    while not animateReady(char) and waited < 15 do
        task.wait(0.1)
        waited = waited + 0.1
        char = LocalPlayer.Character
    end
    if not char then return false end
    local humanoid = char:FindFirstChildOfClass("Humanoid")
    local animate = char:FindFirstChild("Animate")
    if not animate or not humanoid then return false end
    if humanoid.RigType == Enum.HumanoidRigType.R6 then return false end

    for _, track in ipairs(humanoid:GetPlayingAnimationTracks()) do
        pcall(function() track:Stop() end)
    end

    local prefix = opts.prefix or "Applied"
    local appliedFull, appliedIds = false, false

    if setData.lastAnimPackName and not next(setData.lastAnimIds or {}) then
        local packs = opts.packs or monoAnimPackList or monoAnimFetchPacks()
        local found = nil
        for _, pack in ipairs(packs) do
            if pack.name == setData.lastAnimPackName then
                found = pack
                break
            end
        end
        if found then
            local cache = monoAnimLoadCache()
            local mappings = monoAnimMappings(cache, found)
            for _, data in pairs(monoAnimMapOf(mappings, nil)) do
                local folder = monoAnimFindAnimateFolder(animate, data.folderName)
                if folder then
                    local names = {}
                    for name in pairs(data.items) do names[#names + 1] = name end
                    table.sort(names)
                    local ids = {}
                    for _, name in ipairs(names) do ids[#ids + 1] = data.items[name].animationId end
                    if monoAnimWriteSlots(folder, ids) > 0 then appliedFull = true end
                end
            end
            if appliedFull then monoAnimState = nil end
        end
    elseif type(setData.lastAnimIds) == "table" and next(setData.lastAnimIds) then
        for section, animMap in pairs(setData.lastAnimIds) do
            local ids = monoAnimSavedIds(animMap)
            if #ids > 0 then
                local folder = monoAnimFindAnimateFolder(animate, section)
                if folder and monoAnimWriteSlots(folder, ids) > 0 then appliedIds = true end
            end
        end
    end

    if appliedFull or appliedIds then
        monoAnimRestartAnimate(animate)
    end
    if appliedFull then
        notify("Monochrome", prefix .. " last animation: " .. tostring(setData.lastAnimPackName or "Unknown"), 3)
    elseif appliedIds then
        notify("Monochrome", prefix .. " last animations", 3)
    end
    return appliedFull or appliedIds
end

monoAnimStateOrder = { "idle", "walk", "run", "jump", "fall", "swim", "climb" }

monoAnimBaseStates = { "all", "idle", "walk", "run", "jump", "fall", "swim", "climb" }

function monoAnimFavItems(favs)
    favs = favs or {}
    local result = {}
    for _, pack in ipairs(monoAnimPackList or {}) do
        if favs[tostring(pack.id)] == true then
            table.insert(result, pack)
        end
    end
    return result
end

monoAnimPackList = nil
monoAnimState = nil

function monoAnimTabs(animWin, drilled)
    local list = { "All", "Favorites", "Settings" }
    animWin.setTabs(list)
end

function monoAnimChips(animWin, cache, active)
    local chips = {}
    for _, st in ipairs(monoAnimBaseStates) do
        local label = st == "all" and "All" or monoAnimTitle(st)
        chips[#chips + 1] = {
            label = label,
            active = st == active,
            action = function()
                local tab = animWin and animWin.getTab and animWin.getTab()
                if tab == "Favorites" then
                    monoAnimSetState(animWin, cache, st)
                else
                    monoAnimShowPacks(animWin)
                    monoAnimSetState(animWin, cache, st)
                end
            end,
        }
    end
    animWin.setChips(chips)
end

function monoAnimShowPacks(animWin)
    animWin.setItems(monoAnimPackList, "packs", "Search animations...",
        "Loaded " .. #monoAnimPackList .. " packs")
    monoAnimTabs(animWin, false)
end

function monoAnimSetState(animWin, cache, cat)
    if cat == nil or cat == "all" then
        monoAnimState = nil
        animWin.search.PlaceholderText = "Search animations..."
        monoAnimChips(animWin, cache, "all")
    else
        monoAnimState = cat
        animWin.search.PlaceholderText = "Search packs for a " .. cat .. " animation..."
        monoAnimChips(animWin, cache, cat)
    end
end

registerMonoCommand("animations", function(auto, args)
    if not monoLoadDone then return end

    local char = LocalPlayer.Character
    local humanoid = char and char:FindFirstChildOfClass("Humanoid")
    if humanoid and humanoid.RigType == Enum.HumanoidRigType.R6 then
        notify("Monochrome", "Animations require R15", 3)
        return
    end

    local packs = monoAnimFetchPacks()
    if #packs == 0 then
        notify("Monochrome", "No animation packs loaded", 3)
        return
    end

    local cache = monoAnimLoadCache()
    monoAnimPackList = packs
    monoAnimState = nil

    if setData.loadLastAnim then
        monoAnimRestoreLast({ packs = packs, prefix = "Applied" })
    end

    local animWin = nil
    local chipOpts = {}
    for _, st in ipairs(monoAnimBaseStates) do
        chipOpts[#chipOpts + 1] = {
            label = st == "all" and "All" or monoAnimTitle(st),
            active = st == "all",
            action = function()
                monoAnimShowPacks(animWin)
                monoAnimSetState(animWin, cache, st)
            end,
        }
    end

    local animSettingsPanel = create("Frame", {
        Size = UDim2.new(1, -16, 0, 200), Position = UDim2.new(0, 8, 0, 86),
        BackgroundTransparency = 1, Visible = false,
    }, nil)

    local animSettingsSec = monoPanelSection(animSettingsPanel, 0)
    animSettingsSec.Size = UDim2.new(1, 0, 0, 32)
    animSettingsSec.Position = UDim2.new(0, 0, 0, 0)
    create("TextLabel", {
        Size = UDim2.new(1, -100, 1, 0), Position = UDim2.new(0, 12, 0, 0),
        BackgroundTransparency = 1, Text = "Load Last Animations", TextColor3 = C.text,
        TextSize = 11, Font = Enum.Font.Gotham, TextXAlignment = Enum.TextXAlignment.Left,
    }, animSettingsSec)
    local animSettingsPaint = monoPanelPill(animSettingsSec, setData.loadLastAnim)
    monoPanelPillHit(animSettingsSec, function()
        setData.loadLastAnim = not setData.loadLastAnim
        setSave()
        animSettingsPaint(setData.loadLastAnim)
    end)

    animWin = monoExtWindow({
        panelName = "animations",
        title = "Animations",
        contentH = 324,
        folder = monoAnimFolder,
        items = packs,
        noun = "packs",
        placeholder = "Search animations...",
        statusText = "Loaded " .. #packs .. " packs",
        listHeight = 190,
        tabs = { "All", "Favorites", "Settings" },
        skipTabs = { "Settings" },
        chips = chipOpts,
        onTab = function(name, w)
            if name == "Favorites" then
                local favs = (w and w.favs) or {}
                w.setItems(monoAnimFavItems(favs), "favorites", "Search favorites...",
                    "Loaded " .. #monoAnimFavItems(favs) .. " favorites")
                w.scroll.Visible = true
                w.search.Visible = true
                if w.chipsRowRef then w.chipsRowRef.Visible = true end
                animSettingsPanel.Visible = false
            elseif name == "Settings" then
                w.scroll.Visible = false
                w.search.Visible = false
                if w.chipsRowRef then w.chipsRowRef.Visible = false end
                animSettingsPanel.Visible = true
            else
                w.scroll.Visible = true
                w.search.Visible = true
                if w.chipsRowRef then w.chipsRowRef.Visible = true end
                animSettingsPanel.Visible = false
                monoAnimShowPacks(w)
                monoAnimSetState(w, cache, "all")
            end
        end,
        onFavToggle = function(item, now)
            local tab = animWin and animWin.getTab and animWin.getTab()
            if tab == "Favorites" and not now then
                local favs = (animWin and animWin.favs) or {}
                animWin.setItems(monoAnimFavItems(favs), "favorites", "Search favorites...",
                    "Loaded " .. #monoAnimFavItems(favs) .. " favorites")
            end
        end,
        onPick = function(item)
            if monoAnimState then
                monoAnimApply(cache, item, monoAnimState, nil)
                local mappings = monoAnimMappings(cache, item)
                local mappingMap = monoAnimMapOf(mappings, monoAnimState)
                for _, data in pairs(mappingMap) do
                    local names = {}
                    for animName in pairs(data.items) do names[#names + 1] = animName end
                    table.sort(names)
                    local ids = {}
                    for _, animName in ipairs(names) do
                        ids[#ids + 1] = data.items[animName].animationId
                    end
                    setData.lastAnimIds = setData.lastAnimIds or {}
                    setData.lastAnimIds[monoAnimState] = ids
                    setData.lastAnimPackName = nil
                end
            else
                monoAnimApply(cache, item)
                setData.lastAnimIds = {}
                setData.lastAnimPackName = item.name
            end
            setSave()
        end,
    })
    if animWin then
        animSettingsPanel.Parent = animWin.content
        monoAnimChips(animWin, cache, "all")
    end

    local animRespawnConn = LocalPlayer.CharacterAdded:Connect(function()
        if not (monoExtLive["animations"]) then return end
        task.spawn(function()
            monoAnimRestoreLast({ character = LocalPlayer.Character, prefix = "Reapplied" })
        end)
    end)
    monoCmdOnDestroy("animations", function()
        if animRespawnConn then pcall(function() animRespawnConn:Disconnect() end) end
        animRespawnConn = nil
        monoExtCloseAll()
    end)
end)

monoEmotesFolder = "Monochrome/emotes"
monoEmotesSpeed = 1.0
monoEmotesMoveWhileEmoting = false
monoEmotesLogger = false
monoEmotesAddLog = nil
monoEmotesOnMWEChange = nil
monoEmotesExtra = nil
monoEmotesWalkTrack = nil
monoEmotesSpeedConn = nil
monoEmotesSpeedAddedConn = nil
monoEmotesWalkConn = nil
monoEmotesWalkAddedConn = nil
monoEmotesDiedConn = nil
monoEmotesLogConn = nil
monoEmotesLogAddedConn = nil
monoEmotesHeld = {}

monoEmotesExtraPath = configPath(monoEmotesFolder, "settings")

function monoEmotesLoadExtra()
    local extra = {}
    if typeof(readfile) ~= "function" or typeof(isfile) ~= "function" then return extra end
    pcall(function()
        if isfile(monoEmotesExtraPath) then
            local okDec, decoded = pcall(function()
                return HttpService:JSONDecode(readfile(monoEmotesExtraPath))
            end)
            if okDec and type(decoded) == "table" then extra = decoded end
        end
    end)
    return extra
end

function monoEmotesSaveExtra()
    if typeof(writefile) ~= "function" or not monoEmotesExtra then return end
    ensureFolder(monoEmotesFolder)
    pcall(function()
        writefile(monoEmotesExtraPath, HttpService:JSONEncode(monoEmotesExtra))
    end)
end

function monoEmotesHold(conn)
    if not conn then return nil end
    table.insert(monoEmotesHeld, conn)
    return conn
end

function monoEmotesRelease(conn)
    if not conn then return end
    for i, held in ipairs(monoEmotesHeld) do
        if held == conn then
            table.remove(monoEmotesHeld, i)
            break
        end
    end
    pcall(function() conn:Disconnect() end)
end

function monoEmotesReleaseAll()
    for _, conn in ipairs(monoEmotesHeld) do
        pcall(function() conn:Disconnect() end)
    end
    monoEmotesHeld = {}
    monoEmotesSpeedConn = nil
    monoEmotesSpeedAddedConn = nil
    monoEmotesWalkConn = nil
    monoEmotesWalkAddedConn = nil
    monoEmotesDiedConn = nil
    monoEmotesLogConn = nil
    monoEmotesLogAddedConn = nil
end

function monoEmotesApplySpeed(speed)
    local char = LocalPlayer.Character
    if not char then return end
    local holder = char:FindFirstChildOfClass("Humanoid") or char:FindFirstChildOfClass("AnimationController")
    if not holder then return end
    for _, track in ipairs(holder:GetPlayingAnimationTracks()) do
        pcall(function() track:AdjustSpeed(speed) end)
    end
end

function monoEmotesHookSpeed()
    local char = LocalPlayer.Character
    if not char then return end
    local humanoid = char:FindFirstChildOfClass("Humanoid")
    if not humanoid then return end
    local animator = humanoid:FindFirstChildOfClass("Animator")
    if not animator then return end
    return animator.AnimationPlayed:Connect(function(track)
        if monoEmotesSpeed ~= 1 then
            pcall(function() track:AdjustSpeed(monoEmotesSpeed) end)
        end
    end)
end

function monoEmotesSetupSpeed()
    monoEmotesRelease(monoEmotesSpeedConn)
    monoEmotesSpeedConn = monoEmotesHold(monoEmotesHookSpeed())
    monoEmotesApplySpeed(monoEmotesSpeed)
end

function monoEmotesSetSpeed(value)
    local speed = tonumber(value)
    if not speed then return false end
    monoEmotesSpeed = speed
    monoEmotesApplySpeed(speed)
    if not monoEmotesExtra then monoEmotesExtra = monoEmotesLoadExtra() end
    monoEmotesExtra.animSpeed = speed
    monoEmotesSaveExtra()
    return true
end

monoEmotesSpeedMin = 0.1
monoEmotesSpeedMax = 10

function monoEmotesSpeedScale(speed)
    local span = monoEmotesSpeedMax - monoEmotesSpeedMin
    if span <= 0 then return 0 end
    local scale = (speed - monoEmotesSpeedMin) / span
    return math.clamp(scale, 0, 1)
end

function monoEmotesSpeedText()
    local speed = monoEmotesSpeed
    if speed == math.floor(speed) then return tostring(speed) .. ".0x" end
    return tostring(speed) .. "x"
end

function monoEmotesUrlToId(id)
    id = string.gsub(id, "http://www%.roblox%.com/asset/%?id=", "")
    id = string.gsub(id, "https://www%.roblox%.com/asset/%?id=", "")
    id = string.gsub(id, "rbxassetid://", "")
    return id
end

function monoEmotesIsDancing(char, animTrack)
    local animate = char:FindFirstChild("Animate")
    if not animate then return false end
    local animId = monoEmotesUrlToId(animTrack.Animation.AnimationId)
    for _, holder in ipairs(animate:GetChildren()) do
        if holder:IsA("StringValue") then
            for _, animObj in ipairs(holder:GetChildren()) do
                if animObj:IsA("Animation") and monoEmotesUrlToId(animObj.AnimationId) == animId then
                    return false
                end
            end
        end
    end
    return true
end

function monoEmotesStopWalk()
    if not monoEmotesWalkTrack then return end
    local old = monoEmotesWalkTrack
    monoEmotesWalkTrack = nil
    pcall(function() old:Stop() end)
end

function monoEmotesPlayWalk(hum, emoteId)
    monoEmotesStopWalk()
    local anim = Instance.new("Animation")
    anim.AnimationId = "rbxassetid://" .. emoteId
    local track = hum:LoadAnimation(anim)
    monoEmotesWalkTrack = track
    if not track then return end
    track.Priority = Enum.AnimationPriority.Action
    track.Looped = true
    task.wait(0.1)
    if monoEmotesWalkTrack == track then pcall(function() track:Play() end) end
end

function monoEmotesHookWalk(char)
    local hum = char:FindFirstChildOfClass("Humanoid")
    if not hum then return end
    local animator = hum:FindFirstChildOfClass("Animator")
    if not animator then return end

    monoEmotesRelease(monoEmotesWalkConn)
    monoEmotesWalkConn = monoEmotesHold(animator.AnimationPlayed:Connect(function(animTrack)
        if not monoEmotesMoveWhileEmoting then return end
        if not monoEmotesIsDancing(char, animTrack) then return end
        local playedId = monoEmotesUrlToId(animTrack.Animation.AnimationId)
        if monoEmotesWalkTrack then
            local curId = monoEmotesUrlToId(monoEmotesWalkTrack.Animation.AnimationId)
            if curId == playedId then return end
            monoEmotesStopWalk()
        end
        monoEmotesPlayWalk(hum, playedId)
    end))

    monoEmotesRelease(monoEmotesDiedConn)
    monoEmotesDiedConn = monoEmotesHold(hum.Died:Connect(function()
        if monoEmotesMoveWhileEmoting then
            monoEmotesMoveWhileEmoting = false
            if monoEmotesOnMWEChange then pcall(monoEmotesOnMWEChange) end
        end
        monoEmotesStopWalk()
    end))
end

function monoEmotesSetMove(enabled)
    monoEmotesMoveWhileEmoting = enabled

    if not enabled then
        monoEmotesStopWalk()
        monoEmotesRelease(monoEmotesWalkConn)
        monoEmotesRelease(monoEmotesWalkAddedConn)
        return
    end

    local char = LocalPlayer.Character
    if char then
        task.spawn(function()
            task.wait(0.1)
            if monoEmotesMoveWhileEmoting then monoEmotesHookWalk(char) end
        end)
    end

    monoEmotesRelease(monoEmotesWalkAddedConn)
    monoEmotesWalkAddedConn = monoEmotesHold(LocalPlayer.CharacterAdded:Connect(function(newChar)
        task.wait(0.5)
        if monoEmotesMoveWhileEmoting then monoEmotesHookWalk(newChar) end
    end))
end

function monoEmotesHookLogger(char)
    local hum = char:FindFirstChildOfClass("Humanoid")
    if not hum then return end
    local animator = hum:FindFirstChildOfClass("Animator")
    if not animator then return end

    monoEmotesRelease(monoEmotesLogConn)
    monoEmotesLogConn = monoEmotesHold(animator.AnimationPlayed:Connect(function(animTrack)
        if not monoEmotesLogger then return end
        if monoEmotesAddLog then monoEmotesAddLog(monoEmotesUrlToId(animTrack.Animation.AnimationId)) end
    end))
end

function monoEmotesSetLogger(enabled)
    monoEmotesLogger = enabled

    if not enabled then
        monoEmotesRelease(monoEmotesLogConn)
        monoEmotesRelease(monoEmotesLogAddedConn)
        return
    end

    local char = LocalPlayer.Character
    if char then
        task.spawn(function()
            task.wait(0.1)
            if monoEmotesLogger then monoEmotesHookLogger(char) end
        end)
    end

    monoEmotesRelease(monoEmotesLogAddedConn)
    monoEmotesLogAddedConn = monoEmotesHold(LocalPlayer.CharacterAdded:Connect(function(newChar)
        task.wait(0.5)
        if monoEmotesLogger then monoEmotesHookLogger(newChar) end
    end))
end

function monoEmotesPlay(emote)
    local char = LocalPlayer.Character
    if not char then return end
    local humanoid = char:FindFirstChildOfClass("Humanoid")
    if not humanoid then return end
    pcall(function()
        local desc = humanoid:FindFirstChildOfClass("HumanoidDescription")
        if not desc then
            desc = Instance.new("HumanoidDescription")
            desc.Parent = humanoid
        end
        desc:AddEmote(emote.name, emote.id)
        humanoid:PlayEmoteAndGetAnimTrackById(emote.id)
    end)
end

function monoEmotesReleaseCommand()
    monoEmotesReleaseAll()
    monoEmotesStopWalk()
    monoEmotesLogger = false
    monoEmotesMoveWhileEmoting = false
    monoEmotesAddLog = nil
    monoEmotesOnMWEChange = nil
end

registerMonoCommand("emotes", function(auto, args)
    if not monoLoadDone then return end

    local char = LocalPlayer.Character
    local humanoid = char and char:FindFirstChildOfClass("Humanoid")
    if humanoid and humanoid.RigType == Enum.HumanoidRigType.R6 then
        notify("Monochrome", "Emotes require R15", 3)
        return
    end

    local emotes = {}
    local okGet, body = pcall(function()
        return game:HttpGet("https://raw.githubusercontent.com/7yd7/sniper-Emote/refs/heads/test/EmoteSniper.json")
    end)
    if okGet and body and body ~= "" then
        local okDec, decoded = pcall(function() return HttpService:JSONDecode(body) end)
        if okDec and type(decoded) == "table" and decoded.data then
            emotes = decoded.data
        end
    end
    if #emotes == 0 then
        notify("Monochrome", "No emotes loaded", 3)
        return
    end

    local bottomBar = nil
    local settingsPanel = nil

    local emotesWin
    emotesWin = monoExtWindow({
        panelName = "emotes",
        title = "Emotes",
        contentH = 324,
        folder = monoEmotesFolder,
        extra = monoEmotesExtra or monoEmotesLoadExtra(),
        items = emotes,
        noun = "emotes",
        placeholder = "Search emotes...",
        statusText = "Loaded " .. #emotes .. " emotes",
        listHeight = 180,
        tabs = { "All", "Favorites", "Settings" },
        skipTabs = { "Settings" },
        onPick = monoEmotesPlay,
        onClose = monoEmotesReleaseCommand,
        onTab = function(name, w)
            local settings = name == "Settings"
            w.scroll.Visible = not settings
            w.search.Visible = not settings
            settingsPanel.Visible = settings
            bottomBar.Visible = not settings
        end,
        onFavToggle = function(item, now)
            local tab = emotesWin and emotesWin.getTab and emotesWin.getTab()
            if tab == "Favorites" and not now then
                emotesWin.refresh()
            end
        end,
    })
    if not emotesWin then return end

    monoEmotesExtra = emotesWin.extra
    monoEmotesMoveWhileEmoting = emotesWin.extra.moveWhileEmoting == true
    local savedSpeed = tonumber(emotesWin.extra.animSpeed)
    monoEmotesSpeed = savedSpeed or 1.0

    bottomBar = create("Frame", {
        Size = UDim2.new(1, 0, 0, 52), Position = UDim2.new(0, 0, 1, -52),
        BackgroundTransparency = 1,
    }, emotesWin.content)

    local speedLabel = create("TextLabel", {
        Size = UDim2.new(1, -20, 0, 16), Position = UDim2.new(0, 10, 0, 0),
        BackgroundTransparency = 1, Text = "Animation Speed: " .. monoEmotesSpeedText(),
        TextColor3 = C.text, TextSize = 10, Font = Enum.Font.Gotham,
        TextXAlignment = Enum.TextXAlignment.Left,
    }, bottomBar)

    local sliderBg = create("Frame", {
        Size = UDim2.new(1, -20, 0, 6), Position = UDim2.new(0, 10, 0, 22),
        BackgroundColor3 = C.input, BorderSizePixel = 0,
    }, bottomBar)
    corner(sliderBg, 999)

    local initScale = monoEmotesSpeedScale(monoEmotesSpeed)
    local sliderFill = create("Frame", {
        Size = UDim2.new(initScale, 0, 1, 0), BackgroundColor3 = C.accent, BorderSizePixel = 0,
    }, sliderBg)
    corner(sliderFill, 999)

    local sliderKnob = create("Frame", {
        Size = UDim2.new(0, 12, 0, 12), Position = UDim2.new(initScale, -6, 0.5, -6),
        BackgroundColor3 = C.text, BorderSizePixel = 0, ZIndex = 3,
    }, sliderBg)
    corner(sliderKnob, 999)

    local sliderDragging = false
    local lastSliderClick = 0

    local function paintSpeed(speed)
        local scale = monoEmotesSpeedScale(speed)
        sliderFill.Size = UDim2.new(scale, 0, 1, 0)
        sliderKnob.Position = UDim2.new(scale, -6, 0.5, -6)
        speedLabel.Text = "Animation Speed: " .. monoEmotesSpeedText()
    end

    local function setSpeed(value)
        monoEmotesSetSpeed(value)
        paintSpeed(monoEmotesSpeed)
    end

    local function sliderPosFrom(input)
        local pos = math.clamp((input.Position.X - sliderBg.AbsolutePosition.X) / sliderBg.AbsoluteSize.X, 0, 1)
        return monoEmotesSpeedMin + pos * (monoEmotesSpeedMax - monoEmotesSpeedMin)
    end

    sliderBg.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            local now = os.clock()
            if now - lastSliderClick < 0.3 then
                setSpeed(1.0)
                sliderDragging = false
            else
                setSpeed(sliderPosFrom(input))
                sliderDragging = true
            end
            lastSliderClick = now
        end
    end)

    monoEmotesHold(UserInputService.InputChanged:Connect(function(input)
        if not sliderDragging then return end
        if input.UserInputType == Enum.UserInputType.MouseMovement
            or input.UserInputType == Enum.UserInputType.Touch then
            setSpeed(sliderPosFrom(input))
        end
    end))

    monoEmotesHold(UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            sliderDragging = false
        end
    end))

    settingsPanel = create("Frame", {
        Size = UDim2.new(1, -16, 1, -86), Position = UDim2.new(0, 8, 0, 86),
        BackgroundTransparency = 1, Visible = false,
    }, emotesWin.content)

    local function settingRow(parent, order, labelText)
        local sec = monoPanelSection(parent, order)
        sec.Size = UDim2.new(1, 0, 0, 32)
        sec.Position = UDim2.new(0, 0, 0, order)
        create("TextLabel", {
            Size = UDim2.new(1, -100, 1, 0), Position = UDim2.new(0, 12, 0, 0),
            BackgroundTransparency = 1, Text = labelText, TextColor3 = C.text,
            TextSize = 11, Font = Enum.Font.Gotham, TextXAlignment = Enum.TextXAlignment.Left,
        }, sec)
        return sec
    end

    local setMWE = nil
    local setLogger = nil

    local mweSec = settingRow(settingsPanel, 0, "Move While Emoting")
    local mwePaint = monoPanelPill(mweSec, monoEmotesMoveWhileEmoting)
    monoPanelPillHit(mweSec, function() if setMWE then setMWE(not monoEmotesMoveWhileEmoting) end end)
    if monoEmotesMoveWhileEmoting then monoEmotesSetMove(true) end

    local logFrame = create("Frame", {
        Size = UDim2.new(1, 0, 1, -72), Position = UDim2.new(0, 0, 0, 72),
