    local ENTRY_H = 36

    local function addLogEntry(idNum)
        if not idNum or idNum == "" then return end
        if logSeen[idNum] then return end
        logSeen[idNum] = true
        logCount = logCount + 1

        local entryRow = monoPanelSection(logHolder, logCount)
        entryRow.Size = UDim2.new(1, 0, 0, ENTRY_H)

        table.insert(logEntries, entryRow)
        if #logEntries > MAX_LOG then
            local oldest = table.remove(logEntries, 1)
            if oldest then pcall(function() oldest:Destroy() end) end
        end

        create("TextLabel", {
            Size = UDim2.new(1, -84, 1, 0), Position = UDim2.new(0, 8, 0, 0),
            BackgroundTransparency = 1, Text = "ID: " .. idNum,
            TextColor3 = C.textDim, Font = Enum.Font.Gotham, TextSize = 10,
            TextXAlignment = Enum.TextXAlignment.Left,
        }, entryRow)

        local copyBtn = monoExtRowBtn(entryRow, "Copy ID", UDim2.new(0, 74, 0, 22), UDim2.new(1, -84, 0.5, -11), 10)
        copyBtn.TextXAlignment = Enum.TextXAlignment.Center
        copyBtn.MouseButton1Click:Connect(function()
            pcall(function() setclipboard(idNum) end)
            copyBtn.Text = "Copied"
            task.delay(1.5, function()
                if copyBtn and copyBtn.Parent then copyBtn.Text = "Copy ID" end
            end)
        end)

        task.defer(function()
            if not logScroll.Parent then return end
            local maxY = math.max(0, logScroll.AbsoluteCanvasSize.Y - logScroll.AbsoluteWindowSize.Y)
            logScroll.CanvasPosition = Vector2.new(0, maxY)
        end)
    end

