local function _nvAny(t)
    if type(t) ~= "table" then return nil end
    return next(t)
end
local _safeLoadstring = function(src) return loadstring(src) end
local function createInstance(className, props)
    local obj = Instance.new(className)
    local parent = props and props.Parent
    for k, v in pairs(props or {}) do
        if k ~= "Parent" then pcall(function() obj[k] = v end) end
    end
    if parent ~= nil then pcall(function() obj.Parent = parent end) end
    return obj
end

local monoMirrorOriginals = {}
local monoMirrorRealChar = nil
local monoMirrorAnimate = nil
local monoMirrorAnimateWasEnabled = false
local function monoPrepareMirror(real_char)
    table.clear(monoMirrorOriginals)
    monoMirrorRealChar = real_char
    monoMirrorAnimate = nil
    monoMirrorAnimateWasEnabled = false
    if not real_char then return end
    local zero = PhysicalProperties.new(0.001, 0, 0, 0, 0)
    for _, d in ipairs(real_char:GetDescendants()) do
        if d:IsA("Motor6D") then
            monoMirrorOriginals[d] = { joint = true, enabled = d.Enabled }
            pcall(function() d.Enabled = false end)
        elseif d:IsA("BasePart") then
            monoMirrorOriginals[d] = {
                massless = d.Massless, canCollide = d.CanCollide,
                canTouch = d.CanTouch, canQuery = d.CanQuery,
                phys = d.CustomPhysicalProperties,
            }
            pcall(function()
                d.CanCollide = false
                d.CanTouch = false
                d.CanQuery = false
                d.Massless = true
                d.CustomPhysicalProperties = zero
            end)
        elseif d:IsA("BillboardGui") or d:IsA("SurfaceGui") then
            pcall(function() d:Destroy() end)
        end
    end
    local rAnim = real_char:FindFirstChild("Animate")
    if rAnim then
        monoMirrorAnimate = rAnim
        monoMirrorAnimateWasEnabled = not rAnim.Disabled
        pcall(function() rAnim.Disabled = true end)
    end
end
local function monoRestoreMirror()
    for d, st in pairs(monoMirrorOriginals) do
        if d and d.Parent then
            pcall(function()
                if st.joint then
                    d.Enabled = st.enabled
                else
                    d.Massless = st.massless
                    d.CanCollide = st.canCollide
                    d.CanTouch = st.canTouch
                    d.CanQuery = st.canQuery
                    d.CustomPhysicalProperties = st.phys
                end
            end)
        end
    end
    table.clear(monoMirrorOriginals)
    if monoMirrorAnimate and monoMirrorAnimate.Parent then
        pcall(function() monoMirrorAnimate.Disabled = not monoMirrorAnimateWasEnabled end)
    end
    monoMirrorAnimate = nil
    monoMirrorRealChar = nil
end
