    local monoReanimBlend = { mode = nil, source = nil, pre = nil }
    do
        local B = monoReanimBlend
        B.enabled = true
        B.time = 0.25
        local cur
        local outConn = nil

        function B.sample(kfs, total, t, out)
            local lo, hi = 1, #kfs - 1
            while lo < hi do
                local mid = math.floor((lo + hi + 1) / 2)
                if kfs[mid].Time <= t then lo = mid else hi = mid - 1 end
            end
            local cf = kfs[lo]
            local nf = kfs[lo + 1] or kfs[1]
            local fd = nf.Time - cf.Time
            if fd <= 0 then fd = (total - cf.Time) + nf.Time end
            local seg = t - cf.Time
            if seg < 0 then seg = seg + total end
            local a = fd > 0 and math.clamp(seg / fd, 0, 1) or 0
            for name, p in pairs(cf.Data or {}) do
                local np = nf.Data and nf.Data[name]
                out[name] = np and p:Lerp(np, a) or p
            end
            return out
        end

        local function near(a, b)
            local d = a:Inverse() * b
            local _, ang = d:ToAxisAngle()
            return d.Position.Magnitude < 0.05 and math.abs(ang) < 0.05
        end

        local function follows(src, from)
            local ok, poses = pcall(B.sample, src.kfs, src.total, src.at(), {})
            if not ok then return nil end
            local skip, miss, hit = {}, 0, 0
            for name, p in pairs(poses) do
                local f = from[name]
                if f then
                    if near(f, p) then
                        hit = hit + 1
                    else
                        skip[name] = true
                        miss = miss + 1
                        if miss > 2 then return nil end
                    end
                end
            end
            if hit == 0 then return nil end
            return skip
        end

        function B.start(from, carried, src)
            cur = nil
            if not B.enabled then return end
            if not (from and next(from)) then return end
            local dur = math.clamp(B.time or 0.25, 0.1, 1.0)
            local c = { time = dur, from = from, out = {}, seen = {}, hold = {}, t = 0, frame = 0 }
            local skip = src and not carried and follows(src, from) or nil
            if skip then
                local rate = src.rate()
                c.src = { kfs = src.kfs, total = src.total, t = src.at(),
                    rate = rate == rate and rate or 0, skip = skip, pose = {} }
            end
            cur = c
        end

        function B.step(dt)
            local c = cur
            if not c then return false end
            if c.done then
                cur = nil
                return false
            end
            c.t = math.min(c.t + math.min(dt, 1 / 20), c.time)
            c.done = c.t >= c.time
            c.frame = c.frame + 1
            local a = c.t / c.time
            c.w = a * a * (3 - 2 * a)
            local src = c.src
            if src and src.total > 0 then
                src.t = (src.t + dt * src.rate) % src.total
                if pcall(B.sample, src.kfs, src.total, src.t, src.pose) then
                    for name, p in pairs(src.pose) do
                        if not src.skip[name] then c.from[name] = p end
                    end
                end
            end
            return true
        end

        function B.mix(name, pose)
            local c = cur
            if not c then return pose end
            c.seen[name] = c.frame
            c.hold[name] = pose
            local f = c.from[name]
            return f and f:Lerp(pose, c.w) or pose
        end

        function B.rest(write)
            local c = cur
            if not c then return end
            for name in pairs(c.from) do
                if c.seen[name] ~= c.frame then
                    pcall(write, name, B.mix(name, c.hold[name] or CFrame.identity))
                end
            end
        end

        function B.active() return cur ~= nil or outConn ~= nil end

        local function stopOut()
            if outConn then
                pcall(function() outConn:Disconnect() end)
                outConn = nil
            end
        end
        B.stopOut = stopOut

        function B.cancel()
            cur = nil
            B.source = nil
            stopOut()
        end

        
        function B.out(from, seconds)
            stopOut()
            if not (B.enabled and from and next(from)) then return false end
            local dur = math.clamp(seconds or B.time or 0.25, 0.1, 1.0)
            local t = 0
            local function write(name, cf)
                local anim = monoReanim.animation
                if anim.ac_joint_map then
                    local jd = anim.ac_joint_map[name]
                    if jd and jd.constraint and jd.constraint.Parent then
                        jd.constraint.Transform = cf
                    end
                else
                    local motor = anim.joints[name]
                    local orig = motor and anim.original_motor_c0s[motor]
                    if orig and motor and motor.Parent then
                        motor.C0 = orig * cf
                    end
                end
            end
            local function finish()
                for name in pairs(from) do
                    pcall(write, name, CFrame.identity)
                end
                local lp = monoReanim.services.players.LocalPlayer
                local clone = lp and monoReanim.clones[lp]
                local cas = clone and clone:FindFirstChild("Animate")
                if cas then pcall(function() cas.Enabled = true end) end
                stopOut()
            end
            local function stepOut(dt)
                t = math.min(t + math.min(dt, 1 / 20), dur)
                local a = t / dur
                local w = a * a * (3 - 2 * a)
                for name, p in pairs(from) do
                    pcall(write, name, p:Lerp(CFrame.identity, w))
                end
                if t >= dur then finish() end
            end
            outConn = monoReanim.services.run_service.Heartbeat:Connect(function(dt)
                if not B.enabled or not monoReanim.flags.reanimated then
                    stopOut()
                    return
                end
                if not pcall(stepOut, dt) then stopOut() end
            end)
            return true
        end

        local function read()
            local anim = monoReanim.animation
            local from = {}
            if anim.ac_joint_map then
                for part, jd in pairs(anim.ac_joint_map) do
                    local k = type(jd) == "table" and jd.constraint
                    if k and k.Parent then from[part] = k.Transform end
                end
            else
                for name, motor in pairs(anim.joints) do
                    local orig = anim.original_motor_c0s[motor]
                    if orig and motor.Parent then
                        from[name] = orig:Inverse() * motor.C0 * motor.Transform
                    end
                end
            end
            return from
        end

        API.blend = B
        API.set_blend = function(seconds)
            B.enabled = type(seconds) == "number" and seconds > 0
            if B.enabled then B.time = math.clamp(math.floor(seconds * 100 + 0.5) / 100, 0.1, 1.0) end
            if not B.enabled then
                cur = nil
                B.source = nil
                B.pre = nil
                stopOut()
            end
        end
        API.get_blend = function() return B.enabled and B.time or nil end
        API.blend_hold = function()
            if not B.enabled then return end
            local held = { read(), cur ~= nil and not cur.done }
            B.pre = held
            task.defer(function()
                if B.pre == held then B.pre = nil end
            end)
        end
        API.blend_capture = function()
            if not B.enabled then return nil, false, nil end
            local held = B.pre
            if held then
                B.pre = nil
                return held[1], held[2], nil
            end
            return read(), cur ~= nil and not cur.done, B.source
        end
    end
