    local ANIM_CACHE_DIR = "Monochrome/anim_cache"
    local function animCachePath(url)
        local h = 0
        for i = 1, #url do
            h = (h * 31 + string.byte(url, i)) % 2147483647
        end
        return ANIM_CACHE_DIR .. "/" .. tostring(h) .. ".lua"
    end

    local function ensureAnimCacheDir()
        pcall(function()
            if typeof(isfolder) == "function" and typeof(makefolder) == "function" then
                if not isfolder("Monochrome") then makefolder("Monochrome") end
                if not isfolder(ANIM_CACHE_DIR) then makefolder(ANIM_CACHE_DIR) end
            end
        end)
    end

    local function decodeAnimSource(src)
        if type(src) ~= "string" or src == "" then return nil, "empty source" end
        local loaded_fn, load_err = _safeLoadstring(src)
        if not loaded_fn then return nil, "Invalid script from URL. " .. tostring(load_err) end
        local ok2, data = pcall(loaded_fn)
        if not ok2 then return nil, "Script from URL failed to execute. " .. tostring(data) end
        if typeof(data) ~= "table" then return nil, "Script from URL did not return a table." end
        return data, nil
    end

    local function resolveAnimData(url)
        local anim = monoReanim.animation

        if typeof(url) == "table" then
            if type(url) ~= "table" then return nil, "Animation Error: Invalid animation data." end
            anim.cache[url] = url
            return url, nil
        end

        if type(url) ~= "string" or url == "" then
            return nil, "Animation Error: Invalid animation path."
        end

        local cached = anim.cache[url]
        if cached then return cached, nil end

        local isHttp = (url:sub(1, 4) == "http")
        local isInline = (url:find("^%s*return") or url:find("^%s*{") or url:find("^%s*%-%-")) ~= nil
        local path = isHttp and animCachePath(url) or url

        if not isInline and typeof(isfile) == "function" and typeof(readfile) == "function" then
            local okFile, exists = pcall(isfile, path)
            if okFile and exists then
                local okRead, src = pcall(readfile, path)
                if okRead and type(src) == "string" and #src > 0 then
                    local data, _err = decodeAnimSource(src)
                    if data then
                        anim.cache[url] = data
                        return data, nil
                    end
                end
            end
        end

        local response
        if isInline then
            response = url
        elseif isHttp then
            local ok1, res = pcall(game.HttpGet, game, url)
            if not ok1 then return nil, "Animation Error: Failed to fetch URL." end
            response = res
        else
            if typeof(readfile) ~= "function" then
                return nil, "Animation Error: Cannot load local file (readfile not supported)."
            end
            local okRead, src = pcall(readfile, url)
            if not okRead or type(src) ~= "string" then
                return nil, "Animation Error: Failed to read local file."
            end
            response = src
        end

        local data, err = decodeAnimSource(response)
        if not data then return nil, "Animation Error: " .. tostring(err) end
        anim.cache[url] = data

        if isHttp and typeof(writefile) == "function" and type(response) == "string" then
            ensureAnimCacheDir()
            pcall(writefile, path, response)
        end
        return data, nil
    end

    API.preload_animation = function(url)
        local kind = typeof(url)
        if kind ~= "string" and kind ~= "table" then return false end
        if monoReanim.animation.cache[url] then return true end
        local data = resolveAnimData(url)
        return data ~= nil
    end

