    local function buildACJointMap(clone)
        local map = {}
        for _, c in clone:GetDescendants() do
            if c:IsA("AnimationConstraint")
            and c.Attachment0 and c.Attachment0.Parent
            and c.Attachment1 and c.Attachment1.Parent then
                local childName = c.Attachment1.Parent.Name
                map[childName] = {
                    constraint = c,
                    part0 = c.Attachment0.Parent,
                    part1 = c.Attachment1.Parent,
                    att0CF = c.Attachment0.CFrame,
                    att1CF = c.Attachment1.CFrame,
                }
            end
        end
        return map
    end

    local function setACConstraints(clone, enabled)
        for _, c in clone:GetDescendants() do
            if c:IsA("BallSocketConstraint") or c:IsA("AnimationConstraint") then
                pcall(function() c.Enabled = enabled end)
            end
        end
    end

    local function _attachPuppet(real_char, clone_char)
        if not (real_char and clone_char) then return end
        local rHRP = real_char:FindFirstChild("HumanoidRootPart")
        local cHRP = clone_char:FindFirstChild("HumanoidRootPart")
        if not (rHRP and cHRP) then return end
        local parts = {}
        for _, d in real_char:GetDescendants() do
            if d:IsA("BasePart") then
                parts[d] = { massless = d.Massless, canCollide = d.CanCollide }
                pcall(function() d.Massless = true end)
                if d ~= rHRP then pcall(function() d.CanCollide = false end) end
            end
        end
        local rAnim = real_char:FindFirstChild("Animate")
        if rAnim then monoReanim.puppet.animWasEnabled = not rAnim.Disabled; rAnim.Disabled = true end
        local weld = createInstance("Motor6D", {
          Name = "PuppetRoot",
          Part0 = cHRP,
          Part1 = rHRP,
          C0 = CFrame.identity,
          C1 = CFrame.identity,
          Parent = cHRP,
        })
        monoReanim.puppet.weld = weld
        monoReanim.puppet.parts = parts
        monoReanim.puppet.active = true
    end

    local function detachPuppet(real_char)
        if monoReanim.puppet.weld then
            pcall(function() monoReanim.puppet.weld:Destroy() end)
        end
        if real_char then
            for d, st in monoReanim.puppet.parts do
                if d and d.Parent then
                    pcall(function() d.Massless = st.massless end)
                    pcall(function() d.CanCollide = st.canCollide end)
                end
            end
            local rAnim = real_char:FindFirstChild("Animate")
            if rAnim and monoReanim.puppet.animWasEnabled then rAnim.Disabled = false end
        end
        monoReanim.puppet.weld = nil
        monoReanim.puppet.parts = {}
        monoReanim.puppet.active = false
    end

    local function noclipRestore()
        for part in monoReanim.noclip.was do
            if part.Parent then pcall(function() part.CanCollide = true end) end
        end
        table.clear(monoReanim.noclip.was)
    end

    local function noclipWatch(model)
        local parts = monoReanim.noclip.parts
        for _, d in model:GetDescendants() do
            if d:IsA("BasePart") then parts[#parts + 1] = d end
        end
        return model.DescendantAdded:Connect(function(d)
            if d:IsA("BasePart") then parts[#parts + 1] = d end
        end)
    end

    local function noCollide(p)
        p.CanCollide = false
    end

    local function noclipStep()
        local nc = monoReanim.noclip
        if not nc.on then return end
        for _, p in nc.parts do
            if p.CanCollide and p.Parent then
                nc.was[p] = true
                pcall(noCollide, p)
            end
        end
    end

    local get_game_ragdoll_info = function(enable)
        local place_id = game.PlaceId
        local rep = monoReanim.services.replicated
        if place_id == 15546218972 or place_id == 6884319169 then
            local remote = rep:WaitForChild("event_rag", 4)
            if remote then return remote, {"Ball"}, false end
        elseif place_id == 5991163185 then
            local ok, remote = pcall(function() return rep.Remotes.Physics.Ragdoll end)
            if ok and remote then return remote, {}, false end
        elseif place_id == 5683833663 then
            local local_event = rep:WaitForChild("LocalRagdollEvent", 4)
            if local_event then return local_event, {enable}, true end
        elseif place_id == 86382196724726 or game.GameId == 10581310106 then
            local remotes = rep:WaitForChild("Remotes", 4)
            local toggle = remotes and remotes:WaitForChild("RagdollToggle", 4)
            if toggle then return toggle, {enable and "Ball" or false}, false end
            return nil, nil, false
        end
        local function findChild(parent, path)
            local cur = parent
            for part in path:gmatch("[^/]+") do
                if not cur then return nil end
                cur = cur:FindFirstChild(part)
            end
            return cur
        end
        local candidates = {
            "Ragdoll", "RagdollEvent", "event_rag", "Rag", "Ragdolled",
            "Remotes/Ragdoll", "Events/Ragdoll", "Remotes/Physics/Ragdoll",
            "RemoteEvents/Ragdoll", "RemoteEvents/RagdollEvent",
        }
        for _, path in candidates do
            local r = findChild(rep, path)
            if r then
                if r:IsA("BindableEvent") then
                    return r, {enable}, true
                elseif r:IsA("RemoteEvent") or r:IsA("RemoteFunction") then
                    return r, {}, false
                end
            end
        end
        return nil, nil, false
    end

    local set_model_transparency = function(model, transparency)
        if not model then return end
        for _, part in model:GetDescendants() do
            if part:IsA("BasePart") then part.Transparency = transparency end
        end
    end

    local get_local_player = function()
        local player = monoReanim.services.players.LocalPlayer
        if not player then
            return "bad argument to 'get_local_player' (LocalPlayer not found; must run in a LocalScript)"
        end
        return player
    end

    local get_char = function(player)
        if typeof(player) ~= "Instance" or not player:IsA("Player") then
            return ("bad argument #1 to 'get_char' (Player expected, got %s)"):format(typeof(player))
        end
        local character = player.Character
        if not character or not character.Parent then
            return ("Player %s has no active character."):format(player.Name)
        end
        return character
    end

    local clone_char = function(model)
        if typeof(model) ~= "Instance" then
            return ("bad argument #1 to 'clone_char' (Instance expected, got %s)"):format(typeof(model))
        end
        model.Archivable = true
        local new_clone = model:Clone()
        model.Archivable = false
        new_clone.Name = "Reanimation"
        new_clone.Parent = monoReanim.services.workspace
        local _animScript = new_clone:WaitForChild("Animate", 6)
        if _animScript then _animScript.Disabled = true end
        new_clone.Humanoid.RequiresNeck = false
        new_clone.Humanoid.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
        if new_clone:FindFirstChildWhichIsA("ForceField") then
            new_clone:FindFirstChildWhichIsA("ForceField"):Destroy()
        end
        return new_clone
    end

    local fire_remote = function(remote, is_local, ...)
        if typeof(remote) ~= "Instance" then
            return ("bad argument to 'fire_remote' (Instance expected, got %s)"):format(typeof(remote))
        end
        if is_local then
            if not remote:IsA("BindableEvent") then
                return ("bad argument to 'fire_remote' (BindableEvent expected for local event, got %s)"):format(remote.ClassName)
            end
            remote:Fire(...)
        else
            if not (remote:IsA("RemoteEvent") or remote:IsA("RemoteFunction")) then
                return ("bad argument to 'fire_remote' (RemoteEvent or RemoteFunction expected, got %s)"):format(remote.ClassName)
            end
            if remote:IsA("RemoteEvent") then remote:FireServer(...)
            else remote:InvokeServer(...) end
        end
    return end

    API.get_clone = function(player)
        player = player or get_local_player()
        if typeof(player) == "string" then return nil end
        return monoReanim.clones[player]
    end

    API.get_real_character = function(player)
        player = player or get_local_player()
        if typeof(player) == "string" then return nil end
        return monoReanim.real_chars[player]
    end

    API.get_anim_body = function(player)
        return monoReanim.animation.body or API.get_clone(player)
    end

    API.get_original_c0s = function()
        return monoReanim.animation.original_motor_c0s
    end

    API.is_reanimated = function()
        return monoReanim.flags.reanimated
    end

    API.set_noclip = function(on)
        monoReanim.noclip.on = on == true
        if not monoReanim.noclip.on then noclipRestore() end
    end

    API.get_noclip = function()
        return monoReanim.noclip.on
    end
    API.set_animation_speed = function(speed) monoReanim.animation.state.speed = tonumber(speed) or 1.0 end
    API.set_animation_dir = function(dir)
        monoReanim.animation.state.dir = (tonumber(dir) or 1) < 0 and -1 or 1
    end
    API.set_animation_paused = function(paused)
        monoReanim.animation.state.paused = paused and true or false
    end
    API.set_animation_hold = function(on)
        monoReanim.animation.state.hold = on and true or false
    end
    API.get_animation_time = function()
        local st = monoReanim.animation.state
        if not st.is_playing or (st.total_duration or 0) <= 0 then return nil end
        return st.elapsed_time, st.total_duration, st.current_url
    end
    API.set_animation_time = function(t)
        local st = monoReanim.animation.state
        if not st.is_playing or (st.total_duration or 0) <= 0 then return end
        st.elapsed_time = math.clamp(tonumber(t) or 0, 0, st.total_duration - 1e-3)
    end
    API.on_animation_play = function(cb2) if type(cb2)=="function" then monoReanim.callbacks.on_play=cb2 end end
    API.on_animation_stop = function(cb2) if type(cb2)=="function" then monoReanim.callbacks.on_stop=cb2 end end
    API.on_deactivate = function(cb2) if type(cb2)=="function" then monoReanim.callbacks.on_deactivate=cb2 end end
    API.is_animation_playing = function()
        return monoReanim.animation.state.is_playing, monoReanim.animation.state.current_url
    end

    API.cancel_pending = function()
        monoReanim.animation.load_id = (monoReanim.animation.load_id or 0) + 1
    end

    API.stop_animation = function(keep, soft)
        local stopped_url = monoReanim.animation.state.current_url
        local from = nil
        if soft and not keep and API.blend and API.blend.enabled
            and monoReanim.animation.state.is_playing then
            from = API.blend_capture and API.blend_capture() or nil
        end
        if API.blend then API.blend.cancel() end
        local blendingOut = false
        if from and next(from) then
            blendingOut = API.blend.out(from, API.blend.time)
        end
        if monoReanim.connections.animation_hb then
            monoReanim.connections.animation_hb:Disconnect()
            monoReanim.connections.animation_hb = nil
        end
        local _kept = monoReanim.animation.state
        monoReanim.animation.state = {
            is_playing=false, current_url=nil, speed=_kept.speed,
            dir=_kept.dir, paused=_kept.paused,
            keyframes=nil, total_duration=0, elapsed_time=0,
        }
        local player = get_local_player()
        if typeof(player) == "string" then return end
        local cc = API.get_clone(player)
        if cc then
            for motor, orig_c0 in monoReanim.animation.original_motor_c0s do
                if not keep and not blendingOut and motor and motor.Parent then motor.C0 = orig_c0 end
            end
            if monoReanim.animation.ac_joint_map then
                for _, jd in monoReanim.animation.ac_joint_map do
                    if not keep and not blendingOut and jd.constraint and jd.constraint.Parent then
                        pcall(function() jd.constraint.Transform = CFrame.identity end)
                    end
                end
                local cas = cc:FindFirstChild("Animate")
                if cas and not blendingOut then cas.Enabled = true end
            else
                local cas = cc:FindFirstChild("Animate")
                if cas and not blendingOut then cas.Enabled = true end
            end
        end
        if stopped_url and monoReanim.callbacks.on_stop then
            pcall(monoReanim.callbacks.on_stop, stopped_url)
        end
    end

    local monoGuiGuardShelter = nil
    local monoGuiGuardSaved = {}
    local monoGuiGuardRescue = nil
    local monoGuiGuardRestoreGen = 0

    local function monoGuiGuardBegin()
        monoGuiGuardRestoreGen = monoGuiGuardRestoreGen + 1
        monoGuiGuardSaved = {}
        if monoGuiGuardRescue then
            pcall(function() monoGuiGuardRescue:Disconnect() end)
            monoGuiGuardRescue = nil
        end
        if monoGuiGuardShelter then
            pcall(function() monoGuiGuardShelter:Destroy() end)
            monoGuiGuardShelter = nil
        end
        local pg = LocalPlayer and LocalPlayer:FindFirstChildOfClass("PlayerGui")
        if not pg then return end
        local host = LocalPlayer:FindFirstChildOfClass("PlayerScripts")
                  or game:GetService("CoreGui")
        local shelter = Instance.new("Folder")
        shelter.Name = "MonoReanimGuiGuard"
        shelter.Archivable = false
        pcall(function() shelter.Parent = host end)
        if not shelter.Parent then
            pcall(function() shelter.Parent = game:GetService("CoreGui") end)
        end
        if not shelter.Parent then return end
        monoGuiGuardShelter = shelter

        local byObj = {}
        for _, child in ipairs(pg:GetChildren()) do
            local safe = child:IsA("ScreenGui") and child.ResetOnSpawn == false
            if not safe then
                byObj[child] = true
                monoGuiGuardSaved[#monoGuiGuardSaved + 1] = { obj = child, parent = pg }
                pcall(function() child.Parent = shelter end)
            end
        end

        monoGuiGuardRescue = pg.DescendantRemoving:Connect(function(d)
            if byObj[d] and d.Parent ~= shelter then
                pcall(function() d.Parent = shelter end)
            end
        end)
    end

    local function monoGuiGuardRestore()
        local gen = monoGuiGuardRestoreGen + 1
        monoGuiGuardRestoreGen = gen
        local function putBack()
            local shelter = monoGuiGuardShelter
            if not shelter then return end
            for _, rec in ipairs(monoGuiGuardSaved) do
                local obj = rec.obj
                if obj and obj.Parent == shelter and rec.parent and rec.parent.Parent then
                    pcall(function() obj.Parent = rec.parent end)
                end
            end
        end

        putBack()
        for _, d in ipairs({ 0.1, 0.5 }) do
            task.delay(d, function()
                if gen == monoGuiGuardRestoreGen then putBack() end
            end)
        end
        task.delay(1, function()
            if gen ~= monoGuiGuardRestoreGen then return end
            putBack()
            table.clear(monoGuiGuardSaved)
            if monoGuiGuardRescue then
                pcall(function() monoGuiGuardRescue:Disconnect() end)
                monoGuiGuardRescue = nil
            end
            if monoGuiGuardShelter then
                pcall(function() monoGuiGuardShelter:Destroy() end)
                monoGuiGuardShelter = nil
            end
        end)
    end

    API.reanimate = function(bool, remote, args)
        if bool ~= true and bool ~= false then
            return ("bad argument #1 to 'reanimate' (boolean expected, got %s)"):format(typeof(bool))
        end
        local player = get_local_player()
        if typeof(player) == "string" then return player end
        local is_local_event = false
        if not remote then
            local game_remote, game_args, is_local = get_game_ragdoll_info(bool)
            if game_remote then remote=game_remote; args=game_args; is_local_event=is_local end
        end
        if bool then
            if monoReanim.flags.reanimated then return "Already reanimated." end
            local real_char = get_char(player)
            if typeof(real_char) == "string" then return real_char end
            if not real_char:FindFirstChild("Humanoid") then return "Real character is missing a Humanoid." end
            local real_hrp = real_char:FindFirstChild("HumanoidRootPart")
            if not real_hrp then return "Real character is missing a HumanoidRootPart, cannot reanimate." end
            monoReanim.real_chars[player] = real_char
            local cloned_char = clone_char(real_char)
            if typeof(cloned_char) == "string" then return cloned_char end
            if not cloned_char:FindFirstChild("Humanoid") then return "Cloned character failed to create or is missing a Humanoid." end
            monoReanim.clones[player] = cloned_char
            set_model_transparency(cloned_char, 1)
            local player_gui = player:FindFirstChildWhichIsA("PlayerGui")
            local _guisFlipped = {}
            if player_gui then
                for _, gui in player_gui:GetChildren() do
                    if gui:IsA("ScreenGui") and gui.ResetOnSpawn then
                        gui.ResetOnSpawn = false
                        _guisFlipped[gui] = true
                    end
                end
            end
            if monoReanim.destroyBehavior == nil and typeof(sethiddenproperty) == "function" then
                pcall(function()
                    monoReanim.destroyBehavior = gethiddenproperty(monoReanim.services.workspace, "PlayerCharacterDestroyBehavior")
                    sethiddenproperty(monoReanim.services.workspace, "PlayerCharacterDestroyBehavior", Enum.PlayerCharacterDestroyBehavior.Disabled)
                end)
            end
            monoGuiGuardBegin()
            player.Character = cloned_char
            monoGuiGuardRestore()
            if real_char.Parent == nil then pcall(function() real_char.Parent = monoReanim.services.workspace end) end
            local _realHum = real_char:FindFirstChildOfClass("Humanoid")
            if _realHum then
                pcall(function() _realHum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None end)
            end
            local _camHum = cloned_char:WaitForChild("Humanoid", 6)
            if _camHum then monoReanim.services.workspace.CurrentCamera.CameraSubject = _camHum end
            local _animS2 = cloned_char:WaitForChild("Animate", 6)
            if _animS2 then _animS2.Disabled = true ; _animS2.Disabled = false end
            local anim_body = cloned_char
            monoReanim.animation.body = anim_body
            table.clear(monoReanim.animation.original_motor_c0s)
            table.clear(monoReanim.animation.joints)
            local hasMotor6D = false
            for _, descendant in anim_body:GetDescendants() do
                if descendant:IsA("Motor6D") and descendant.Part1 then
                    hasMotor6D = true
                    monoReanim.animation.joints[descendant.Part1.Name] = descendant
                    monoReanim.animation.original_motor_c0s[descendant] = descendant.C0
                end
            end
            if not hasMotor6D then
                monoReanim.animation.ac_joint_map = buildACJointMap(anim_body)
            else
                monoReanim.animation.ac_joint_map = nil
            end
            if player_gui then
                for _, gui in player_gui:GetChildren() do
                    if gui:IsA("ScreenGui") and _guisFlipped[gui] then gui.ResetOnSpawn=true end
                end
            end
            local real_humanoid = real_char.Humanoid
            local cloned_humanoid = cloned_char.Humanoid

            if real_humanoid and real_humanoid.Parent then
                real_humanoid.Health = real_humanoid.MaxHealth
            end
            for _, dt2 in {0.1, 0.5, 1.0} do
                task.delay(dt2, function()
                    if real_humanoid and real_humanoid.Parent and monoReanim.flags.reanimated then
                        real_humanoid.Health = real_humanoid.MaxHealth
                    end
                end)
            end
            pcall(function()
                real_humanoid:SetStateEnabled(Enum.HumanoidStateType.Dead, false)
            end)
            pcall(function()
                real_humanoid.HealthChanged:Connect(function(hp)
                    if monoReanim.flags.reanimated
                    and real_humanoid and real_humanoid.Parent
                    and hp < real_humanoid.MaxHealth then
                        real_humanoid.Health = real_humanoid.MaxHealth
                    end
                end)
            end)

            if cloned_humanoid then
                pcall(function() cloned_humanoid.BreakJointsOnDeath = false end)
                pcall(function()
                    cloned_humanoid:SetStateEnabled(Enum.HumanoidStateType.Dead,       false)
                    cloned_humanoid:SetStateEnabled(Enum.HumanoidStateType.FallingDown, false)
                    cloned_humanoid:SetStateEnabled(Enum.HumanoidStateType.Ragdoll,     false)
                    cloned_humanoid:SetStateEnabled(Enum.HumanoidStateType.Physics,     false)
                end)
                pcall(function()
                    cloned_humanoid.HealthChanged:Connect(function(hp)
                        if monoReanim.flags.reanimated
                        and cloned_humanoid and cloned_humanoid.Parent
                        and hp < cloned_humanoid.MaxHealth then
                            cloned_humanoid.Health = cloned_humanoid.MaxHealth
                        end
                    end)
                end)
                pcall(function()
                    cloned_humanoid.StateChanged:Connect(function(_, new)
                        local bad = new == Enum.HumanoidStateType.Dead
                                 or new == Enum.HumanoidStateType.Ragdoll
                                 or new == Enum.HumanoidStateType.Physics
                                 or new == Enum.HumanoidStateType.FallingDown
                        if bad and monoReanim.flags.reanimated
                        and cloned_humanoid and cloned_humanoid.Parent then
                            cloned_humanoid.Health = cloned_humanoid.MaxHealth
                            pcall(function()
                                cloned_humanoid:ChangeState(Enum.HumanoidStateType.Running)
                            end)
                        end
                    end)
                end)
            end

            monoReanim.connections.hb = monoReanim.services.run_service.Heartbeat:Connect(
                function()
                    if real_char and real_char.Parent == nil then
                        pcall(function() real_char.Parent = monoReanim.services.workspace end)
                    end
                    if not real_char or not real_char.Parent or not cloned_char or not cloned_char.Parent then
                        API.reanimate(false, remote, args); return
                    end
                    local mouse_behavior = monoReanim.services.user_input_service.MouseBehavior
                    local is_panning = monoReanim.services.user_input_service:IsMouseButtonPressed(Enum.UserInputType.MouseButton2)
                    local hrp = cloned_char:FindFirstChild("HumanoidRootPart")
                    if hrp then
                        local bg = hrp:FindFirstChild("ShiftLockGyro")
                        if not bg then
                            bg = createInstance("BodyGyro", {
                              Name = "ShiftLockGyro",
                              P = 5000,
                              D = 300,
                              MaxTorque = Vector3.new(0,0,0),
                              Parent = hrp,
                            })
                        end
                        if mouse_behavior==Enum.MouseBehavior.LockCenter and not is_panning then
                            local cam = monoReanim.services.workspace.CurrentCamera
                            if cam then
                                local look = cam.CFrame.LookVector
                                local hzLook = Vector3.new(look.X,0,look.Z)
                                if hzLook.Magnitude > 0.001 then
                                    bg.MaxTorque = Vector3.new(400000,400000,400000)
                                    bg.CFrame = CFrame.new(Vector3.new(), hzLook)
                                end
                            end
                        else
                            bg.MaxTorque = Vector3.new(0, 0, 0)
                        end
                    end
                    if monoReanim.trickStep then pcall(monoReanim.trickStep) end
                    if not monoReanim.puppet.active then
                        local skip = monoReanim.pole.skip
                        local reachSkip = monoReanim.reach.skip
                        local freeSkip = monoReanim.free.skip
                        for _, p in real_char:GetChildren() do
                            local clone_part = cloned_char:FindFirstChild(p.Name)
                            if p:IsA("BasePart") and clone_part and not skip[p] and not reachSkip[p] and not freeSkip[p] then
                                local hidden = _G.hiddenBodyParts and (
                                    _G.hiddenBodyParts[p.Name]
                                    or (_G.hiddenBodyParts["Head"] and p.Parent and p.Parent:IsA("Accessory"))
                                )
                                if hidden then
                                    p.CFrame = CFrame.new(0, 10000, 0)
                                    p.AssemblyLinearVelocity = Vector3.new()
                                    p.AssemblyAngularVelocity = Vector3.new()
                                else
                                    p.CFrame=clone_part.CFrame; p.Velocity=Vector3.new()
                                end
                            end
                        end
                        for _, acc in real_char:GetChildren() do
                            if acc:IsA("Accessory") then
                                local rHandle = acc:FindFirstChild("Handle")
                                local fAcc = cloned_char:FindFirstChild(acc.Name)
                                local fHandle = fAcc and fAcc:FindFirstChild("Handle")
                                if rHandle and fHandle and rHandle:IsA("BasePart")
                                and fHandle:IsA("BasePart") and not skip[rHandle] then
                                    local hidden = _G.hiddenBodyParts
                                        and (_G.hiddenBodyParts["Head"] or _G.hiddenBodyParts[acc.Name])
                                    if hidden then
                                        rHandle.CFrame = CFrame.new(0, 10000, 0)
                                        rHandle.AssemblyLinearVelocity = Vector3.new()
                                        rHandle.AssemblyAngularVelocity = Vector3.new()
                                    else
                                        rHandle.CFrame = fHandle.CFrame
                                        rHandle.Velocity = Vector3.new()
                                    end
                                end
                            end
                        end
                        if monoReanim.pairStep then
                            pcall(monoReanim.pairStep, real_char, cloned_char, function(p) return skip[p] or reachSkip[p] or freeSkip[p] end)
                        end
                        local poles = monoReanim.pole.list
                        local rroot = _nvAny(poles) and real_hrp and real_hrp.Parent and real_hrp.AssemblyRootPart
                        for _, entry in poles do
                            local base = entry.base
                            for _, it in base and entry.items or {} do
                                local part = it.part
                                if part.Parent and part.AssemblyRootPart ~= rroot then
                                    part.CFrame = base * it.offset
                                    part.AssemblyLinearVelocity = Vector3.zero
                                    part.AssemblyAngularVelocity = Vector3.zero
                                end
                            end
                        end
                        if _nvAny(monoReanim.reach.arms) and monoReanim.reach.step then monoReanim.reach.step(false) end
                    end
                    if real_humanoid and real_humanoid.Parent and real_humanoid.Health < real_humanoid.MaxHealth then
                        real_humanoid.Health = real_humanoid.MaxHealth
                    end
                    if cloned_humanoid and cloned_humanoid.Parent and cloned_humanoid.Health < cloned_humanoid.MaxHealth then
                        cloned_humanoid.Health = cloned_humanoid.MaxHealth
                    end
                end)
            task.delay(1.5, function()
                if not monoReanim.flags.reanimated then return end
                monoReanim.connections.died = real_humanoid.Died:Connect(function()
                    API.reanimate(false, remote, args)
                end)
                monoReanim.connections.real_char_child_removed = real_char.ChildRemoved:Connect(function(child)
                    if child==real_humanoid or child==real_hrp then API.reanimate(false,remote,args) end
                end)
            end)
            monoReanim.connections.clone_char_child_removed = cloned_char.ChildRemoved:Connect(function(child)
                if child==cloned_humanoid then API.reanimate(false,remote,args) end
            end)
            monoReanim.connections.clone_died = cloned_humanoid.Died:Connect(function()
                task.delay(0.35, function()
                    if not monoReanim.flags.reanimated then return end
                    if not cloned_humanoid or not cloned_humanoid.Parent then
                        API.reanimate(false, remote, args)
                    end
                end)
            end)
            monoReanim.connections.character_removing = player.CharacterRemoving:Connect(function(cbr)
                if cbr == cloned_char then API.reanimate(false, remote, args) end
            end)
            table.clear(monoReanim.noclip.parts)
            monoReanim.connections.noclip_real = noclipWatch(real_char)
            monoReanim.connections.noclip_clone = noclipWatch(cloned_char)
            monoReanim.connections.noclip = monoReanim.services.run_service.Stepped:Connect(noclipStep)
            if remote then
                pcall(fire_remote, remote, is_local_event, unpack(args or {}))
            end
            monoPrepareMirror(real_char)
            monoReanim.flags.reanimated = true
            _G._nv_reanimRunning = API
        else
            if not monoReanim.flags.reanimated then
                for key, conn in monoReanim.connections do
                    if conn and type(conn) == "table" and type(conn.Disconnect) == "function" then
                        pcall(conn.Disconnect, conn); monoReanim.connections[key] = nil
                    end
                end
                return
            end
            if API.trick_clear then pcall(API.trick_clear) end
            API.set_arm_poles(false)
            API.pole_clear()
            API.reach_clear()
            API.stop_animation()
            detachPuppet(monoReanim.real_chars[player])
            noclipRestore()
            monoReanim.animation.body = nil
            do
                local _cc_off = API.get_clone(player)
                if _cc_off and monoReanim.animation.ac_joint_map then
                    setACConstraints(_cc_off, true)
                    monoReanim.animation.ac_joint_map = nil
                end
            end
            if remote then
                pcall(fire_remote, remote, is_local_event, unpack(args or {}))
            end
            for key, connection in monoReanim.connections do
                if connection then connection:Disconnect(); monoReanim.connections[key]=nil end
            end
            local cc2 = monoReanim.clones[player]
            local rc2 = monoReanim.real_chars[player]
            local _savedHRPCF = nil
            if cc2 and cc2.Parent then
                local _cHRP = cc2:FindFirstChild("HumanoidRootPart")
                if _cHRP then _savedHRPCF = _cHRP.CFrame end
            end
            if rc2 and rc2.Parent then
                set_model_transparency(rc2, 0)
                local hrp2 = rc2:FindFirstChild("HumanoidRootPart")
                if hrp2 then hrp2.Transparency=1 end
                local pg2 = player:FindFirstChildWhichIsA("PlayerGui")
                local _guisFlipped2 = {}
                if pg2 then
                    for _, gui in pg2:GetChildren() do
                        if gui:IsA("ScreenGui") and gui.ResetOnSpawn then
                            gui.ResetOnSpawn = false
                            _guisFlipped2[gui] = true
                        end
                    end
                end
                monoGuiGuardBegin()
                player.Character = rc2
                monoGuiGuardRestore()
                if cc2 then pcall(function() cc2:Destroy() end); monoReanim.clones[player]=nil end
                local crh2 = rc2:FindFirstChild("Humanoid")
                if crh2 then monoReanim.services.workspace.CurrentCamera.CameraSubject=crh2 end
                if _savedHRPCF then
                    local _snapCF = _savedHRPCF
                    local _snapRC = rc2
                    task.spawn(function()
                        local t0 = tick()
                        while tick() - t0 < 0.5 do
                            task.wait()
                            local h = _snapRC and _snapRC.Parent
                                      and _snapRC:FindFirstChild("HumanoidRootPart")
                            if not h then break end
                            h.CFrame = _snapCF
                            pcall(function() h.Velocity = Vector3.new() end)
                            pcall(function() h.AssemblyLinearVelocity = Vector3.new() end)
                        end
                        if not (_snapRC and _snapRC.Parent) then return end
                        local wrapLayers = {}
                        for _, desc in _snapRC:GetDescendants() do
                            if desc:IsA("WrapLayer") then
                                wrapLayers[#wrapLayers + 1] = desc
                                pcall(function() desc.Enabled = false end)
                            end
                        end
                        task.defer(function()
                            for _, wl in wrapLayers do
                                pcall(function()
                                    if wl and wl.Parent then wl.Enabled = true end
                                end)
                            end
                        end)
                        for _, child in _snapRC:GetChildren() do
                            if child:IsA("Accessory") then
                                local handle = child:FindFirstChild("Handle")
                                if handle then
                                    local weld = handle:FindFirstChildWhichIsA("Weld")
                                               or handle:FindFirstChildWhichIsA("AccessoryWeld")
                                    if weld and weld.Part1 and weld.Part1.Parent then
                                        pcall(function()
                                            handle.CFrame = weld.Part1.CFrame
                                                          * weld.C1 * weld.C0:Inverse()
                                        end)
                                    end
                                end
                            end
                        end
                    end)
                end
                if pg2 then
                    for _, gui in pg2:GetChildren() do
                        if gui:IsA("ScreenGui") and _guisFlipped2[gui] then gui.ResetOnSpawn=true end
                    end
                end
            end
            monoReanim.real_chars[player] = nil
            if monoReanim.destroyBehavior ~= nil then
                pcall(sethiddenproperty, monoReanim.services.workspace, "PlayerCharacterDestroyBehavior", monoReanim.destroyBehavior)
                monoReanim.destroyBehavior = nil
            end
            if monoReanim.callbacks.on_deactivate then pcall(monoReanim.callbacks.on_deactivate) end
            monoReanim.flags.reanimated = false
            if _G._nv_reanimRunning == API then _G._nv_reanimRunning = nil end
        end
    return end

    API.play_animation = function(url, speed)
        if not monoReanim.flags.reanimated then return "Cannot play animation, not reanimated." end
        local player = get_local_player()
        if typeof(player) == "string" then return player end
        local cc = monoReanim.animation.body or API.get_clone(player)
        if not cc then return "Cannot play animation, clone character not found." end
        if monoReanim.animation.state.is_playing and monoReanim.animation.state.current_url==url then
            API.stop_animation(); return
        end
        local anim = monoReanim.animation
        anim.load_id = (anim.load_id or 0) + 1
        local loadId = anim.load_id
        local keyframe_data, resolveErr = resolveAnimData(url)
        if loadId ~= anim.load_id then return end
        if not keyframe_data then return resolveErr or "Animation Error: Failed to load." end
        local keyframes = keyframe_data[_nvAny(keyframe_data)]
        if not keyframes or #keyframes==0 then return "No keyframes array found for animation URL: "..url end

        local blendFrom, blendCarried, blendSrc
        if API.blend_capture then blendFrom, blendCarried, blendSrc = API.blend_capture() end
        API.stop_animation(blendFrom ~= nil and next(blendFrom) ~= nil)
        if loadId ~= anim.load_id then return end
        local ctrl = cc:FindFirstChildOfClass("Humanoid") or cc:FindFirstChildOfClass("AnimationController")
        if ctrl then
            local tracks = ctrl:GetPlayingAnimationTracks()
            if tracks then for _, track in tracks do track:Stop(0) end end
        end
        local cas = cc:FindFirstChild("Animate")
        if cas then cas.Enabled = false end
        anim.state.speed = tonumber(speed) or 1.0
        anim.state.dir = anim.state.dir or 1
        anim.state.keyframes = keyframes
        anim.state.is_playing = true
        anim.state.current_url = url
        anim.state.total_duration = keyframes[#keyframes].Time
        if anim.state.total_duration<=0 then API.stop_animation(); return end
        anim.state.elapsed_time = 0
        table.clear(anim.joints)
        local restC0s = API.get_original_c0s and API.get_original_c0s() or {}
        for _, d in cc:GetDescendants() do
            if d:IsA("Motor6D") and d.Part1 then
                anim.joints[d.Part1.Name] = d
                anim.original_motor_c0s[d] = restC0s[d] or d.C0
            end
        end

        local hasMotor6D_pa = _nvAny(anim.joints) ~= nil
        if not hasMotor6D_pa then
            anim.ac_joint_map = buildACJointMap(cc)
            if not (anim.ac_joint_map and _nvAny(anim.ac_joint_map)) then
                anim.ac_joint_map = nil
            end
        end
        local blend = API.blend
        if blend then
            local st = anim.state
            blend.start(blendFrom, blendCarried, blendSrc)
            blend.source = {
                kfs = keyframes, total = st.total_duration,
                at = function() return st.elapsed_time end,
                rate = function() return (st.paused or st.hold) and 0 or (st.speed or 1) * (st.dir or 1) end,
            }
        end
        if monoReanim.callbacks.on_play then pcall(monoReanim.callbacks.on_play, anim.state.current_url) end
        local _animCC = cc
        local _animEvent = anim.ac_joint_map
            and monoReanim.services.run_service.PreSimulation
            or  monoReanim.services.run_service.Heartbeat
        local _animAnimator = anim.ac_joint_map and (function()
            local h = _animCC:FindFirstChildOfClass("Humanoid")
                   or _animCC:FindFirstChildOfClass("AnimationController")
            return h and h:FindFirstChildOfClass("Animator")
        end)() or nil
        monoReanim.connections.animation_hb = _animEvent:Connect(
            function(dt)
                if not anim.state.is_playing then return end
                if not _animCC or not _animCC.Parent then
                    API.stop_animation(); return
                end
                if not anim.state.paused and not anim.state.hold then
                    local dir = anim.state.dir or 1
                    anim.state.elapsed_time =
                        (anim.state.elapsed_time + dt * anim.state.speed * dir) % anim.state.total_duration
                end
                local kfs = anim.state.keyframes
                local t = anim.state.elapsed_time
                local lo, hi = 1, #kfs - 1
                while lo < hi do
                    local mid = math.floor((lo + hi + 1) / 2)
                    if kfs[mid].Time <= t then lo = mid else hi = mid - 1 end
                end
                local cf = kfs[lo]
                local nf = kfs[lo + 1] or kfs[1]
                local fd = nf.Time - cf.Time
                if fd <= 0 then fd = (anim.state.total_duration - cf.Time) + nf.Time end
                local segElapsed = t - cf.Time
                if segElapsed < 0 then segElapsed = segElapsed + anim.state.total_duration end
                local alpha = math.clamp(segElapsed / fd, 0, 1)
                if anim.ac_joint_map then
                    if _animAnimator and _animAnimator.EvaluationThrottled then return end
                    local blending = blend and blend.step(dt)
                    for _, entry in AC_HIERARCHY do
                        local jd = anim.ac_joint_map[entry.part]
                        if jd and jd.constraint and jd.constraint.Parent then
                            local poseCF = CFrame.identity
                            if cf.Data and cf.Data[entry.part] then
                                local p = cf.Data[entry.part]
                                local np = nf.Data and nf.Data[entry.part]
                                poseCF = (np ~= nil) and p:Lerp(np, alpha) or p
                            end
                            if blending then poseCF = blend.mix(entry.part, poseCF) end
                            jd.constraint.Transform = poseCF
                        end
                    end
                else
                    local blending = blend and blend.step(dt)
                    for partName, pose_cf in cf.Data do
                        local motor = anim.joints[partName]
                        if motor and anim.original_motor_c0s[motor]
                        and not (monoReanim.trickJoints and monoReanim.trickJoints[motor]) then
                            local orig = anim.original_motor_c0s[motor]
                            local np = nf.Data and nf.Data[partName]
                            local pose = np and pose_cf:Lerp(np,alpha) or pose_cf
                            if blending then pose = blend.mix(partName, pose) end
                            motor.C0 = orig*pose
                        end
                    end
                    if blending then
                        blend.rest(function(name, pose)
                            local motor = anim.joints[name]
                            local orig = motor and anim.original_motor_c0s[motor]
                            if orig and motor.Parent then motor.C0 = orig*pose end
                        end)
                    end
                end
            end)
    return end

    local ARM_SETS = {
        r15 = {
            { pole = "LeftUpperArm",  hide = { "LeftLowerArm", "LeftHand" } },
            { pole = "RightUpperArm", hide = { "RightLowerArm", "RightHand" } },
        },
        r6 = {
            { pole = "Left Arm",  hide = {} },
            { pole = "Right Arm", hide = {} },
        },
    }

    local function findMotorByPart1(char, name)
        for _, d in char:GetDescendants() do
            if d:IsA("Motor6D") and d.Part1 and d.Part1.Name == name then return d end
        end
        return nil
    end

    API.are_arms_poles = function() return monoReanim.poles.active end

    API.set_arm_poles = function(enable, length)
        local player = get_local_player()
        if typeof(player) == "string" then return player end
        local rc = monoReanim.real_chars[player]
        if enable then
            if not monoReanim.flags.reanimated then return "Cannot make poles, not reanimated." end
            if not (rc and rc.Parent) then return "Reanimated body not found." end
            if monoReanim.poles.active then return end
            local L = math.max(4, tonumber(length) or monoReanim.poles.length)
            monoReanim.poles.length = L
            local isR6 = rc:FindFirstChild("Torso") ~= nil and rc:FindFirstChild("Left Arm") ~= nil
            local sets = isR6 and ARM_SETS.r6 or ARM_SETS.r15
            local items, hidden = {}, {}
            for _, set in sets do
                local part = rc:FindFirstChild(set.pole)
                local motor = findMotorByPart1(rc, set.pole)
                if part and part:IsA("BasePart") and motor then
                    items[#items+1] = {
                        part = part, motor = motor,
                        origSize = part.Size, origC0 = motor.C0, anchorC0 = motor.C0,
                        origCanCollide = part.CanCollide,
                    }
                    pcall(function()
                        part.Size = Vector3.new(part.Size.X, L, part.Size.Z)
                        part.CanCollide = false
                    end)
                end
                for _, hn in set.hide do
                    local hp = rc:FindFirstChild(hn)
                    if hp and hp:IsA("BasePart") then
                        hidden[#hidden+1] = { part = hp, t = hp.Transparency }
                        pcall(function() hp.Transparency = 1 end)
                    end
                end
            end
            if #items == 0 then return "No arm parts found to convert." end
            monoReanim.poles.items = items
            monoReanim.poles.hidden = hidden
            monoReanim.poles.active = true
            monoReanim.poles.conn = monoReanim.services.run_service.Heartbeat:Connect(function()
                if not monoReanim.flags.reanimated then API.set_arm_poles(false); return end
                local down = Vector3.new(0, L * 0.5, 0)
                for _, it in monoReanim.poles.items do
                    local m = it.motor
                    if m and m.Parent and m.Part0 and m.Part1 then
                        local shoulder = m.Part0.CFrame * it.anchorC0
                        local targetCF = CFrame.new(shoulder.Position - down)
                        if monoReanim.puppet.active then
                            m.C0 = m.Part0.CFrame:Inverse() * targetCF * m.C1
                        else
                            pcall(function() it.part.CFrame = targetCF end)
                        end
                    end
                end
            end)
        else
            if monoReanim.poles.conn then
                pcall(function() monoReanim.poles.conn:Disconnect() end)
                monoReanim.poles.conn = nil
            end
            for _, it in monoReanim.poles.items do
                if it.part and it.part.Parent then
                    pcall(function() it.part.Size = it.origSize end)
                    pcall(function() it.part.CanCollide = it.origCanCollide end)
                end
                if it.motor and it.motor.Parent then pcall(function() it.motor.C0 = it.origC0 end) end
            end
            for _, h in monoReanim.poles.hidden do
                if h.part and h.part.Parent then pcall(function() h.part.Transparency = h.t end) end
            end
            monoReanim.poles.items = {}
            monoReanim.poles.hidden = {}
            monoReanim.poles.active = false
        end
    return end

    local POLE_LIMBS = {
        rightArm = {r15 = {"RightUpperArm", "RightLowerArm", "RightHand"}, r6 = {"Right Arm"}},
        leftArm = {r15 = {"LeftUpperArm", "LeftLowerArm", "LeftHand"}, r6 = {"Left Arm"}},
        rightLeg = {r15 = {"RightUpperLeg", "RightLowerLeg", "RightFoot"}, r6 = {"Right Leg"}},
        leftLeg = {r15 = {"LeftUpperLeg", "LeftLowerLeg", "LeftFoot"}, r6 = {"Left Leg"}},
    }
    local POLE_FLIP = CFrame.Angles(math.pi, 0, 0)

    local function poleLayout(parts, height)
        local list = {}
        local bottom, middle, top = parts[1], parts[2], parts[3]
        if not bottom then return list, 0 end
        local floor = bottom.Size.Y + (middle and middle.Size.Y or 0) + (top and top.Size.Y or 0)
        height = math.max(tonumber(height) or 0, floor)
        list[1] = {part = bottom, offset = CFrame.new(0, bottom.Size.Y * 0.5, 0) * POLE_FLIP}
        local tip = top and top.Size.Y or 0
        if middle then
            list[#list + 1] = {part = middle, offset = CFrame.new(0, height - tip - middle.Size.Y * 0.5, 0) * POLE_FLIP}
        end
        if top then
            list[#list + 1] = {part = top, offset = CFrame.new(0, height - top.Size.Y * 0.5, 0) * POLE_FLIP}
        end
        if not middle and not top then height = bottom.Size.Y end
        return list, height
    end

    local function poleRelayout(entry, height)
        local list, h = poleLayout(entry.parts, height)
        local byPart = {}
        for _, it in list do byPart[it.part] = it.offset end
        for _, it in entry.items do
            if byPart[it.part] then it.offset = byPart[it.part] end
        end
        entry.height = h
    end

    local function poleRelease(limb)
        local pole = monoReanim.pole
        local entry = pole.list[limb]
        if not entry then return end
        pole.list[limb] = nil
        if _nvAny(entry.collide) then
            local player = get_local_player()
            local cc = typeof(player) ~= "string" and monoReanim.clones[player] or nil
            local rcHome = typeof(player) ~= "string" and monoReanim.real_chars[player] or nil
            local anchor = rcHome and rcHome:FindFirstChild("HumanoidRootPart")
            for _, it in entry.items do
                local part = it.part
                local src = cc and cc:FindFirstChild(part.Name)
                local to = src and src:IsA("BasePart") and src.CFrame or nil
                if not to and rcHome then
                    local m = findMotorByPart1(rcHome, part.Name)
                    if m and m.Part0 and m.Part0.Parent then to = m.Part0.CFrame * m.C0 * m.C1:Inverse() end
                end
                if not to and anchor then to = anchor.CFrame end
                if part.Parent and to then
                    pcall(function()
                        part.CFrame = to
                        part.AssemblyLinearVelocity = Vector3.zero
                        part.AssemblyAngularVelocity = Vector3.zero
                    end)
                end
            end
        end
        for inst, was in entry.enabled do
            if inst.Parent then pcall(function() inst.Enabled = was end) end
        end
        for part, was in entry.collide do
            if part.Parent then pcall(function() part.CanCollide = was end) end
            pole.skip[part] = nil
        end
        for motor, c0 in entry.c0 do
            if motor.Parent then
                local rest = monoReanim.animation.original_motor_c0s[motor] or c0
                pcall(function() motor.C0 = rest end)
            end
        end
        if not _nvAny(pole.list) and pole.render then
            pcall(function() pole.render:Disconnect() end)
            pole.render = nil
        end
    end

    local function poleReleaseAll()
        local names = {}
        for limb in monoReanim.pole.list do names[#names + 1] = limb end
        for _, limb in names do poleRelease(limb) end
    end

    local function poleBuild(rc, setName, wantHeight)
        local pole = monoReanim.pole
        local group = POLE_LIMBS[setName] or POLE_LIMBS.rightArm
        local r6 = rc:FindFirstChild("UpperTorso") == nil and rc:FindFirstChild("Torso") ~= nil
        local parts = {}
        for _, name in r6 and group.r6 or group.r15 do
            local part = rc:FindFirstChild(name)
            if part and part:IsA("BasePart") then parts[#parts + 1] = part end
        end
        local list, height = poleLayout(parts, wantHeight)
        if #list == 0 then return nil, "That limb is missing" end
        for _, part in parts do
            if pole.skip[part] or monoReanim.reach.skip[part] or monoReanim.free.skip[part] then return nil, "That limb is busy" end
        end
        local root = rc:FindFirstChild("HumanoidRootPart")
        local visible = not monoReanim.puppet.active
        local items, seen, riders, riderCount = {}, {}, {}, 0
        for _, it in list do
            if visible then
                local ar = it.part.AssemblyRootPart
                if not (root and ar == root.AssemblyRootPart) then
                    if ar and seen[ar] then
                        if it.part ~= parts[3] then
                            return nil, "This game keeps your elbows and knees attached"
                        end
                        riders[it.part] = true
                        riderCount = riderCount + 1
                    else
                        if ar then seen[ar] = true end
                        items[#items + 1] = it
                    end
                end
            else
                it.motor = findMotorByPart1(rc, it.part.Name)
                if it.motor then items[#items + 1] = it end
            end
        end
        if #items == 0 then
            return nil, visible and "This game keeps your limbs attached" or "No joints found for your limbs"
        end
        if visible and #items + riderCount < #list then
            return nil, "This game keeps your shoulders and hips attached"
        end
        local entry = {items = items, parts = parts, height = height, limb = setName, enabled = {}, collide = {}, c0 = {}}
        local inPole = {}
        for _, it in items do inPole[it.part] = true end
        if visible then
            local function ownerPart(x)
                if x and x:IsA("Attachment") then x = x.Parent end
                if x and x:IsA("BasePart") then return x end
                return nil
            end
            local function rides(x)
                return x ~= nil and not inPole[x] and (riders[x] == true or (x.Parent ~= rc and x:IsDescendantOf(rc)))
            end
            local function grabs(p0, p1)
                return (p0 ~= nil and inPole[p0] and not rides(p1)) or (p1 ~= nil and inPole[p1] and not rides(p0))
            end
            local function joint(d)
                return d:IsA("BallSocketConstraint") or d:IsA("HingeConstraint") or d:IsA("UniversalConstraint")
                    or d:IsA("RodConstraint") or d:IsA("RopeConstraint") or d:IsA("SpringConstraint")
                    or d:IsA("PrismaticConstraint") or d:IsA("CylindricalConstraint")
            end
            for _, d in rc:GetDescendants() do
                if d:IsA("Constraint") and not d:IsA("NoCollisionConstraint") and not joint(d) then
                    if grabs(ownerPart(d.Attachment0), ownerPart(d.Attachment1)) then
                        entry.enabled[d] = d.Enabled
                        pcall(function() d.Enabled = false end)
                    end
                elseif d:IsA("WeldConstraint") then
                    if grabs(d.Part0, d.Part1) then
                        entry.enabled[d] = d.Enabled
                        pcall(function() d.Enabled = false end)
                    end
                end
            end
            for _, it in items do
                entry.collide[it.part] = it.part.CanCollide
                pcall(function() it.part.CanCollide = false end)
                pole.skip[it.part] = true
            end
            for part in riders do
                entry.collide[part] = part.CanCollide
                pcall(function() part.CanCollide = false end)
                pole.skip[part] = true
            end
        else
            for _, it in items do entry.c0[it.motor] = it.motor.C0 end
            if not pole.render then
                pole.render = monoReanim.services.run_service.RenderStepped:Connect(function()
                    for _, e in monoReanim.pole.list do
                        if e.base then
                            local targets = {}
                            for _, it in e.items do targets[it.part] = e.base * it.offset end
                            for _, it in e.items do
                                local m = it.motor
                                if m and m.Parent and m.Part0 then
                                    local parentCF = targets[m.Part0] or m.Part0.CFrame
                                    m.C0 = parentCF:Inverse() * targets[it.part] * m.C1 * m.Transform:Inverse()
                                end
                            end
                        end
                    end
                end)
            end
        end
        return entry
    end

    API.pole_place = function(cf, setName, height)
        local player = get_local_player()
        if typeof(player) == "string" then return false, player end
        if not monoReanim.flags.reanimated then return false, "Reanimate first" end
        local rc = monoReanim.real_chars[player]
        if not rc or not rc.Parent then return false, "No character" end
        local pole = monoReanim.pole
        local entry = pole.list[setName]
        if not entry then
            local built, err = poleBuild(rc, setName, height)
            if not built then return false, err end
            entry = built
            pole.list[setName] = entry
        elseif height and height ~= entry.height then
            poleRelayout(entry, height)
        end
        entry.base = cf
        return true, monoReanim.puppet.active and "local" or "shared", entry.height
    end

    API.pole_clear = function(setName)
        if setName then poleRelease(setName) else poleReleaseAll() end
    end

    API.pole_active = function(setName)
        if setName then return monoReanim.pole.list[setName] ~= nil end
        return _nvAny(monoReanim.pole.list) ~= nil
    end

    API.pole_height = function(setName)
        local entry = setName and monoReanim.pole.list[setName] or select(2, _nvAny(monoReanim.pole.list))
        return entry and entry.height or nil
    end

    API.pole_stretchable = function(setName)
        local entry = setName and monoReanim.pole.list[setName] or select(2, _nvAny(monoReanim.pole.list))
        return entry ~= nil and #entry.parts > 1
    end

    API.pole_mode = function()
        if not monoReanim.flags.reanimated then return nil end
        return monoReanim.puppet.active and "local" or "shared"
    end

    local REACH_PARTS = {
        left = {"LeftUpperArm", "LeftLowerArm", "LeftHand"},
        right = {"RightUpperArm", "RightLowerArm", "RightHand"},
        attach_leftArm = {"LeftUpperArm", "LeftLowerArm", "LeftHand"},
        attach_rightArm = {"RightUpperArm", "RightLowerArm", "RightHand"},
        attach_leftLeg = {"LeftUpperLeg", "LeftLowerLeg", "LeftFoot"},
        attach_rightLeg = {"RightUpperLeg", "RightLowerLeg", "RightFoot"},
    }

    local function reachEase(t, extending)
        t = math.clamp(t, 0, 1)
        if extending then
            local c = 1.25
            local y = t - 1
            return 1 + (c + 1) * y * y * y + c * y * y
        end
        return t * t * t
    end

    local function reachBasis(pos, dir, ref)
        local up = -dir
        local fwd = ref.LookVector
        fwd = fwd - up * fwd:Dot(up)
        if fwd.Magnitude < 0.05 then fwd = ref.RightVector:Cross(up) end
        fwd = fwd.Unit
        return CFrame.fromMatrix(pos, up:Cross(-fwd), up, -fwd)
    end

    local function reachUpper(arm, animated, e)
        local m = arm.motorUpper
        if not (m and m.Part0 and m.Part0.Parent) then return animated end
        local restC0 = monoReanim.animation.original_motor_c0s[m] or arm.restUpperC0 or m.C0
        local pivot = (m.Part0.CFrame * restC0).Position
        local dir = arm.target - pivot
        if dir.Magnitude < 0.05 then return animated end
        dir = dir.Unit
        local aimed = reachBasis(pivot + dir * (arm.upper.Size.Y * 0.5), dir, m.Part0.CFrame)
        return animated:Lerp(aimed, math.clamp(e, 0, 1))
    end

    local function reachFrames(arm, upperCF, rest, e)
        local elbow = (upperCF * CFrame.new(0, -arm.upper.Size.Y * 0.5, 0)).Position
        local tip = rest:Lerp(arm.target, e)
        local dir = tip - elbow
        if dir.Magnitude < 0.05 then
            dir = -upperCF.UpVector
        else
            dir = dir.Unit
        end
        local up = -dir
        local fwd = upperCF.LookVector
        fwd = fwd - up * fwd:Dot(up)
        if fwd.Magnitude < 0.05 then fwd = upperCF.RightVector:Cross(up) end
        fwd = fwd.Unit
        local right = up:Cross(-fwd)
        local handPos = tip - dir * (arm.hand.Size.Y * 0.5)
        local lowerPos = handPos - dir * (arm.hand.Size.Y * 0.5 + arm.lower.Size.Y * 0.5)
        return CFrame.fromMatrix(lowerPos, right, up, -fwd), CFrame.fromMatrix(handPos, right, up, -fwd)
    end

    local function reachRelease(side)
        local reach = monoReanim.reach
        local arm = reach.arms[side]
        if not arm then return end
        reach.arms[side] = nil
        for part, was in arm.collide do
            if part.Parent then pcall(function() part.CanCollide = was end) end
            reach.skip[part] = nil
        end
        for motor, c0 in arm.c0 do
            if motor.Parent then
                local rest = monoReanim.animation.original_motor_c0s[motor] or c0
                pcall(function() motor.C0 = rest end)
            end
        end
        if not _nvAny(reach.arms) and reach.render then
            pcall(function() reach.render:Disconnect() end)
            reach.render = nil
        end
    end

    monoReanim.reach.step = function(puppet)
        local reach = monoReanim.reach
        local now = os.clock()
        local dt = math.min(now - (reach.last or now), 0.1)
        reach.last = now
        local player = get_local_player()
        local cc = typeof(player) ~= "string" and monoReanim.clones[player] or nil
        for side, arm in reach.arms do
            if arm.goal == 1 then
                arm.t = math.min(1, arm.t + dt / 0.26)
            else
                arm.t = math.max(0, arm.t - dt / 0.18)
            end
            if arm.goal == 0 and arm.t <= 0 then
                reachRelease(side)
            elseif arm.upper.Parent and arm.lower.Parent and arm.hand.Parent then
                local surface = arm.surface
                if surface and surface.Parent and arm.grip then
                    arm.target = surface.CFrame:PointToWorldSpace(arm.grip)
                elseif surface then
                    arm.surface = nil
                end
                local e = reachEase(arm.t, arm.goal == 1)
                local animated
                local upperSrc = cc and cc:FindFirstChild(arm.upper.Name)
                local mu = arm.motorUpper
                if not puppet and upperSrc and upperSrc:IsA("BasePart") then
                    animated = upperSrc.CFrame
                elseif mu and mu.Part0 and mu.Part0.Parent then
                    animated = mu.Part0.CFrame * (monoReanim.animation.original_motor_c0s[mu] or arm.restUpperC0 or mu.C0) * mu.C1:Inverse()
                else
                    animated = arm.upper.CFrame
                end
                local upperCF = reachUpper(arm, animated, e)
                local src = cc and cc:FindFirstChild(arm.hand.Name)
                local rest
                if not puppet and src and src:IsA("BasePart") then
                    rest = (src.CFrame * CFrame.new(0, -src.Size.Y * 0.5, 0)).Position
                else
                    rest = (upperCF * CFrame.new(0, -arm.upper.Size.Y * 0.5 - arm.lower.Size.Y - arm.hand.Size.Y, 0)).Position
                end
                local lowerCF, handCF = reachFrames(arm, upperCF, rest, e)
                if puppet then
                    local ml, mh = arm.motorLower, arm.motorHand
                    if mu and mu.Parent and mu.Part0 then
                        mu.C0 = mu.Part0.CFrame:Inverse() * upperCF * mu.C1 * mu.Transform:Inverse()
                    end
                    if ml and ml.Parent then
                        ml.C0 = upperCF:Inverse() * lowerCF * ml.C1 * ml.Transform:Inverse()
                    end
                    if mh and mh.Parent then
                        mh.C0 = lowerCF:Inverse() * handCF * mh.C1 * mh.Transform:Inverse()
                    end
                else
                    if arm.aimUpper then
                        arm.upper.CFrame = upperCF
                        arm.upper.AssemblyLinearVelocity = Vector3.zero
                        arm.upper.AssemblyAngularVelocity = Vector3.zero
                    end
                    arm.lower.CFrame = lowerCF
                    arm.hand.CFrame = handCF
                    arm.lower.AssemblyLinearVelocity = Vector3.zero
                    arm.hand.AssemblyLinearVelocity = Vector3.zero
                    arm.lower.AssemblyAngularVelocity = Vector3.zero
                    arm.hand.AssemblyAngularVelocity = Vector3.zero
                end
            end
        end
    end

    API.reach_set = function(side, point, surface)
        local reach = monoReanim.reach
        local names = REACH_PARTS[side]
        if not names then return false, "Unknown arm" end
        if not point then
            local arm = reach.arms[side]
            if arm then arm.goal = 0 end
            return true
        end
        local player = get_local_player()
        if typeof(player) == "string" then return false, player end
        if not monoReanim.flags.reanimated then return false, "Reanimate first" end
        local rc = monoReanim.real_chars[player]
        if not rc or not rc.Parent then return false, "No character" end
        local arm = reach.arms[side]
        if not arm then
            local upper, lower, hand = rc:FindFirstChild(names[1]), rc:FindFirstChild(names[2]), rc:FindFirstChild(names[3])
            if not (upper and lower and hand and upper:IsA("BasePart") and lower:IsA("BasePart") and hand:IsA("BasePart")) then
                return false, "Your arms are one piece, so they cannot stretch"
            end
            local pskip = monoReanim.pole.skip
            if pskip[upper] or pskip[lower] or pskip[hand] then return false, "That arm is in your pole" end
            local rskip, fskip = reach.skip, monoReanim.free.skip
            if rskip[upper] or rskip[lower] or rskip[hand] or fskip[upper] or fskip[lower] or fskip[hand] then return false, "That limb is busy" end
            for _, other in reach.arms do
                if other.upper == upper or other.lower == lower or other.hand == hand then return false, "That limb is busy" end
            end
            local puppet = monoReanim.puppet.active
            arm = {upper = upper, lower = lower, hand = hand, t = 0, goal = 1, collide = {}, c0 = {}}
            arm.motorUpper = findMotorByPart1(rc, upper.Name)
            if arm.motorUpper then arm.restUpperC0 = arm.motorUpper.C0 end
            if puppet then
                arm.motorLower = findMotorByPart1(rc, lower.Name)
                arm.motorHand = findMotorByPart1(rc, hand.Name)
                if not (arm.motorLower and arm.motorHand) then return false, "No arm joints found" end
                arm.c0[arm.motorLower] = arm.motorLower.C0
                arm.c0[arm.motorHand] = arm.motorHand.C0
                if arm.motorUpper then arm.c0[arm.motorUpper] = arm.motorUpper.C0 end
            else
                local root = rc:FindFirstChild("HumanoidRootPart")
                local body = root and root.AssemblyRootPart
                if lower.AssemblyRootPart == body or hand.AssemblyRootPart == body or lower.AssemblyRootPart == upper.AssemblyRootPart then
                    return false, "This game keeps your arms attached"
                end
                local driven = {lower, hand}
                if upper.AssemblyRootPart ~= body then
                    arm.aimUpper = true
                    driven[3] = upper
                end
                for _, part in driven do
                    arm.collide[part] = part.CanCollide
                    pcall(function() part.CanCollide = false end)
                    reach.skip[part] = true
                end
            end
            reach.arms[side] = arm
            reach.last = os.clock()
            if puppet and not reach.render then
                reach.render = monoReanim.services.run_service.RenderStepped:Connect(function()
                    monoReanim.reach.step(true)
                end)
            end
        end
        arm.target = point
        if typeof(surface) == "Instance" and surface:IsA("BasePart") and not surface:IsA("Terrain") then
            arm.surface = surface
            arm.grip = surface.CFrame:PointToObjectSpace(point)
        else
            arm.surface, arm.grip = nil, nil
        end
        arm.goal = 1
        return true, monoReanim.puppet.active and "local" or "shared"
    end

    API.reach_clear = function()
        for side in monoReanim.reach.arms do reachRelease(side) end
    end

    API.reach_active = function(side)
        local arm = monoReanim.reach.arms[side]
        return arm ~= nil and arm.goal == 1
    end

    API._buildACJointMap = buildACJointMap
    API._setACConstraints = setACConstraints
    API._AC_HIERARCHY = AC_HIERARCHY

_G.hiddenBodyParts = _G.hiddenBodyParts or {}

API.set_limb_visibility = function(partName, visible)
    _G.hiddenBodyParts = _G.hiddenBodyParts or {}
    if visible then
        _G.hiddenBodyParts[partName] = nil
    else
        _G.hiddenBodyParts[partName] = true
    end
end
API.is_limb_hidden = function(partName)
    return (_G.hiddenBodyParts and _G.hiddenBodyParts[partName] == true) or false
end
API.unhide_all_limbs = function()
    if _G.hiddenBodyParts then table.clear(_G.hiddenBodyParts) end
end

monoReanimLocalPlayer = function() return game:GetService("Players").LocalPlayer end
monoReanimAPI = API
monoReanimHidden = _G.hiddenBodyParts
monoReanim.refreshHidden = function() end

monoReanim.poles.list = monoReanim.pole.list
monoReanim.poles.skip = monoReanim.pole.skip
monoReanim.poles.render = monoReanim.pole.render

monoReanim.trickJoints = {}

monoReanimAPI.on_deactivate(function()
    local real_char = monoMirrorRealChar
    monoRestoreMirror()
    if not real_char then return end

    local real_hum = real_char:FindFirstChildOfClass("Humanoid")
    if real_hum then
        pcall(function()
            for _, state in ipairs({
                Enum.HumanoidStateType.Dead,
                Enum.HumanoidStateType.FallingDown,
                Enum.HumanoidStateType.Ragdoll,
                Enum.HumanoidStateType.GettingUp,
                Enum.HumanoidStateType.Freefall,
                Enum.HumanoidStateType.Flying,
                Enum.HumanoidStateType.Landed,
                Enum.HumanoidStateType.Running,
                Enum.HumanoidStateType.Climbing,
                Enum.HumanoidStateType.Swimming,
                Enum.HumanoidStateType.Seated,
                Enum.HumanoidStateType.PlatformStanding,
            }) do
                real_hum:SetStateEnabled(state, true)
            end
            real_hum.PlatformStand = false
            real_hum.Sit = false
            real_hum.RequiresNeck = true
            real_hum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.Viewer
            real_hum:ChangeState(Enum.HumanoidStateType.GettingUp)
            real_hum:ChangeState(Enum.HumanoidStateType.Landed)
            real_hum:ChangeState(Enum.HumanoidStateType.Running)
        end)
    end

    local rightLegAssets = { "902843398" }
    local leftLegAssets = { "902842271", "9598310137" }
    local legTargetTransparency = {
        RightUpperLeg = 0, RightLowerLeg = 1, RightFoot = 1,
        LeftFoot = 1, LeftUpperLeg = 0, LeftLowerLeg = 0,
    }

    local function partMeshId(p)
        local ids = ""
        pcall(function()
            if p:IsA("MeshPart") then
                ids = tostring(p.MeshId or "") .. " " .. tostring(p.TextureID or "")
            else
                local sm = p:FindFirstChildOfClass("SpecialMesh")
                if sm then ids = tostring(sm.MeshId or "") .. " " .. tostring(sm.TextureId or "") end
            end
        end)
        return ids
    end

    local function legEquipped(partPrefix, assets)
        for _, suffix in ipairs({ "UpperLeg", "LowerLeg", "Foot" }) do
            local p = real_char:FindFirstChild(partPrefix .. suffix)
            if p and p:IsA("BasePart") then
                local mid = partMeshId(p)
                for _, a in ipairs(assets) do
                    if mid:find(a, 1, true) then return true end
                end
            end
        end
        return false
    end

    local rightLegOn = legEquipped("Right", rightLegAssets)
    local leftLegOn = legEquipped("Left", leftLegAssets)

    for _, v in ipairs(real_char:GetDescendants()) do
        if v:IsA("NoCollisionConstraint") then
            pcall(function() v:Destroy() end)
        elseif v:IsA("Motor6D") or v:IsA("Weld") or v:IsA("WeldConstraint") then
            pcall(function() v.Enabled = true end)
        elseif v:IsA("BasePart") then
            pcall(function()
                v.Massless = false
                v.CanTouch = true
                v.CanQuery = true
                v.CustomPhysicalProperties = nil
                v.AssemblyLinearVelocity = Vector3.new()
                v.AssemblyAngularVelocity = Vector3.new()
                local n = v.Name
                local tr = 0
                if (rightLegOn and (n == "RightUpperLeg" or n == "RightLowerLeg" or n == "RightFoot"))
                or (leftLegOn and (n == "LeftUpperLeg" or n == "LeftLowerLeg" or n == "LeftFoot")) then
                    tr = legTargetTransparency[n] or 0
                end
                if n ~= "HumanoidRootPart" then
                    v.Transparency = tr
                    v.LocalTransparencyModifier = tr
                else
                    v.Transparency = 1
                    v.LocalTransparencyModifier = 1
                end
                if n == "UpperTorso" or n == "LowerTorso" or n == "Torso" then
                    v.CanCollide = true
                else
                    v.CanCollide = false
                end
            end)
        elseif v:IsA("Decal") then
            pcall(function() v.Transparency = 0 end)
        end
    end
end)

local monoPoleLimbs = {
    rightArm = { r15 = { "RightUpperArm", "RightLowerArm", "RightHand" }, r6 = { "Right Arm" } },
    leftArm  = { r15 = { "LeftUpperArm", "LeftLowerArm", "LeftHand" }, r6 = { "Left Arm" } },
    rightLeg = { r15 = { "RightUpperLeg", "RightLowerLeg", "RightFoot" }, r6 = { "Right Leg" } },
    leftLeg  = { r15 = { "LeftUpperLeg", "LeftLowerLeg", "LeftFoot" }, r6 = { "Left Leg" } },
}
local monoPoleFlip = CFrame.Angles(math.pi, 0, 0)

local function monoPoleFindMotor(char, partName)
    for _, m in ipairs(char:GetDescendants()) do
        if m:IsA("Motor6D") and m.Part1 and m.Part1.Name == partName then return m end
    end
    return nil
end

local function monoPoleLayout(parts, height)
    local list = {}
    local bottom, middle, top = parts[1], parts[2], parts[3]
    if not bottom then return list, 0 end
    local floor = bottom.Size.Y + (middle and middle.Size.Y or 0) + (top and top.Size.Y or 0)
    height = math.max(tonumber(height) or 0, floor)
    list[1] = { part = bottom, offset = CFrame.new(0, bottom.Size.Y * 0.5, 0) * monoPoleFlip }
    local tip = top and top.Size.Y or 0
    if middle then
        list[#list + 1] = { part = middle, offset = CFrame.new(0, height - tip - middle.Size.Y * 0.5, 0) * monoPoleFlip }
    end
    if top then
        list[#list + 1] = { part = top, offset = CFrame.new(0, height - top.Size.Y * 0.5, 0) * monoPoleFlip }
    end
    if not middle and not top then height = bottom.Size.Y end
    return list, height
end

local function monoPoleRelease(setName)
    local entry = monoReanim.poles.list[setName]
    if not entry then return end
    monoReanim.poles.list[setName] = nil
    local player = monoReanimLocalPlayer()
    local rc = typeof(player) ~= "string" and monoReanim.real_chars[player] or nil
    local cc = typeof(player) ~= "string" and monoReanim.clones[player] or nil
    local anchor = rc and rc:FindFirstChild("HumanoidRootPart")
    for _, it in ipairs(entry.items or {}) do
        local part = it.part
        local src = cc and cc:FindFirstChild(part.Name)
        local to = src and src:IsA("BasePart") and src.CFrame or nil
        if not to and rc then
            local m = monoPoleFindMotor(rc, part.Name)
            if m and m.Part0 and m.Part0.Parent then to = m.Part0.CFrame * m.C0 * m.C1:Inverse() end
        end
        if not to and anchor then to = anchor.CFrame end
        if part.Parent and to then
            pcall(function()
                part.CFrame = to
                part.AssemblyLinearVelocity = Vector3.zero
                part.AssemblyAngularVelocity = Vector3.zero
            end)
        end
    end
    for inst, was in pairs(entry.enabled or {}) do
        if inst.Parent then pcall(function() inst.Enabled = was end) end
    end
    for part, was in pairs(entry.collide or {}) do
        if part.Parent then pcall(function() part.CanCollide = was end) end
        monoReanim.poles.skip[part] = nil
    end
    for motor, c0 in pairs(entry.c0 or {}) do
        if motor.Parent then
            local rest = (monoReanim.animation.original_motor_c0s and monoReanim.animation.original_motor_c0s[motor]) or c0
            pcall(function() motor.C0 = rest end)
        end
    end
    local any = false
    for _ in pairs(monoReanim.poles.list) do any = true; break end
    if not any then
    end
end

local function monoPoleReleaseAll()
    local names = {}
    for limb in pairs(monoReanim.poles.list) do names[#names + 1] = limb end
    for _, limb in ipairs(names) do monoPoleRelease(limb) end
end

local function monoPoleBuild(rc, setName, wantHeight)
    local group = monoPoleLimbs[setName] or monoPoleLimbs.rightArm
    local r6 = rc:FindFirstChild("UpperTorso") == nil and rc:FindFirstChild("Torso") ~= nil
    local parts = {}
    for _, name in ipairs(r6 and group.r6 or group.r15) do
        local part = rc:FindFirstChild(name)
        if part and part:IsA("BasePart") then parts[#parts + 1] = part end
    end
    local list, height = monoPoleLayout(parts, wantHeight)
    if #list == 0 then return nil, "That limb is missing" end
    for _, part in ipairs(parts) do
        if monoReanim.poles.skip[part] then return nil, "That limb is busy" end
    end
    local entries = {}
    for _, it in ipairs(list) do
        it.motor = monoPoleFindMotor(rc, it.part.Name)
        if it.motor then entries[#entries + 1] = it end
    end
    if #entries == 0 then return nil, "No joints found for your limbs" end
    local entry = { items = entries, parts = parts, height = height, limb = setName, enabled = {}, collide = {}, c0 = {} }
    local inPole = {}
    for _, it in ipairs(entries) do inPole[it.part] = true end
    for _, d in ipairs(rc:GetDescendants()) do
        if (d:IsA("Motor6D") or d:IsA("Weld") or d:IsA("WeldConstraint")) and d.Part0 and d.Part1 then
            if inPole[d.Part0] or inPole[d.Part1] then
                entry.enabled[d] = d.Enabled
                pcall(function() d.Enabled = false end)
            end
        end
    end
    for _, it in ipairs(entries) do
        entry.collide[it.part] = it.part.CanCollide
        entry.c0[it.motor] = it.motor.C0
        pcall(function() it.part.CanCollide = false end)
        monoReanim.poles.skip[it.part] = true
    end
    return entry
end

function monoReanimPolePlace(spot, setName, wantHeight)
    if not monoReanim.flags.reanimated then return false, "Enable Reanim first" end
    local player = monoReanimLocalPlayer()
    if typeof(player) == "string" then return false, player end
    local rc = monoReanim.real_chars[player]
    if not (rc and rc.Parent) then return false, "No character" end
    local existing = monoReanim.poles.list[setName]
    if existing then monoPoleRelease(setName) end
    local built, err = monoPoleBuild(rc, setName, wantHeight)
    if not built then return false, err end
    built.base = spot
    monoReanim.poles.list[setName] = built
    return true
end

function monoReanimPoleClear()
    monoPoleReleaseAll()
end

monoReanimFolder = "Monochrome/reanim"
monoReanimCacheFolder = "Monochrome/reanim/cache"
monoReanimCatalogUrl = "https://static.rawth.net/animations.lua"
monoReanimCatalogFile = "catalog2"

function monoReanimUtf8(cp)
    if cp < 128 then return string.char(cp) end
    if cp < 2048 then
        return string.char(192 + math.floor(cp / 64), 128 + (cp % 64))
    end
    return string.char(
        224 + math.floor(cp / 4096),
        128 + (math.floor(cp / 64) % 64),
        128 + (cp % 64)
    )
end

monoReanimGlyphs = {
    starOn = monoReanimUtf8(9733),
    starOff = monoReanimUtf8(9734),
}

monoReanimCfg = nil
monoReanimCatalog = {}
monoReanimBuilt = false
monoReanimWin = nil
monoReanimGui = nil
monoReanimHeight = 560
monoReanimEntry = nil
monoReanimSyncToggle = nil
monoReanimStopBody = nil
monoReanimBuildConns = {}

function monoReanimSay(msg, time)
    if not (monoReanimWin and monoReanimWin.Visible) then return end
    notify("Reanim", tostring(msg), time or 3)
end

function monoReanimIsCustom(item)
    return item.isCustom == true or item.category == "Custom"
end

function monoReanimSort(a, b)
    local ac, bc = monoReanimIsCustom(a), monoReanimIsCustom(b)
    if ac ~= bc then return not ac end
    local ax, bx = a.category or "Reanims", b.category or "Reanims"
    if ax ~= bx then return ax:lower() < bx:lower() end
    return a.name:lower() < b.name:lower()
end

function monoReanimRepairOrder()
    local valid, seen = {}, {}
    for _, name in ipairs(monoReanimCfg.favOrder or {}) do
        if monoReanimCfg.favs[name] and not seen[name] then
            valid[#valid + 1] = name
            seen[name] = true
        end
    end
    local missing = {}
    for name in pairs(monoReanimCfg.favs) do
        if not seen[name] then missing[#missing + 1] = name end
    end
    table.sort(missing, function(a, b) return a:lower() < b:lower() end)
    for _, name in ipairs(missing) do valid[#valid + 1] = name end
    monoReanimCfg.favOrder = valid
end

function monoReanimLoad()
    monoReanimCfg = {
        favs = {}, binds = {}, states = {}, speed = 1.0, speedHotkeys = {},
        customAnims = {}, customIndex = {}, hiddenLimbs = {}, favOrder = {}, height = 1.0,
        armStretch = {}, faceAttach = {}, torsoAim = {}, torsoHeight = {}, headTracker = {}, armLink = {}, headController = {},
        legStretch = {}, legAttach = {}, legLink = {},
        smoothingOn = true, smoothing = 0.25,
    }
    if typeof(readfile) == "function" and typeof(isfile) == "function" then
        local path = configPath(monoReanimFolder, "config")
        pcall(function()
            if isfile(path) then
                local okDec, decoded = pcall(function() return HttpService:JSONDecode(readfile(path)) end)
                if okDec and type(decoded) == "table" then
                    for k, v in pairs(decoded) do
                        if monoReanimCfg[k] ~= nil then monoReanimCfg[k] = v end
                    end
                end
            end
        end)
    end
    monoReanimCfg.favOrder = monoReanimCfg.favOrder or {}

    if monoReanimCfg.states and monoReanimCfg.states["Run"] then
        if not monoReanimCfg.states["Walk"] then
            monoReanimCfg.states["Walk"] = monoReanimCfg.states["Run"]
        end
        monoReanimCfg.states["Run"] = nil
    end
    monoReanimCfg.customAnims = monoReanimCfg.customAnims or {}
    monoReanimCfg.customIndex = monoReanimCfg.customIndex or {}
    monoReanimCfg.hiddenLimbs = monoReanimCfg.hiddenLimbs or {}
    monoReanimRepairOrder()
    for limb, hidden in pairs(monoReanimCfg.hiddenLimbs) do
        if hidden then monoReanimHidden[limb] = true end
    end
    local smoothing = tonumber(monoReanimCfg.smoothing)
    if not smoothing or smoothing ~= smoothing then smoothing = 0.25 end
    monoReanimCfg.smoothing = math.clamp(math.floor(smoothing * 100 + 0.5) / 100, 0.1, 1.0)
    pcall(monoReanimApplyBlend)
    return monoReanimCfg
end

function monoReanimSave()
    if typeof(writefile) ~= "function" then return end
    ensureFolder(monoReanimFolder)
    pcall(function()
        writefile(configPath(monoReanimFolder, "config"), HttpService:JSONEncode(monoReanimCfg))
    end)
end

function monoReanimApplyBlend()
    if type(monoReanimAPI) ~= "table" or type(monoReanimAPI.set_blend) ~= "function" then return end
    local cfg = monoReanimCfg
    local on = true
    if cfg and cfg.smoothingOn == false then on = false end
    local seconds = (cfg and tonumber(cfg.smoothing)) or 0.25
    if seconds ~= seconds then seconds = 0.25 end
    seconds = math.clamp(math.floor(seconds * 100 + 0.5) / 100, 0.1, 1.0)
    return pcall(monoReanimAPI.set_blend, on and seconds or nil)
end
pcall(monoReanimApplyBlend)

function monoReanimCatalogAdd(name, path, seen)
    if type(name) ~= "string" or type(path) ~= "string" then return end
    if path:sub(1, 4) ~= "http" then return end
    local clean = name:gsub("^[Ss][Hh][Aa][Rr][Pp]%s*/%s*", ""):gsub("^[Pp][Oo][Oo][Dd][Ll][Ee]%s*/%s*", "")
    clean = clean:gsub("^%s+", ""):gsub("%s+$", "")
    if clean == "" then return end
    local key = clean:lower()
    if seen[key] then return end
    seen[key] = true
    monoReanimCatalog[#monoReanimCatalog + 1] = {
        name = clean, path = path, category = "Reanims",
    }
end

function monoReanimCatalogParse(raw)
    if type(raw) ~= "string" or raw == "" then return 0 end
    if raw:sub(1, 3) == "\239\187\191" then raw = raw:sub(4) end
    local seen = {}
    local okDec, decoded = pcall(function() return HttpService:JSONDecode(raw) end)
    if okDec and type(decoded) == "table" then
        for _, item in ipairs(decoded) do
            if type(item) == "table" then monoReanimCatalogAdd(item.name, item.path, seen) end
        end
        return #monoReanimCatalog
    end
    local loader = nil
    if type(loadstring) == "function" then loader = loadstring
    elseif type(load) == "function" then loader = load end
    if loader == nil then return 0 end
    local okLoad, chunk = pcall(loader, raw, "monoreanimcatalog")
    if not (okLoad and type(chunk) == "function") then return 0 end
    local okRun, map = pcall(chunk)
    if not (okRun and type(map) == "table") then return 0 end
    local keys = {}
    for k in pairs(map) do keys[#keys + 1] = k end
    table.sort(keys, function(a, b) return tostring(a) < tostring(b) end)
    for i = 1, #keys do
        monoReanimCatalogAdd(keys[i], map[keys[i]], seen)
    end
    return #monoReanimCatalog
end

function monoReanimEnsureCatalog()
    if #monoReanimCatalog > 0 then return monoReanimCatalog end
    local path = configPath(monoReanimFolder, monoReanimCatalogFile)
    local raw = nil
    if typeof(readfile) == "function" and typeof(isfile) == "function" then
        pcall(function() if isfile(path) then raw = readfile(path) end end)
    end
    if type(raw) ~= "string" or raw == "" then
        raw = nil
        local okGet, body = pcall(function() return game:HttpGet(monoReanimCatalogUrl) end)
        if okGet and type(body) == "string" and body ~= "" then
            raw = body
            if typeof(writefile) == "function" then
                ensureFolder(monoReanimFolder)
                pcall(function() writefile(path, body) end)
            end
        end
    end
    monoReanimCatalogParse(raw)
    table.sort(monoReanimCatalog, monoReanimSort)
    return monoReanimCatalog
end

function monoReanimBuildUI()

