    local function applyCorner(parent, radius)
        local c = Instance.new("UICorner", parent)
        c.CornerRadius = UDim.new(0, radius or 8)
        return c
    end

    local function applyStroke(parent, color, thickness, transparency)
        local s = Instance.new("UIStroke", parent)
        s.Color = color or REAnimC.borderSoft
        s.Thickness = thickness or 1
        s.Transparency = transparency or 0.5
        s.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
        return s
    end

    if CoreGui:FindFirstChild("MonochromeReanimationRunner") then
        CoreGui.MonochromeReanimationRunner:Destroy()
    end

    local api = monoReanimAPI

    local function isCustomAnim(a)
        return a.isCustom or a.category == "Custom"
    end

    local compareAnims = monoReanimSort

    local animations = {}
    for _, item in ipairs(monoReanimCatalog) do
        table.insert(animations, { name = item.name, path = item.path, category = item.category or "Reanims" })
    end
    table.sort(animations, compareAnims)

    local savedConfig = monoReanimLoad()

    local function reanimSaveConfig()
        monoReanimSave()
    end

    local monoReanimCustomFolder = "Monochrome/reanim/custom"

    local function monoReanimCustomSafeName(name)
        local clean = tostring(name or "")
        clean = clean:gsub("[^%w %-_]", "")
        clean = clean:gsub("^%s+", "")
        clean = clean:gsub("%s+$", "")
        if clean == "" then return nil end
        return clean
    end

    local function monoReanimCustomWrite(name, data)
        if type(data) ~= "string" or data == "" then return nil, nil end
        if typeof(writefile) ~= "function" then return nil, nil end
        local safe = monoReanimCustomSafeName(name)
        if not safe then return nil, nil end
        local isJson = false
        pcall(function()
            if type(HttpService:JSONDecode(data)) == "table" then isJson = true end
        end)
        ensureFolder(monoReanimFolder)
        ensureFolder(monoReanimCustomFolder)
        local file = safe .. (isJson and ".json" or ".lua")
        local full = monoReanimCustomFolder .. "/" .. file
        local ok = pcall(function() writefile(full, data) end)
        if not ok then return nil, nil end
        local idx = savedConfig.customIndex
        for i = #idx, 1, -1 do
            if idx[i].name == safe then table.remove(idx, i) end
        end
        table.insert(idx, { name = safe, file = file })
        reanimSaveConfig()
        return safe, full
    end

    local function monoReanimCustomDelete(name)
        local idx = savedConfig.customIndex
        for _, e in ipairs(idx) do
            if e.name == name and typeof(delfile) == "function" and typeof(isfile) == "function" then
                pcall(function()
                    local full = monoReanimCustomFolder .. "/" .. e.file
                    if isfile(full) then delfile(full) end
                end)
            end
        end
        for i = #idx, 1, -1 do
            if idx[i].name == name then table.remove(idx, i) end
        end
    end

    local function _listAnimFiles(dir)
        local files = {}
        if type(listfiles) ~= "function" then return files end
        local ok, result = pcall(listfiles, dir)
        if not ok or type(result) ~= "table" then return files end
        for _, path in ipairs(result) do
            if type(path) == "string" and (path:match("%.lua$") or path:match("%.txt$") or path:match("%.json$")) then
                files[#files + 1] = path
            end
        end
        return files
    end

    if isfolder and makefolder then
        pcall(function()
            if not isfolder(monoReanimFolder) then makefolder(monoReanimFolder) end
            if not isfolder(monoReanimCustomFolder) then makefolder(monoReanimCustomFolder) end
        end)
    end

    if #savedConfig.customIndex == 0 and #savedConfig.customAnims > 0 then
        for _, ca in ipairs(savedConfig.customAnims) do
            if ca and ca.name and ca.script then monoReanimCustomWrite(ca.name, ca.script) end
        end
        savedConfig.customAnims = {}
        reanimSaveConfig()
    end

    local function normalizeAnimPath(p)
        return (tostring(p or ""):gsub("\\", "/"):lower())
    end

    local function hasCustomEntry(name, path)
        local np = normalizeAnimPath(path)
        for _, a in ipairs(animations) do
            if a.isCustom or a.category == "Custom" then
                if normalizeAnimPath(a.path) == np then return true end
                if a.name == name then return true end
            end
        end
        return false
    end

    for _, e in ipairs(savedConfig.customIndex) do
        if e and e.name and e.file and not hasCustomEntry(e.name, monoReanimCustomFolder .. "/" .. e.file) then
            table.insert(animations, {
                name = e.name,
                path = monoReanimCustomFolder .. "/" .. e.file,
                category = "Custom",
                isCustom = true,
            })
        end
    end

    local function _addCustomFile(path)
        local fileName = path:match("[/\\]([^/\\]+)$") or path
        local dispName = fileName:gsub("%.[^%.]+$", "")
        if hasCustomEntry(dispName, path) then return end
        table.insert(animations, { name = dispName, path = path, category = "Custom", isCustom = true })
    end

