    local MODAL_ROW_H = 34
    local MODAL_BATCH = 20
    local modalDisplay = {}
    local modalRows = {}
    local modalRowAnim = setmetatable({}, { __mode = "k" })
    local modalLoaded = 0
    local modalLoading = false
    local modalPopulateToken = 0
    local modalSearchProgrammatic = false

    local function buildModalRow(a, index)
        local ok, ab = pcall(function()
            local row = modalRows[index]
            if not row then
                row = Instance.new("TextButton")
                row.Size = UDim2.new(1, -6, 0, 30)
                row.BackgroundColor3 = REAnimC.bg
                row.BackgroundTransparency = 0
                row.Font = Enum.Font.Gotham
                row.TextSize = 11
                row.TextXAlignment = Enum.TextXAlignment.Left
                row.TextTruncate = Enum.TextTruncate.AtEnd
                row.AutoButtonColor = false
                row.ZIndex = 53
                row.Parent = modalList
                corner(row, 7)
                local pad = Instance.new("UIPadding", row)
                pad.PaddingLeft = UDim.new(0, 10)
                row.MouseButton1Click:Connect(function()
                    local stName = modalSelectingState
                    local anim = modalRowAnim[row]
                    if stName and anim then
                        savedConfig.states[stName] = { name = anim.name, path = anim.path }
                        task.defer(reanimSaveConfig)
                        if stateSelectButtons[stName] then
                            stateSelectButtons[stName].Text = anim.name
                            stateSelectButtons[stName].TextColor3 = REAnimC.accentDim
                        end
                    end
                    modalOverlay.Visible = false
                    modalSelectingState = nil
                end)
                modalRows[index] = row
            end
            row.LayoutOrder = index
            row.Text = a and a.name or ""
            row.TextColor3 = REAnimC.text
            modalRowAnim[row] = a
            return row
        end)
        if ok then return ab end
        return nil
    end

    local function updateModalCanvasSize()
        local wantY = modalLoaded * MODAL_ROW_H + 4
        if modalList.CanvasSize.Y.Offset ~= wantY then
            modalList.CanvasSize = UDim2.new(0, 0, 0, wantY)
        end
    end

    local function loadModalBatch(startIdx, count)
        if modalLoading then return end
        modalLoading = true
        pcall(function()
            local total = #modalDisplay
            local endIdx = math.min(startIdx + count - 1, total)
            for i = startIdx, endIdx do
                local a = modalDisplay[i]
                if a then buildModalRow(a, i) end
            end
            if endIdx > modalLoaded then modalLoaded = endIdx end
            updateModalCanvasSize()
        end)
        modalLoading = false
    end

    local function checkLoadMoreModal()
        local total = #modalDisplay
        if modalLoaded >= total then return end
        local buffer = MODAL_ROW_H * MODAL_BATCH
        if modalList.CanvasPosition.Y + modalList.AbsoluteWindowSize.Y + buffer >= modalList.CanvasSize.Y.Offset - 1 then
            loadModalBatch(modalLoaded + 1, MODAL_BATCH)
        end
    end

    local function renderModalWindow()
        local total = #modalDisplay
        for idx, row in pairs(modalRows) do
            if idx > total then
                pcall(function() row:Destroy() end)
                modalRows[idx] = nil
            end
        end
        if modalLoaded > total then modalLoaded = total end
        local winH = modalList.AbsoluteWindowSize.Y
        if winH < 40 then winH = 330 end
        local needed = math.ceil((modalList.CanvasPosition.Y + winH) / MODAL_ROW_H) + 5
        if needed > total then needed = total end
        if needed > modalLoaded then modalLoaded = needed end
        for i = 1, needed do
            local a = modalDisplay[i]
            if a then buildModalRow(a, i) end
        end
        updateModalCanvasSize()
    end

    local function populateModalList(filter)
        modalPopulateToken = modalPopulateToken + 1
        local myToken = modalPopulateToken
        local term = (filter or ""):lower()
        task.defer(function()
            if myToken ~= modalPopulateToken then return end
            if not modalList.Parent then return end
            local list = {}
            for _, a in ipairs(animations) do
                if term == "" or a.name:lower():find(term, 1, true) then
                    list[#list + 1] = a
                end
            end
            modalDisplay = list
            modalLoaded = 0
            modalLoading = false
            for idx, row in pairs(modalRows) do
                if row then pcall(function() row:Destroy() end) end
                modalRows[idx] = nil
            end
            modalList.CanvasPosition = Vector2.new(0, 0)
            renderModalWindow()
        end)
    end

    modalSearch:GetPropertyChangedSignal("Text"):Connect(function()
        if modalSearchProgrammatic then return end
        populateModalList(modalSearch.Text)
    end)
    table.insert(monoReanimBuildConns, RunService.Heartbeat:Connect(function()
        if not modalOverlay.Visible then return end
        checkLoadMoreModal()
    end))

