    addSubmitBtn.MouseButton1Click:Connect(function()
        local raw = addDataBox.Text:gsub("^%s+",""):gsub("%s+$","")
        if raw == "" then
            addStatus.Text = "Please paste keyframe script or table first!"
            addStatus.TextColor3 = REAnimC.accentDim
            return
        end
        if not raw:find("{",1,true) then
            addStatus.Text = "Invalid data: doesn't look like keyframes table or script."
            addStatus.TextColor3 = REAnimC.accentDim
            return
        end
        local typed = (addNameBox.Text:match("^%s*(.-)%s*$") or "")
        local finalName = typed ~= "" and typed or ("Custom_"..(#savedConfig.customIndex+1))
        local safeName, fullPath = monoReanimCustomWrite(finalName, raw)
        if not fullPath then
            addStatus.Text = "Failed to save animation (writefile unavailable?)."
            addStatus.TextColor3 = REAnimC.accentDim
            return
        end
        if not hasCustomEntry(safeName, fullPath) then table.insert(animations, { name = safeName, path = fullPath, category = "Custom", isCustom = true }) end
        table.sort(animations, compareAnims)
        addCustomModal.Visible = false
        addDataBox.Text = ""
        addNameBox.Text = ""
        if markListDirty then markListDirty() end
        if populateList then populateList() end
    end)

