                    hiddenCount = hiddenCount + 1
                    break
                end
            end
        end
        local targetHidden = (hiddenCount == 0)
        for _, ldef in ipairs(limbDefinitions) do
            setLimbHidden(ldef, targetHidden)
        end
    end)

