    table.insert(monoReanimBuildConns, RunService.RenderStepped:Connect(function()
        local clone = api and api.get_clone and api.get_clone()
        if not clone then return end
        if not monoReanimHidden or not next(monoReanimHidden) then return end
        for partName, _ in pairs(monoReanimHidden) do
            local p = clone:FindFirstChild(partName)
            if p and p:IsA("BasePart") then
                p.LocalTransparencyModifier = 1
                p.Transparency = 1
            end
            if partName == "Head" then
                for _, d in ipairs(clone:GetDescendants()) do
                    if d:IsA("Decal") then d.Transparency = 1
                    elseif d:IsA("Accessory") then
                        local handle = d:FindFirstChild("Handle")
                        if handle and handle:IsA("BasePart") then
                            handle.LocalTransparencyModifier = 1
                            handle.Transparency = 1
                        end
                    end
                end
                local hum = clone:FindFirstChildOfClass("Humanoid")
                if hum then
                    hum.DisplayName = ""
                    hum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.Viewer
                end
            end
        end
    end))

