    local function monoReanimBindName(kc)
        if kc == nil then return nil end
        if typeof(kc) == "EnumItem" then
            local ok, n = pcall(function() return kc.Name end)
            if ok and type(n) == "string" and n ~= "" then return n end
            return nil
        end
        if type(kc) == "string" and kc ~= "" then return kc end
        return nil
    end

    local function monoReanimBindKey(n)
        if type(n) ~= "string" or n == "" then return nil end
        local ok, kc = pcall(function() return Enum.KeyCode[n] end)
        if ok and kc ~= nil then return kc end
        return nil
    end

    local function monoReanimBindLabel(label, kc)
        if kc and kc.Name and kc.Name ~= "" then
            return label .. ": " .. monoCmdBindShort(kc.Name)
        end
        return label .. ": None"
    end

    local function monoReanimSaveBody()
        local c = savedConfig
        local a = BodyArm.ArmStretch
        local f = BodyArm.FaceAttach
        local t = BodyArm.TorsoAim
        local th = BodyArm.TorsoHeight
        local cp = BodyArm.Catapult or {}
