        c.armStretch = {
            mode = a.mode or "Toggle",
            side = a.side or "Right",
            length = a.length or 1300,
            bind = monoReanimBindName(a.bind),
            endMode = a.endMode or "Hand",
            collision = a.collision ~= false,
        }
        c.faceAttach = {
            bind = monoReanimBindName(f.bind),
            endMode = f.endMode or "Hand",
