    local function monoReanimLoadBody()
        local a = type(savedConfig.armStretch) == "table" and savedConfig.armStretch or {}
        if a.mode == "Hold" or a.mode == "Toggle" then BodyArm.ArmStretch.mode = a.mode end
        if a.side == "Left" or a.side == "Right" or a.side == "Both" then BodyArm.ArmStretch.side = a.side end
        if type(a.length) == "number" then BodyArm.ArmStretch.length = math.clamp(math.floor(a.length), 1, 3000) end
        BodyArm.ArmStretch.bind = monoReanimBindKey(a.bind)
        local cp = type(savedConfig.catapult) == "table" and savedConfig.catapult or {}
        BodyArm.Catapult.bind = monoReanimBindKey(cp.bind)
        if a.endMode == "Hand" or a.endMode == "Lower Arm" then BodyArm.ArmStretch.endMode = a.endMode end
        BodyArm.ArmStretch.collision = a.collision ~= false
        local f = type(savedConfig.faceAttach) == "table" and savedConfig.faceAttach or {}
        BodyArm.FaceAttach.bind = monoReanimBindKey(f.bind)
        if f.endMode == "Hand" or f.endMode == "Lower Arm" then BodyArm.FaceAttach.endMode = f.endMode end
        if f.mode == "One Target" or f.mode == "Two Targets" then BodyArm.FaceAttach.mode = f.mode end
        if f.side == "Left" or f.side == "Right" then BodyArm.FaceAttach.side = f.side end
        local ls = type(savedConfig.legStretch) == "table" and savedConfig.legStretch or {}
        if ls.mode == "Hold" or ls.mode == "Toggle" then BodyArm.LegStretch.mode = ls.mode end
        if ls.side == "Left" or ls.side == "Right" or ls.side == "Both" then BodyArm.LegStretch.side = ls.side end
        if type(ls.length) == "number" then BodyArm.LegStretch.length = math.clamp(math.floor(ls.length), 1, 3000) end
        BodyArm.LegStretch.bind = monoReanimBindKey(ls.bind)
        if ls.endMode == "Foot" or ls.endMode == "Lower Leg" then BodyArm.LegStretch.endMode = ls.endMode end
        BodyArm.LegStretch.collision = ls.collision ~= false
        local la = type(savedConfig.legAttach) == "table" and savedConfig.legAttach or {}
        BodyArm.LegAttach.bind = monoReanimBindKey(la.bind)
        if la.endMode == "Foot" or la.endMode == "Lower Leg" then BodyArm.LegAttach.endMode = la.endMode end
        if la.mode == "One Target" or la.mode == "Two Targets" then BodyArm.LegAttach.mode = la.mode end
        if la.side == "Left" or la.side == "Right" then BodyArm.LegAttach.side = la.side end
        local t = type(savedConfig.torsoAim) == "table" and savedConfig.torsoAim or {}
        if t.mode == "Stretch" or t.mode == "Follow" or t.mode == "Attach" then BodyArm.TorsoAim.mode = t.mode end
        if type(t.stretchReach) == "number" then BodyArm.TorsoAim.stretchReach = math.clamp(math.floor(t.stretchReach), 1, 3000) end
        if type(t.followStrength) == "number" then BodyArm.TorsoAim.followStrength = math.clamp(math.floor(t.followStrength), 1, 100) end
        BodyArm.TorsoAim.stretchBind = monoReanimBindKey(t.stretchBind)
        BodyArm.TorsoAim.followBind = monoReanimBindKey(t.followBind)
        BodyArm.TorsoAim.faceAttachBind = monoReanimBindKey(t.faceAttachBind)
        BodyArm.TorsoAim.allowFlip = t.allowFlip == true
        BodyArm.TorsoAim.collision = t.collision ~= false
        local th = type(savedConfig.torsoHeight) == "table" and savedConfig.torsoHeight or {}
        if type(th.height) == "number" then BodyArm.TorsoHeight.height = math.clamp(math.floor(th.height), 1, 3000) end
        BodyArm.TorsoHeight.bind = monoReanimBindKey(th.bind)
        local htc = type(savedConfig.headTracker) == "table" and savedConfig.headTracker or {}
        BodyArm.HeadTracker.bind = monoReanimBindKey(htc.bind)
        local alc = type(savedConfig.armLink) == "table" and savedConfig.armLink or {}
        if alc.mode == "One Arm" or alc.mode == "Two Arms" then BodyArm.ArmLink.mode = alc.mode end
        if alc.side == "Left" or alc.side == "Right" then BodyArm.ArmLink.side = alc.side end
        if alc.style == "Chain" or alc.style == "Separate" then BodyArm.ArmLink.style = alc.style end
        local llc = type(savedConfig.legLink) == "table" and savedConfig.legLink or {}
        if llc.mode == "One Leg" or llc.mode == "Two Legs" then BodyArm.LegLink.mode = llc.mode end
        if llc.side == "Left" or llc.side == "Right" then BodyArm.LegLink.side = llc.side end
        if llc.style == "Chain" or llc.style == "Separate" then BodyArm.LegLink.style = llc.style end
        BodyArm.LegLink.bind = monoReanimBindKey(llc.bind)
        BodyArm.ArmLink.bind = monoReanimBindKey(alc.bind)
        local hccc = type(savedConfig.headController) == "table" and savedConfig.headController or {}
        BodyArm.HeadController.bind = monoReanimBindKey(hccc.bind)
        if BodyArm.refreshArmStretchUI then BodyArm.refreshArmStretchUI() end
        BodyArm.refreshFaceAttachUI()
        if BodyArm.refreshLegStretchUI then BodyArm.refreshLegStretchUI() end
        if BodyArm.refreshLegAttachUI then BodyArm.refreshLegAttachUI() end
        if BodyArm.refreshLegLinkUI then BodyArm.refreshLegLinkUI() end
        BodyArm.refreshTorsoAimUI()
        if BodyArm.refreshTorsoHeightUI then BodyArm.refreshTorsoHeightUI() end
        if BodyArm.refreshHeadTrackerUI then BodyArm.refreshHeadTrackerUI() end
        if BodyArm.refreshArmLinkUI then BodyArm.refreshArmLinkUI() end
        if BodyArm.refreshHeadControllerUI then BodyArm.refreshHeadControllerUI() end
        monoReanimSaveBody()
    end

