        create("TextLabel", {
            Size = UDim2.new(1, -96, 1, 0), Position = UDim2.new(0, 12, 0, 0),
            BackgroundTransparency = 1, Text = "Smooth transitions",
            TextColor3 = REAnimC.text, TextSize = 11, Font = Enum.Font.GothamBold,
            TextXAlignment = Enum.TextXAlignment.Left,
        }, smoothToggleCard)
        local smoothPillSetter = monoPanelPill(smoothToggleCard, savedConfig.smoothingOn ~= false)
        monoPanelPillHit(smoothToggleCard, function()
            savedConfig.smoothingOn = not (savedConfig.smoothingOn ~= false)
            reanimSaveConfig()
            monoReanimApplyBlend()
            smoothPillSetter(savedConfig.smoothingOn ~= false)
        end)

        local smoothSliderCard = Instance.new("Frame")
        smoothSliderCard.Size = UDim2.new(1, 0, 0, 80)
        smoothSliderCard.BackgroundColor3 = REAnimC.surface
        smoothSliderCard.BackgroundTransparency = 0.4
        smoothSliderCard.BorderSizePixel = 0
        smoothSliderCard.LayoutOrder = 0
        smoothSliderCard.Parent = bodyPanel
        corner(smoothSliderCard, 7)
        stroke(smoothSliderCard, REAnimC.borderSoft, 1, 0.55)

        local SMOOTH_MIN, SMOOTH_MAX = 0.1, 1.0
        local function smoothScale(v)
            return math.clamp((v - SMOOTH_MIN) / (SMOOTH_MAX - SMOOTH_MIN), 0, 1)
        end
        local function smoothText(v)
            local s = string.format("%.3f", v):gsub("0+$", ""):gsub("%.$", "")
            return "Smoothing: " .. s .. "s"
        end
        local smoothValue = create("TextLabel", {
            Size = UDim2.new(1, -24, 0, 16), Position = UDim2.new(0, 12, 0, 8),
            BackgroundTransparency = 1, Text = smoothText(savedConfig.smoothing or 0.25),
            TextColor3 = REAnimC.text, TextSize = 10, Font = Enum.Font.GothamMedium,
            TextXAlignment = Enum.TextXAlignment.Left,
        }, smoothSliderCard)

        local smoothBarBg = create("Frame", {
            Size = UDim2.new(1, -24, 0, 6), Position = UDim2.new(0, 12, 0, 38),
            BackgroundColor3 = REAnimC.input, BorderSizePixel = 0,
        }, smoothSliderCard)
        corner(smoothBarBg, 999)
        local smoothFill = create("Frame", {
            Size = UDim2.new(smoothScale(savedConfig.smoothing or 0.25), 0, 1, 0),
            BackgroundColor3 = REAnimC.accent, BorderSizePixel = 0,
        }, smoothBarBg)
        corner(smoothFill, 999)
        local smoothKnob = create("Frame", {
            Size = UDim2.new(0, 12, 0, 12),
            Position = UDim2.new(smoothScale(savedConfig.smoothing or 0.25), -6, 0.5, -6),
            BackgroundColor3 = REAnimC.text, BorderSizePixel = 0, ZIndex = 3,
        }, smoothBarBg)
        corner(smoothKnob, 999)

        local function applySmoothing(value)
            value = math.clamp(math.floor(value * 100 + 0.5) / 100, SMOOTH_MIN, SMOOTH_MAX)
            savedConfig.smoothing = value
            reanimSaveConfig()
            monoReanimApplyBlend()
            local scale = smoothScale(value)
            smoothFill.Size = UDim2.new(scale, 0, 1, 0)
            smoothKnob.Position = UDim2.new(scale, -6, 0.5, -6)
            smoothValue.Text = smoothText(value)
        end
        local function smoothingFromInput(input)
            local pos = math.clamp((input.Position.X - smoothBarBg.AbsolutePosition.X)
                / math.max(1, smoothBarBg.AbsoluteSize.X), 0, 1)
            return SMOOTH_MIN + pos * (SMOOTH_MAX - SMOOTH_MIN)
        end
        local smoothDragging = false
        local smoothLastClick = 0
        smoothBarBg.InputBegan:Connect(function(input)
            if input.UserInputType ~= Enum.UserInputType.MouseButton1
                and input.UserInputType ~= Enum.UserInputType.Touch then return end
            local now = tick()
            if now - smoothLastClick < 0.3 then
                smoothLastClick = 0
                smoothDragging = false
                applySmoothing(0.25)
            else
                smoothLastClick = now
                smoothDragging = true
                applySmoothing(smoothingFromInput(input))
            end
        end)
        table.insert(monoReanimBuildConns, UserInputService.InputChanged:Connect(function(input)
            if not smoothDragging then return end
            if input.UserInputType ~= Enum.UserInputType.MouseMovement
                and input.UserInputType ~= Enum.UserInputType.Touch then return end
            applySmoothing(smoothingFromInput(input))
        end))
        table.insert(monoReanimBuildConns, UserInputService.InputEnded:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1
                or input.UserInputType == Enum.UserInputType.Touch then
                smoothDragging = false
            end
        end))
        create("TextLabel", {
