        local function getActiveCharacter()
            if api and api.is_reanimated and api.is_reanimated() then
                local clone = api.get_clone and api.get_clone()
                if clone then return clone end
            end
            return player.Character
        end

        local function findPartInModel(model, name)
            if not model then return nil end
            local d = model:FindFirstChild(name)
            if d and d:IsA("BasePart") then return d end
            for _, o in ipairs(model:GetDescendants()) do
                if o:IsA("BasePart") and o.Name == name then return o end
            end
            return nil
        end

        local function findMotorInModel(model, part)
            if not model then return nil end
            for _, o in ipairs(model:GetDescendants()) do
                if o:IsA("Motor6D") and o.Part1 == part then return o end
            end
            return nil
        end

        local function buildBoneCFrame(origin, alongBone, refRight)
            alongBone = alongBone.Unit
            local xAxis = refRight:Cross(alongBone)
            if xAxis.Magnitude < 0.08 then
                xAxis = Vector3.new(0,1,0):Cross(alongBone)
                if xAxis.Magnitude < 0.08 then xAxis = Vector3.new(1,0,0):Cross(alongBone) end
            end
            xAxis = xAxis.Unit
            local zAxis = xAxis:Cross(alongBone).Unit
            xAxis = alongBone:Cross(zAxis).Unit
            return CFrame.fromMatrix(origin, xAxis, alongBone, zAxis)
        end

        local stopFaceAttach, refreshFaceAttachUI, FaceAttach

        local function buildLimbDataForChar(model, side, isLeg)
            local upperName = isLeg and (side.."UpperLeg") or (side.."UpperArm")
            local lowerName = isLeg and (side.."LowerLeg") or (side.."LowerArm")
            local endName   = isLeg and (side.."Foot") or (side.."Hand")
            local up = findPartInModel(model, upperName)
            local lo = findPartInModel(model, lowerName)
            local hd = findPartInModel(model, endName)
            if not up or not lo or not hd then return nil end
            local sM = findMotorInModel(model, up)
            local eM = findMotorInModel(model, lo)
            local wM = findMotorInModel(model, hd)
            if not sM or not eM or not wM then return nil end

            local root = model:FindFirstChild("HumanoidRootPart")
            if not root then return nil end

            local shoulderPosition = (up.CFrame * CFrame.new(0, up.Size.Y * 0.5, 0)).Position

            local data = {
                side = side, upper = up, lower = lo, hand = hd,
                shoulderMotor = sM, elbowMotor = eM, wristMotor = wM,
                origSizes = {upper = up.Size, lower = lo.Size, hand = hd.Size},
                origAnchored = {upper = up.Anchored, lower = lo.Anchored, hand = hd.Anchored},
                origCC = {upper = up.CanCollide, lower = lo.CanCollide, hand = hd.CanCollide},
                origTouch = {upper = up.CanTouch, lower = lo.CanTouch, hand = hd.CanTouch},
                origCQ = {upper = up.CanQuery, lower = lo.CanQuery, hand = hd.CanQuery},
                origML = {upper = up.Massless, lower = lo.Massless, hand = hd.Massless},
                origMotorOn = {shoulder = sM.Enabled, elbow = eM.Enabled, wrist = wM.Enabled},
                shoulderRootOffset = root.CFrame:PointToObjectSpace(shoulderPosition),
            }

            sM.Enabled = false
            eM.Enabled = false
            wM.Enabled = false
            for _, p in ipairs({up, lo, hd}) do
                p.Anchored = true; p.CanCollide = false; p.CanTouch = false
                p.CanQuery = true; p.Massless = true
            end
            return data
        end

        local function buildArmDataForChar(model, side)
            return buildLimbDataForChar(model, side, false)
        end

        local function restoreArmData(data)
            if not data then return end
            pcall(function()
                local up, lo, hd = data.upper, data.lower, data.hand
                if up and up.Parent then
                    up.Size = data.origSizes.upper
                    up.Anchored = data.origAnchored.upper
                    up.CanCollide = data.origCC.upper
                    up.CanTouch = data.origTouch.upper
                    up.CanQuery = data.origCQ.upper
                    up.Massless = data.origML.upper
                    pcall(function() up.AssemblyLinearVelocity = Vector3.zero end)
                    pcall(function() up.AssemblyAngularVelocity = Vector3.zero end)
                end
                if lo and lo.Parent then
                    lo.Size = data.origSizes.lower
                    lo.Anchored = data.origAnchored.lower
                    lo.CanCollide = data.origCC.lower
                    lo.CanTouch = data.origTouch.lower
                    lo.CanQuery = data.origCQ.lower
                    lo.Massless = data.origML.lower
                    pcall(function() lo.AssemblyLinearVelocity = Vector3.zero end)
                    pcall(function() lo.AssemblyAngularVelocity = Vector3.zero end)
                end
                if hd and hd.Parent then
                    hd.Size = data.origSizes.hand
                    hd.Anchored = data.origAnchored.hand
                    hd.CanCollide = data.origCC.hand
                    hd.CanTouch = data.origTouch.hand
                    hd.CanQuery = data.origCQ.hand
                    hd.Massless = data.origML.hand
                    pcall(function() hd.AssemblyLinearVelocity = Vector3.zero end)
                    pcall(function() hd.AssemblyAngularVelocity = Vector3.zero end)
                end
                if data.shoulderMotor and data.shoulderMotor.Parent then
                    data.shoulderMotor.Enabled = data.origMotorOn.shoulder
                end
                if data.elbowMotor and data.elbowMotor.Parent then
                    data.elbowMotor.Enabled = data.origMotorOn.elbow
                end
                if data.wristMotor and data.wristMotor.Parent then
                    data.wristMotor.Enabled = data.origMotorOn.wrist
                end
            end)
        end

        local function getShoulderOrigin(data, root)
            if not data then return nil end

            local motor = data.shoulderMotor
            if motor and motor.Parent and motor.Part0 and motor.Part0.Parent and motor.C0 then
                return (motor.Part0.CFrame * motor.C0).Position
            end

            if not data.upper or not data.upper.Parent then return nil end
            if not root or not root.Parent then return nil end
            if not data.shoulderRootOffset then return nil end
            return root.CFrame:PointToWorldSpace(data.shoulderRootOffset)
        end

        local function updateStretchArm(data, origin, dir, length)
            if not data then return end
            if not data.upper or not data.upper.Parent then return end
            if not data.lower or not data.lower.Parent then return end
            if not data.hand or not data.hand.Parent then return end
            if not dir or dir.Magnitude < 0.01 then return end
            if not origin then return end
            dir = dir.Unit
            length = math.clamp(length or 3000, 1, 3000)

            local uL = data.origSizes.upper.Y
            local lL = math.max(length - uL, 0.1)
            lL = math.min(lL, 3000)

            local refRight = Vector3.new(1, 0, 0)
            if math.abs(dir:Dot(refRight)) > 0.95 then refRight = Vector3.new(0, 0, 1) end

            local uC = origin + dir * (uL * 0.5)
            data.upper.Size = Vector3.new(data.origSizes.upper.X, uL, data.origSizes.upper.Z)
            data.upper.CFrame = buildBoneCFrame(uC, -dir, refRight)

            local elbowPos = origin + dir * uL
            local lC = elbowPos + dir * (lL * 0.5)
            data.lower.Size = Vector3.new(data.origSizes.lower.X, lL, data.origSizes.lower.Z)
            data.lower.CFrame = buildBoneCFrame(lC, -dir, refRight)

            local handPos = origin + dir * (uL + lL)
            data.hand.Size = data.origSizes.hand
            data.hand.CFrame = buildBoneCFrame(handPos, -dir, refRight)
        end

        local function stopArmStretch()
            if ArmStretch.connection then
                ArmStretch.connection:Disconnect()
                ArmStretch.connection = nil
            end
            if ArmStretch.data then
                for _, d in ipairs(ArmStretch.data) do
                    restoreArmData(d)
                    if d.shoulderMotor and d.shoulderMotor.Parent and d.origMotorOn.shoulder then
                        d.shoulderMotor.Enabled = true
                    end
                    if d.elbowMotor and d.elbowMotor.Parent and d.origMotorOn.elbow then
                        d.elbowMotor.Enabled = true
                    end
                    if d.wristMotor and d.wristMotor.Parent and d.origMotorOn.wrist then
                        d.wristMotor.Enabled = true
                    end
                end
                ArmStretch.data = nil
            end
            pcall(function()
                local clone = api and api.get_clone and api.get_clone()
                local root = clone and clone:FindFirstChild("HumanoidRootPart")
                if root then
                    root.AssemblyLinearVelocity = Vector3.zero
                    root.AssemblyAngularVelocity = Vector3.zero
                end
                local realChar = api and api.get_real_character and api.get_real_character()
                local realRoot = realChar and realChar:FindFirstChild("HumanoidRootPart")
                if realRoot then
                    realRoot.AssemblyLinearVelocity = Vector3.zero
                    realRoot.AssemblyAngularVelocity = Vector3.zero
                end
            end)
            ArmStretch.active = false
            ArmStretch.lastDir = nil
            ArmStretch.currentTarget = nil
            ArmStretch.currentReach = nil
            ArmStretch.rayParams = nil
        end

        local function startArmStretch()
            if not (api and api.is_reanimated and api.is_reanimated()) then
                return false, "Enable Reanim first"
            end
            stopArmStretch()
            if FaceAttach.active then
                stopFaceAttach()
                refreshFaceAttachUI()
            end

            local model = getActiveCharacter()
            if not model then return false, "No character / clone" end

            local sides = {}
            if ArmStretch.side == "Left" then sides = {"Left"}
            elseif ArmStretch.side == "Both" then sides = {"Right", "Left"}
            else sides = {"Right"} end

            local built = {}
            for _, s in ipairs(sides) do
                local d = buildArmDataForChar(model, s)
                if not d then
                    for _, b in ipairs(built) do restoreArmData(b) end
                    return false, "Failed to build " .. s .. " arm (clone may not be ready)"
                end
                table.insert(built, d)
            end

            ArmStretch.data = built
            ArmStretch.active = true
            ArmStretch.lastDir = nil
            ArmStretch.currentTarget = nil
            ArmStretch.currentReach = nil

            pcall(function()
                local params = RaycastParams.new()
                params.FilterType = Enum.RaycastFilterType.Exclude
                local filter = {}
                local realChar = api and api.get_real_character and api.get_real_character()
                if realChar then filter[#filter + 1] = realChar end
                if model then filter[#filter + 1] = model end
                params.FilterDescendantsInstances = filter
                ArmStretch.rayParams = params
            end)

            ArmStretch.connection = RunService.Heartbeat:Connect(function(dt)
                if not ArmStretch.active then return end

                local model = getActiveCharacter()
                if not model then stopArmStretch(); return end

                for _, d in ipairs(ArmStretch.data or {}) do
                    if not (d.upper and d.upper.Parent and d.lower and d.lower.Parent and d.hand and d.hand.Parent) then
                        stopArmStretch(); return
                    end
                end

                local root = model:FindFirstChild("HumanoidRootPart")
                if not root then return end

                local dir
                if UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) then
                    local mouseLoc = UserInputService:GetMouseLocation()
                    local ray = workspace.CurrentCamera:ViewportPointToRay(mouseLoc.X, mouseLoc.Y)
                    local target = ray.Origin + ray.Direction * 100
                    local v = target - root.Position
                    if v.Magnitude > 0.05 then
                        dir = v.Unit
                        ArmStretch.lastDir = dir
                    end
                end
                if not dir then
                    dir = ArmStretch.lastDir or root.CFrame.LookVector
                end

                local aimOrigin = nil
                for _, d in ipairs(ArmStretch.data) do
                    aimOrigin = getShoulderOrigin(d, root)
                    if aimOrigin then break end
                end
                if not aimOrigin then return end

                local aimLen = ArmStretch.length
                local target = aimOrigin + dir * aimLen
                if not ArmStretch.currentTarget then
                    ArmStretch.currentTarget = target
                else
                    local aimGap = (ArmStretch.currentTarget - target).Magnitude
                    local aimSpeed = 10 + 30 * math.clamp(aimGap / 3000, 0, 1)
                    local a = math.clamp(dt * aimSpeed, 0, 1)
                    ArmStretch.currentTarget = ArmStretch.currentTarget:Lerp(target, a)
                end

                for _, d in ipairs(ArmStretch.data) do
                    local origin = getShoulderOrigin(d, root)
                    if origin then
                        local toTarget = ArmStretch.currentTarget - origin
                        local dist = toTarget.Magnitude
                        if dist > 0.05 then
                            local dirUnit = toTarget.Unit
                            local desiredReach = math.min(dist, 3000)
                            if ArmStretch.collision and ArmStretch.rayParams then
                                pcall(function()
                                    local hit = workspace:Raycast(origin, dirUnit * desiredReach, ArmStretch.rayParams)
                                    if hit then desiredReach = math.min(desiredReach, hit.Distance) end
                                end)
                            end
                            local curReach = ArmStretch.currentReach or desiredReach
                            local reachGap = math.abs(curReach - desiredReach)
                            local reachSpeed = 10 + 30 * math.clamp(reachGap / 3000, 0, 1)
                            curReach = curReach + (desiredReach - curReach) * math.clamp(dt * reachSpeed, 0, 1)
                            ArmStretch.currentReach = curReach
                            updateStretchArm(d, origin, dirUnit, ArmStretch.currentReach)
                        end
                        if d.lower and d.lower.Parent then
                            d.lower.CFrame = d.lower.CFrame * CFrame.new(0, -(d.lower.Size.Y * 0.5), 0)
                        end
                    end
                end
            end)

            return true, "Arm stretch ON ("..table.concat(sides, "+")..")"
        end

        local function refreshArmStretchUI()
            if ArmStretch.active then
                asEnableBtn.Text = "Disable Arm Stretch"
                asEnableBtn.BackgroundColor3 = REAnimC.surfaceHi
                asEnableBtn.BackgroundTransparency = 0.15
                asEnableBtn.TextColor3 = REAnimC.accent
                asEnableStroke.Color = REAnimC.border
                asEnableStroke.Transparency = 0.15
            else
                asEnableBtn.Text = "Enable Arm Stretch"
                asEnableBtn.BackgroundColor3 = REAnimC.surface
                asEnableBtn.BackgroundTransparency = 0.4
                asEnableBtn.TextColor3 = REAnimC.text
                asEnableStroke.Color = REAnimC.borderSoft
                asEnableStroke.Transparency = 0.55
            end
            asSideBtn.Text = "Side: "..ArmStretch.side
            asModeBtn.Text = "Mode: "..ArmStretch.mode
            asBindBtn.Text = monoReanimBindLabel("Arm Stretch", ArmStretch.bind)
            asBindBtn.TextColor3 = REAnimC.accent
            asEndBtn.Text = "End: " .. (ArmStretch.endMode or "Hand")
            asCollisionBtn.Text = "Collision: " .. (ArmStretch.collision and "On" or "Off")
            asCollisionBtn.TextColor3 = REAnimC.accent
            asLenLabel.Text = "REACH: "..tostring(math.floor(ArmStretch.length))
            local pct = math.clamp((ArmStretch.length - 1) / (3000 - 1), 0, 1)
            asLenFill.Size = UDim2.new(pct, 0, 1, 0)
        end

        asEnableBtn.MouseButton1Click:Connect(function()
            if ArmStretch.active then
                stopArmStretch()
                refreshArmStretchUI()
            else
                local ok, msg = startArmStretch()
                if not ok then monoReanimSay("Arm stretch: "..tostring(msg)) end
                refreshArmStretchUI()
            end
        end)

        asSideBtn.MouseButton1Click:Connect(function()
            local opts = {"Right", "Left", "Both"}
            local i = 1
            for k, v in ipairs(opts) do if v == ArmStretch.side then i = k end end
            ArmStretch.side = opts[(i % #opts) + 1]
            local attachedTargets = FaceAttach.active and FaceAttach.targets or nil
            if ArmStretch.active then
                stopArmStretch()
                startArmStretch()
            elseif attachedTargets and #attachedTargets > 0 then
                local ok, msg = BodyArm.startFaceAttach(attachedTargets)
                if not ok then monoReanimSay("Attach: "..tostring(msg)) end
                refreshFaceAttachUI()
            end
            refreshArmStretchUI()
            monoReanimSaveBody()
        end)

        asModeBtn.MouseButton1Click:Connect(function()
            ArmStretch.mode = (ArmStretch.mode == "Toggle") and "Hold" or "Toggle"
            refreshArmStretchUI()
            monoReanimSaveBody()
        end)

        asEndBtn.MouseButton1Click:Connect(function()
            ArmStretch.endMode = (ArmStretch.endMode == "Hand") and "Lower Arm" or "Hand"
            refreshArmStretchUI()
            monoReanimSaveBody()
        end)

        asCollisionBtn.MouseButton1Click:Connect(function()
            ArmStretch.collision = not ArmStretch.collision
            refreshArmStretchUI()
            monoReanimSaveBody()
        end)

        asBindBtn.MouseButton1Click:Connect(function()
            if ArmStretch.capturing then
                ArmStretch.capturing = false
                refreshArmStretchUI()
                return
            end
            if ArmStretch.bind then
                ArmStretch.bind = nil
                refreshArmStretchUI()
                monoReanimSaveBody()
                return
            end
            ArmStretch.capturing = true
            asBindBtn.Text = "..."
            asBindBtn.TextColor3 = REAnimC.accent
        end)

        local draggingArmLen = false
        local function updateArmLenFromInput(input)
            local relX = math.clamp(input.Position.X - asLenTrack.AbsolutePosition.X, 0, asLenTrack.AbsoluteSize.X)
            local pct = relX / asLenTrack.AbsoluteSize.X
            ArmStretch.length = math.floor(1 + pct * (3000 - 1))
            refreshArmStretchUI()
            monoReanimSaveBody()
        end
        asLenTrack.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 then
                draggingArmLen = true
                updateArmLenFromInput(input)
            end
        end)
        table.insert(monoReanimBuildConns, UserInputService.InputEnded:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 then draggingArmLen = false end
        end))
        table.insert(monoReanimBuildConns, UserInputService.InputChanged:Connect(function(input)
            if draggingArmLen and input.UserInputType == Enum.UserInputType.MouseMovement then
                updateArmLenFromInput(input)
            end
        end))


        -- CATAPULT: arms anchor below the clone; release launches along its
        -- facing direction while preserving any existing forward momentum.
        local Catapult = BodyArm.Catapult
        Catapult.active = false
        Catapult.data = nil
        Catapult.anchors = nil
        Catapult.connection = nil
        Catapult.launchForward = 520
        Catapult.launchUp = 280

        local catapultCard = Instance.new("Frame")
        catapultCard.Size = UDim2.new(1, 0, 0, 142)
        catapultCard.BackgroundColor3 = REAnimC.surface
        catapultCard.BackgroundTransparency = 0.4
        catapultCard.BorderSizePixel = 0
        catapultCard.LayoutOrder = 3
        catapultCard.Parent = bodyPanel
        corner(catapultCard, 7)
        stroke(catapultCard, REAnimC.borderSoft, 1, 0.55)

        local catapultBtn = Instance.new("TextButton")
        catapultBtn.Size = UDim2.new(1, -24, 0, 30)
        catapultBtn.Position = UDim2.new(0, 12, 0, 10)
        catapultBtn.BackgroundColor3 = REAnimC.surface
        catapultBtn.BackgroundTransparency = 0.4
        catapultBtn.Text = "Catapult: Off"
        catapultBtn.TextColor3 = REAnimC.text
        catapultBtn.Font = Enum.Font.GothamBold
        catapultBtn.TextSize = 11
        catapultBtn.AutoButtonColor = false
        catapultBtn.Parent = catapultCard
        corner(catapultBtn, 7)
        local catapultStroke = stroke(catapultBtn, REAnimC.borderSoft, 1, 0.55)

        local catapultBindBtn = Instance.new("TextButton")
        catapultBindBtn.Size = UDim2.new(0, 168, 0, 26)
        catapultBindBtn.Position = UDim2.new(0, 12, 0, 48)
        catapultBindBtn.BackgroundColor3 = REAnimC.surface
        catapultBindBtn.BackgroundTransparency = 0.4
        catapultBindBtn.Text = "Catapult: None"
        catapultBindBtn.TextColor3 = REAnimC.accent
        catapultBindBtn.Font = Enum.Font.GothamBold
        catapultBindBtn.TextSize = 10
        catapultBindBtn.AutoButtonColor = false
        catapultBindBtn.Parent = catapultCard
        corner(catapultBindBtn, 7)
        stroke(catapultBindBtn, REAnimC.borderSoft, 1, 0.55)

        local catapultInfo = Instance.new("TextLabel")
        catapultInfo.Size = UDim2.new(1, -24, 0, 48)
        catapultInfo.Position = UDim2.new(0, 12, 0, 82)
        catapultInfo.BackgroundTransparency = 1
        catapultInfo.Text = "Anchor both hands, move away to build stretch, then toggle off to launch forward and upward."
        catapultInfo.TextColor3 = REAnimC.textDim
        catapultInfo.Font = Enum.Font.Gotham
        catapultInfo.TextSize = 9
        catapultInfo.TextWrapped = true
        catapultInfo.TextXAlignment = Enum.TextXAlignment.Left
        catapultInfo.TextYAlignment = Enum.TextYAlignment.Top
        catapultInfo.Parent = catapultCard

        local function refreshCatapultUI()
            catapultBtn.Text = Catapult.active and "Catapult: On (toggle to launch)" or "Catapult: Off"
            catapultBtn.BackgroundColor3 = Catapult.active and REAnimC.surfaceHi or REAnimC.surface
            catapultBtn.BackgroundTransparency = Catapult.active and 0.15 or 0.4
            catapultBtn.TextColor3 = Catapult.active and REAnimC.accent or REAnimC.text
            catapultStroke.Color = Catapult.active and REAnimC.border or REAnimC.borderSoft
            catapultStroke.Transparency = Catapult.active and 0.15 or 0.55
            catapultBindBtn.Text = Catapult.capturing and "Press a key..." or monoReanimBindLabel("Catapult", Catapult.bind)
            catapultBindBtn.TextColor3 = Catapult.capturing and REAnimC.text or REAnimC.accent
        end

        local function catapultGroundPoints(model, root)
            local params = RaycastParams.new()
            params.FilterType = Enum.RaycastFilterType.Exclude
            local exclude = { model }
            local realChar = api and api.get_real_character and api.get_real_character()
            if realChar then table.insert(exclude, realChar) end
            params.FilterDescendantsInstances = exclude
            local hit = workspace:Raycast(root.Position, Vector3.new(0, -1500, 0), params)
            local groundPos
            if hit then
                groundPos = hit.Position
            else
                local baseplate = workspace:FindFirstChild("Baseplate")
                if baseplate and baseplate:IsA("BasePart") then
                    groundPos = Vector3.new(root.Position.X, baseplate.Position.Y + baseplate.Size.Y * 0.5, root.Position.Z)
                end
            end
            if not groundPos then return nil end
            local right = root.CFrame.RightVector
            right = Vector3.new(right.X, 0, right.Z)
            if right.Magnitude < 0.01 then right = Vector3.new(1, 0, 0) end
            right = right.Unit
            return { groundPos - right * 1.15, groundPos + right * 1.15 }
        end

        local function stopCatapult(release)
            if Catapult.connection then pcall(function() Catapult.connection:Disconnect() end); Catapult.connection = nil end
            local model = getActiveCharacter()
            local root = model and model:FindFirstChild("HumanoidRootPart")
            local launchVelocity
            if release and root and Catapult.anchors then
                local currentVelocity = root.AssemblyLinearVelocity
                local look = root.CFrame.LookVector
                local forward = Vector3.new(look.X, 0, look.Z)
                if forward.Magnitude < 0.01 then forward = Vector3.new(0, 0, -1) end
                forward = forward.Unit
                -- Retain forward travel momentum, but never let a backwards
                -- velocity or the anchor displacement reverse the launch.
                local carried = math.max(0, Vector3.new(currentVelocity.X, 0, currentVelocity.Z):Dot(forward))
                local midpoint = (Catapult.anchors[1] + Catapult.anchors[2]) * 0.5
                local stretch = (Vector3.new(root.Position.X, 0, root.Position.Z) - Vector3.new(midpoint.X, 0, midpoint.Z)).Magnitude
                local stretchBoost = math.clamp(stretch * 3, 0, 180)
                local forwardSpeed = math.clamp(Catapult.launchForward + carried * 0.75 + stretchBoost, 0, 700)
                local upSpeed = math.clamp(Catapult.launchUp + stretch * 1.5 + math.max(0, currentVelocity.Y) * 0.35, 0, 520)
                launchVelocity = forward * forwardSpeed + Vector3.new(0, upSpeed, 0)
            end
            for _, d in ipairs(Catapult.data or {}) do pcall(function() restoreArmData(d) end) end
            Catapult.data = nil
            Catapult.anchors = nil
            Catapult.active = false
            if launchVelocity and root and root.Parent then
                pcall(function()
                    root.AssemblyAngularVelocity = Vector3.zero
                    root.AssemblyLinearVelocity = launchVelocity
                end)
            end
            refreshCatapultUI()
        end

        local function startCatapult()
            if not (api and api.is_reanimated and api.is_reanimated()) then return false, "Enable Reanim first" end
            if ArmStretch and ArmStretch.active then stopArmStretch(); refreshArmStretchUI() end
            stopCatapult(false)
            local model = getActiveCharacter()
            local root = model and model:FindFirstChild("HumanoidRootPart")
            if not model or not root then return false, "Reanim clone is not ready" end
            local anchors = catapultGroundPoints(model, root)
            if not anchors then return false, "No ground found beneath you" end
            local built = {}
            for _, side in ipairs({"Left", "Right"}) do
                local d = buildArmDataForChar(model, side)
                if not d then
                    for _, item in ipairs(built) do restoreArmData(item) end
                    return false, "Could not prepare both arms"
                end
                table.insert(built, d)
            end
            Catapult.data, Catapult.anchors, Catapult.active = built, anchors, true
            Catapult.connection = RunService.Heartbeat:Connect(function()
                if not Catapult.active then return end
                if not (api and api.is_reanimated and api.is_reanimated()) then stopCatapult(false); return end
                local activeModel = getActiveCharacter()
                local activeRoot = activeModel and activeModel:FindFirstChild("HumanoidRootPart")
                if not activeRoot then stopCatapult(false); return end
                for i, d in ipairs(Catapult.data or {}) do
                    local origin = getShoulderOrigin(d, activeRoot)
                    local target = Catapult.anchors and Catapult.anchors[i]
                    if not origin or not target then stopCatapult(false); return end
                    local delta = target - origin
                    if delta.Magnitude > 0.01 then updateStretchArm(d, origin, delta.Unit, math.clamp(delta.Magnitude, 1, 3000)) end
                end
            end)
            refreshCatapultUI()
            return true
        end

        local function toggleCatapult()
            if Catapult.active then
                stopCatapult(true)
            else
                local ok, err = startCatapult()
                if not ok then monoReanimSay("Catapult: " .. tostring(err)) end
            end
        end

        catapultBtn.MouseButton1Click:Connect(toggleCatapult)
        catapultBindBtn.MouseButton1Click:Connect(function()
            if Catapult.capturing then Catapult.capturing = false
            else Catapult.capturing = true end
            refreshCatapultUI()
        end)
        refreshCatapultUI()

        table.insert(monoReanimBuildConns, LocalPlayer.CharacterRemoving:Connect(function()
            if Catapult.active then stopCatapult(false) end
        end))

        bodySectionTitle("ARM ATTACH", 3)

        local faceAttachCard = Instance.new("Frame")
        faceAttachCard.Size = UDim2.new(1, 0, 0, 172)
        faceAttachCard.BackgroundColor3 = REAnimC.surface
        faceAttachCard.BackgroundTransparency = 0.4
        faceAttachCard.BorderSizePixel = 0
        faceAttachCard.LayoutOrder = 4
        faceAttachCard.Parent = bodyPanel
        corner(faceAttachCard, 7)
        stroke(faceAttachCard, REAnimC.borderSoft, 1, 0.55)

        local faceAttachBtn = Instance.new("TextButton")
        faceAttachBtn.Size = UDim2.new(1, -24, 0, 30)
        faceAttachBtn.Position = UDim2.new(0, 12, 0, 12)
        faceAttachBtn.BackgroundColor3 = REAnimC.surface
        faceAttachBtn.BackgroundTransparency = 0.4
        faceAttachBtn.Text = "Attach Arm to Cursor Target"
        faceAttachBtn.TextColor3 = REAnimC.text
        faceAttachBtn.Font = Enum.Font.GothamBold
        faceAttachBtn.TextSize = 11
        faceAttachBtn.AutoButtonColor = false
