        local function getFaceAttachment(head)
            if not head then return nil end
            local direct = head:FindFirstChild("FaceFrontAttachment")
            if direct and direct:IsA("Attachment") then return direct end
            for _, o in ipairs(head:GetDescendants()) do
                if o:IsA("Attachment") and o.Name == "FaceFrontAttachment" then
                    return o
                end
            end
            return nil
        end

        local function _getCursorTargetPlayer()
            local camera = workspace.CurrentCamera
            if not camera then return nil end

            local mouseLoc = UserInputService:GetMouseLocation()
            local ray = camera:ViewportPointToRay(mouseLoc.X, mouseLoc.Y)
            local result = workspace:Raycast(ray.Origin, ray.Direction * 2000)

            if not result or not result.Instance then return nil end

            local model = result.Instance:FindFirstAncestorOfClass("Model")
            if not model then return nil end

            local targetPlayer = Players:GetPlayerFromCharacter(model)
            if targetPlayer and targetPlayer ~= player then
                return targetPlayer
            end

            return nil
        end

        local function monoReanimCursorRaycast(ray, distance)
            local ignored = {}
            for _ = 1, 8 do
                local params = RaycastParams.new()
                params.FilterType = Enum.RaycastFilterType.Exclude
                params.FilterDescendantsInstances = ignored
                local result = workspace:Raycast(ray.Origin, ray.Direction * distance, params)
                if not result then return nil end
                local hit = result.Instance
                if hit and not hit:FindFirstAncestorOfClass("Accessory") then
                    return result
                end
                if hit then
                    local acc = hit:FindFirstAncestorOfClass("Accessory")
                    if acc then ignored[#ignored + 1] = acc end
                end
            end
            return nil
        end

        local function getCursorTargetInfo()
            local camera = workspace.CurrentCamera
            if not camera then return nil end

            local mouseLoc = UserInputService:GetMouseLocation()
            local ray = camera:ViewportPointToRay(mouseLoc.X, mouseLoc.Y)
            local result = monoReanimCursorRaycast(ray, 2000)
            if not result or not result.Instance then return nil end

            local hit = result.Instance
            if not hit:IsA("BasePart") then
                hit = hit:FindFirstAncestorOfClass("BasePart")
            end
            if not hit then return nil end

            local model = hit:FindFirstAncestorOfClass("Model")
            if not model then return nil end
            local targetPlayer = Players:GetPlayerFromCharacter(model)
            if not targetPlayer or targetPlayer == player then return nil end

            local partName = hit.Name

            return { player = targetPlayer, partName = partName, part = hit }
        end

        refreshFaceAttachUI = function()
            if FaceAttach.active then
                faceAttachBtn.Text = "Detach Arm"
                faceAttachBtn.BackgroundColor3 = REAnimC.surfaceHi
                faceAttachBtn.BackgroundTransparency = 0.15
                faceAttachBtn.TextColor3 = REAnimC.accent
        local faceStroke = faceAttachBtn:FindFirstChildOfClass("UIStroke")
        if faceStroke then faceStroke.Color = REAnimC.border; faceStroke.Transparency = 0.15 end
            else
                faceAttachBtn.Text = "Attach Arm to Cursor Target"
                faceAttachBtn.BackgroundColor3 = REAnimC.surface
                faceAttachBtn.BackgroundTransparency = 0.4
                faceAttachBtn.TextColor3 = REAnimC.text
        local faceStroke = faceAttachBtn:FindFirstChildOfClass("UIStroke")
        if faceStroke then faceStroke.Color = REAnimC.borderSoft; faceStroke.Transparency = 0.55 end
            end

            faceAttachBindBtn.Text = monoReanimBindLabel("Arm Attach", FaceAttach.bind)
            faceAttachBindBtn.TextColor3 = REAnimC.accent

            faceAttachEndBtn.Text = "End: " .. (FaceAttach.endMode or "Hand")
            faceAttachModeBtn.Text = "Targets: " .. (FaceAttach.mode or "One Target")
            faceAttachSideBtn.Text = "First Arm: " .. (FaceAttach.side or "Right")
            faceAttachModeBtn.TextColor3 = REAnimC.accent
        end

        stopFaceAttach = function()
            if FaceAttach.connection then
                FaceAttach.connection:Disconnect()
                FaceAttach.connection = nil
            end

            if FaceAttach.data then
                for _, d in ipairs(FaceAttach.data) do
                    restoreArmData(d)
                    if d.realLower and d.realLower.Parent then
                        d.realLower.Size = d.origRealLowerSize or d.realLower.Size
                        d.realLower.Transparency = d.origRealLowerTransparency or 0
                        d.realLower.Anchored = d.origRealLowerAnchored or false
                    end
                    if d.realHand and d.realHand.Parent then
                        d.realHand.Transparency = d.origRealHandTransparency or 0
                    end
                end
                FaceAttach.data = nil
            end

            pcall(function()
                local clone = api and api.get_clone and api.get_clone()
                local root = clone and clone:FindFirstChild("HumanoidRootPart")
                if root then
                    root.AssemblyLinearVelocity = Vector3.zero
                    root.AssemblyAngularVelocity = Vector3.zero
                end
                local realChar = api and api.get_real_character and api.get_real_character()
                local realRoot = realChar and realChar:FindFirstChild("HumanoidRootPart")
                if realRoot then
                    realRoot.AssemblyLinearVelocity = Vector3.zero
                    realRoot.AssemblyAngularVelocity = Vector3.zero
                end
            end)

            FaceAttach.active = false
            FaceAttach.targetPlayer = nil
            FaceAttach.targetHead = nil
            FaceAttach.targetFaceAttachment = nil
            FaceAttach.targets = {}
            FaceAttach.pendingTargets = {}
            refreshFaceAttachUI()
        end

        local function startFaceAttach(targetList, onlySide)
            if typeof(targetList) == "Instance" then
                targetList = { { player = targetList, partName = "Head" } }
            end
            if type(targetList) ~= "table" then return false, "No target" end

            local targets = {}
            for _, t in ipairs(targetList) do
                if type(t) ~= "table" or not t.player or t.player == player then
                    return false, "Invalid target"
                end
                targets[#targets + 1] = { player = t.player, partName = t.partName or "Head" }
            end

            local twoTargets = FaceAttach.mode == "Two Targets"
            if #targets == 0 then return false, "No player under cursor" end
            if twoTargets and not onlySide and #targets < 2 then return false, "Pick two targets first" end

            if not (api and api.is_reanimated and api.is_reanimated()) then
                return false, "Enable Reanim first"
            end

            stopFaceAttach()
            if ArmStretch.active then
                stopArmStretch()
                refreshArmStretchUI()
            end

            local model = getActiveCharacter()
            if not model then return false, "No character / clone" end

            local first = FaceAttach.side or "Right"
            local opposite = (first == "Right") and "Left" or "Right"
            local sides = {}
            if onlySide then
                sides = { onlySide }
            elseif twoTargets then
                sides = { first, opposite }
            else
                sides = { first }
            end

            local built = {}
            for i, side in ipairs(sides) do
                local d = buildArmDataForChar(model, side)
                if not d then
                    for _, b in ipairs(built) do restoreArmData(b) end
                    return false, "Failed to build "..side.." arm"
                end
                local realChar = api and api.get_real_character and api.get_real_character()
                if realChar then
                    local rl = findPartInModel(realChar, side.."LowerArm")
                    if rl then
                        d.realLower = rl
                        d.origRealLowerSize = rl.Size
                        d.origRealLowerTransparency = rl.Transparency
                        d.origRealLowerAnchored = rl.Anchored
                    end
                    local rh = findPartInModel(realChar, side.."Hand")
                    if rh then
                        d.realHand = rh
                        d.origRealHandTransparency = rh.Transparency
                    end
                end
                d.target = targets[twoTargets and i or 1]
                table.insert(built, d)
            end

            FaceAttach.data = built
            FaceAttach.targets = targets
            FaceAttach.targetPlayer = targets[1].player
            FaceAttach.active = true

            FaceAttach.connection = RunService.Heartbeat:Connect(function()
                if not FaceAttach.active then return end

                local modelNow = getActiveCharacter()
                local root = modelNow and modelNow:FindFirstChild("HumanoidRootPart")
                if not root then return end

                local dataCount = #(FaceAttach.data or {})

                for i, d in ipairs(FaceAttach.data or {}) do
                    if not (d.upper and d.upper.Parent and d.lower and d.lower.Parent and d.hand and d.hand.Parent) then
                        stopFaceAttach()
                        return
                    end

                    local tgt = d.target
                    if not (tgt and tgt.player and tgt.player.Parent) then
                        if #(FaceAttach.data or {}) > 1 then
                            restoreArmData(d)
                            if d.realLower and d.realLower.Parent then
                                d.realLower.Size = d.origRealLowerSize or d.realLower.Size
                                d.realLower.Transparency = d.origRealLowerTransparency or 0
                                d.realLower.Anchored = d.origRealLowerAnchored or false
                            end
                            if d.realHand and d.realHand.Parent then
                                d.realHand.Transparency = d.origRealHandTransparency or 0
                            end
                            table.remove(FaceAttach.data, i)
                            for j, t in ipairs(FaceAttach.targets) do
                                if t == tgt then table.remove(FaceAttach.targets, j); break end
                            end
                            refreshFaceAttachUI()
                            return
                        end
                        stopFaceAttach()
                        return
                    end
                    local targetChar = tgt.player.Character
                    local part = targetChar and targetChar:FindFirstChild(tgt.partName, true)
                    local targetCF = nil
                    if part and part:IsA("BasePart") then
                        if tgt.partName == "Head" then
                            local face = getFaceAttachment(part)
                            if face then targetCF = face.WorldCFrame end
                        end
                        if not targetCF then targetCF = part.CFrame end
                    end
                    if not targetCF then
                        local head = targetChar and targetChar:FindFirstChild("Head")
                        local face = getFaceAttachment(head)
                        if face then targetCF = face.WorldCFrame
                        elseif head then targetCF = head.CFrame end
                    end
                    if not targetCF then continue end

                    local origin = getShoulderOrigin(d, root)
                    if origin then
                        local offset = Vector3.zero
                        if not twoTargets and dataCount == 2 then
                            offset = (i == 1) and (targetCF.RightVector * 0.12) or (targetCF.RightVector * -0.12)
                        end

                        local targetPos = targetCF.Position + offset
                        local toTarget = targetPos - origin
                        if toTarget.Magnitude > 0.05 then
                            updateStretchArm(d, origin, toTarget.Unit, math.min(toTarget.Magnitude, 3000))
                        end

                        if d.lower and d.lower.Parent then
                            d.lower.CFrame = d.lower.CFrame * CFrame.new(0, -(d.lower.Size.Y * 0.5), 0)
                        end

                        if d.realHand and d.realHand.Parent then
                            d.realHand.Transparency = d.origRealHandTransparency or 0
                        end
                    end
                end
            end)

            refreshFaceAttachUI()
            local label = {}
            for _, t in ipairs(targets) do
                label[#label + 1] = tostring(t.player.DisplayName).." ("..t.partName..")"
            end
            return true, "Attached to "..table.concat(label, " / ")
        end

        local function attachSecondArm(info)
            if not FaceAttach.active then return false, "Attach an arm first" end
            if #(FaceAttach.targets or {}) >= 2 then return false, "Both arms already attached" end

            local model = getActiveCharacter()
            if not model then return false, "No character / clone" end

            local second = (FaceAttach.side == "Right") and "Left" or "Right"
            local d = buildArmDataForChar(model, second)
            if not d then return false, "Failed to build "..second.." arm" end

            local realChar = api and api.get_real_character and api.get_real_character()
            if realChar then
                local rl = findPartInModel(realChar, second.."LowerArm")
                if rl then
                    d.realLower = rl
                    d.origRealLowerSize = rl.Size
                    d.origRealLowerTransparency = rl.Transparency
                    d.origRealLowerAnchored = rl.Anchored
                end
                local rh = findPartInModel(realChar, second.."Hand")
                if rh then
                    d.realHand = rh
                    d.origRealHandTransparency = rh.Transparency
                end
            end

            d.target = info
            FaceAttach.targets[#FaceAttach.targets + 1] = info
            FaceAttach.data[#FaceAttach.data + 1] = d
            refreshFaceAttachUI()
            return true, "Attached "..second.." arm to "..tostring(info.player.DisplayName).." ("..info.partName..")"
        end

        local function toggleFaceAttachAtCursor()
            if FaceAttach.active then
                if FaceAttach.mode == "Two Targets" and #(FaceAttach.targets or {}) < 2 then
                    local info = getCursorTargetInfo()
                    if not info then
                        stopFaceAttach()
                        monoReanimSay("Attach: cleared partial attachment", 2)
                        return
                    end
                    local ok, msg = attachSecondArm(info)
                    if not ok then monoReanimSay("Attach: "..tostring(msg)) end
                    return
                end
                stopFaceAttach()
                return
            end

            local info = getCursorTargetInfo()
            if not info then
                monoReanimSay("Attach: put your cursor over a player's limb")
                return
            end

            if FaceAttach.mode == "Two Targets" then
                local ok, msg = startFaceAttach({ info }, FaceAttach.side or "Right")
                if not ok then monoReanimSay("Attach: "..tostring(msg)) end
                return
            end

            local ok, msg = startFaceAttach({ info })
            if not ok then monoReanimSay("Attach: "..tostring(msg)) end
        end

