        faceAttachSideBtn.MouseButton1Click:Connect(function()
            FaceAttach.side = (FaceAttach.side == "Right") and "Left" or "Right"
            if FaceAttach.active then stopFaceAttach() end
            refreshFaceAttachUI()
            monoReanimSaveBody()
        end)

