        lsHint.Text = "Stretches one or both legs toward the cursor. Uses the same reach and collision settings as Arm Stretch."
        lsHint.TextColor3 = REAnimC.textDim
        lsHint.Font = Enum.Font.Gotham
        lsHint.TextSize = 9
        lsHint.TextWrapped = true
        lsHint.TextXAlignment = Enum.TextXAlignment.Left
        lsHint.TextYAlignment = Enum.TextYAlignment.Top
        lsHint.Parent = legStretchCard

        LegStretch = {
            active = false, capturing = false, side = "Right", mode = "Toggle",
            length = 1300, collision = true, endMode = "Foot", bind = nil,
            data = nil, connection = nil, lastDir = nil,
            currentTarget = nil, currentReach = nil, rayParams = nil,
        }

        stopLegStretch = function()
            if LegStretch.connection then
                LegStretch.connection:Disconnect()
                LegStretch.connection = nil
            end
            if LegStretch.data then
                for _, d in ipairs(LegStretch.data) do
                    restoreArmData(d)
                    if d.shoulderMotor and d.shoulderMotor.Parent and d.origMotorOn.shoulder then d.shoulderMotor.Enabled = true end
                    if d.elbowMotor and d.elbowMotor.Parent and d.origMotorOn.elbow then d.elbowMotor.Enabled = true end
                    if d.wristMotor and d.wristMotor.Parent and d.origMotorOn.wrist then d.wristMotor.Enabled = true end
                end
                LegStretch.data = nil
            end
            LegStretch.active = false
            LegStretch.lastDir = nil
            LegStretch.currentTarget = nil
            LegStretch.currentReach = nil
        end

        local function startLegStretch()
            if not (api and api.is_reanimated and api.is_reanimated()) then return false, "Enable Reanim first" end
            stopLegStretch()
            if BodyArm.stopLegAttach then BodyArm.stopLegAttach() end
            local model = getActiveCharacter()
            if not model then return false, "No character / clone" end

            local sides = {}
            if LegStretch.side == "Left" then sides = {"Left"}
            elseif LegStretch.side == "Both" then sides = {"Right", "Left"}
            else sides = {"Right"} end

            local built = {}
            for _, side in ipairs(sides) do
                local d = buildLimbDataForChar(model, side, true)
                if not d then
                    for _, b in ipairs(built) do restoreArmData(b) end
                    return false, "Failed to build "..side.." leg"
                end
                built[#built + 1] = d
            end

            LegStretch.data = built
            LegStretch.active = true
            LegStretch.currentReach = nil
            LegStretch.rayParams = RaycastParams.new()
            LegStretch.rayParams.FilterType = Enum.RaycastFilterType.Exclude
            LegStretch.rayParams.FilterDescendantsInstances = { model }

            LegStretch.connection = RunService.Heartbeat:Connect(function(dt)
                if not LegStretch.active then return end
                local modelNow = getActiveCharacter()
                if not modelNow then stopLegStretch(); return end
                for _, d in ipairs(LegStretch.data or {}) do
                    if not (d.upper and d.upper.Parent and d.lower and d.lower.Parent and d.hand and d.hand.Parent) then
                        stopLegStretch(); return
                    end
                end
                local root = modelNow:FindFirstChild("HumanoidRootPart")
                if not root then return end

                local dir
                if UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) then
                    local mouseLoc = UserInputService:GetMouseLocation()
                    local ray = workspace.CurrentCamera:ViewportPointToRay(mouseLoc.X, mouseLoc.Y)
                    local target = ray.Origin + ray.Direction * 100
                    local v = target - root.Position
                    if v.Magnitude > 0.05 then dir = v.Unit; LegStretch.lastDir = dir end
                end
                if not dir then dir = LegStretch.lastDir or root.CFrame.LookVector end

                local origin = getShoulderOrigin(LegStretch.data[1], root)
                if not origin then return end
                local target = origin + dir * LegStretch.length
                if not LegStretch.currentTarget then
                    LegStretch.currentTarget = target
                else
                    local gap = (LegStretch.currentTarget - target).Magnitude
                    local speed = 10 + 30 * math.clamp(gap / 3000, 0, 1)
                    LegStretch.currentTarget = LegStretch.currentTarget:Lerp(target, math.clamp(dt * speed, 0, 1))
                end

                for _, d in ipairs(LegStretch.data) do
                    local o = getShoulderOrigin(d, root)
                    if o then
                        local toTarget = LegStretch.currentTarget - o
                        if toTarget.Magnitude > 0.05 then
                            local dist = toTarget.Magnitude
                            local reach = math.min(dist, 3000)
                            if LegStretch.collision and LegStretch.rayParams then
                                pcall(function()
                                    local hit = workspace:Raycast(o, toTarget.Unit * reach, LegStretch.rayParams)
                                    if hit then reach = math.min(reach, hit.Distance) end
                                end)
                            end
                            local curReach = LegStretch.currentReach or reach
                            local reachGap = math.abs(curReach - reach)
                            local speed = 10 + 30 * math.clamp(reachGap / 3000, 0, 1)
                            curReach = curReach + (reach - curReach) * math.clamp(dt * speed, 0, 1)
                            LegStretch.currentReach = curReach
                            updateStretchArm(d, o, toTarget.Unit, LegStretch.currentReach)
                        end
                        if d.lower and d.lower.Parent then
                            d.lower.CFrame = d.lower.CFrame * CFrame.new(0, -(d.lower.Size.Y * 0.5), 0)
                        end
                    end
                end
            end)

            refreshLegStretchUI()
            return true, "Leg stretch ON ("..table.concat(sides, "+")..")"
        end

        refreshLegStretchUI = function()
            if LegStretch.active then
                lsEnableBtn.Text = "Disable Leg Stretch"
