        end)

        local draggingLsLen = false
        local lsLenLastClick = 0
        local function setLsLenFromAlpha(a)
            LegStretch.length = math.floor(1 + math.clamp(a, 0, 1) * 2999)
            refreshLegStretchUI()
            monoReanimSaveBody()
        end
        local function updateLsLenFromInput(input)
            local relX = math.clamp(input.Position.X - lsLenTrack.AbsolutePosition.X, 0, lsLenTrack.AbsoluteSize.X)
            setLsLenFromAlpha(relX / math.max(1, lsLenTrack.AbsoluteSize.X))
        end
        lsLenTrack.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
                local now = tick()
                if now - lsLenLastClick <= 0.35 then
                    lsLenLastClick = 0
                    draggingLsLen = false
                    setLsLenFromAlpha((1300 - 1) / 2999)
                    return
                end
                lsLenLastClick = now
                draggingLsLen = true
                updateLsLenFromInput(input)
            end
        end)
        table.insert(monoReanimBuildConns, UserInputService.InputEnded:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 then draggingLsLen = false end
        end))
        table.insert(monoReanimBuildConns, UserInputService.InputChanged:Connect(function(input)
            if draggingLsLen and input.UserInputType == Enum.UserInputType.MouseMovement then
                updateLsLenFromInput(input)
            end
        end))

