        stopLegAttach = function()
            if LegAttach.connection then
                LegAttach.connection:Disconnect()
                LegAttach.connection = nil
            end
            if LegAttach.data then
                for _, d in ipairs(LegAttach.data) do restoreArmData(d) end
                LegAttach.data = nil
            end
            LegAttach.active = false
            LegAttach.targetPlayer = nil
            LegAttach.targets = {}
            refreshLegAttachUI()
        end

        local function resolveLegTargetCF(tgt)
            local tc = tgt and tgt.player and tgt.player.Character
            local part = tc and tc:FindFirstChild(tgt.partName, true)
            local cf = nil
            if part and part:IsA("BasePart") then
                if tgt.partName == "Head" then
                    local f = getFaceAttachment(part)
                    if f then cf = f.WorldCFrame end
                end
                if not cf then cf = part.CFrame end
            end
            if not cf then
                local head = tc and tc:FindFirstChild("Head")
                local f = getFaceAttachment(head)
                if f then cf = f.WorldCFrame
                elseif head then cf = head.CFrame end
            end
            return cf
        end

        local function startLegAttach(targetList, onlySide)
            if typeof(targetList) == "Instance" then
                targetList = { { player = targetList, partName = "Head" } }
            end
            if type(targetList) ~= "table" then return false, "No target" end
            local targets = {}
            for _, t in ipairs(targetList) do
                if type(t) ~= "table" or not t.player or t.player == player then return false, "Invalid target" end
                targets[#targets + 1] = { player = t.player, partName = t.partName or "Head" }
            end
            local twoTargets = LegAttach.mode == "Two Targets"
            if #targets == 0 then return false, "No player under cursor" end
            if twoTargets and not onlySide and #targets < 2 then return false, "Pick two targets first" end
            if not (api and api.is_reanimated and api.is_reanimated()) then return false, "Enable Reanim first" end

            stopLegAttach()
            if BodyArm.stopLegStretch then BodyArm.stopLegStretch() end
            local model = getActiveCharacter()
            if not model then return false, "No character / clone" end

            local sides = {}
            local first = LegAttach.side or "Right"
            local opposite = (first == "Right") and "Left" or "Right"
            if onlySide then sides = { onlySide }
            elseif twoTargets then sides = { first, opposite }
            else sides = { first } end

            local built = {}
            for i, side in ipairs(sides) do
                local d = buildLimbDataForChar(model, side, true)
                if not d then
                    for _, b in ipairs(built) do restoreArmData(b) end
                    return false, "Failed to build "..side.." leg"
                end
                d.target = targets[twoTargets and i or 1]
                built[#built + 1] = d
            end

            LegAttach.data = built
            LegAttach.targets = targets
            LegAttach.targetPlayer = targets[1].player
            LegAttach.active = true

            LegAttach.connection = RunService.Heartbeat:Connect(function()
                if not LegAttach.active then return end
                local modelNow = getActiveCharacter()
                local root = modelNow and modelNow:FindFirstChild("HumanoidRootPart")
                if not root then return end
                for i, d in ipairs(LegAttach.data or {}) do
                    local tgt = d.target
                    if not (tgt and tgt.player and tgt.player.Parent) then
                        if #(LegAttach.data or {}) > 1 then
                            restoreArmData(d)
                            table.remove(LegAttach.data, i)
                            for j, t in ipairs(LegAttach.targets) do
                                if t == tgt then table.remove(LegAttach.targets, j); break end
                            end
                            refreshLegAttachUI()
                            return
                        end
                        stopLegAttach()
                        return
                    end
                    local cf = resolveLegTargetCF(tgt)
                    if not cf then continue end
                    local origin = getShoulderOrigin(d, root)
                    if origin then
                        local toTarget = cf.Position - origin
                        if toTarget.Magnitude > 0.05 then
                            updateStretchArm(d, origin, toTarget.Unit, math.min(toTarget.Magnitude, 3000))
                        end
                        if d.lower and d.lower.Parent then
                            d.lower.CFrame = d.lower.CFrame * CFrame.new(0, -(d.lower.Size.Y * 0.5), 0)
                        end
                    end
                end
            end)

            refreshLegAttachUI()
            local label = {}
            for _, t in ipairs(targets) do label[#label + 1] = tostring(t.player.DisplayName).." ("..t.partName..")" end
            return true, "Leg attached to "..table.concat(label, " / ")
        end

        local function attachSecondLeg(info)
            if not LegAttach.active then return false, "Attach a leg first" end
            if #(LegAttach.targets or {}) >= 2 then return false, "Both legs already attached" end
            local model = getActiveCharacter()
            if not model then return false, "No character / clone" end
            local second = (LegAttach.side == "Right") and "Left" or "Right"
            local d = buildLimbDataForChar(model, second, true)
            if not d then return false, "Failed to build "..second.." leg" end
            d.target = info
            LegAttach.targets[#LegAttach.targets + 1] = info
            LegAttach.data[#LegAttach.data + 1] = d
            refreshLegAttachUI()
            return true, second.." leg attached to "..tostring(info.player.DisplayName).." ("..info.partName..")"
        end

        local function toggleLegAttachAtCursor()
            if LegAttach.active then
                if LegAttach.mode == "Two Targets" and #(LegAttach.targets or {}) < 2 then
                    local info = getCursorTargetInfo()
                    if not info then
                        stopLegAttach()
                        monoReanimSay("Attach: cleared partial attachment", 2)
                        return
                    end
                    local ok, msg = attachSecondLeg(info)
                    if not ok then monoReanimSay("Attach: "..tostring(msg)) end
                    return
                end
                stopLegAttach()
                return
            end
            local info = getCursorTargetInfo()
            if not info then monoReanimSay("Attach: put your cursor over a limb"); return end
            local ok, msg
            if LegAttach.mode == "Two Targets" then
                ok, msg = startLegAttach({ info }, LegAttach.side or "Right")
            else
                ok, msg = startLegAttach({ info })
            end
            if not ok then monoReanimSay("Attach: "..tostring(msg)) end
        end

