            refreshLegAttachUI()
            monoReanimSaveBody()
        end)

        laModeBtn.MouseButton1Click:Connect(function()
            LegAttach.mode = (LegAttach.mode == "Two Targets") and "One Target" or "Two Targets"
            if LegAttach.active then stopLegAttach() end
