        local TorsoAim = {
            active = false,
            mode = "Stretch",
            stretchReach = 14,
            followStrength = 100,
            capturing = nil,
            data = nil,
            connection = nil,
            smoothPos = nil,
            lastDir = nil,
            targetPlayer = nil,
            targetFaceAttachment = nil,
            stretchBind = nil, followBind = nil, faceAttachBind = nil,
            allowFlip = false,
            collision = true, currentReach = nil, collisionBtn = nil, refreshUI = nil,
        }

        do
        local torsoCollisionBtn = Instance.new("TextButton")
        torsoCollisionBtn.Size = UDim2.new(0, 168, 0, 26)
