        local function setPartCFrame(part, pos, lookDir)
            if not part or not part.Parent then return end
            local look = lookDir
            if not look or look.Magnitude < 0.01 then look = Vector3.new(0,0,-1) end
            look = look.Unit
            local right = Vector3.new(0,1,0):Cross(look)
            if right.Magnitude < 0.05 then right = Vector3.new(1,0,0):Cross(look) end
            right = right.Unit
            local up = look:Cross(right).Unit
            part.CFrame = CFrame.fromMatrix(pos, right, up, -look)
        end

        local function findWaistMotor(model)
            if not model then return nil, nil end
            local up = model:FindFirstChild("UpperTorso")
            if not up then return nil, nil end
            local waistMotor
            for _, m in ipairs(model:GetDescendants()) do
                if m:IsA("Motor6D") and m.Part1 == up then waistMotor = m; break end
            end
            if not waistMotor then
                for _, m in ipairs(model:GetDescendants()) do
                    if m:IsA("Motor6D") and m.Name:lower():find("waist") then waistMotor = m; break end
                end
            end
            return up, waistMotor
        end

        local getFaceAttachmentT = getFaceAttachment
        local getCursorTargetPlayerT = getCursorTargetPlayer
        local getCursorTargetInfoT = getCursorTargetInfo

        local function trueRestC0(joint, partName)
            local realChar = api and api.get_real_character and api.get_real_character()
            if realChar then
                for _, m in ipairs(realChar:GetDescendants()) do
                    if m:IsA("Motor6D") and m.Part1 and m.Part1.Name == partName then
                        return m.C0
                    end
                end
            end
            local animC0s = monoReanim.animation and monoReanim.animation.original_motor_c0s
            return (joint and animC0s and animC0s[joint]) or (joint and joint.C0) or CFrame.new()
        end

        local function syncAnimCachedC0(joint, restC0)
            pcall(function()
                local anim = monoReanim.animation
                if anim and anim.original_motor_c0s and joint then
                    anim.original_motor_c0s[joint] = restC0
                end
            end)
        end

        local function prepareStretchData(model)
            if not model then return nil end
            local up, waistMotor = findWaistMotor(model)
            if not up or not waistMotor then return nil end

            local data = {
                mode = "Stretch",
                upper = up,
                waistMotor = waistMotor,
                origUpper = {
                    anchored = up.Anchored,
                    canCollide = up.CanCollide,
                    canTouch = up.CanTouch,
                    canQuery = up.CanQuery,
                    massless = up.Massless,
                },
                origWaist = {
                    enabled = waistMotor.Enabled,
                    c0 = waistMotor.C0,
                    c1 = waistMotor.C1,
                },
                rootPart = model:FindFirstChild("LowerTorso") or model:FindFirstChild("HumanoidRootPart"),
                waistRestC0 = trueRestC0(waistMotor, "UpperTorso"),
            }
            syncAnimCachedC0(waistMotor, data.waistRestC0)
            waistMotor.Enabled = false
            up.Anchored = true
            up.CanCollide = false
            up.CanTouch = false
            up.CanQuery = false
            up.Massless = true
            return data
        end

        local function prepareFollowData(model)
            if not model then return nil end
            local up, waistMotor = findWaistMotor(model)
            if not up or not waistMotor then return nil end
            if not waistMotor.Part0 then return nil end

            local restC0 = trueRestC0(waistMotor, "UpperTorso")
            syncAnimCachedC0(waistMotor, restC0)
            return {
                mode = "Follow",
                upper = up,
                waistMotor = waistMotor,
                origC0 = waistMotor.C0,
                restC0 = restC0 or waistMotor.C0,
                origC1 = waistMotor.C1,
                rootPart = waistMotor.Part0,
            }
        end

        local function restoreTorsoData(data)
            if not data then return end
            pcall(function()
                if data.mode == "Stretch" or data.mode == "Attach" then
                    if data.upper and data.upper.Parent then
                        data.upper.Anchored = data.origUpper.anchored
                        data.upper.CanCollide = data.origUpper.canCollide
                        data.upper.CanTouch = data.origUpper.canTouch
                        data.upper.CanQuery = data.origUpper.canQuery
                        data.upper.Massless = data.origUpper.massless
                    end
                    if data.waistMotor and data.waistMotor.Parent then
                        local rc = data.waistRestC0 or data.origWaist.c0
                        data.waistMotor.Enabled = data.origWaist.enabled
                        data.waistMotor.C0 = rc
                        data.waistMotor.C1 = data.origWaist.c1
                        syncAnimCachedC0(data.waistMotor, rc)
                    end
                elseif data.mode == "Follow" then
                    if data.waistMotor and data.waistMotor.Parent then
                        local rc = data.restC0 or data.origC0
                        data.waistMotor.C0 = rc
                        data.waistMotor.C1 = data.origC1
                        syncAnimCachedC0(data.waistMotor, rc)
                    end
                end
            end)
        end

        local function stopTorsoAim()
            if TorsoAim.connection then
                TorsoAim.connection:Disconnect()
                TorsoAim.connection = nil
            end
            if TorsoAim.data then
                if monoReanim.trickJoints and TorsoAim.data.waistMotor then
                    monoReanim.trickJoints[TorsoAim.data.waistMotor] = nil
                end
                restoreTorsoData(TorsoAim.data)
                TorsoAim.data = nil
            end
            TorsoAim.active = false
            TorsoAim.smoothPos = nil
            TorsoAim.currentReach = nil
            TorsoAim.lastDir = nil
            TorsoAim.targetPlayer = nil
            TorsoAim.targetPartName = nil
            TorsoAim.targetFaceAttachment = nil
        end

        local function getCursorDirection(origin)
            if UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) then
                local mouseLoc = UserInputService:GetMouseLocation()
                local ray = workspace.CurrentCamera:ViewportPointToRay(mouseLoc.X, mouseLoc.Y)
                local target = ray.Origin + ray.Direction * 200
                local v = target - origin
                if v.Magnitude > 0.1 then
                    return v.Unit
                end
            end
            return nil
        end

        local function startTorsoStretch()
            if not (api and api.is_reanimated and api.is_reanimated()) then
                return false, "Enable Reanim first"
            end
            if BodyArm.stopTorsoHeight then BodyArm.stopTorsoHeight() end
            stopTorsoAim()

            local model = getActiveCharacter()
            if not model then return false, "No character / clone" end

            local data = prepareStretchData(model)
            if not data then return false, "Could not prepare torso" end

            pcall(function()
                local params = RaycastParams.new()
                params.FilterType = Enum.RaycastFilterType.Exclude
                local filter = {}
                local realChar = api and api.get_real_character and api.get_real_character()
                if realChar then filter[#filter + 1] = realChar end
                if model then filter[#filter + 1] = model end
                params.FilterDescendantsInstances = filter
                TorsoAim.rayParams = params
            end)
            TorsoAim.currentReach = nil

            TorsoAim.data = data
            TorsoAim.active = true
            TorsoAim.mode = "Stretch"
            TorsoAim.smoothPos = nil
            TorsoAim.lastDir = nil

            TorsoAim.connection = RunService.Heartbeat:Connect(function(dt)
                if not TorsoAim.active then return end
                local model = getActiveCharacter()
                if not model then stopTorsoAim(); return end
                local data = TorsoAim.data
                if not data or not data.upper or not data.upper.Parent then stopTorsoAim(); return end

                local root = model:FindFirstChild("HumanoidRootPart")
                if not root then return end
                local lt = data.rootPart
                local origin
                if lt and lt.Parent then
                    origin = lt.Position + Vector3.new(0, 1.2, 0)
                else
                    origin = root.Position + Vector3.new(0, 1.2, 0)
                end

                local dir = getCursorDirection(origin)
                if dir then
                    TorsoAim.lastDir = dir
                else
                    dir = TorsoAim.lastDir or root.CFrame.LookVector
                end

                local desiredReach = TorsoAim.stretchReach
                if TorsoAim.collision and TorsoAim.rayParams then
                    pcall(function()
                        local hit = workspace:Raycast(origin, dir * desiredReach, TorsoAim.rayParams)
                        if hit then desiredReach = math.min(desiredReach, hit.Distance) end
                    end)
                end
                local curReach = TorsoAim.currentReach or desiredReach
                local reachGap = math.abs(curReach - desiredReach)
                local reachSpeed = 10 + 30 * math.clamp(reachGap / 3000, 0, 1)
                curReach = curReach + (desiredReach - curReach) * math.clamp(dt * reachSpeed, 0, 1)
                TorsoAim.currentReach = curReach

                local dp = origin + dir * curReach
                if not TorsoAim.smoothPos then
                    TorsoAim.smoothPos = dp
                else
                    local aimGap = (TorsoAim.smoothPos - dp).Magnitude
                    local aimSpeed = 10 + 30 * math.clamp(aimGap / 3000, 0, 1)
                    TorsoAim.smoothPos = TorsoAim.smoothPos:Lerp(dp, math.clamp(dt * aimSpeed, 0, 1))
                end

                setPartCFrame(data.upper, TorsoAim.smoothPos, dir)
            end)

            return true, "Torso stretch ON"
        end

        local function startTorsoFollow()
            if not (api and api.is_reanimated and api.is_reanimated()) then
                return false, "Enable Reanim first"
            end
            if BodyArm.stopTorsoHeight then BodyArm.stopTorsoHeight() end
            stopTorsoAim()

            local model = getActiveCharacter()
            if not model then return false, "No character / clone" end

            local data = prepareFollowData(model)
            if not data then return false, "Could not prepare torso (clone not ready?)" end

            TorsoAim.data = data
            monoReanim.trickJoints[data.waistMotor] = true
            TorsoAim.active = true
            TorsoAim.mode = "Follow"
            TorsoAim.lastDir = nil

            TorsoAim.connection = RunService.Heartbeat:Connect(function(dt)
                if not TorsoAim.active then return end
                local model = getActiveCharacter()
                if not model then stopTorsoAim(); return end
                local data = TorsoAim.data
                if not data or not data.waistMotor or not data.waistMotor.Parent then
                    stopTorsoAim(); return
                end
                local part0 = data.waistMotor.Part0
                if not part0 then return end

                local origin = part0.Position
                local dir = getCursorDirection(origin)
                if dir then
                    TorsoAim.lastDir = dir
                else
                    dir = TorsoAim.lastDir or part0.CFrame.LookVector
                end

                local rel = part0.CFrame:VectorToObjectSpace(dir)

                local strength = math.clamp((TorsoAim.followStrength - 1) / 99, 0, 1)

                local rot
                if TorsoAim.allowFlip then
                    local yaw = math.atan2(-rel.X, -rel.Z) * strength
                    local pitch = math.atan2(rel.Y, -rel.Z) * strength
                    rot = CFrame.Angles(pitch, yaw, 0)
                else
                    local look = rel
                    if look.Magnitude < 0.001 then look = Vector3.new(0, 0, -1) end
                    look = look.Unit
                    local pitch = math.asin(math.clamp(look.Y, -0.97, 0.97))
                    local flat = Vector3.new(look.X, 0, look.Z)
                    if flat.Magnitude < 0.001 then flat = Vector3.new(0, 0, -1) end
                    local wanted = flat.Unit * math.cos(pitch) + Vector3.new(0, math.sin(pitch), 0)
                    local blended = Vector3.new(0, 0, -1):Lerp(wanted, strength)
                    if blended.Magnitude < 0.001 then blended = Vector3.new(0, 0, -1) end
                    rot = CFrame.lookAt(Vector3.zero, blended.Unit)
                end

                data.waistMotor.C0 = CFrame.new(data.origC0.Position) * rot
            end)

            return true, "Torso follow ON"
        end

        local function startTorsoFaceAttach(targetInfo)
            if typeof(targetInfo) == "Instance" then
                targetInfo = { player = targetInfo, partName = "Head" }
            end
            if type(targetInfo) ~= "table" or not targetInfo.player or targetInfo.player == player then
                return false, "No player under cursor"
            end
            if not (api and api.is_reanimated and api.is_reanimated()) then
                return false, "Enable Reanim first"
            end
            if BodyArm.stopTorsoHeight then BodyArm.stopTorsoHeight() end

            local targetPlayer = targetInfo.player
            local partName = targetInfo.partName or "Head"

            stopTorsoAim()

            local model = getActiveCharacter()
            if not model then return false, "No character / clone" end

            local data = prepareStretchData(model)
            if not data then return false, "Could not prepare torso" end
            data.mode = "Attach"

            TorsoAim.data = data
            TorsoAim.active = true
            TorsoAim.mode = "Attach"
            TorsoAim.targetPlayer = targetPlayer
            TorsoAim.targetPartName = partName
            TorsoAim.targetFaceAttachment = nil
            TorsoAim.smoothPos = nil

            TorsoAim.connection = RunService.Heartbeat:Connect(function(dt)
                if not TorsoAim.active then return end
                local model = getActiveCharacter()
                if not model then stopTorsoAim(); return end
                local data = TorsoAim.data
                if not data or not data.upper or not data.upper.Parent then stopTorsoAim(); return end

                local currentChar = targetPlayer.Character
                local part = currentChar and currentChar:FindFirstChild(partName, true)
                local hcf = nil
                local aimPart = nil
                if part and part:IsA("BasePart") then
                    if partName == "Head" then
                        local f = getFaceAttachmentT(part)
                        if f then hcf = f.WorldCFrame end
                    end
                    if not hcf then hcf = part.CFrame end
                    aimPart = part
                end
                if not hcf then
                    local head = currentChar and currentChar:FindFirstChild("Head")
                    local f = getFaceAttachmentT(head)
                    if f then hcf = f.WorldCFrame
                    elseif head then hcf = head.CFrame end
                    aimPart = head
                end
                if not hcf or not aimPart then stopTorsoAim(); return end
                TorsoAim.targetFaceAttachment = hcf

                local targetPos = hcf.Position + hcf.LookVector * 0.4

                if not TorsoAim.smoothPos then
                    TorsoAim.smoothPos = targetPos
                else
                    local a = math.clamp(dt * 22, 0, 1)
                    TorsoAim.smoothPos = TorsoAim.smoothPos:Lerp(targetPos, a)
                end

                local lookDir = aimPart.CFrame.LookVector
                if lookDir.Magnitude < 0.01 then lookDir = hcf.LookVector end
                setPartCFrame(data.upper, TorsoAim.smoothPos, lookDir)
            end)

            return true, "Torso attached to "..targetPlayer.DisplayName.." ("..partName..")"
        end

        local function startTorsoAim(mode)
            if mode == "Follow" then
                return startTorsoFollow()
            elseif mode == "Attach" then
                local info = getCursorTargetInfoT()
                if not info then return false, "Put cursor over a player's limb" end
                return startTorsoFaceAttach(info)
            else
                return startTorsoStretch()
            end
        end

        local function refreshTorsoAimUI()
            if TorsoAim.active then
                torsoEnableBtn.Text = "Disable Torso Aim"
                torsoEnableBtn.BackgroundColor3 = REAnimC.surfaceHi
                torsoEnableBtn.BackgroundTransparency = 0.15
                torsoEnableBtn.TextColor3 = REAnimC.accent
        local torsoStroke = torsoEnableBtn:FindFirstChildOfClass("UIStroke")
        if torsoStroke then torsoStroke.Color = REAnimC.border; torsoStroke.Transparency = 0.15 end
            else
                torsoEnableBtn.Text = "Enable Torso Aim"
                torsoEnableBtn.BackgroundColor3 = REAnimC.surface
                torsoEnableBtn.BackgroundTransparency = 0.4
                torsoEnableBtn.TextColor3 = REAnimC.text
        local torsoStroke = torsoEnableBtn:FindFirstChildOfClass("UIStroke")
        if torsoStroke then torsoStroke.Color = REAnimC.borderSoft; torsoStroke.Transparency = 0.55 end
            end

            if TorsoAim.mode == "Attach" and TorsoAim.active then
                torsoModeBtn.Text = "Mode: Attach"
            else
                torsoModeBtn.Text = "Mode: "..TorsoAim.mode
            end

            torsoStretchBindBtn.Text = monoReanimBindLabel("Stretch", TorsoAim.stretchBind)
            torsoStretchBindBtn.TextColor3 = REAnimC.accent
            torsoFollowBindBtn.Text = monoReanimBindLabel("Follow", TorsoAim.followBind)
            torsoFollowBindBtn.TextColor3 = REAnimC.accent
            torsoFaceAttachBindBtn.Text = monoReanimBindLabel("Limb Attach", TorsoAim.faceAttachBind)
            torsoFaceAttachBindBtn.TextColor3 = REAnimC.accent

            if TorsoAim.active and TorsoAim.mode == "Attach" then
                torsoFaceAttachActionBtn.Text = "Detach Face"
                torsoFaceAttachActionBtn.BackgroundColor3 = REAnimC.surfaceHi
                torsoFaceAttachActionBtn.BackgroundTransparency = 0.15
                torsoFaceAttachActionBtn.TextColor3 = REAnimC.accent
                local s = torsoFaceAttachActionBtn:FindFirstChildOfClass("UIStroke")
                if s then s.Color = REAnimC.border; s.Transparency = 0.15 end
            else
                torsoFaceAttachActionBtn.Text = "Attach to Face"
                torsoFaceAttachActionBtn.BackgroundColor3 = REAnimC.surface
                torsoFaceAttachActionBtn.BackgroundTransparency = 0.4
                torsoFaceAttachActionBtn.TextColor3 = REAnimC.accent
                local s = torsoFaceAttachActionBtn:FindFirstChildOfClass("UIStroke")
                if s then s.Color = REAnimC.borderSoft; s.Transparency = 0.55 end
            end

            if TorsoAim.mode == "Attach" and TorsoAim.active then
                torsoReachInfo.Text = "Attached"
                torsoReachLabel.Text = "ATTACHED TO FACE"
                torsoReachFill.Size = UDim2.new(1, 0, 1, 0)
            elseif TorsoAim.mode == "Follow" then
                torsoReachInfo.Text = "Lean: "..tostring(math.floor(TorsoAim.followStrength)).."%"
                torsoReachLabel.Text = "LEAN STRENGTH: "..tostring(math.floor(TorsoAim.followStrength)).."%"
                local pct = math.clamp((TorsoAim.followStrength - 1) / 99, 0, 1)
                torsoReachFill.Size = UDim2.new(pct, 0, 1, 0)
            else
                torsoReachInfo.Text = "Reach: "..tostring(math.floor(TorsoAim.stretchReach))
                torsoReachLabel.Text = "REACH: "..tostring(math.floor(TorsoAim.stretchReach))
                local pct = math.clamp((TorsoAim.stretchReach - 1) / (3000 - 1), 0, 1)
                torsoReachFill.Size = UDim2.new(pct, 0, 1, 0)
            end

            torsoFlipBtn.Text = "Flip: " .. (TorsoAim.allowFlip and "On" or "Off")
            if TorsoAim.collisionBtn then
                TorsoAim.collisionBtn.Text = "Collision: " .. (TorsoAim.collision and "On" or "Off")
            end
            torsoFlipBtn.TextColor3 = REAnimC.accent
        end

        torsoEnableBtn.MouseButton1Click:Connect(function()
