        local function refreshTorsoHeightUI()
            if TorsoHeight.active then
                thEnableBtn.Text = "Disable Torso Height"
                thEnableBtn.BackgroundColor3 = REAnimC.surfaceHi
                thEnableBtn.BackgroundTransparency = 0.15
                thEnableBtn.TextColor3 = REAnimC.accent
                thEnableStroke.Color = REAnimC.border
