            else
                thEnableBtn.Text = "Enable Torso Height"
                thEnableBtn.BackgroundColor3 = REAnimC.surface
                thEnableBtn.BackgroundTransparency = 0.4
                thEnableBtn.TextColor3 = REAnimC.text
                thEnableStroke.Color = REAnimC.borderSoft
                thEnableStroke.Transparency = 0.55
            end
            thLabel.Text = "HEIGHT: "..tostring(math.floor(TorsoHeight.height))
            local pct = math.clamp((TorsoHeight.height - 1) / (3000 - 1), 0, 1)
            thFill.Size = UDim2.new(pct, 0, 1, 0)
            thBindBtn.Text = monoReanimBindLabel("Torso Height", TorsoHeight.bind)
            thBindBtn.TextColor3 = REAnimC.accent
        end

        local function stopTorsoHeight()
            if TorsoHeight.connection then
                TorsoHeight.connection:Disconnect()
                TorsoHeight.connection = nil
            end
            if TorsoHeight.data then
                local d = TorsoHeight.data
                pcall(function()
                    if d.waistMotor and d.waistMotor.Parent then
                        d.waistMotor.C0 = d.restC0 or d.origC0
                    end
                    syncAnimCachedC0(d.waistMotor, d.restC0 or d.origC0)
                end)
                if monoReanim.trickJoints and d.waistMotor then
                    monoReanim.trickJoints[d.waistMotor] = nil
                end
                TorsoHeight.data = nil
            end
            TorsoHeight.active = false
            if refreshTorsoHeightUI then refreshTorsoHeightUI() end
        end

        local function startTorsoHeight()
            if not (api and api.is_reanimated and api.is_reanimated()) then
                return false, "Enable Reanim first"
            end
            stopTorsoHeight()
            if TorsoAim.active then
                stopTorsoAim()
                refreshTorsoAimUI()
            end
            local model = getActiveCharacter()
            if not model then return false, "No character / clone" end
            local up, waist = findWaistMotor(model)
            if not up or not waist or not waist.Part0 then return false, "Could not find waist joint" end

            local restC0 = trueRestC0(waist, "UpperTorso")
            TorsoHeight.data = { waistMotor = waist, origC0 = waist.C0, restC0 = restC0 }
            syncAnimCachedC0(waist, restC0)
            monoReanim.trickJoints[waist] = true
            TorsoHeight.active = true

            TorsoHeight.connection = RunService.Heartbeat:Connect(function()
                if not TorsoHeight.active then return end
                local d = TorsoHeight.data
                if not d or not d.waistMotor or not d.waistMotor.Parent then
                    stopTorsoHeight()
                    return
                end
                pcall(function()
                    d.waistMotor.C0 = (d.restC0 or d.origC0) * CFrame.new(0, TorsoHeight.height, 0)
                end)
            end)

            return true, "Torso height ON"
        end

        thEnableBtn.MouseButton1Click:Connect(function()
            if TorsoHeight.active then
                stopTorsoHeight()
            else
                local ok, msg = startTorsoHeight()
                if not ok then monoReanimSay("Torso height: "..tostring(msg)) end
            end
            refreshTorsoHeightUI()
        end)

        thBindBtn.MouseButton1Click:Connect(function()
            if TorsoHeight.capturing then
                TorsoHeight.capturing = false
                refreshTorsoHeightUI()
                return
            end
            if TorsoHeight.bind then
                TorsoHeight.bind = nil
                refreshTorsoHeightUI()
                monoReanimSaveBody()
                return
            end
            TorsoHeight.capturing = true
            thBindBtn.Text = "..."
            thBindBtn.TextColor3 = REAnimC.accent
        end)

        local draggingTh = false
        local function updateThFromInput(input)
            local relX = math.clamp(input.Position.X - thTrack.AbsolutePosition.X, 0, thTrack.AbsoluteSize.X)
            TorsoHeight.height = math.floor(1 + (relX / thTrack.AbsoluteSize.X) * (3000 - 1))
            refreshTorsoHeightUI()
            monoReanimSaveBody()
        end
        thTrack.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 then
                draggingTh = true
                updateThFromInput(input)
            end
        end)
        table.insert(monoReanimBuildConns, UserInputService.InputEnded:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 then draggingTh = false end
        end))
        table.insert(monoReanimBuildConns, UserInputService.InputChanged:Connect(function(input)
            if draggingTh and input.UserInputType == Enum.UserInputType.MouseMovement then
                updateThFromInput(input)
            end
        end))

        BodyArm.TorsoHeight = TorsoHeight
        BodyArm.stopTorsoHeight = stopTorsoHeight
        BodyArm.startTorsoHeight = startTorsoHeight
        BodyArm.refreshTorsoHeightUI = refreshTorsoHeightUI
        refreshTorsoHeightUI()

