        local HeadTracker = {
            active = false,
            bind = nil,
            capturing = false,
            connection = nil,
            data = nil,
            lastDir = nil,
        }

        local function refreshHeadTrackerUI()
            if HeadTracker.active then
                htEnableBtn.Text = "Disable Head Tracker"
                htEnableBtn.BackgroundColor3 = REAnimC.surfaceHi
                htEnableBtn.BackgroundTransparency = 0.15
                htEnableBtn.TextColor3 = REAnimC.accent
                htEnableStroke.Color = REAnimC.border
                htEnableStroke.Transparency = 0.15
            else
                htEnableBtn.Text = "Enable Head Tracker"
                htEnableBtn.BackgroundColor3 = REAnimC.surface
                htEnableBtn.BackgroundTransparency = 0.4
                htEnableBtn.TextColor3 = REAnimC.text
                htEnableStroke.Color = REAnimC.borderSoft
                htEnableStroke.Transparency = 0.55
            end
            htBindBtn.Text = monoReanimBindLabel("Head Tracker", HeadTracker.bind)
            htBindBtn.TextColor3 = REAnimC.accent
        end

        findHeadMotor = function(model)
            if not model then return nil end
            local head = model:FindFirstChild("Head")
            if not head then return nil end
            for _, m in ipairs(model:GetDescendants()) do
                if m:IsA("Motor6D") and m.Part1 == head then return m end
            end
            for _, m in ipairs(model:GetDescendants()) do
                if m:IsA("Motor6D") and m.Name:lower():find("neck") then return m end
            end
            return nil
        end

        local function stopHeadTracker()
            if HeadTracker.connection then
                HeadTracker.connection:Disconnect()
                HeadTracker.connection = nil
            end
            if HeadTracker.data then
                local d = HeadTracker.data
                pcall(function()
                    if d.headMotor and d.headMotor.Parent then
                        d.headMotor.C0 = d.restC0 or d.origC0
                    end
                    local anim = monoReanim.animation
                    if anim and anim.original_motor_c0s and d.headMotor then
                        anim.original_motor_c0s[d.headMotor] = (d.restC0 or d.origC0)
                    end
                end)
                if monoReanim.trickJoints and d.headMotor then
                    monoReanim.trickJoints[d.headMotor] = nil
                end
                HeadTracker.data = nil
            end
            HeadTracker.active = false
            HeadTracker.lastDir = nil
            if refreshHeadTrackerUI then refreshHeadTrackerUI() end
        end

        local function startHeadTracker()
            if not (api and api.is_reanimated and api.is_reanimated()) then
                return false, "Enable Reanim first"
            end
            stopHeadTracker()

            local model = getActiveCharacter()
            if not model then return false, "No character / clone" end
            local headMotor = findHeadMotor(model)
            if not headMotor or not headMotor.Part0 then return false, "Could not find neck joint" end

            local restC0 = nil
            local realChar = api and api.get_real_character and api.get_real_character()
            local realHead = realChar and realChar:FindFirstChild("Head")
            if realHead then
                for _, m in ipairs(realChar:GetDescendants()) do
                    if m:IsA("Motor6D") and m.Part1 == realHead then restC0 = m.C0; break end
                end
            end
            if not restC0 then
                local animC0s = monoReanim.animation and monoReanim.animation.original_motor_c0s
                restC0 = animC0s and animC0s[headMotor] or nil
            end
            HeadTracker.data = { headMotor = headMotor, origC0 = headMotor.C0, restC0 = restC0 or headMotor.C0 }
            monoReanim.trickJoints[headMotor] = true
            pcall(function()
                local anim = monoReanim.animation
                if anim and anim.original_motor_c0s then
                    anim.original_motor_c0s[headMotor] = (restC0 or headMotor.C0)
                end
            end)
            HeadTracker.active = true

            HeadTracker.connection = RunService.Heartbeat:Connect(function()
                if not HeadTracker.active then return end
                local d = HeadTracker.data
                if not d or not d.headMotor or not d.headMotor.Parent then
                    stopHeadTracker()
                    return
                end
                local part0 = d.headMotor.Part0
                if not part0 then return end

                local origin = part0.Position
                local dir = getCursorDirection(origin)
                if dir then
                    HeadTracker.lastDir = dir
                else
                    dir = HeadTracker.lastDir
                end
                if not dir then return end

                local rel = part0.CFrame:VectorToObjectSpace(dir)
                local look = rel
                if look.Magnitude < 0.001 then look = Vector3.new(0, 0, -1) end
                look = look.Unit
                local pitch = math.asin(math.clamp(look.Y, -0.9, 0.9))
                local flat = Vector3.new(look.X, 0, look.Z)
                if flat.Magnitude < 0.001 then flat = Vector3.new(0, 0, -1) end
                local wanted = flat.Unit * math.cos(pitch) + Vector3.new(0, math.sin(pitch), 0)
                local rot = CFrame.lookAt(Vector3.zero, wanted.Unit)
                pcall(function()
                    d.headMotor.C0 = (d.restC0 or d.origC0) * rot
                end)
            end)

            return true, "Head tracker ON"
        end

        htEnableBtn.MouseButton1Click:Connect(function()
            if HeadTracker.active then
                stopHeadTracker()
            else
                local ok, msg = startHeadTracker()
                if not ok then monoReanimSay("Head tracker: "..tostring(msg)) end
            end
            refreshHeadTrackerUI()
        end)

        htBindBtn.MouseButton1Click:Connect(function()
            if HeadTracker.capturing then
                HeadTracker.capturing = false
                refreshHeadTrackerUI()
                return
            end
            if HeadTracker.bind then
                HeadTracker.bind = nil
                refreshHeadTrackerUI()
                monoReanimSaveBody()
                return
            end
            HeadTracker.capturing = true
            htBindBtn.Text = "..."
            htBindBtn.TextColor3 = REAnimC.accent
        end)

        BodyArm.HeadTracker = HeadTracker
        BodyArm.stopHeadTracker = stopHeadTracker
        BodyArm.startHeadTracker = startHeadTracker
        BodyArm.refreshHeadTrackerUI = refreshHeadTrackerUI
        refreshHeadTrackerUI()

        end

