        alBindBtn.BackgroundColor3 = REAnimC.surface
        alBindBtn.BackgroundTransparency = 0.4
        alBindBtn.Text = "Arm Link: None"
        alBindBtn.TextColor3 = REAnimC.accent
        alBindBtn.Font = Enum.Font.GothamBold
