        alStyleBtn.Position = UDim2.new(1, -182, 0, 48)
        alStyleBtn.BackgroundColor3 = REAnimC.surface
        alStyleBtn.BackgroundTransparency = 0.4
        alStyleBtn.Text = "Style: Chain"
        alStyleBtn.TextColor3 = REAnimC.accent
        alStyleBtn.Font = Enum.Font.GothamBold
        alStyleBtn.TextSize = 10
        alStyleBtn.AutoButtonColor = false
        alStyleBtn.Parent = alCard
        corner(alStyleBtn, 7)
        stroke(alStyleBtn, REAnimC.borderSoft, 1, 0.55)

        local alHint = Instance.new("TextLabel")
        alHint.Size = UDim2.new(1, -24, 0, 56)
        alHint.Position = UDim2.new(0, 12, 0, 116)
        alHint.BackgroundTransparency = 1
        alHint.Text = "Pick which arm is used first. One Arm links two parts (A-B). Two Arms uses Style: Chain for A-B, B-C (3 parts) or Style: Separate for A-B, C-D (4 parts). Two Arms allows picking the same part twice. Press again to restore."
        alHint.TextColor3 = REAnimC.textDim
        alHint.Font = Enum.Font.Gotham
        alHint.TextSize = 9
        alHint.TextWrapped = true
        alHint.TextXAlignment = Enum.TextXAlignment.Left
        alHint.TextYAlignment = Enum.TextYAlignment.Top
        alHint.Parent = alCard

        local ArmLink = {
            mode = "One Arm",
            side = "Right",
            style = "Chain",
            bind = nil,
            capturing = false,
            active = false,
            targets = {},
            data = {},
            connection = nil,
        }

        local function armLinkNeeded()
            if ArmLink.mode ~= "Two Arms" then return 2 end
            return ArmLink.style == "Separate" and 4 or 3
        end

        local function refreshArmLinkUI()
            alModeBtn.Text = "Mode: "..ArmLink.mode
            alSideBtn.Text = "First Arm: "..ArmLink.side
            alStatus.Text = "Targets: "..tostring(#ArmLink.targets).." / "..tostring(armLinkNeeded())
            alStyleBtn.Text = "Style: "..ArmLink.style
            alBindBtn.Text = monoReanimBindLabel("Arm Link", ArmLink.bind)
            alBindBtn.TextColor3 = REAnimC.accent
        end

        local function clearArmLink()
            if ArmLink.connection then
                ArmLink.connection:Disconnect()
                ArmLink.connection = nil
            end
            for _, d in ipairs(ArmLink.data) do
                pcall(function() restoreArmData(d) end)
            end
            ArmLink.data = {}
            ArmLink.targets = {}
            ArmLink.active = false
            if refreshArmLinkUI then refreshArmLinkUI() end
        end

        local function resolveArmLinkTargetCF(tgt)
            local tc = tgt and tgt.player and tgt.player.Character
            local part = tc and tc:FindFirstChild(tgt.partName, true)
            local cf = nil
            if part and part:IsA("BasePart") then
                if tgt.partName == "Head" then
                    local f = getFaceAttachment(part)
                    if f then cf = f.WorldCFrame end
                end
                if not cf then cf = part.CFrame end
            end
            if not cf then
                local head = tc and tc:FindFirstChild("Head")
                local f = getFaceAttachment(head)
                if f then cf = f.WorldCFrame
                elseif head then cf = head.CFrame end
            end
            return cf
        end

        local function applyArmLink()
            local model = getActiveCharacter()
            if not model then return false, "No character / clone" end
            local count = #ArmLink.targets
            if count < 2 then return false, "Need at least two targets" end
            local first = ArmLink.side
            local second = (first == "Right") and "Left" or "Right"
            local two = ArmLink.mode == "Two Arms"
            local separate = two and ArmLink.style == "Separate"
            local sides = two and { first, second } or { first }
            local built = {}
            for i = 1, #sides do
                local d = buildArmDataForChar(model, sides[i])
                if not d then
                    for _, b in ipairs(built) do pcall(function() restoreArmData(b) end) end
                    return false, "Failed to build "..sides[i].." arm"
                end
                if separate then
                    d.fromTarget = ArmLink.targets[(i - 1) * 2 + 1]
                    d.toTarget = ArmLink.targets[(i - 1) * 2 + 2]
                else
                    d.fromTarget = ArmLink.targets[i]
                    d.toTarget = ArmLink.targets[i + 1]
                end
                built[#built + 1] = d
            end
            ArmLink.data = built
            ArmLink.active = true

            ArmLink.connection = RunService.Heartbeat:Connect(function()
                if not ArmLink.active then return end
                for i, d in ipairs(ArmLink.data) do
                    if not (d.upper and d.upper.Parent and d.lower and d.lower.Parent and d.hand and d.hand.Parent) then
                        clearArmLink()
                        return
                    end
                    local fromTgt, toTgt = d.fromTarget, d.toTarget
                    if not (fromTgt and fromTgt.player and fromTgt.player.Parent)
                        or not (toTgt and toTgt.player and toTgt.player.Parent) then
                        if #ArmLink.data > 1 then
                            pcall(function() restoreArmData(d) end)
                            table.remove(ArmLink.data, i)
                            local kept = {}
                            for _, rec in ipairs(ArmLink.data) do
                                local hasFrom, hasTo = false, false
                                for _, t in ipairs(kept) do
                                    if t == rec.fromTarget then hasFrom = true end
                                    if t == rec.toTarget then hasTo = true end
                                end
                                if not hasFrom then kept[#kept + 1] = rec.fromTarget end
                                if not hasTo then kept[#kept + 1] = rec.toTarget end
                            end
                            ArmLink.targets = kept
                            refreshArmLinkUI()
                            return
                        end
                        clearArmLink()
                        return
                    end
                    local fromCF = resolveArmLinkTargetCF(fromTgt)
                    local toCF = resolveArmLinkTargetCF(toTgt)
                    if not fromCF or not toCF then continue end
                    local origin = fromCF.Position
                    local handPos = toCF.Position
                    local toTarget = handPos - origin
                    local dist = toTarget.Magnitude
                    if dist > 0.05 then
                        local dirUnit = toTarget.Unit
                        updateStretchArm(d, origin, dirUnit, math.min(dist, 3000))
                        if d.lower and d.lower.Parent then
                            d.lower.CFrame = d.lower.CFrame * CFrame.new(0, -(d.lower.Size.Y * 0.5), 0)
                        end
                    end
                end
            end)
            return true
        end

        local function toggleArmLinkAtCursor()
            if ArmLink.active then
                clearArmLink()
                return
            end
            local target = BodyArm.getCursorTargetInfoT and BodyArm.getCursorTargetInfoT()
            if not target then
                if #ArmLink.targets > 0 then
                    ArmLink.targets = {}
                    refreshArmLinkUI()
                    monoReanimSay("Arm link: selection cleared", 2)
                else
                    monoReanimSay("Arm link: put cursor over a player's limb")
                end
                return
            end
            if not (api and api.is_reanimated and api.is_reanimated()) then
                monoReanimSay("Arm link: enable Reanim first")
                return
            end
            if ArmLink.mode == "One Arm" then
                for _, t in ipairs(ArmLink.targets) do
                    if t.player == target.player and t.partName == target.partName then
                        monoReanimSay("Arm link: that part is already selected")
                        return
                    end
                end
            end
            ArmLink.targets[#ArmLink.targets + 1] = target
            refreshArmLinkUI()
            if #ArmLink.targets >= armLinkNeeded() then
                local ok, msg = applyArmLink()
                if not ok then
                    monoReanimSay("Arm link: "..tostring(msg))
                    ArmLink.targets = {}
                    refreshArmLinkUI()
                else
                    monoReanimSay("Arm link ON", 3)
                end
            else
                monoReanimSay("Arm link: selected "..tostring(target.player.DisplayName).." ("..tostring(target.partName)..") "..tostring(#ArmLink.targets).."/"..tostring(armLinkNeeded()), 3)
            end
        end

        alModeBtn.MouseButton1Click:Connect(function()
            clearArmLink()
            ArmLink.mode = (ArmLink.mode == "One Arm") and "Two Arms" or "One Arm"
            refreshArmLinkUI()
            monoReanimSaveBody()
        end)

        alSideBtn.MouseButton1Click:Connect(function()
            clearArmLink()
            ArmLink.side = (ArmLink.side == "Right") and "Left" or "Right"
            refreshArmLinkUI()
            monoReanimSaveBody()
        end)

        alStyleBtn.MouseButton1Click:Connect(function()
            clearArmLink()
            ArmLink.style = ArmLink.style == "Chain" and "Separate" or "Chain"
            refreshArmLinkUI()
            monoReanimSaveBody()
            monoReanimSay("Arm link style: "..ArmLink.style, 2)
        end)

        alBindBtn.MouseButton1Click:Connect(function()
            if ArmLink.capturing then
                ArmLink.capturing = false
                refreshArmLinkUI()
                return
            end
            if ArmLink.bind then
                ArmLink.bind = nil
                refreshArmLinkUI()
                monoReanimSaveBody()
                return
            end
            ArmLink.capturing = true
            alBindBtn.Text = "..."
            alBindBtn.TextColor3 = REAnimC.accent
        end)

        BodyArm.ArmLink = ArmLink
        BodyArm.clearArmLink = clearArmLink
        BodyArm.toggleArmLinkAtCursor = toggleArmLinkAtCursor
        BodyArm.refreshArmLinkUI = refreshArmLinkUI
        refreshArmLinkUI()

    end

