        local function headCtrlSpeedFromInput(input)
            local rel = math.clamp(input.Position.X - hcTrack.AbsolutePosition.X, 0, hcTrack.AbsoluteSize.X)
            local pct = rel / hcTrack.AbsoluteSize.X
            monoFreeCamSpeed(monoFreeCamMin + pct * (monoFreeCamMax - monoFreeCamMin))
        end
        local hcDraggingSpeed = false
        local hcSpeedLastClick = 0
        hcTrack.InputBegan:Connect(function(input)
            if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then return end
            local now = tick()
            if now - hcSpeedLastClick < 0.3 then
                hcSpeedLastClick = 0
                hcDraggingSpeed = false
                monoFreeCamSpeed(monoFreeCamReset)
                return
            end
            hcSpeedLastClick = now
            hcDraggingSpeed = true
            headCtrlSpeedFromInput(input)
        end)
        table.insert(monoReanimBuildConns, UserInputService.InputEnded:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                hcDraggingSpeed = false
            end
        end))
        table.insert(monoReanimBuildConns, UserInputService.InputChanged:Connect(function(input)
            if hcDraggingSpeed and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
                headCtrlSpeedFromInput(input)
            end
        end))

