        local function headCtrlHideParts()
            local found = {}
            local seen = {}
            local realChar = api and api.get_real_character and api.get_real_character()
            local chars = {}
            if realChar then chars[#chars + 1] = realChar end
            local plrChar = player and player.Character
            local already = false
            for _, c in ipairs(chars) do if c == plrChar then already = true end end
            if plrChar and not already then chars[#chars + 1] = plrChar end
            for _, ch in ipairs(chars) do
                local head = ch:FindFirstChild("Head")
                if head and head:IsA("BasePart") and not seen[head] then
                    seen[head] = true
                    found[#found + 1] = { part = head, orig = head.LocalTransparencyModifier }
                end
                for _, desc in ipairs(ch:GetDescendants()) do
                    if desc:IsA("Accessory") then
                        local handle = desc:FindFirstChild("Handle")
                        if handle and handle:IsA("BasePart") and not seen[handle] then
                            seen[handle] = true
                            found[#found + 1] = { part = handle, orig = handle.LocalTransparencyModifier }
                        end
                    end
                end
            end
            return found
        end

        monoHeadCtrlStop = function()
            if not HeadController.active then return end
            monoFreeCamStop()
            if HeadController.data then
                local d = HeadController.data
                if d.hideConn then
                    pcall(function() d.hideConn:Disconnect() end)
                    d.hideConn = nil
                end
                for _, rec in ipairs(d.hideParts or {}) do
                    pcall(function()
                        if rec.part and rec.part.Parent then
                            rec.part.LocalTransparencyModifier = rec.orig or 0
                        end
                    end)
                end
                pcall(function()
                    if d.headMotor and d.headMotor.Parent then d.headMotor.Enabled = d.origEnabled end
                    if d.head and d.head.Parent then d.head.Anchored = d.origAnchored end
                end)
                HeadController.data = nil
            end
            HeadController.active = false
            monoHeadCtrlActive = false
            if refreshHeadControllerUI then refreshHeadControllerUI() end
        end

        local function monoHeadCtrlStart()
            if not (api and api.is_reanimated and api.is_reanimated()) then
                return false, "Enable Reanim first"
            end
            if HeadController.active then return true end
            local model = getActiveCharacter()
            if not model then return false, "No character / clone" end
            local head = model:FindFirstChild("Head")
            local headMotor = findHeadMotor(model)
            if not head or not headMotor then return false, "Could not find head joint" end

            if monoFreeCam.running then monoFreeCamStop() end
            local origEnabled = headMotor.Enabled
            local origAnchored = head.Anchored
            headMotor.Enabled = false
            head.Anchored = true

            local hideParts = headCtrlHideParts()
            local conn = RunService.RenderStepped:Connect(function()
                for _, rec in ipairs(hideParts) do
                    pcall(function()
                        if rec.part and rec.part.Parent then rec.part.LocalTransparencyModifier = 1 end
                    end)
                end
            end)
            for _, rec in ipairs(hideParts) do
                pcall(function()
                    if rec.part and rec.part.Parent then rec.part.LocalTransparencyModifier = 1 end
                end)
            end

            HeadController.data = {
                head = head,
                headMotor = headMotor,
                origEnabled = origEnabled,
                origAnchored = origAnchored,
                hideParts = hideParts,
                hideConn = conn,
            }
            HeadController.active = true
            monoHeadCtrlActive = true
            monoFreeCam.headData = { head = head, dist = 12 }
            monoFreeCamStart(true, head.CFrame)
            return true
        end

        local function monoHeadCtrlToggle()
            if HeadController.active then
                monoHeadCtrlStop()
            else
                local ok, msg = monoHeadCtrlStart()
                if not ok then monoReanimSay("Head controller: "..tostring(msg)) end
            end
        end

        hcEnableBtn.MouseButton1Click:Connect(function()
            monoHeadCtrlToggle()
            refreshHeadControllerUI()
        end)

        hcBindBtn.MouseButton1Click:Connect(function()
