                monoReanimSaveBody()
                return
            end
            HeadController.capturing = true
            hcBindBtn.Text = "..."
            hcBindBtn.TextColor3 = REAnimC.accent
        end)

        BodyArm.HeadController = HeadController
        BodyArm.stopHeadController = monoHeadCtrlStop
        BodyArm.startHeadController = monoHeadCtrlStart
        BodyArm.refreshHeadControllerUI = refreshHeadControllerUI
        refreshHeadControllerUI()

        end

