        local function poleUnarm(i)
            local b = poleBtns[i]
            if b and b.Parent then b.TextColor3 = REAnimC.accent end
        end

        local function poleCancel()
            local i = poleArmedIdx
            poleArmedIdx = nil
            if i then poleUnarm(i) end
        end

        local function poleSpot()
            local cam = workspace.CurrentCamera
            if not cam then return nil end
            local ml = UserInputService:GetMouseLocation()
            local ray = cam:ViewportPointToRay(ml.X, ml.Y)
            local hit = workspace:Raycast(ray.Origin, ray.Direction * 2000)
            local pt = hit and hit.Position or (ray.Origin + ray.Direction * 25)
            local look = cam.CFrame.LookVector
            local flat = Vector3.new(look.X, 0, look.Z)
            if flat.Magnitude > 0.01 then
                return CFrame.lookAt(pt, pt + flat)
            end
            return CFrame.new(pt)
        end

        local function poleDoPlace(i)
            if not api.is_reanimated() then
                notify("Reanim", "Pole: enable Reanim first", 3)
                poleUnarm(i)
                return
            end
            local spot = poleSpot()
            if not spot then
                notify("Reanim", "Pole: no camera", 3)
                poleUnarm(i)
                return
            end
            local ok, err = monoReanimPolePlace(spot, poleNames[i], poleLen)
            if not ok then
                notify("Reanim", "Pole: " .. tostring(err), 4)
                poleUnarm(i)
                return
            end
            poleArmedIdx = nil
            local b = poleBtns[i]
            if b and b.Parent then b.TextColor3 = REAnimC.accent end
        end

        for i = 1, 4 do
            local b = Instance.new("TextButton")
            local col = (i - 1) % 2
            local row = math.floor((i - 1) / 2)
            b.Size = UDim2.new(0, 168, 0, 26)
            b.Position = col == 0 and UDim2.new(0, 12, 0, 12 + row * 32)
                or UDim2.new(1, -182, 0, 12 + row * 32)
            b.BackgroundColor3 = REAnimC.surface
            b.BackgroundTransparency = 0.4
            b.Text = poleLabels[i] .. " Pole"
            b.TextColor3 = REAnimC.accent
            b.Font = Enum.Font.GothamBold
            b.TextSize = 10
            b.AutoButtonColor = false
            b.Parent = poleCard
            corner(b, 7)
            stroke(b, REAnimC.borderSoft, 1, 0.55)
            poleBtns[i] = b
            b.MouseButton1Click:Connect(function()
                if poleArmedIdx == i then
                    poleCancel()
                    return
                end
                if poleArmedIdx then poleUnarm(poleArmedIdx) end
                poleArmedIdx = i
                poleArmedAt = os.clock()
                b.TextColor3 = REAnimC.accent
                notify("Reanim", "Click in the world to place the " .. poleLabels[i] .. " pole", 5)
            end)
        end

