        local function poleRefreshSlider()
            local pct = math.clamp((poleLen - POLE_MIN) / (POLE_MAX - POLE_MIN), 0, 1)
            poleHeightLabel.Text = "HEIGHT: " .. tostring(poleLen)
            poleFill.Size = UDim2.new(pct, 0, 1, 0)
            poleKnob.Position = UDim2.new(pct, 0, 0.5, 0)
        end
        poleRefreshSlider()

        local function poleSetHeight(v)
            poleLen = math.clamp(math.floor(v + 0.5), POLE_MIN, POLE_MAX)
            poleRefreshSlider()
            for _, name in ipairs(poleNames) do
                if monoReanim.poles.list[name] then
                    local e = monoReanim.poles.list[name]
                    local base = e.base
                    monoPoleRelease(name)
                    monoReanimPolePlace(base, name, poleLen)
                end
            end
        end

        local poleDragging = false
        local poleLastClick = 0
        poleTrack.InputBegan:Connect(function(input)
            if input.UserInputType ~= Enum.UserInputType.MouseButton1
            and input.UserInputType ~= Enum.UserInputType.Touch then return end
            local now = tick()
            if now - poleLastClick < 0.3 then
                poleLastClick = 0
                poleDragging = false
                poleSetHeight(POLE_DEFAULT)
                return
            end
            poleLastClick = now
            poleDragging = true
            local w = math.max(1, poleTrack.AbsoluteSize.X)
            local rel = math.clamp(input.Position.X - poleTrack.AbsolutePosition.X, 0, w)
            poleSetHeight(POLE_MIN + (rel / w) * (POLE_MAX - POLE_MIN))
        end)
        table.insert(monoReanimBuildConns, UserInputService.InputChanged:Connect(function(input)
            if not poleDragging then return end
            if input.UserInputType ~= Enum.UserInputType.MouseMovement
            and input.UserInputType ~= Enum.UserInputType.Touch then return end
            local w = math.max(1, poleTrack.AbsoluteSize.X)
            local rel = math.clamp(input.Position.X - poleTrack.AbsolutePosition.X, 0, w)
            poleSetHeight(POLE_MIN + (rel / w) * (POLE_MAX - POLE_MIN))
        end))
        table.insert(monoReanimBuildConns, UserInputService.InputEnded:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
                poleDragging = false
            end
        end))

        table.insert(monoReanimBuildConns, UserInputService.InputBegan:Connect(function(input)
            if not poleArmedIdx then return end
            if input.UserInputType ~= Enum.UserInputType.MouseButton1
            and input.UserInputType ~= Enum.UserInputType.Touch then return end
            if UserInputService:GetFocusedTextBox() then return end
            if os.clock() - poleArmedAt < 0.25 then return end
            local idx = poleArmedIdx
            poleArmedIdx = nil
            task.defer(poleDoPlace, idx)
        end))

