        key.MouseButton1Click:Connect(function()
            local anim = row.anim
            if not anim then return end
            if monoBindCapturing then
                monoBindEndCapture()
                savedConfig.binds[anim.name] = nil
                reanimSaveConfig()
                key.Text = monoCmdBindShort(nil)
                key.TextColor3 = bindDim
                markListDirty()
                return
            end
            key.Text = "..."
            key.TextColor3 = bindAccent
            monoBindCapture(function(input)
                savedConfig.binds[anim.name] = input.KeyCode.Name
                reanimSaveConfig()
                key.Text = monoCmdBindShort(input.KeyCode.Name)
                key.TextColor3 = bindAccent
                markListDirty()
                notify("Monochrome", anim.name .. " bound to " .. input.KeyCode.Name, 2)
            end, function()
                local k = savedConfig.binds[anim.name]
                key.Text = monoCmdBindShort(k)
                key.TextColor3 = k and bindAccent or bindDim
            end)
        end)

        del.MouseButton1Click:Connect(function()
            local anim = row.anim
            if not anim then return end
            for i, a in ipairs(animations) do
                if a.name == anim.name then table.remove(animations, i); break end
            end
            monoReanimCustomDelete(anim.name)
            savedConfig.favs[anim.name] = nil
            savedConfig.binds[anim.name] = nil
            removeFromFavOrder(anim.name)
            reanimSaveConfig()
            markListDirty()
            queueListRefresh()
        end)

        grip.MouseButton1Down:Connect(function()
            if currentTab ~= "Favs" then return end
            local anim = row.anim
            if not anim then return end
            local idx = table.find(savedConfig.favOrder, anim.name)
            if not idx then return end
            dragState = { animName = anim.name, index = idx }
            frame.BackgroundColor3 = REAnimC.surfaceActive
            frame.BackgroundTransparency = 0.15
            rowStroke.Color = REAnimC.accent
            rowStroke.Transparency = 0.15
        end)

        return row
    end

    local BATCH_SIZE = 20
    local isLoading = false
    local loadedCount = 0

    markListDirty = function() listDirty = true end

    local function computeDisplayList()
        local key = currentTab .. "|" .. searchBox.Text .. "|" .. tostring(#animations) .. "|" .. tostring(#savedConfig.favOrder)
        if not listDirty and displayCacheKey == key and displayCache then
            return displayCache
        end
        local term = searchBox.Text:lower()
        local out = {}
        for _, a in ipairs(animations) do
            local custom = isCustomAnim(a)
            if currentTab == "Favs" then
                if savedConfig.favs[a.name] and (term == "" or a.name:lower():find(term,1,true)) then
                    table.insert(out, a)
                end
            elseif currentTab == "Custom" then
                if custom and (term == "" or a.name:lower():find(term,1,true)) then
                    table.insert(out, a)
                end
            else
                if term == "" or a.name:lower():find(term,1,true) then
                    table.insert(out, a)
                end
            end
        end

        if currentTab == "Favs" then
            local posMap = {}
            for idx, name in ipairs(savedConfig.favOrder) do
                posMap[name] = idx
            end
            table.sort(out, function(a, b)
                local pa = posMap[a.name] or math.huge
                local pb = posMap[b.name] or math.huge
                if pa ~= pb then return pa < pb end
                return a.name:lower() < b.name:lower()
            end)
        else
            table.sort(out, function(a, b) return a.name:lower() < b.name:lower() end)
        end

        displayCache = out
        displayCacheKey = key
        listDirty = false
        return out
    end

    local function styleRow(row, anim, i, isFavsTab, leftPad)
        row.anim = anim
        row.Frame.LayoutOrder = i

        local isPlaying = (activeOutlineAnim == anim.name)
        local isDragged = dragState and dragState.animName == anim.name

        if isDragged or isPlaying then
            row.Frame.BackgroundColor3 = REAnimC.surfaceActive
            row.Frame.BackgroundTransparency = 0.15
            row.Stroke.Color = REAnimC.borderSoft
            row.Stroke.Transparency = 0.55
        else
            row.Frame.BackgroundColor3 = REAnimC.surface
            row.Frame.BackgroundTransparency = 0.4
            row.Stroke.Color = REAnimC.borderSoft
            row.Stroke.Transparency = 0.55
        end
        row.AccentBar.Visible = isPlaying or isDragged

        local isFav = savedConfig.favs[anim.name]
        row.Star.Text = isFav and monoReanimGlyphs.starOn or monoReanimGlyphs.starOff
        row.Star.TextColor3 = isFav and REAnimC.accent or REAnimC.textMuted

        local custom = isCustomAnim(anim)
        if custom then
            row.Play.Text = anim.name .. " <font color=\"rgb(150,154,164)\">[CUSTOM]</font>"
        else
            row.Play.Text = anim.name
        end
        row.Play.Size = UDim2.new(1, -((custom and 124 or 94) + leftPad), 1, 0)
        row.Key.Visible = true
        row.Del.Visible = custom
        row.Play.TextColor3 = isPlaying and REAnimC.accent or REAnimC.text
        row.Play.Font = isPlaying and Enum.Font.GothamBold or Enum.Font.Gotham

        local boundKey = savedConfig.binds[anim.name]
        row.Key.Text = monoCmdBindShort(boundKey)
        row.Key.TextColor3 = boundKey and bindAccent or bindDim

        activeRows[i] = row
    end

    local function buildRowAt(i, displayList)
        local anim = displayList[i]
        if not anim then return end
        local row = activeRows[i]
        if not row then row = buildRow() end
        local isFavsTab = (currentTab == "Favs")
        local leftPad = isFavsTab and 26 or 12
        row.Grip.Visible = isFavsTab
        row.Play.Position = UDim2.new(0, leftPad, 0, 0)
        styleRow(row, anim, i, isFavsTab, leftPad)
    end

    local function updateCanvasSize()
        local wantY = loadedCount * (ROW_HEIGHT + 5) + 8
        if scrollList.CanvasSize.Y.Offset ~= wantY then
            scrollList.CanvasSize = UDim2.new(0, 0, 0, wantY)
        end
    end

    local function loadBatch(startIdx, count)
        if isLoading then return end
        isLoading = true
        local displayList = displayCache or {}
        local total = #displayList
        local endIdx = math.min(startIdx + count - 1, total)
        for i = startIdx, endIdx do
            buildRowAt(i, displayList)
        end
        if endIdx > loadedCount then loadedCount = endIdx end
        updateCanvasSize()
        isLoading = false
    end

    local function checkLoadMore()
        local total = displayCache and #displayCache or 0
        if loadedCount >= total then return end
        local buffer = (ROW_HEIGHT + 5) * BATCH_SIZE
        if scrollList.CanvasPosition.Y + scrollList.AbsoluteWindowSize.Y + buffer >= scrollList.CanvasSize.Y.Offset - 1 then
            loadBatch(loadedCount + 1, BATCH_SIZE)
        end
    end

    function populateList()
        local displayList = computeDisplayList()
        local total = #displayList

        for idx, row in pairs(activeRows) do
            if idx > total then
                if row.Frame then pcall(function() row.Frame:Destroy() end) end
                activeRows[idx] = nil
            end
        end
        if loadedCount > total then loadedCount = total end

        if currentTab == "Favs" then
            emptyFavsLabel.Visible = (total == 0)
            emptyCustomLabel.Visible = false
        elseif currentTab == "Custom" then
            emptyFavsLabel.Visible = false
            emptyCustomLabel.Visible = (total == 0)
        else
            emptyFavsLabel.Visible = false
            emptyCustomLabel.Visible = false
        end

        local winH = scrollList.AbsoluteWindowSize.Y
        if winH < 40 then winH = 460 end
        local needed = math.ceil((scrollList.CanvasPosition.Y + winH) / (ROW_HEIGHT + 5)) + 5
        if needed > total then needed = total end
        if needed > loadedCount then loadedCount = needed end
        for i = 1, needed do
            buildRowAt(i, displayList)
        end
        updateCanvasSize()
    end

    local listRefreshToken = 0
    queueListRefresh = function()
        listRefreshToken = listRefreshToken + 1
        local myToken = listRefreshToken
        task.defer(function()
            if myToken ~= listRefreshToken then return end
            if not scrollList.Parent then return end
            populateList()
        end)
    end

    table.insert(monoReanimBuildConns, RunService.Heartbeat:Connect(function()
        if monoReanimResizing then return end
        if not (monoReanimWin and monoReanimWin.Visible) then return end
        if not listPanel.Visible then return end
        if not scrollList.Parent then return end
        checkLoadMore()
    end))

    table.insert(monoReanimBuildConns, UserInputService.InputChanged:Connect(function(input)
        if not dragState then return end
        if input.UserInputType ~= Enum.UserInputType.MouseMovement
            and input.UserInputType ~= Enum.UserInputType.Touch then return end

        local pointerY = input.Position.Y
        local relY = pointerY - scrollList.AbsolutePosition.Y + scrollList.CanvasPosition.Y
        local total = #savedConfig.favOrder
        if total == 0 then return end

        local newIndex = math.clamp(math.floor(relY / (ROW_HEIGHT + 5)) + 1, 1, total)

        if newIndex ~= dragState.index then
            table.remove(savedConfig.favOrder, dragState.index)
            table.insert(savedConfig.favOrder, newIndex, dragState.animName)
            dragState.index = newIndex
            markListDirty()
            populateList()
        end
    end))

    table.insert(monoReanimBuildConns, UserInputService.InputEnded:Connect(function(input)
        if not dragState then return end
        if input.UserInputType ~= Enum.UserInputType.MouseButton1
            and input.UserInputType ~= Enum.UserInputType.Touch then return end
        dragState = nil
        reanimSaveConfig()
        markListDirty()
        populateList()
    end))

    local searchToken = 0
    local function queueSearch()
        searchToken = searchToken + 1
        local myToken = searchToken
        task.delay(0.08, function()
            if myToken == searchToken then
                markListDirty()
                populateList()
            end
        end)
    end
    searchBox:GetPropertyChangedSignal("Text"):Connect(queueSearch)

    local function populateBindsList()
        for _, child in ipairs(bindsPanel:GetChildren()) do
            if child:IsA("Frame") then child:Destroy() end
        end
        local boundItems = {}
        for animName, keyName in pairs(savedConfig.binds) do
            local path
            for _, a in ipairs(animations) do
                if a.name == animName then path = a.path; break end
            end
            if path then table.insert(boundItems, { name = animName, path = path, key = keyName }) end
        end
        table.sort(boundItems, function(a,b) return a.name:lower() < b.name:lower() end)
        emptyBindsLabel.Visible = (#boundItems == 0)
        for i, item in ipairs(boundItems) do
            local row = Instance.new("Frame")
            row.Size = UDim2.new(1, -6, 0, 38)
            row.BackgroundColor3 = REAnimC.surface
            row.BackgroundTransparency = 0.4
            row.BorderSizePixel = 0
            row.LayoutOrder = i+1
            row.Parent = bindsPanel
            corner(row, 8)
            stroke(row, REAnimC.borderSoft, 1, 0.55)

            local playBtn = Instance.new("TextButton")
            playBtn.Size = UDim2.new(1, -124, 1, 0)
            playBtn.Position = UDim2.new(0, 14, 0, 0)
            playBtn.BackgroundTransparency = 1
            playBtn.Text = item.name
            playBtn.TextColor3 = REAnimC.text
            playBtn.Font = Enum.Font.Gotham
            playBtn.TextSize = 11
            playBtn.TextXAlignment = Enum.TextXAlignment.Left
            playBtn.TextTruncate = Enum.TextTruncate.AtEnd
            playBtn.AutoButtonColor = false
            playBtn.Parent = row
            playBtn.MouseButton1Click:Connect(function()
                for _, a in ipairs(animations) do if a.name == item.name then playSelectedAnimation(a); break end end
            end)

            local keyBtn = Instance.new("TextButton")
            keyBtn.Size = UDim2.new(0, 48, 0, 24)
            keyBtn.Position = UDim2.new(1, -104, 0.5, -12)
            keyBtn.BackgroundColor3 = bindInput
            keyBtn.Text = monoCmdBindShort(item.key)
            keyBtn.TextColor3 = bindAccent
            keyBtn.Font = Enum.Font.GothamBold
            keyBtn.TextSize = 9
            keyBtn.AutoButtonColor = false
            keyBtn.TextTruncate = Enum.TextTruncate.AtEnd
            keyBtn.ClipsDescendants = true
            keyBtn.Parent = row
            corner(keyBtn, 7)
            stroke(keyBtn, bindStroke, 1, 0.55)
            keyBtn.MouseButton1Click:Connect(function()
                if monoBindCapturing then
                    monoBindEndCapture()
                    savedConfig.binds[item.name] = nil
                    reanimSaveConfig()
                    keyBtn.Text = monoCmdBindShort(nil)
                    keyBtn.TextColor3 = bindDim
                    markListDirty()
                    return
                end
                keyBtn.Text = "..."
                keyBtn.TextColor3 = bindAccent
                monoBindCapture(function(input)
                    savedConfig.binds[item.name] = input.KeyCode.Name
                    reanimSaveConfig()
                    keyBtn.Text = monoCmdBindShort(input.KeyCode.Name)
                    keyBtn.TextColor3 = bindAccent
                    markListDirty()
                    notify("Monochrome", item.name .. " bound to " .. input.KeyCode.Name, 2)
                end, function()
                    local k = savedConfig.binds[item.name]
                    keyBtn.Text = monoCmdBindShort(k)
                    keyBtn.TextColor3 = k and bindAccent or bindDim
                end)
            end)

            local unbindBtn = Instance.new("TextButton")
            unbindBtn.Size = UDim2.new(0, 46, 0, 24)
            unbindBtn.Position = UDim2.new(1, -52, 0.5, -12)
            unbindBtn.BackgroundColor3 = REAnimC.surface
            unbindBtn.BackgroundTransparency = 0.4
            unbindBtn.Text = "Unbind"
            unbindBtn.TextColor3 = REAnimC.textMuted
            unbindBtn.Font = Enum.Font.Gotham
            unbindBtn.TextSize = 9
            unbindBtn.AutoButtonColor = false
            unbindBtn.Parent = row
            corner(unbindBtn, 7)
            unbindBtn.MouseButton1Click:Connect(function()
                savedConfig.binds[item.name] = nil
                reanimSaveConfig()
                markListDirty()
                populateBindsList()
            end)
        end
        bindsPanel.CanvasSize = UDim2.new(0,0,0, 26 + #boundItems * 44)
    end

    switchTab = function(tab)
        if dragState then
            dragState = nil
            reanimSaveConfig()
        end
        currentTab = tab
        for tName, data in pairs(tabButtons) do
            paintReanimTab(data.btn, tName == tab)
        end

        local isAnimList = (tab == "Reanims" or tab == "Favs" or tab == "Custom")
        listPanel.Visible = isAnimList
        bindsPanel.Visible = (tab == "Binds")
        speedPanel.Visible = (tab == "Speed")
        statesPanel.Visible = (tab == "States")
        limbsPanel.Visible = (tab == "Limbs")
        BodyArm.panel.Visible = (tab == "Body")

        if isAnimList then
            if tab == "Favs" then
                searchBox.PlaceholderText = "Search favorites..."
                addCustomBtn.Visible = false
                searchBox.Size = UDim2.new(1, 0, 0, 32)
            elseif tab == "Custom" then
                searchBox.PlaceholderText = "Search custom animations..."
                addCustomBtn.Visible = true
                searchBox.Size = UDim2.new(1, -100, 0, 32)
            else
                searchBox.PlaceholderText = "Search animations..."
                addCustomBtn.Visible = true
                searchBox.Size = UDim2.new(1, -100, 0, 32)
            end
            markListDirty()
            populateList()
        elseif tab == "Binds" then
            populateBindsList()
        elseif tab == "Limbs" then
            updateLimbsUI()
        end
    end

    local lastLogicalState = nil
    local pendingLogical = nil
    local pendingCount = 0
    local stateThrottle = 0
    table.insert(monoReanimBuildConns, RunService.Heartbeat:Connect(function()
        if not (api and api.is_reanimated and api.is_reanimated()) then return end
        if manualAnimationPlaying then return end
        if reanimStateRefresh then
            reanimStateRefresh = false
            lastLogicalState = nil
            pendingLogical = nil
            pendingCount = 0
        end
        if not (savedConfig.states and next(savedConfig.states)) then return end
        stateThrottle = stateThrottle + 1
        if stateThrottle % 2 ~= 0 then return end
        local char = player.Character
        if not char then return end
        local hum = char:FindFirstChildOfClass("Humanoid")
        local hrp = char:FindFirstChild("HumanoidRootPart")
        if not hum or not hrp then return end
        local hs = hum:GetState()
        local logical = "Idle"
        if hs == Enum.HumanoidStateType.Jumping then
            logical = "Jump"
        elseif hs == Enum.HumanoidStateType.Freefall then
            if hrp.AssemblyLinearVelocity.Y > 0.1 then logical = "Jump" else logical = "Fall" end
        else
            local horizSpeed = Vector2.new(hrp.AssemblyLinearVelocity.X, hrp.AssemblyLinearVelocity.Z).Magnitude

            if lastLogicalState == "Walk" then
                logical = (horizSpeed > 0.8) and "Walk" or "Idle"
            else
                logical = (horizSpeed > 2.0) and "Walk" or "Idle"
            end
        end
        if logical ~= lastLogicalState then

            if logical ~= pendingLogical then
                pendingLogical = logical
                pendingCount = 1
            else
                pendingCount = pendingCount + 1
            end
            if pendingCount < 3 then return end
            pendingLogical = nil
            pendingCount = 0
            lastLogicalState = logical
            local assigned = savedConfig.states[logical]
            local isPlaying, playingUrl = api.is_animation_playing()
            if assigned and assigned.path then
                if not (isPlaying and playingUrl == assigned.path) then
                    api.play_animation(assigned.path, currentSpeed)
                end
                updateNowPlayingUI("["..logical.."] "..assigned.name)
            else
                api.stop_animation(false, true)
                updateNowPlayingUI(nil)
            end
        else
            pendingLogical = nil
            pendingCount = 0
        end
    end))

    table.insert(monoReanimBuildConns, UserInputService.InputBegan:Connect(function(input, gpe)
        if input.UserInputType ~= Enum.UserInputType.Keyboard then return end

        if BodyArm.Catapult and BodyArm.Catapult.capturing then
            BodyArm.Catapult.bind = input.KeyCode
            BodyArm.Catapult.capturing = false
            refreshCatapultUI()
            monoReanimSaveBody()
            return
        end

        if BodyArm.FaceAttach and BodyArm.FaceAttach.capturing then
            BodyArm.FaceAttach.bind = input.KeyCode
            BodyArm.FaceAttach.capturing = false
            BodyArm.refreshFaceAttachUI()
            monoReanimSaveBody()
            return
        end

        if BodyArm.ArmStretch.capturing then
            BodyArm.ArmStretch.bind = input.KeyCode
            BodyArm.ArmStretch.capturing = false
            BodyArm.refreshArmStretchUI()
            monoReanimSaveBody()
            return
        end

        if BodyArm.LegStretch and BodyArm.LegStretch.capturing then
            BodyArm.LegStretch.bind = input.KeyCode
            BodyArm.LegStretch.capturing = false
            BodyArm.refreshLegStretchUI()
            monoReanimSaveBody()
            return
        end

        if BodyArm.LegAttach and BodyArm.LegAttach.capturing then
            BodyArm.LegAttach.bind = input.KeyCode
            BodyArm.LegAttach.capturing = false
            BodyArm.refreshLegAttachUI()
            monoReanimSaveBody()
            return
        end

        if BodyArm.TorsoHeight and BodyArm.TorsoHeight.capturing then
            BodyArm.TorsoHeight.bind = input.KeyCode
            BodyArm.TorsoHeight.capturing = false
            BodyArm.refreshTorsoHeightUI()
            monoReanimSaveBody()
            return
        end

        if BodyArm.HeadTracker and BodyArm.HeadTracker.capturing then
            BodyArm.HeadTracker.bind = input.KeyCode
            BodyArm.HeadTracker.capturing = false
            BodyArm.refreshHeadTrackerUI()
            monoReanimSaveBody()
            return
        end

        if BodyArm.ArmLink and BodyArm.ArmLink.capturing then
            BodyArm.ArmLink.bind = input.KeyCode
            BodyArm.ArmLink.capturing = false
            BodyArm.refreshArmLinkUI()
            monoReanimSaveBody()
            return
        end

        if BodyArm.LegLink and BodyArm.LegLink.capturing then
            BodyArm.LegLink.bind = input.KeyCode
            BodyArm.LegLink.capturing = false
            BodyArm.refreshLegLinkUI()
            monoReanimSaveBody()
            return
        end

        if BodyArm.HeadController and BodyArm.HeadController.capturing then
            BodyArm.HeadController.bind = input.KeyCode
            BodyArm.HeadController.capturing = false
            BodyArm.refreshHeadControllerUI()
            monoReanimSaveBody()
            return
        end

        if BodyArm.TorsoAim and BodyArm.TorsoAim.capturing then
            if BodyArm.TorsoAim.capturing == "stretch" then
                BodyArm.TorsoAim.stretchBind = input.KeyCode
            elseif BodyArm.TorsoAim.capturing == "follow" then
                BodyArm.TorsoAim.followBind = input.KeyCode
            elseif BodyArm.TorsoAim.capturing == "faceattach" then
                BodyArm.TorsoAim.faceAttachBind = input.KeyCode
            end
            BodyArm.TorsoAim.capturing = nil
            BodyArm.refreshTorsoAimUI()
            monoReanimSaveBody()
            return
        end

        if currentlyBindingSpeedHotkey then
            local kName = input.KeyCode.Name
            currentlyBindingSpeedHotkey.key = kName
            reanimSaveConfig()
            refreshSpeedHotkeyRows()
            currentlyBindingSpeedHotkey = nil
            return
        end
        if gpe then return end

        if BodyArm.Catapult and BodyArm.Catapult.bind and input.KeyCode == BodyArm.Catapult.bind then
            toggleCatapult()
            monoReanimSaveBody()
            return
        end

        if BodyArm.FaceAttach and input.KeyCode == BodyArm.FaceAttach.bind then
            BodyArm.toggleFaceAttachAtCursor()
            return
        end

        if BodyArm.LegAttach and input.KeyCode == BodyArm.LegAttach.bind then
            BodyArm.toggleLegAttachAtCursor()
            return
        end

        if BodyArm.LegStretch and input.KeyCode == BodyArm.LegStretch.bind then
            if BodyArm.LegStretch.active then
                BodyArm.stopLegStretch()
            else
                local ok, msg = BodyArm.startLegStretch()
                if not ok then monoReanimSay("Leg stretch: "..tostring(msg)) end
            end
            if BodyArm.refreshLegStretchUI then BodyArm.refreshLegStretchUI() end
            return
        end

        if BodyArm.TorsoHeight and input.KeyCode == BodyArm.TorsoHeight.bind then
            if BodyArm.TorsoHeight.active then
                BodyArm.stopTorsoHeight()
            else
                local ok = BodyArm.startTorsoHeight()
                if not ok then monoReanimSay("Torso height: enable Reanim first") end
            end
            if BodyArm.refreshTorsoHeightUI then BodyArm.refreshTorsoHeightUI() end
            return
        end

        if BodyArm.HeadTracker and input.KeyCode == BodyArm.HeadTracker.bind then
            if BodyArm.HeadTracker.active then
                BodyArm.stopHeadTracker()
            else
                local ok = BodyArm.startHeadTracker()
                if not ok then monoReanimSay("Head tracker: enable Reanim first") end
            end
            if BodyArm.refreshHeadTrackerUI then BodyArm.refreshHeadTrackerUI() end
            return
        end

        if BodyArm.ArmLink and input.KeyCode == BodyArm.ArmLink.bind then
            BodyArm.toggleArmLinkAtCursor()
            return
        end

        if BodyArm.LegLink and input.KeyCode == BodyArm.LegLink.bind then
            BodyArm.toggleLegLinkAtCursor()
            return
        end

        if BodyArm.HeadController and input.KeyCode == BodyArm.HeadController.bind then
            if BodyArm.HeadController.active then
                BodyArm.stopHeadController()
            else
                local ok, msg = BodyArm.startHeadController()
                if not ok then monoReanimSay("Head controller: "..tostring(msg)) end
            end
            if BodyArm.refreshHeadControllerUI then BodyArm.refreshHeadControllerUI() end
            return
        end

        if BodyArm.TorsoAim then
            if input.KeyCode == BodyArm.TorsoAim.stretchBind then
                if BodyArm.TorsoAim.active and BodyArm.TorsoAim.mode == "Stretch" then
                    BodyArm.stopTorsoAim()
                else
                    local ok = BodyArm.startTorsoAim("Stretch")
                    if not ok then monoReanimSay("Torso aim: enable Reanim first") end
                end
                BodyArm.refreshTorsoAimUI()
                monoReanimSaveBody()
                return
            elseif input.KeyCode == BodyArm.TorsoAim.followBind then
                if BodyArm.TorsoAim.active and BodyArm.TorsoAim.mode == "Follow" then
                    BodyArm.stopTorsoAim()
                else
                    local ok = BodyArm.startTorsoAim("Follow")
                    if not ok then monoReanimSay("Torso aim: enable Reanim first") end
                end
                BodyArm.refreshTorsoAimUI()
                monoReanimSaveBody()
                return
            elseif input.KeyCode == BodyArm.TorsoAim.faceAttachBind then

                if BodyArm.TorsoAim.active and BodyArm.TorsoAim.mode == "Attach" then
                    BodyArm.stopTorsoAim()
                else
                    local info = BodyArm.getCursorTargetInfoT and BodyArm.getCursorTargetInfoT()
                    if not info then
                        monoReanimSay("Torso attach: put cursor over a player's limb")
                    else
                        local ok, msg = BodyArm.startTorsoFaceAttach(info)
                        if not ok then monoReanimSay("Torso attach: "..tostring(msg)) end
                    end
                end
                BodyArm.refreshTorsoAimUI()
                monoReanimSaveBody()
                return
            end
        end

        if input.KeyCode == BodyArm.ArmStretch.bind then
            if BodyArm.ArmStretch.mode == "Toggle" then
                if BodyArm.ArmStretch.active then
                    BodyArm.stopArmStretch()
                    BodyArm.refreshArmStretchUI()
                else
                    local ok = BodyArm.startArmStretch()
                    BodyArm.refreshArmStretchUI()
                    if not ok then monoReanimSay("Arm stretch: enable Reanim first") end
                end
            else
                if not BodyArm.ArmStretch.active then
                    local ok = BodyArm.startArmStretch()
                    BodyArm.refreshArmStretchUI()
                    if not ok then monoReanimSay("Arm stretch: enable Reanim first") end
                end
            end
            return
        end

        for _, hk in ipairs(savedConfig.speedHotkeys or {}) do
            if hk.key and input.KeyCode.Name == hk.key then
                reanimApplySpeed(hk.speed or 1)
                return
            end
        end
        for animName, kName in pairs(savedConfig.binds) do
            if input.KeyCode.Name == kName then
                for _, a in ipairs(animations) do
                    if a.name == animName then
                        playSelectedAnimation(a)
                        queueListRefresh()
                        return
                    end
                end
            end
        end
    end))

    table.insert(monoReanimBuildConns, UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType ~= Enum.UserInputType.Keyboard then return end
        if BodyArm.ArmStretch.mode == "Hold" and input.KeyCode == BodyArm.ArmStretch.bind then
            if BodyArm.ArmStretch.active then
                BodyArm.stopArmStretch()
                BodyArm.refreshArmStretchUI()
            end
        end
        if BodyArm.LegStretch and BodyArm.LegStretch.mode == "Hold" and input.KeyCode == BodyArm.LegStretch.bind then
            if BodyArm.LegStretch.active then
                BodyArm.stopLegStretch()
                BodyArm.refreshLegStretchUI()
            end
        end
    end))

    local function updateReanimButtonState()
        local isReanimated = api.is_reanimated()
        toggleBtn.Text = isReanimated and "Disable Reanim" or "Enable Reanim"
        toggleBtn.TextColor3 = isReanimated and REAnimC.accent or REAnimC.text
        toggleBtn.BackgroundColor3 = REAnimC.surface
        toggleBtn.BackgroundTransparency = 0.4
        toggleStroke.Color = REAnimC.borderSoft
        toggleStroke.Transparency = 0.55
    end

    local reanimToggleBusy = false
    local reanimToggleGen = 0
    local reanimEverEnabled = api.is_reanimated() == true
    toggleBtn.MouseButton1Click:Connect(function()
        if reanimToggleBusy then return end
        reanimToggleBusy = true
        reanimToggleGen = reanimToggleGen + 1
        local togGen = reanimToggleGen
        task.delay(3, function()
            if togGen == reanimToggleGen then reanimToggleBusy = false end
        end)
        local newState = not api.is_reanimated()
        monoRsLastIgnoreNext = true
        toggleBtn.Text = newState and "Reanimating..." or "Disabling..."
        toggleBtn.TextColor3 = REAnimC.textMuted
        BodyArm.stopArmStretch()
        BodyArm.refreshArmStretchUI()
        if BodyArm.stopFaceAttach then BodyArm.stopFaceAttach() end
        if BodyArm.stopLegStretch then BodyArm.stopLegStretch() end
        if BodyArm.stopLegAttach then BodyArm.stopLegAttach() end
        if BodyArm.stopTorsoAim then BodyArm.stopTorsoAim(); BodyArm.refreshTorsoAimUI() end
        if BodyArm.stopTorsoHeight then BodyArm.stopTorsoHeight() end
        if BodyArm.stopHeadTracker then BodyArm.stopHeadTracker() end
        if BodyArm.clearArmLink then BodyArm.clearArmLink() end
        if BodyArm.clearLegLink then BodyArm.clearLegLink() end
        if BodyArm.stopHeadController then BodyArm.stopHeadController() end
        task.spawn(function()
            if not (newState and not reanimEverEnabled) then
                task.wait(1)
            end
            if togGen ~= reanimToggleGen then return end
            if newState then reanimEverEnabled = true end
            local ok, result = pcall(function() return api.reanimate(newState) end)
            if not ok then
                warn("Monochrome reanimate failed:", result)
            elseif result and typeof(result) == "string" and result ~= "Already reanimated." then
                monoReanimSay("Reanimation: " .. result)
            end
            updateReanimButtonState()
            if type(monoRsLastHookReanim) == "function" then pcall(monoRsLastHookReanim) end
            if not newState then
                manualAnimationPlaying = false
                updateNowPlayingUI(nil)
            end
            task.wait(0.15)
            if togGen == reanimToggleGen then reanimToggleBusy = false end
            task.delay(0.5, function() monoRsLastIgnoreNext = false end)
        end)
    end)

    updateReanimButtonState()
    reanimApplySpeed(currentSpeed)

    markListDirty()
    populateList()
monoReanimWin = mainFrame
monoReanimGui = gui
if monoReanimEntry then
    monoReanimEntry.free = true
    local found = false
    for _, e in ipairs(monoPanelCols) do
        if e == monoReanimEntry then found = true end
    end
    if not found then table.insert(monoPanelCols, monoReanimEntry) end
end
monoReanimSyncToggle = updateReanimButtonState
monoReanimStopBody = function()
    BodyArm.stopArmStretch()
    BodyArm.refreshArmStretchUI()
    BodyArm.stopFaceAttach()
    BodyArm.stopLegStretch()
    BodyArm.stopLegAttach()
    BodyArm.stopTorsoAim()
    BodyArm.refreshTorsoAimUI()
    BodyArm.stopTorsoHeight()
    BodyArm.stopHeadTracker()
    BodyArm.clearArmLink()
    BodyArm.stopHeadController()
end
end

function monoReanimOpen()
    if not monoLoadDone then return end
    if not monoReanimBuilt then
        monoReanimEnsureCatalog()
        local okBuild, _errBuild = pcall(monoReanimBuildUI)
        if not okBuild then
            monoReanimBuilt = false
            monoReanimShutdown()
            return
        end
        monoReanimBuilt = true
    end
    if not monoReanimWin then return end
    if monoReanimGui then pcall(function() monoReanimGui.Enabled = monoPanelVisible and true or false end) end
    monoReanimWin.Visible = not monoReanimWin.Visible
    if monoReanimWin.Visible then
        clampFrameToScreen(monoReanimWin, 400, monoReanimHeight or 560)
    end
    if monoReanimWin.Visible and monoReanimSyncToggle then
        monoReanimSyncToggle()
    end
    if monoReanimEntry then
        monoPanelBgSync(monoReanimEntry)
    end
end

function monoReanimShutdown()
    if monoReanimDragDisconnect then
        pcall(monoReanimDragDisconnect)
        monoReanimDragDisconnect = nil
    end
    if monoReanimEntry then
        for i = #monoPanelCols, 1, -1 do
            if monoPanelCols[i] == monoReanimEntry then table.remove(monoPanelCols, i) end
        end
        if monoReanimEntry.frame then monoPanelLive[monoReanimEntry.frame] = nil end
        monoReanimEntry = nil
    end
    if monoReanimGui then
        pcall(function() monoReanimGui:Destroy() end)
    end
    monoReanimGui = nil
    monoReanimWin = nil
    monoReanimBuilt = false
    if monoReanimStopBody then
        pcall(monoReanimStopBody)
        monoReanimStopBody = nil
    end
    if monoReanimBuildConns then
        for _, Conn in ipairs(monoReanimBuildConns) do
            pcall(function() Conn:Disconnect() end)
        end
    end
    monoReanimBuildConns = nil
    monoReanimSyncToggle = nil
end

_G.MONO_REANIM = monoReanimAPI

registerMonoCommand("reanim", function(auto, args)
    if not monoLoadDone then return end
    monoReanimOpen()
end)

monoCmdOnDestroy("reanim", function()
    pcall(function()
        if monoReanimAPI.is_reanimated and monoReanimAPI.is_reanimated() then
            monoReanimAPI.reanimate(false)
        end
    end)
    monoReanimShutdown()
end)
function monoDoDestroy()
    Window:Destroy()
end

registerMonoCommand("destroy", function(auto, args)
    monoDoDestroy()
end)

