task.spawn(function()
    local tries = 0
    while tries < 100 do
        tries = tries + 1
        task.wait(0.1)
        if not sbListScroll.Parent then return end
        if sbPage.AbsoluteSize.Y > 50 then break end
    end
    if not sbListScroll.Parent then return end
    local rel = sbListScroll.AbsolutePosition.Y - sbPage.AbsolutePosition.Y
    local h = sbPage.AbsoluteSize.Y - rel
    if h > 60 then sbListScroll.Size = UDim2.new(1, 0, 0, math.floor(h)) end
end)

sbRender = function()
    for _, ch in ipairs(sbListScroll:GetChildren()) do
        if ch:IsA("TextButton") then ch:Destroy() end
    end
    local entries = {}
    for _, s in ipairs(sbData) do
        if not sbExcludeFull or (s.playing or 0) < (s.maxPlayers or 0) then
            table.insert(entries, s)
        end
    end
    if sbFilter == "lowping" then
        table.sort(entries, function(a, b) return (a.ping or math.huge) < (b.ping or math.huge) end)
    elseif sbFilter == "most" then
        table.sort(entries, function(a, b) return (a.playing or 0) > (b.playing or 0) end)
    else
        table.sort(entries, function(a, b) return (a.playing or 0) < (b.playing or 0) end)
    end
    for i = 1, math.min(#entries, 25) do
        local s = entries[i]
        local ping = s.ping or 0
        local pingC = ping < 50 and Color3.fromRGB(80, 220, 120)
            or ping < 150 and Color3.fromRGB(255, 200, 80)
            or Color3.fromRGB(255, 80, 80)
        local row = create("TextButton", {
            Size = UDim2.new(1, -6, 0, 32), BackgroundColor3 = C.surface,
            BackgroundTransparency = 0.4, BorderSizePixel = 0, Text = "", AutoButtonColor = false,
        }, sbListScroll)
        corner(row, 8); stroke(row, C.borderSoft, 1, 0.55)
        create("TextLabel", {
            Size = UDim2.new(0.5, 0, 1, 0), Position = UDim2.new(0, 12, 0, 0),
            BackgroundTransparency = 1, Text = "Ping: " .. ping .. "ms",
            TextColor3 = pingC, TextSize = 11, Font = Enum.Font.GothamBold,
            TextXAlignment = Enum.TextXAlignment.Left,
        }, row)
        create("TextLabel", {
            Size = UDim2.new(0.5, -12, 1, 0), Position = UDim2.new(0.5, 0, 0, 0),
            BackgroundTransparency = 1, Text = (s.playing or 0) .. "/" .. (s.maxPlayers or 0) .. " players",
            TextColor3 = C.text, TextSize = 11, Font = Enum.Font.Gotham,
            TextXAlignment = Enum.TextXAlignment.Right,
        }, row)
        row.MouseEnter:Connect(function() tween(row, { BackgroundTransparency = 0.15 }, 0.15) end)
        row.MouseLeave:Connect(function() tween(row, { BackgroundTransparency = 0.4 }, 0.15) end)
        row.MouseButton1Click:Connect(function()
            TeleportService:TeleportToPlaceInstance(game.PlaceId, s.id, LocalPlayer)
        end)
    end
end

