function sbFetch()
    if sbFetching or not sbAlive then return end
    sbFetching = true
    task.spawn(function()
        local ok, result = pcall(function()
            return HttpService:JSONDecode(game:HttpGet(
                "https://games.roblox.com/v1/games/" .. game.PlaceId .. "/servers/Public?sortOrder=Asc&limit=100", true))
        end)
        sbFetching = false
