miscDefaultTime = nil
miscSuppress = true
Misc:Section("Time")

function miscTimeLabel(v)
    local h = math.floor(v)
    local m = math.floor((v - h) * 100 + 0.5)
    if m > 99 then m = 99 end
    local h12 = h % 12
    if h12 == 0 then h12 = 12 end
    return string.format("%d:%02d", h12, m)
end

miscClock = Misc:Slider({
    Name = "Time of Day",
    Min = 0, Max = 24, Decimals = 2,
    Default = 12,
    Format = miscTimeLabel,
    Callback = function(v)
        if miscSuppress then return end
        miscLighting.ClockTime = math.clamp(v, 0, 24)
        miscData.clockTime = miscLighting.ClockTime
        miscSave()
    end,
    OnReset = function()
        miscData.clockTime = nil
        miscSave()
    end,
})
miscSuppress = false

miscRevealK = 0
miscRevealStarted = false
miscRevealActive = false
miscRevealFrom = nil
miscRevealTo = nil
MISC_REVEAL_DUR = 1.4

function miscLerp(a, b, k) return a + (b - a) * k end
function _miscEase(k) return k * k * (3 - 2 * k) end

function miscApplyAll()
    pcall(miscFXApply)
    pcall(miscSkyApply)
    pcall(miscCloudApply)
    pcall(miscFogApply)
    pcall(miscShadowApply)
    pcall(miscWeatherSync)
end

function miscRevealBegin()
    miscRevealActive = false
    miscRevealStarted = true
    miscRevealK = 1
    miscDefaultTime = miscLighting.ClockTime
    miscRevealFrom = miscDefaultTime
    miscRevealTo = math.clamp(miscData.clockTime or miscDefaultTime, 0, 24)
    miscClock:SetDefault(miscDefaultTime)
    miscWeatherReady = true
    miscSkyReady = true
    miscShadowReady = true
    miscCloudReady = true
    miscFogReady = true
    if math.abs(miscRevealTo - miscDefaultTime) > 0.001 then
        miscSuppress = true
        miscClock:Set(miscRevealTo)
        miscSuppress = false
        miscLighting.ClockTime = miscRevealTo
        miscData.clockTime = miscRevealTo
        miscSave()
    end
    miscApplyAll()
end

task.spawn(function()
    if not monoWaitLoad() then return end
    miscRevealBegin()
