miscWeatherSnow.Parent = miscWeatherAnchor

miscWeatherRates = { None = 0, Rain = 800, Snow = 200 }
miscWeatherBaseSpeed = { Rain = 70, Snow = 3.6 }
miscWeatherBaseAccel = { Rain = 1.5, Snow = 1.275 }

function miscWeatherSync()
    if not miscWeatherAlive then return end
    if not miscWeatherReady then return end
    local rate = miscWeatherRates[miscWeatherMode] or 0
    local scale = miscWeatherIntensity / 55
    local want = rate * scale * miscRevealK

    local drift = miscWeatherWind * 0.6
    local fall = miscWeatherFall / 50
    local rS = miscWeatherBaseSpeed.Rain * fall
    local sS = miscWeatherBaseSpeed.Snow * fall
    miscWeatherProp(miscWeatherRain, {
        Enabled = miscWeatherMode == "Rain" and want > 0,
        Rate = miscWeatherMode == "Rain" and want or 0,
        Speed = NumberRange.new(rS * 0.88, rS * 1.12),
        Acceleration = Vector3.new(drift, -miscWeatherBaseAccel.Rain * fall, drift * 0.4),
        Color = ColorSequence.new(miscWeatherRainColor),
    })
    miscWeatherProp(miscWeatherSnow, {
        Enabled = miscWeatherMode == "Snow" and want > 0,
        Rate = miscWeatherMode == "Snow" and want or 0,
        Speed = NumberRange.new(sS * 0.67, sS * 1.33),
        Acceleration = Vector3.new(drift, -miscWeatherBaseAccel.Snow * fall, drift * 0.4),
        Color = ColorSequence.new(miscWeatherSnowColor),
    })
end

function miscWeatherSet(mode)
    if not miscWeatherAlive then return end
    for _, n in ipairs(miscWeatherOrder) do
        if n == mode then miscWeatherMode = n end
    end
    miscWeatherSync()
    miscData.weatherMode = miscWeatherMode
    miscSave()
end

function miscWeatherDestroy()
    miscWeatherAlive = false
    miscWeatherSync()
    if miscWeatherFolder then pcall(function() miscWeatherFolder:Destroy() end) end
    miscWeatherFolder = nil
    miscWeatherAnchor = nil
    miscWeatherRain = nil
    miscWeatherSnow = nil
end

