miscWeatherRayParams = RaycastParams.new()
miscWeatherRayParams.FilterType = Enum.RaycastFilterType.Exclude
miscWeatherRayParams.IgnoreWater = true

miscWeatherBase = 85
local miscWeatherAcc = 0
trackConn(RunService.PreRender:Connect(function(dt)
    if not miscWeatherAlive then return end
    if not miscWeatherFolder or not miscWeatherFolder.Parent then return end
    local cam = workspace.CurrentCamera
    if not cam then return end
    local on = miscWeatherRain and miscWeatherRain.Enabled
    local onS = miscWeatherSnow and miscWeatherSnow.Enabled
    if not on and not onS then return end

    miscWeatherAcc += dt
    if miscWeatherAcc >= 0.1 then
        miscWeatherAcc = 0
        miscWeatherRayParams.FilterDescendantsInstances = { miscWeatherAnchor, LocalPlayer.Character }
        local origin = cam.CFrame.Position
        local hit = workspace:Raycast(origin, Vector3.new(0, 400, 0), miscWeatherRayParams)
        miscWeatherBase = 85
        if hit then
            local drop = hit.Position.Y - origin.Y
            if drop < miscWeatherBase then miscWeatherBase = math.max(drop + 20, 8) end
            miscWeatherAnchor.Size = Vector3.new(200, 8, 200)
        else
            miscWeatherAnchor.Size = Vector3.new(200, 200, 200)
        end
    end
    miscWeatherAnchor.CFrame = cam.CFrame * CFrame.new(0, miscWeatherBase, 0)
end))

Library:OnDestroy(function()
    miscWeatherDestroy()
end)

Library:OnDestroy(function()
    if miscDefaultTime then miscLighting.ClockTime = miscDefaultTime end
end)

miscFXAlive = true
miscFXOn = true
miscFXLock = false
miscFXSaveTimer = nil
miscFX = {}
miscFXMade = {}

miscFXClasses = {
    "BloomEffect", "SunRaysEffect", "ColorGradingEffect",
    "DepthOfFieldEffect", "ColorCorrectionEffect", "BlurEffect",
}

miscFXOrigFX = {}
miscFXOrigEnabled = {}
for _, class in ipairs(miscFXClasses) do
    local orig = miscLighting:FindFirstChildOfClass(class)
    miscFXOrigFX[class] = orig
    if orig then pcall(function() miscFXOrigEnabled[class] = orig.Enabled end) end
end

miscFXV = {
    bloomIntensity = 0.35,
    bloomSize = 24,
    bloomThreshold = 0.9,
    rayIntensity = 0.05,
    raySpread = 0.5,
    dofNear = 0,
    dofFar = 0.2,
    dofFocus = 20,
    dofRadius = 20,
    ccBrightness = 0,
    ccContrast = 0,
    ccSaturation = 0,
    blurSize = 0,
}
miscFXTint = { 255, 255, 255 }
miscFXTintReset = { 255, 255, 255 }
miscFXT = { bloom = true, rays = true, grade = false, dof = false, colour = true, blur = false }
miscFXTone = "Default"
miscFXToneOrder = { "Default", "Retro" }

function miscFXDefaults()
    local v = {}
    for k, val in pairs(miscFXV) do v[k] = val end
    return v
end

miscFXReset = miscFXDefaults()

pcall(function()
    if readfile and isfile and isfile(MISC_SAVE) then
        local d = HttpService:JSONDecode(readfile(MISC_SAVE))
        if type(d) == "table" then
            local def = miscFXDefaults()
            if type(d.fxValues) == "table" then
                for k, val in pairs(d.fxValues) do
                    if def[k] ~= nil then miscFXV[k] = val end
                end
            end
            if type(d.fxToggles) == "table" then
                for k, val in pairs(d.fxToggles) do
                    if miscFXT[k] ~= nil then miscFXT[k] = val and true or false end
                end
            end
            if type(d.fxTint) == "table" then
                miscFXTint = { tonumber(d.fxTint[1]) or 255, tonumber(d.fxTint[2]) or 255, tonumber(d.fxTint[3]) or 255 }
            end
            for _, n in ipairs(miscFXToneOrder) do
                if d.fxTone == n then miscFXTone = n end
            end
        end
    end
end)

function miscFXRGB(t)
    return Color3.fromRGB(
        math.clamp(tonumber(t[1]) or 255, 0, 255),
        math.clamp(tonumber(t[2]) or 255, 0, 255),
        math.clamp(tonumber(t[3]) or 255, 0, 255))
end

function miscFXWrite(inst, props)
    for k, v in pairs(props) do pcall(function() inst[k] = v end) end
    return inst
end

function miscFXMake(class)
    local inst = Instance.new(class)
    inst.Parent = miscLighting
    miscFXMade[#miscFXMade + 1] = inst
    return inst
end

function miscFXSetup()
    for _, class in ipairs(miscFXClasses) do
        if not miscFX[class] then
            miscFX[class] = miscFXOrigFX[class] or miscFXMake(class)
        end
    end
end

function miscFXApply()
    if not miscFXOn or not miscFXAlive then return end
    if not miscRevealStarted then return end
    miscFXSetup()
    local k = miscRevealK

    miscFXWrite(miscFX.BloomEffect, {
        Intensity = miscFXV.bloomIntensity * k,
        Size = miscFXV.bloomSize * k,
        Threshold = miscFXV.bloomThreshold * k,
        Enabled = miscFXT.bloom,
    })

    miscFXWrite(miscFX.SunRaysEffect, {
        Intensity = miscFXV.rayIntensity * k,
        Spread = miscFXV.raySpread * k,
        Enabled = miscFXT.rays,
    })

    miscFXWrite(miscFX.BlurEffect, {
        Size = miscFXV.blurSize * k,
        Enabled = miscFXT.blur,
    })

    miscFXWrite(miscFX.ColorCorrectionEffect, {
        Brightness = miscFXV.ccBrightness * k,
        Contrast = miscFXV.ccContrast * k,
        Saturation = miscFXV.ccSaturation * k,
        TintColor = Color3.new(1, 1, 1):Lerp(miscFXRGB(miscFXTint), k),
        Enabled = miscFXT.colour,
    })

    miscFXWrite(miscFX.DepthOfFieldEffect, {
        NearIntensity = miscFXV.dofNear * k,
        FarIntensity = miscFXV.dofFar * k,
        FocusDistance = miscFXV.dofFocus * k,
        InFocusRadius = miscFXV.dofRadius * k,
        Enabled = miscFXT.dof,
    })

    miscFXWrite(miscFX.ColorGradingEffect, {
        TonemapperPreset = Enum.TonemapperPreset[miscFXTone],
        Enabled = miscFXT.grade and k > 0.35,
    })
end

function miscFXSave()
    if not miscFXAlive then return end
    miscData.fxValues = miscFXV
    miscData.fxToggles = miscFXT
    miscData.fxTint = miscFXTint
    miscData.fxTone = miscFXTone
    if not miscFXSaveTimer then
        miscFXSaveTimer = task.delay(0.6, function()
            miscFXSaveTimer = nil
            if miscFXAlive then miscSave() end
        end)
    end
end

function miscFXRestore()
    miscFXOn = false
    for _, class in ipairs(miscFXClasses) do
        local orig = miscFXOrigFX[class]
        if orig and orig.Parent then
            pcall(function() orig.Enabled = miscFXOrigEnabled[class] end)
        end
    end
    for _, inst in ipairs(miscFXMade) do
        if inst.Parent then pcall(function() inst:Destroy() end) end
    end
    miscFXMade = {}
    miscFX = {}
end

function miscFXSlider(key, v)
    if miscFXLock then return end
    miscFXV[key] = v
    miscFXApply()
    miscFXSave()
end

function miscFXToggle(key, on)
    if miscFXLock then return end
    miscFXT[key] = on and true or false
    miscFXApply()
    miscFXSave()
end

function miscFXSliderUI(key, name, min, max, dec)
    return Misc:Slider({
        Name = name, Min = min, Max = max, Decimals = dec,
        Default = miscFXV[key], Reset = miscFXReset[key],
        Callback = function(v) miscFXSlider(key, v) end,
    })
end

