miscSkyOrigSky = miscLighting:FindFirstChildOfClass("Sky")
if miscSkyOrigSky then
    miscSkyStars = miscSkyOrigSky.StarCount
    miscSkySunSize = miscSkyOrigSky.SunAngularSize
    miscSkyMoonSize = miscSkyOrigSky.MoonAngularSize
    miscSkyBodies = miscSkyOrigSky.CelestialBodiesShown
end

if miscSkyStars == nil then miscSkyStars = 3000 end
if miscSkySunSize == nil then miscSkySunSize = 21 end
if miscSkyMoonSize == nil then miscSkyMoonSize = 11 end

miscSkyReset = { Bodies = miscSkyBodies, Stars = miscSkyStars, SunSize = miscSkySunSize, MoonSize = miscSkyMoonSize }

pcall(function()
    if readfile and isfile and isfile(MISC_SAVE) then
        local d = HttpService:JSONDecode(readfile(MISC_SAVE))
        if type(d) == "table" then
            if d.skyBodies ~= nil then miscSkyBodies = d.skyBodies and true or false end
            if tonumber(d.skyStars) ~= nil then miscSkyStars = math.clamp(tonumber(d.skyStars) or 3000, 0, 3000) end
            if tonumber(d.skySunSize) ~= nil then miscSkySunSize = math.clamp(tonumber(d.skySunSize) or 21, 0, 60) end
            if tonumber(d.skyMoonSize) ~= nil then miscSkyMoonSize = math.clamp(tonumber(d.skyMoonSize) or 11, 0, 60) end
        end
    end
end)

function miscSkyWrite(sky, props)
    for k, v in pairs(props) do pcall(function() sky[k] = v end) end
    return sky
end

function miscSkyTarget()
    if miscSkyOrigSky and miscSkyOrigSky.Parent then return miscSkyOrigSky end
    if not miscSkyOur or not miscSkyOur.Parent then
        miscSkyOur = Instance.new("Sky")
        miscSkyOur.Name = "MonochromeSky"
        miscSkyOur.Parent = miscLighting
    end
    return miscSkyOur
end

function miscSkyApply()
    if not miscSkyAlive or not miscSkyReady then return end
    if not miscRevealStarted then return end
    local k = miscRevealK
    miscSkyWrite(miscSkyTarget(), {
        CelestialBodiesShown = miscSkyBodies,
        StarCount = math.clamp(math.floor(miscSkyStars * k), 0, 3000),
        SunAngularSize = math.clamp(miscSkySunSize * k, 0, 60),
        MoonAngularSize = math.clamp(miscSkyMoonSize * k, 0, 60),
    })
end

function miscSkyRestore()
    if miscSkyOur then
        pcall(function() miscSkyOur:Destroy() end)
        miscSkyOur = nil
    end
end

function miscSkyDestroy()
    miscSkyAlive = false
    miscSkyRestore()
end

function miscSkySave()
    if not miscSkyAlive then return end
    miscData.skyBodies = miscSkyBodies
    miscData.skyStars = miscSkyStars
    miscData.skySunSize = miscSkySunSize
    miscData.skyMoonSize = miscSkyMoonSize
    miscSave()
end

