miscCloudAlive = true
miscCloudReady = false
miscCloudOur = nil
miscCloudOn = true
miscCloudColor = nil
miscCloudCover = nil
miscCloudDensity = nil

miscCloudOrig = nil
pcall(function() miscCloudOrig = workspace:FindFirstChildOfClass("Terrain"):FindFirstChildOfClass("Clouds") end)
if miscCloudOrig then
    miscCloudColor = miscCloudOrig.Color
    miscCloudCover = miscCloudOrig.Cover
    miscCloudDensity = miscCloudOrig.Density
end

if miscCloudColor == nil then miscCloudColor = Color3.fromRGB(255, 255, 255) end
if miscCloudCover == nil then miscCloudCover = 0.5 end
if miscCloudDensity == nil then miscCloudDensity = 0.5 end

miscCloudReset = { On = miscCloudOn, Color = miscCloudColor, Cover = miscCloudCover, Density = miscCloudDensity }

pcall(function()
    if readfile and isfile and isfile(MISC_SAVE) then
        local d = HttpService:JSONDecode(readfile(MISC_SAVE))
        if type(d) == "table" then
            if d.cloudOn ~= nil then miscCloudOn = d.cloudOn and true or false end
            if type(d.cloudColor) == "table" then
                miscCloudColor = Color3.fromRGB(
                    math.clamp(tonumber(d.cloudColor[1]) or 255, 0, 255),
                    math.clamp(tonumber(d.cloudColor[2]) or 255, 0, 255),
                    math.clamp(tonumber(d.cloudColor[3]) or 255, 0, 255))
            end
            if tonumber(d.cloudCover) ~= nil then miscCloudCover = math.clamp(tonumber(d.cloudCover) or 0.5, 0, 1) end
            if tonumber(d.cloudDensity) ~= nil then miscCloudDensity = math.clamp(tonumber(d.cloudDensity) or 0.5, 0, 1) end
        end
    end
end)

function miscCloudWrite(inst, props)
    for k, v in pairs(props) do pcall(function() inst[k] = v end) end
    return inst
end

function miscCloudTarget()
    if miscCloudOrig and miscCloudOrig.Parent then return miscCloudOrig end
    if miscCloudOur and miscCloudOur.Parent then return miscCloudOur end
    local terrain = workspace:FindFirstChildOfClass("Terrain")
    if not terrain then return nil end
    local ok, inst = pcall(function() return Instance.new("Clouds") end)
    if not ok or not inst then return nil end
    inst.Name = "MonochromeClouds"
    pcall(function() inst.Parent = terrain end)
    if not inst.Parent then return nil end
    miscCloudOur = inst
    return miscCloudOur
end

function miscCloudApply()
    if not miscCloudAlive or not miscCloudReady then return end
    if not miscRevealStarted then return end
    local k = miscRevealK
    local t = miscCloudTarget()
    if not t then return end
    miscCloudWrite(t, {
        Color = miscCloudColor,
        Cover = miscCloudOn and math.clamp(miscCloudCover * k, 0, 1) or 0,
        Density = miscCloudOn and math.clamp(miscCloudDensity * k, 0, 1) or 0,
    })
end

function miscCloudRestore()
    if miscCloudOur then
        pcall(function() miscCloudOur:Destroy() end)
        miscCloudOur = nil
    end
    if miscCloudOrig and miscCloudOrig.Parent then
        miscCloudWrite(miscCloudOrig, {
            Color = miscCloudReset.Color,
            Cover = miscCloudReset.Cover,
            Density = miscCloudReset.Density,
        })
    end
end

function miscCloudDestroy()
    miscCloudAlive = false
    miscCloudRestore()
end

function miscCloudSave()
    if not miscCloudAlive then return end
    miscData.cloudOn = miscCloudOn
    miscData.cloudColor = {
        math.round(miscCloudColor.R * 255),
        math.round(miscCloudColor.G * 255),
        math.round(miscCloudColor.B * 255),
    }
    miscData.cloudCover = miscCloudCover
    miscData.cloudDensity = miscCloudDensity
    miscSave()
end

