    miscFogHaze = miscFogOrig.Haze
end

if miscFogColor == nil then miscFogColor = Color3.fromRGB(255, 255, 255) end
if miscFogDensity == nil then miscFogDensity = 0.3 end
if miscFogOffset == nil then miscFogOffset = 0.2 end
if miscFogHaze == nil then miscFogHaze = 1 end

