pcall(function()
    if readfile and isfile and isfile(MISC_SAVE) then
        local d = HttpService:JSONDecode(readfile(MISC_SAVE))
        if type(d) == "table" then
            if d.fogOn ~= nil then miscFogOn = d.fogOn and true or false end
            if type(d.fogColor) == "table" then
                miscFogColor = Color3.fromRGB(
                    math.clamp(tonumber(d.fogColor[1]) or 255, 0, 255),
                    math.clamp(tonumber(d.fogColor[2]) or 255, 0, 255),
                    math.clamp(tonumber(d.fogColor[3]) or 255, 0, 255))
            end
            if tonumber(d.fogDensity) ~= nil then miscFogDensity = math.clamp(tonumber(d.fogDensity) or 0.3, 0, 1) end
            if tonumber(d.fogOffset) ~= nil then miscFogOffset = math.clamp(tonumber(d.fogOffset) or 0.2, 0, 1) end
            if tonumber(d.fogHaze) ~= nil then miscFogHaze = math.clamp(tonumber(d.fogHaze) or 1, 0, 1) end
        end
    end
end)

function miscFogWrite(inst, props)
    for k, v in pairs(props) do pcall(function() inst[k] = v end) end
    return inst
end

function miscFogTarget()
    if miscFogOrig and miscFogOrig.Parent then return miscFogOrig end
    if not miscFogOur or not miscFogOur.Parent then
        local ok, inst = pcall(function() return Instance.new("Atmosphere") end)
        if not ok or not inst then return nil end
        inst.Name = "MonochromeFog"
        miscFogOur = inst
        pcall(function() inst.Parent = miscLighting end)
        if not inst.Parent then
            miscFogOur = nil
            return nil
        end
    end
    return miscFogOur
end

function miscFogApply()
    if not miscFogAlive or not miscFogReady then return end
    if not miscRevealStarted then return end
    local k = miscRevealK
    local t = miscFogTarget()
    if not t then return end
    miscFogWrite(t, {
        Color = miscFogColor,
        Density = miscFogOn and math.clamp(miscFogDensity * k, 0, 1) or 0,
        Offset = math.clamp(miscFogOffset * k, 0, 1),
        Haze = miscFogOn and math.clamp(miscFogHaze * k, 0, 1) or 0,
    })
end

function miscFogRestore()
    if miscFogOur then
        pcall(function() miscFogOur:Destroy() end)
        miscFogOur = nil
    end
    if miscFogOrig and miscFogOrig.Parent then
        miscFogWrite(miscFogOrig, {
            Color = miscFogReset.Color,
            Density = miscFogReset.Density,
            Offset = miscFogReset.Offset,
            Haze = miscFogReset.Haze,
        })
    end
end

function miscFogDestroy()
    miscFogAlive = false
    miscFogRestore()
end

function miscFogSave()
    if not miscFogAlive then return end
    miscData.fogOn = miscFogOn
    miscData.fogColor = {
        math.round(miscFogColor.R * 255),
        math.round(miscFogColor.G * 255),
        math.round(miscFogColor.B * 255),
    }
    miscData.fogDensity = miscFogDensity
    miscData.fogOffset = miscFogOffset
    miscData.fogHaze = miscFogHaze
    miscSave()
end

