miscShadowAlive = true
miscShadowReady = false
miscShadowEnabled = false
miscShadowHard = false
miscShadowAmbientFixed = true
miscShadowOrigSoft = nil
miscShadowOrigAmbient = nil
miscShadowOrigGlobal = nil
pcall(function() miscShadowOrigSoft = miscLighting.ShadowSoftness end)
pcall(function() miscShadowOrigAmbient = miscLighting.Ambient end)
pcall(function() miscShadowOrigGlobal = miscLighting.GlobalShadows end)
if miscShadowOrigSoft == nil then miscShadowOrigSoft = 0.2 end
miscShadowTargetAmbient = miscShadowOrigAmbient
pcall(function()
    if miscShadowOrigAmbient then
        miscShadowTargetAmbient = miscShadowOrigAmbient:Lerp(Color3.new(0, 0, 0), 0.45)
    end
end)

pcall(function()
    if readfile and isfile and isfile(MISC_SAVE) then
        local d = HttpService:JSONDecode(readfile(MISC_SAVE))
        if type(d) == "table" then
            if d.shadows ~= nil then miscShadowEnabled = d.shadows and true or false end
            if d.shadowHard ~= nil then miscShadowHard = d.shadowHard and true or false end
            if d.shadowAmbient ~= nil then miscShadowAmbientFixed = d.shadowAmbient and true or false end
        end
    end
end)

function miscShadowSave()
    miscData.shadows = miscShadowEnabled
    miscData.shadowHard = miscShadowHard
    miscData.shadowAmbient = miscShadowAmbientFixed
    miscSave()
end

function miscShadowApply()
    if not miscShadowAlive or not miscShadowReady then return end
    pcall(function() miscLighting.GlobalShadows = miscShadowEnabled end)
    local k = miscRevealK
    if miscShadowEnabled then
        pcall(function()
            miscLighting.ShadowSoftness = miscLerp(1, miscShadowHard and 0 or miscShadowOrigSoft, k)
        end)
    else
        pcall(function() miscLighting.ShadowSoftness = miscShadowOrigSoft end)
    end
    if miscShadowOrigAmbient then
        if miscShadowAmbientFixed and miscShadowTargetAmbient then
            pcall(function()
                miscLighting.Ambient = miscShadowOrigAmbient:Lerp(miscShadowTargetAmbient, k)
            end)
        else
            pcall(function() miscLighting.Ambient = miscShadowOrigAmbient end)
        end
    end
end

function miscShadowRestore()
    if miscShadowOrigGlobal ~= nil then
        pcall(function() miscLighting.GlobalShadows = miscShadowOrigGlobal end)
    end
    pcall(function() miscLighting.ShadowSoftness = miscShadowOrigSoft end)
    if miscShadowOrigAmbient then
        pcall(function() miscLighting.Ambient = miscShadowOrigAmbient end)
    end
end

function miscShadowDestroy()
    miscShadowAlive = false
    miscShadowRestore()
end

Library:OnDestroy(function()
    miscShadowDestroy()
end)

