miscPartyAlive = true
miscPartyOn = false
miscPartySpeed = 0.5
miscPartyT = 0
miscPartyAtmos = nil
miscPartyClouds = nil
miscPartyMadeAtmos = nil
miscPartyMadeClouds = nil
miscPartyOrig = {}
miscPartyResetSpeed = 0.5

pcall(function()
    if readfile and isfile and isfile(MISC_SAVE) then
        local d = HttpService:JSONDecode(readfile(MISC_SAVE))
        if type(d) == "table" then
            if d.party ~= nil then miscPartyOn = d.party and true or false end
            if tonumber(d.partySpeed) ~= nil then
                miscPartySpeed = math.clamp(tonumber(d.partySpeed) or 0.5, 0.05, 2)
            end
        end
    end
end)

function miscPartySave()
    miscData.party = miscPartyOn
    miscData.partySpeed = miscPartySpeed
    miscSave()
end

function miscPartyTargetOf(prefix)
    if prefix == "atmos" then return miscPartyAtmos end
    if prefix == "cloud" then return miscPartyClouds end
    return miscLighting
end

function miscPartyGrab(prefix, field)
    local inst = miscPartyTargetOf(prefix)
    if not inst then return end
    local key = prefix .. field
    if miscPartyOrig[key] ~= nil then return end
    local ok, v = pcall(function() return inst[field] end)
    if ok and v ~= nil then
        miscPartyOrig[key] = { inst = inst, field = field, value = v }
    end
end

function miscPartyCapture()
    if miscPartyAtmos == nil then
        local target = nil
        if type(miscFogTarget) == "function" then target = miscFogTarget() end
        if target == nil then target = miscLighting:FindFirstChildOfClass("Atmosphere") end
        if target == nil then
            local ok, inst = pcall(function() return Instance.new("Atmosphere") end)
            if ok and inst then
                inst.Name = "MonochromeParty"
                pcall(function() inst.Parent = miscLighting end)
                if inst.Parent then
                    miscPartyMadeAtmos = inst
                    target = inst
                end
            end
        end
        miscPartyAtmos = target
    end
    if miscPartyClouds == nil then
        local target = nil
        if type(miscCloudTarget) == "function" then target = miscCloudTarget() end
        if target == nil then
            local terrain = workspace:FindFirstChildOfClass("Terrain")
            if terrain then target = terrain:FindFirstChildOfClass("Clouds") end
        end
        if target == nil then
            local ok, inst = pcall(function() return Instance.new("Clouds") end)
            if ok and inst then
                inst.Name = "MonochromePartyClouds"
                pcall(function() inst.Parent = workspace.Terrain end)
                if inst.Parent then
                    miscPartyMadeClouds = inst
                    target = inst
                end
            end
        end
        miscPartyClouds = target
    end
    for _, f in ipairs({
        "Brightness", "ExposureCompensation", "EnvironmentDiffuseScale",
        "EnvironmentSpecularScale", "GlobalShadows", "Ambient",
        "OutdoorAmbient", "ColorShift_Top", "ColorShift_Bottom",
    }) do
        miscPartyGrab("", f)
    end
    for _, f in ipairs({ "Color", "Decay", "Density", "Haze", "Glare" }) do
        miscPartyGrab("atmos", f)
    end
    miscPartyGrab("cloud", "Color")
end

function miscPartyRestore()
    for _, rec in pairs(miscPartyOrig) do
        if rec and rec.inst and rec.field and rec.inst.Parent then
            local field = rec.field
            local value = rec.value
            pcall(function() rec.inst[field] = value end)
        end
    end
    miscPartyOrig = {}
    if miscWeatherRain and miscWeatherRain.Parent then
        pcall(function() miscWeatherRain.Color = ColorSequence.new(miscWeatherRainColor) end)
    end
    if miscWeatherSnow and miscWeatherSnow.Parent then
        pcall(function() miscWeatherSnow.Color = ColorSequence.new(miscWeatherSnowColor) end)
    end
    if miscPartyMadeAtmos and miscPartyMadeAtmos.Parent then
        pcall(function() miscPartyMadeAtmos:Destroy() end)
    end
    if miscPartyMadeClouds and miscPartyMadeClouds.Parent then
        pcall(function() miscPartyMadeClouds:Destroy() end)
    end
    miscPartyMadeAtmos = nil
    miscPartyMadeClouds = nil
    miscPartyAtmos = nil
    miscPartyClouds = nil
end

function miscPartySet(on)
    miscPartyOn = on and true or false
    if miscPartyOn then
        miscPartyCapture()
        miscPartyT = 0
    else
        miscPartyRestore()
    end
    miscPartySave()
end

local miscPartyAcc = 0
trackConn(RunService.Heartbeat:Connect(function(dt)
    if not miscPartyAlive then return end
    if not miscPartyOn then return end
    miscPartyAcc += dt
    if miscPartyAcc < 0.08 then return end
    local step = miscPartyAcc
    miscPartyAcc = 0
    miscPartyT = miscPartyT + step * (1 / math.max(miscPartySpeed, 0.05))
    local hue = miscPartyT % 1
    local c = Color3.fromHSV(hue, 1, 1)
    pcall(function() miscLighting.Ambient = c end)
    pcall(function() miscLighting.OutdoorAmbient = c end)
    pcall(function() miscLighting.ColorShift_Top = c end)
    pcall(function() miscLighting.ColorShift_Bottom = c end)
    pcall(function() miscLighting.Brightness = 5 end)
    pcall(function() miscLighting.ExposureCompensation = 1 end)
    pcall(function() miscLighting.EnvironmentDiffuseScale = 1 end)
    pcall(function() miscLighting.EnvironmentSpecularScale = 1 end)
    pcall(function() miscLighting.GlobalShadows = false end)
    if miscPartyAtmos == nil or not miscPartyAtmos.Parent then
        local target = nil
        if type(miscFogTarget) == "function" then target = miscFogTarget() end
        if target == nil then target = miscLighting:FindFirstChildOfClass("Atmosphere") end
        if target == nil then
            local ok, inst = pcall(function() return Instance.new("Atmosphere") end)
            if ok and inst then
                inst.Name = "MonochromeParty"
                pcall(function() inst.Parent = miscLighting end)
                if inst.Parent then
                    target = inst
                    miscPartyMadeAtmos = inst
                end
            end
        end
        miscPartyAtmos = target
    end
    local atmos = miscPartyAtmos
    if atmos and atmos.Parent then
        pcall(function() atmos.Color = c end)
        pcall(function() atmos.Decay = c end)
    end
    pcall(function() miscLighting.FogColor = c end)
    local clouds = miscPartyClouds
    if clouds and clouds.Parent then
        pcall(function() clouds.Color = c end)
    end
    if miscWeatherRain and miscWeatherRain.Parent then
        pcall(function() miscWeatherRain.Color = ColorSequence.new(c) end)
    end
    if miscWeatherSnow and miscWeatherSnow.Parent then
        pcall(function() miscWeatherSnow.Color = ColorSequence.new(c) end)
    end
end))

