function ppRow(h, order)
    local r = create("Frame", {
        Size = UDim2.new(1, 0, 0, h), BackgroundColor3 = C.surface,
        BackgroundTransparency = 0.4, BorderSizePixel = 0, LayoutOrder = order,
    }, pp)
    corner(r, 10); stroke(r, C.borderSoft, 1, 0.55)
    return r
end

function ppLabel(parent, text, x, y, w, align, color, size, font)
    return create("TextLabel", {
        Size = UDim2.new(0, w or 200, 0, 16), Position = UDim2.new(0, x, 0, y),
        BackgroundTransparency = 1, Text = text, TextColor3 = color or C.text,
        TextSize = size or 11, Font = font or Enum.Font.Gotham,
        TextXAlignment = align or Enum.TextXAlignment.Left,
        TextTruncate = Enum.TextTruncate.AtEnd,
    }, parent)
end

function _ppCopyBtn(parent, text, x, y, copyText)
    local b = create("TextButton", {
        Size = UDim2.new(0, 44, 0, 18), Position = UDim2.new(0, x, 0, y),
        BackgroundColor3 = C.input, BorderSizePixel = 0, Text = text,
        TextColor3 = C.textMut, TextSize = 9, Font = Enum.Font.GothamMedium,
        AutoButtonColor = false,
    }, parent)
    corner(b, 6)
    b.MouseEnter:Connect(function() tween(b, { BackgroundColor3 = C.surfaceHi }, 0.15) end)
    b.MouseLeave:Connect(function() tween(b, { BackgroundColor3 = C.input }, 0.15) end)
    b.MouseButton1Click:Connect(function()
        if typeof(setclipboard) == "function" then pcall(setclipboard, copyText) end
    end)
    return b
end

