monoBgActive = false
monoBgStatus = ""

function monoBgPropagate()
    if not monoBgImage or not monoBgImage.Parent then return end
    local src = monoBgImage.Image
    local transparency = monoCustomBgTransparency()
    monoBgImage.ImageTransparency = transparency
    for _, rec in pairs(toastLive or {}) do
        if rec and rec.bg then
            rec.bg.Image = src
            rec.bg.ImageTransparency = transparency
        end
    end
    for _, entry in pairs(monoPanelLive or {}) do
        if entry and entry.bg then
            entry.bg.Image = src
            entry.bg.ImageTransparency = transparency
        end
    end
    if monoTerm and monoTerm.bg then
        monoTerm.bg.Image = src
        monoTerm.bg.ImageTransparency = transparency
    end
end

function monoBgShow()
    if not monoBgImage or not monoBgImage.Parent then return end
    monoBgShade.BackgroundTransparency = setData.bgDim / 100
    monoBgImage.ImageTransparency = monoCustomBgTransparency()
    monoBgImage.Visible = true
    monoBgShade.Visible = true
    if monoBgDot then monoBgDot.Visible = false end
    for _, layer in ipairs(monoBgLayers or {}) do
        if layer and layer.Parent then
            tween(layer, { BackgroundTransparency = 1 }, 0.25)
        end
    end
    for c in pairs(toastLive or {}) do
        toastBgSync(c)
    end
    monoPanelBgSyncAll()
    if monoTerm and type(monoTermBgSync) == "function" then monoTermBgSync() end
end

function monoBgHide()
    if not monoBgImage or not monoBgImage.Parent then return end
    monoBgImage.Image = ""
    monoBgImage.ImageTransparency = 0
    monoBgImage.Visible = false
    monoBgShade.Visible = false
    if monoBgDot then monoBgDot.Visible = true end
    for _, layer in ipairs(monoBgLayers or {}) do
        if layer and layer.Parent then
            local rest = monoBgRest and monoBgRest[layer]
            tween(layer, { BackgroundTransparency = rest or 0 }, 0.25)
        end
    end
    for c in pairs(toastLive or {}) do
        toastBgSync(c)
    end
    monoPanelBgSyncAll()
    if monoTerm and type(monoTermBgSync) == "function" then monoTermBgSync() end
end

monoUiTransparency = monoUiTransparency or 0.12
monoUiBaseRest = monoUiBaseRest or {}

function monoUiTransparencyApply(t)
    t = tonumber(t)
    if t == nil or t ~= t then t = 0.12 end
    t = math.clamp(t, 0, 0.2)
    monoUiTransparency = t
    MONO_UI_TRANSPARENCY = t
    if type(setData) == "table" then setData.uiTransparency = t end

    if monoBgImage and monoBgImage.Parent then
        monoBgImage.ImageTransparency = monoCustomBgTransparency()
    end

    monoBgRest = monoBgRest or {}
    for _, layer in ipairs(monoBgLayers or {}) do
        if layer and layer.Parent then
            if monoUiBaseRest[layer] == nil then
                monoUiBaseRest[layer] = tonumber(monoBgRest[layer]) or 0
            end
            local rest = monoIsSidebarLayer(layer) and 1 or math.max(monoUiBaseRest[layer], t)
            monoBgRest[layer] = rest
            local customOn = monoBgImage and monoBgImage.Parent
                and monoBgImage.Visible and monoBgImage.Image ~= ""
            if not customOn then
                tween(layer, { BackgroundTransparency = rest }, 0.2)
            end
        end
    end
    for c in pairs(toastLive or {}) do
        toastBgSync(c)
    end
    monoPanelBgSyncAll()
    if monoReanimEntry then pcall(monoPanelBgSync, monoReanimEntry) end
    if monoTerm and type(monoTermBgSync) == "function" then monoTermBgSync() end
end

function monoBgApply(urlText, silent)
    local urls = parseFrameUrlList(urlText or "")
    if #urls == 0 then
        monoBgStatus = "No valid http(s) URL"
        return false
    end
    monoBgStatus = "Downloading image"
    local path = downloadImageForUser(LocalPlayer.UserId, urls[1])
    local asset = path and getAsset(path) or nil
    if not asset then
        monoBgStatus = "Download failed"
        return false
    end
    if not monoBgImage or not monoBgImage.Parent then
        monoBgStatus = "No window"
        return false
    end
    monoBgActive = true
    monoBgImage.Image = asset
    monoBgPropagate()
    monoBgShow()
    monoBgStatus = "Active - static image"
    return true
end

function monoBgClear()
    monoBgHide()
    monoBgActive = false
    setData.bgUrl = ""
    setSave()
    monoBgStatus = "Cleared"
end

monoBgAutoRan = false

function monoBgAutoApply()
    if monoBgAutoRan then return end
    monoBgAutoRan = true
    task.spawn(function()
        local tries = 0
        while tries < 80 do
            tries = tries + 1
            if monoBgImage and monoBgImage.Parent then
                if setData.bgUrl and setData.bgUrl ~= "" then
                    monoBgApply(setData.bgUrl, true)
                end
                break
            end
            task.wait(0.1)
        end
    end)
end

