monoBubbleScreen = nil

local function monoBillboardHasVisibleContent(bill)
    local shown = false
    pcall(function()
        for _, d in ipairs(bill:GetDescendants()) do
            if d:IsA("ImageLabel") or d:IsA("ImageButton") then
                if d.Visible and d.ImageTransparency < 0.95 then
                    shown = true
                    break
                end
            elseif d:IsA("TextLabel") then
                if d.Visible and d.Text ~= "" and d.TextTransparency < 0.95 then
                    shown = true
                    break
                end
            end
        end
    end)
    return shown
end

local function monoFindBubbleScreen()
    if monoBubbleScreen and monoBubbleScreen.Parent then return monoBubbleScreen end
    local ec = CoreGui:FindFirstChild("ExperienceChat")
    monoBubbleScreen = ec and ec:FindFirstChild("bubbleChat") or nil
    return monoBubbleScreen
end

monoNativeOverlapHistory = monoNativeOverlapHistory or {}

function monoMaxBubbles()
    local n = 3
    pcall(function()
        local tcs = game:GetService("TextChatService")
        local cfg = tcs and tcs:FindFirstChild("BubbleChatConfiguration")
        if cfg then
            local v = tonumber(cfg.MaxBubbles)
            if v and v >= 0 then n = math.floor(v) end
        end
    end)
    return math.max(0, n)
end



function monoBubbleStep()
    local s = MONO_BUBBLE_STEP
    pcall(function()
        local tcs = game:GetService("TextChatService")
        local cfg = tcs and tcs:FindFirstChild("BubbleChatConfiguration")
        if cfg then
            local v = tonumber(cfg.BubblesSpacing)
            if v and v >= 0 then s = math.clamp(v / 6, 0.5, MONO_BUBBLE_STEP) end
        end
    end)
    return s
end




local function monoVisibleBubbleCount(bill)
    local count = 0
    pcall(function()
        local list = bill and bill:FindFirstChild("BubbleChatList")
        if not list then return end
        for _, c in ipairs(list:GetChildren()) do
            if c:IsA("GuiObject") and c.Visible and not c.Name:find("MonoStack", 1, true)
                and monoBillboardHasVisibleContent(c) then
                local ok, size = pcall(function() return c.AbsoluteSize end)
                if ok and size and size.Y > 0 then count = count + 1 end
            end
        end
    end)
    return math.min(count, monoMaxBubbles())
end



local function monoMeasuredBubbleStep(bill)
    local fallback = monoBubbleStep()
    local ok, result = pcall(function()
        local spacing = 6
        pcall(function()
            local tcs = game:GetService("TextChatService")
            local cfg = tcs and tcs:FindFirstChild("BubbleChatConfiguration")
            if cfg then
                local v = tonumber(cfg.BubblesSpacing)
                if v and v >= 0 then spacing = v end
            end
        end)
        local list = bill and bill:FindFirstChild("BubbleChatList")
        if not list then return fallback end
        local heights, total = 0, 0
        for _, c in ipairs(list:GetChildren()) do
            if c:IsA("GuiObject") and c.Visible then
                local okSz, sz = pcall(function() return c.AbsoluteSize end)
                if okSz and sz and sz.Y > 0 then
                    heights = heights + 1
                    total = total + sz.Y
                end
            end
        end
        if heights == 0 then return fallback end
        local ad = bill.Adornee
        if not ad then return fallback end
        local cam = workspace.CurrentCamera
        if not cam then return fallback end
        local a = cam:WorldToScreenPoint(ad.Position)
        local b = cam:WorldToScreenPoint(ad.Position + Vector3.new(0, 1, 0))
        local pxPerStud = math.abs(a.Y - b.Y)
        if pxPerStud < 1 then return fallback end
        local step = ((total / heights) + spacing) / pxPerStud
        if step ~= step or step <= 0 then return fallback end
        return math.clamp(step, 0.5, 1.5)
    end)
    return ok and result or fallback
end




monoStackMirrors = monoStackMirrors or {}

local function _monoStackDetach(uid)
    local m = monoStackMirrors[uid]
    if not m then return end
    pcall(function()
        if m.voice then m.voice:Destroy() end
        if m.tag then m.tag:Destroy() end
    end)
    monoStackMirrors[uid] = nil
end

local function _monoStackMakeVoice()
    local f = Instance.new("Frame")
    f.Name = "MonoStackVoice"
    f.Size = UDim2.new(0, 30, 0, 30)
    f.BackgroundColor3 = Color3.fromRGB(250, 250, 250)
    f.BackgroundTransparency = 0.1
    corner(f, 8)
    local img = Instance.new("ImageLabel")
    img.Size = UDim2.new(0, 24, 0, 24)
    img.Position = UDim2.fromScale(0.5, 0.5)
    img.AnchorPoint = Vector2.new(0.5, 0.5)
    img.BackgroundTransparency = 1
    img.Image = monoVcVoiceSheet
    img.ImageRectSize = Vector2.new(36, 36)
    img.ImageRectOffset = monoVcVoiceTalkFrame
    img.ScaleType = Enum.ScaleType.Stretch
    img.Parent = f
    return f, img
end

local function _monoStackMakeTag(uid)
    local plr = Players:GetPlayerByUserId(uid)
    local cfg = plr and monoNametagConfigFor(plr) or nil
    local f = Instance.new("Frame")
    f.Name = "MonoStackTag"
    f.Size = UDim2.new(0, (cfg and cfg.width) or 150, 0, (cfg and cfg.height) or 50)
    f.BackgroundColor3 = (cfg and cfg.bgColor) or C.card
    f.BackgroundTransparency = (cfg and cfg.bgColor) and 1 or 0.1
    corner(f, 10)

    local outline = Instance.new("UIStroke")
    outline.Name = "Border"
    outline.Color = (cfg and cfg.borderColor) or C.sep
    outline.Thickness = 1
    outline.Transparency = 0.35
    outline.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    outline.Parent = f
    if cfg and cfg.gradientColor and cfg.gradientSpinColor then
        local grad = Instance.new("UIGradient")
        grad.Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0, cfg.gradientSpinColor),
            ColorSequenceKeypoint.new(0.25, cfg.gradientColor),
            ColorSequenceKeypoint.new(0.5, cfg.gradientSpinColor),
            ColorSequenceKeypoint.new(0.75, cfg.gradientColor),
            ColorSequenceKeypoint.new(1, cfg.gradientSpinColor),
        })
        grad.Parent = outline
    end

    if cfg and cfg.imagePath and typeof(isfile) == "function" and isfile(cfg.imagePath) then
        local asset = getAsset(cfg.imagePath)
        if asset then
            
            
            f.BackgroundTransparency = 1
            local img = Instance.new("ImageLabel")
            img.Name = "BgImage"
            img.Size = UDim2.fromScale(1, 1)
            img.BackgroundTransparency = 1
            img.Image = asset
            img.ScaleType = Enum.ScaleType.Stretch
            img.ZIndex = 1
            img.Parent = f
            corner(img, 8)
        end
    end

    local showDn = not cfg or cfg.showDisplayName ~= false
    local showUn = not cfg or cfg.showUsername ~= false
    if showDn then
        local t = Instance.new("TextLabel")
        t.Name = "DisplayName"
        t.Size = UDim2.new(1, -10, 0, 20)
        t.Position = UDim2.new(0, 5, 0, 5)
        t.BackgroundTransparency = 1
        t.Text = (cfg and cfg.displayNameText) or (plr and plr.DisplayName) or "?"
        t.TextColor3 = (cfg and cfg.textColor) or C.text
        t.TextSize = (cfg and cfg.textSize) or 14
        t.Font = (cfg and cfg.font) or Enum.Font.GothamBold
        t.ZIndex = 2
        t.Parent = f
    end
    if showUn then
        local u = Instance.new("TextLabel")
        u.Name = "Username"
        u.Size = UDim2.new(1, -10, 0, 16)
        u.Position = UDim2.new(0, 5, 0, showDn and 25 or 5)
        u.BackgroundTransparency = 1
        local text = (cfg and cfg.usernameText) or (plr and plr.Name) or ""
        local prefix = (cfg and cfg.usernamePrefix) or "@"
        if text ~= "" and prefix ~= "" and text:sub(1, #prefix) ~= prefix then text = prefix .. text end
        u.Text = text
        u.TextColor3 = (cfg and cfg.usernameColor) or C.textMut
        u.TextSize = (cfg and cfg.usernameSize) or 11
        u.Font = Enum.Font.Gotham
        u.ZIndex = 2
        u.Parent = f
    end
    if uid ~= Players.LocalPlayer.UserId then
        f.Active = true
        f.InputBegan:Connect(function(input)
            if input.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
            local target = Players:GetPlayerByUserId(uid)
            local myChar = Players.LocalPlayer.Character
            local targetChar = target and target.Character
            local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
            local tRoot = targetChar and targetChar:FindFirstChild("HumanoidRootPart")
            if not myRoot or not tRoot then return end
            local behind = tRoot.CFrame * CFrame.new(0, 0, 3)
            myRoot.CFrame = CFrame.new(behind.Position, behind.Position + tRoot.CFrame.LookVector)
        end)
    end
    return f, f:FindFirstChild("DisplayName")
end

local function _monoStackAttach(uid, bill, wantVoice)
    local list = bill and bill:FindFirstChild("BubbleChatList")
    if not list then return end
    pcall(function() bill.Active = true end)
    local m = monoStackMirrors[uid]
    if m and m.bill == bill then
        if wantVoice and not m.voice then
            local voice, voiceIcon = _monoStackMakeVoice()
            voice.LayoutOrder = -1
            voice.Parent = list
            m.voice, m.voiceIcon = voice, voiceIcon
        elseif not wantVoice and m.voice then
            pcall(function() m.voice:Destroy() end)
            m.voice, m.voiceIcon = nil, nil
        end
        return
    end
    if m then _monoStackDetach(uid) end
    local tag, tagText = _monoStackMakeTag(uid)
    tag.LayoutOrder = -2
    tag.Parent = list
    local voice, voiceIcon = nil, nil
    if wantVoice then
        voice, voiceIcon = _monoStackMakeVoice()
        voice.LayoutOrder = -1
        voice.Parent = list
    end
    monoStackMirrors[uid] = {
        bill = bill, voice = voice, voiceIcon = voiceIcon, tag = tag, tagText = tagText,
    }
end

function monoRefreshNativeHeadOverlaps()
    if nametagEnabled == false and (not monoVc or not monoVc.active) then return end
    table.clear(monoNativeOverlap.bubbles)

    if monoAvoidBubbles then
        local screen = monoFindBubbleScreen()
        if screen then
            pcall(function()
                for _, bill in ipairs(screen:GetChildren()) do
                    if bill:IsA("BillboardGui") and bill.Enabled ~= false then
                        local plr = monoPlayerFromAdornee(bill.Adornee)
                        if plr then
                            local uid = plr.UserId
                            local count = monoVisibleBubbleCount(bill)
                            local y = nil
                            pcall(function()
                                y = tonumber(bill.StudsOffsetWorldSpace.Y)
                                if not y or y ~= y then y = tonumber(bill.StudsOffset.Y) end
                                if not y or y ~= y then y = nil end
                            end)

                            local step = monoMeasuredBubbleStep(bill)
                            local hist = monoNativeOverlapHistory[uid] or {}
                            if count == 1 and y and not hist.baseY then hist.baseY = y end
                            hist.count = count
                            hist.y = y
                            hist.step = step
                            monoNativeOverlapHistory[uid] = hist

                            if count > 0 then
                                monoNativeOverlap.bubbles[uid] = {
                                    count = count,
                                    minY = y,
                                    maxY = y,
                                    step = step,
                                }
                            end
                        end
                    end
                end
            end)
        end
    end

    return monoNativeOverlap
end

monoNativeScanAt = 0

function monoNativeScanNow()
    local now = tick()
    if (now - monoNativeScanAt) < 0.2 then return end
    monoNativeScanAt = now
    pcall(monoRefreshNativeHeadOverlaps)
end

task.spawn(function()
    while true do
        task.wait(0.75)
        pcall(monoRefreshNativeHeadOverlaps)
    end
end)

