function rowSignature(row)
    if not row then return "" end
    local parts = {}
    for i = 1, #SIGNATURE_FIELDS do parts[i] = tostring(row[SIGNATURE_FIELDS[i]]) end
    return table.concat(parts, "|")
end

function safeFont(name, fallback)
    if not name or name == "" then return fallback end
    local ok, f = pcall(function() return Enum.Font[name] end)
    if ok and f then return f end
    return fallback
end

function hexToColor3(hex)
    if not hex or hex == "" then return nil end
    hex = tostring(hex):gsub("#", "")
    if #hex ~= 6 then return nil end
    return Color3.fromRGB(
        tonumber(hex:sub(1,2), 16) or 0,
        tonumber(hex:sub(3,4), 16) or 0,
        tonumber(hex:sub(5,6), 16) or 0)
end

function hashString(s)
    local h = 5381
    for i = 1, #s do h = ((h * 33) + s:byte(i)) % 0x7FFFFFFF end
    return string.format("%x", h)
end

function getAsset(path)
    if not path or path == "" then return nil end
    if assetCache[path] then return assetCache[path] end
    if not waxgetcustomasset then return nil end
    local ok, asset = pcall(waxgetcustomasset, path)
    if ok and asset then
        assetCache[path] = asset
        return asset
    end
    return nil
end

function detectImageKind(data)
    if type(data) ~= "string" or #data < 12 then return nil, "empty response" end
    if data:sub(1, 8) == "\137PNG\r\n\26\n" then return "png" end
    if data:sub(1, 3) == "\255\216\255" then return "jpg" end
    if data:sub(1, 4) == "GIF8" then return nil, "GIF (Roblox cannot load GIF)" end
    if data:sub(1, 4) == "RIFF" and data:sub(9, 12) == "WEBP" then return nil, "WebP (Roblox cannot load WebP)" end
    local head = data:sub(1, 60):lower()
    if head:find("<!doctype") or head:find("<html") or head:find("{") then
        return nil, "not an image (got text/HTML/JSON, likely a 404 or error page)"
    end
    return nil, "unknown file format"
end

function urlEncode(s)
    local s2 = tostring(s)
    local out = {}
    for i = 1, #s2 do
        local b = string.byte(s2, i)
        local keep = (b >= 48 and b <= 57) or (b >= 65 and b <= 90) or (b >= 97 and b <= 122)
            or b == 45 or b == 46 or b == 95 or b == 126
        out[#out + 1] = keep and string.char(b) or string.format("%%%02X", b)
    end
    return table.concat(out)
end

function prefersDirectDownload(url)
    url = tostring(url):lower()
    return url:find("raw%.githubusercontent%.com", 1, false)
        or url:find("i%.postimg%.cc", 1, false)
        or url:find("postimg%.cc", 1, false)
        or url:find("i%.imgur%.com", 1, false)
        or url:find("cdn%.jsdelivr%.net", 1, false)
        or url:find("%.png", 1, true)
        or url:find("%.jpg", 1, true)
        or url:find("%.jpeg", 1, true)
end

function normalizeImageUrl(url)

    if url:find("wsrv.nl", 1, true) then
        if not url:find("output=", 1, true) then
            url = url .. (url:find("?", 1, true) and "&" or "?") .. "output=png&il=0"
        end
        return url
    end
    return "https://wsrv.nl/?url=" .. urlEncode(url) .. "&output=png&il=0"
end

downloadFailedAt = {}

function downloadImageForUser(userId, url)
    if type(url) ~= "string" or url == "" then return nil end
    url = url:gsub("^%s+", ""):gsub("%s+$", "")

    local mdText, mdTarget, mdRest = url:match("^%[(.-)%]%((.-)%)(.*)$")
    if mdText then
        if mdRest ~= "" then url = mdText .. mdRest else url = mdTarget end
    end
    url = url:gsub("^[%s\"'<]+", ""):gsub("[%s\"'>]+$", "")
    if not url:match("^https?://") then
        local found = url:find("https?://")
        if found then url = url:sub(found) end
    end
    if not url:match("^https?://") then
        return nil
    end

    if downloadFailedAt[url] and tick() - downloadFailedAt[url] < 30 then return nil end

    local candidates, seen = {}, {}
    local function addCandidate(u)
        if u and u ~= "" and not seen[u] then seen[u] = true; candidates[#candidates + 1] = u end
    end
    local directFirst = prefersDirectDownload(url)
    if directFirst then
        addCandidate(url)
        addCandidate(normalizeImageUrl(url))
    else
        addCandidate(normalizeImageUrl(url))
        addCandidate(url)
    end
    if url:find("wsrv.nl", 1, true) then
        local inner = url:match("[?&]url=([^&]+)")
        if inner then
            inner = inner:gsub("%%(%x%x)", function(h) return string.char(tonumber(h, 16) or 0) end)
            if not inner:match("^https?://") then inner = "https://" .. inner end
            addCandidate(inner)
        end
    end

    local folder = "monochrome/nametags/supabase/user_" .. tostring(userId)
    if makefolder and not isfolder(folder) then pcall(makefolder, folder) end

    local base = folder .. "/" .. hashString(url)

    for _, ext in ipairs({ ".png", ".jpg" }) do
        local cached = base .. ext
        if isfile and isfile(cached) then
            local okRead, existing = pcall(readfile, cached)
            if okRead and detectImageKind(existing) then return cached end
            pcall(delfile, cached)
        end
    end

    for _, tryUrl in ipairs(candidates) do
        local data, status
        if httprequest then
            local ok, r = pcall(httprequest, { Url = tryUrl, Method = "GET" })
            if ok and r then
                data   = r.Body or r.body
                status = r.StatusCode or r.status
            end
        else
            local ok, r = pcall(function() return game:HttpGet(tryUrl) end)
            if ok then data = r end
        end

        local badStatus = status and (status < 200 or status >= 300)
        if not badStatus then
            local kind = detectImageKind(data)
            if kind then
                local path = base .. "." .. kind
                if pcall(function() writefile(path, data) end) then
                    return path
                end
            end
        end
    end

    downloadFailedAt[url] = tick()
    return nil
end

function parseFrameUrlList(text)
    local urls = {}
    if type(text) ~= "string" or text == "" then return urls end
    for u in text:gmatch("https?://[^%s,<>\"']+") do
        u = u:gsub("[%.,;]+$", "")
        if u ~= "" then urls[#urls + 1] = u end
    end
    return urls
end

function downloadFrameAssets(userId, urls)
    local assets = {}
    if type(urls) ~= "table" then return assets end
    for i = 1, #urls do
        local path = downloadImageForUser(userId, urls[i])
        if path then
            local asset = getAsset(path)
            if asset then
                assets[#assets + 1] = asset
            end
        end
    end
    return assets
end

function buildConfigFromRow(userId, row)
    local imagePath = nil
    if row.background_image and row.background_image ~= "" then
        imagePath = downloadImageForUser(userId, row.background_image)
    end

    local frameAssets = {}
    local frameUrlList = parseFrameUrlList(row.frame_urls)
    if #frameUrlList > 0 then
        frameAssets = downloadFrameAssets(userId, frameUrlList)
    end
    local frameAnimActive = #frameAssets >= 2
    local frameTime = tonumber(row.frame_time) or 0.1

    return {
        userIds           = {},
        imagePath         = imagePath,
        borderColor       = hexToColor3(row.border_color),
        gradientColor     = hexToColor3(row.gradient_color),
        gradientSpinColor = hexToColor3(row.gradient_spin_color),
        bgColor           = hexToColor3(row.background_color),
        textColor         = hexToColor3(row.text_color),
        usernameColor     = hexToColor3(row.username_color),

        displayNameText   = (row.display_name_override ~= nil and row.display_name_override ~= "" and row.display_name_override) or row.display_name,
        usernameText      = (row.username_override ~= nil and row.username_override ~= "" and row.username_override) or row.username,
        showDisplayName   = not (row.show_display_name == false or row.show_display_name == 0
            or row.show_display_name == "false" or row.show_display_name == "0"),
        showUsername      = not (row.show_username == false or row.show_username == 0
            or row.show_username == "false" or row.show_username == "0"),
        usernamePrefix    = row.username_prefix,
        typingText        = row.typing_text,
        distanceLabel     = row.distance_label,
        font              = safeFont(row.font, nil),
        textSize          = tonumber(row.text_size),
        usernameSize      = tonumber(row.username_size),
        width             = tonumber(row.nametag_width),
        height            = tonumber(row.nametag_height),
        isAnimated        = frameAnimActive,
        frameBasePath     = nil,
        frameCount        = #frameAssets,
        frameAssets       = frameAssets,
        frameTime         = frameTime,
        _fromSupabase = true,
    }
end

playerPresence = {}
presenceFetched = false

function _isPlayerRunning(uid)
    if uid == LocalPlayer.UserId then return true end
    return playerPresence[tonumber(uid)] == true
end

function getNametagConfig(userId)
    userId = tonumber(userId)

    if userId ~= LocalPlayer.UserId and presenceFetched
        and playerPresence[userId] == false then
        return nil
    end
    local row = remoteConfigs[userId]
    if row then
        if row.enabled == false then return nil end
        local sig = rowSignature(row)
        local cached = configCache[userId]
        if cached and cached.sig == sig then return cached.config end

        local cfg = buildConfigFromRow(userId, row)

    local wantsImage  = row.background_image and row.background_image ~= ""
        local wantsFrames = row.frame_urls and row.frame_urls ~= ""
        local complete = (not wantsImage or cfg.imagePath ~= nil or wantsFrames)
                     and (not wantsFrames or (cfg.frameAssets and #cfg.frameAssets >= 1))
        if complete then configCache[userId] = { sig = sig, config = cfg } end
        return cfg
    end
    return nil
end

function getUserInfo()
    local player = Players.LocalPlayer
    if not player then return nil end
    local placeName = "Unknown"
    pcall(function()
        local ok, info = pcall(function()
            return game:GetService("MarketplaceService"):GetProductInfoAsync(game.PlaceId)
        end)
        if ok and info then placeName = info.Name or "Unknown" end
    end)
    return {
        user_id      = player.UserId,
        username     = player.Name,
        display_name = player.DisplayName or player.Name,
        job_id       = game.JobId,
        game_name    = placeName,
        last_seen    = DateTime.now():ToIsoDate(),
    }
end
rowVersions = {}
NO_VERSION = "\1no-version"

lastPresence = nil
lastPresenceAt = 0

function inList(ids)
    local parts = {}
    for i = 1, #ids do parts[i] = tostring(ids[i]) end
    return "%28" .. table.concat(parts, "%2C") .. "%29"
end

function serverUserIds()
    local ids = {}
    for _, plr in ipairs(Players:GetPlayers()) do ids[#ids + 1] = plr.UserId end
    return ids
end
function parseIsoDate(value)
    if type(value) ~= "string" or value == "" then return nil end
    local ok, dt = pcall(function() return DateTime.fromIsoDate(value) end)
    if not ok or not dt then return nil end
    return dt
end

function fetchPresence(ids)
    if #ids == 0 then return end
    local rows = supabaseGet(SUPABASE.usersTable .. "?select=user_id,last_seen&user_id=in." .. inList(ids))
    if type(rows) ~= "table" then return end
    local now = DateTime.now()
    local nextPresence = {}
    for _, id in ipairs(ids) do nextPresence[tonumber(id)] = false end
    for _, row in ipairs(rows) do
        local uid = tonumber(row.user_id)
        if uid then
            local seen = parseIsoDate(row.last_seen)
            if seen and (now.UnixTimestamp - seen.UnixTimestamp) < SUPABASE.presenceStaleAfter then
                nextPresence[uid] = true
            end
        end
    end
    playerPresence = nextPresence
    presenceFetched = true
end

function markPresenceOffline(uid)
    return supabaseRequest("PATCH", SUPABASE.usersTable .. "?user_id=eq." .. tostring(uid),
        { last_seen = DateTime.fromUnixTimestamp(DateTime.now().UnixTimestamp - 7200):ToIsoDate() },
        { ["Prefer"] = "return=minimal" })
end

function fetchTagVersions(ids)
    if #ids == 0 then return nil end
    return supabaseGet(SUPABASE.tagsTable
        .. "?select=user_id,version&user_id=in." .. inList(ids))
end

function fetchTagRows(ids)
    if #ids == 0 then return nil end
    return supabaseGet(SUPABASE.tagsTable
        .. "?select=*&user_id=in." .. inList(ids))
end

function syncPresence(force)
    local i = getUserInfo()
    if not i then return end
    local changed = force or lastPresence == nil
    if not changed and lastPresence then
        changed = lastPresence.username ~= i.username
            or lastPresence.display_name ~= i.display_name
            or lastPresence.job_id ~= i.job_id
            or lastPresence.game_name ~= i.game_name
    end
    if not changed and (tick() - lastPresenceAt) < SUPABASE.presenceInterval then return end
    local res = registerUser(i.user_id, i.username, i.display_name, i.job_id, i.game_name)
    if res == nil then
        lastPresence = nil
        lastPresenceAt = 0
        return
    end
    lastPresence = i
    lastPresenceAt = tick()
end

function ensureOwnRowIfMissing(present)
    if present then return end
    local i = getUserInfo()
    if not i then return end
    pcall(function() ensureNametagRow(i.user_id, i.username, i.display_name) end)
end

function syncTags()
    local ids = serverUserIds()
    pcall(fetchPresence, ids)
    local rows = fetchTagVersions(ids)
    if rows == nil then
        return false
    end

    local versions, present = {}, false
    for _, row in ipairs(rows) do
        local uid = tonumber(row.user_id)
        if uid then
            versions[uid] = row.version == nil and NO_VERSION or row.version
            if LocalPlayer and uid == LocalPlayer.UserId then present = true end
        end
    end

    local toFetch = {}
    for uid, ver in pairs(versions) do
        if ver == NO_VERSION or rowVersions[uid] ~= ver then toFetch[#toFetch + 1] = uid end
    end

    if #rows > 0 then
        for uid in pairs(rowVersions) do
            if versions[uid] == nil then
                remoteConfigs[uid] = nil
                configCache[uid] = nil
                rowVersions[uid] = nil
                appliedSignatures[uid] = nil
                MonochromeNametags.removeOtherNametag(uid)
            end
        end
    end

    local full = fetchTagRows(toFetch)
    if full then
        local fetched = {}
        for _, row in ipairs(full) do
            local uid = tonumber(row.user_id)
            if uid and fetched[uid] == nil then
                fetched[uid] = true
                remoteConfigs[uid] = row
                configCache[uid] = nil
            end
        end
        for _, uid in ipairs(toFetch) do
            if versions[uid] ~= NO_VERSION then rowVersions[uid] = versions[uid] end
        end
    end

    ensureOwnRowIfMissing(present)
    return true
end

typingEffectConnections = {}

function stopTypingEffect(textLabel)
    if typingEffectConnections[textLabel] then
        for _, c in ipairs(typingEffectConnections[textLabel]) do c:Disconnect() end
        typingEffectConnections[textLabel] = nil
    end
end

function startTypingEffect(textLabel, displayName, typingText)
    stopTypingEffect(textLabel)
    local connections = {}
    local targetText = displayName .. "  " .. (typingText or "Owner")
    local dotChar = "."
    local visibleLength = 0
    local isHiding = false
    local showCursor = true
    local lastCursorToggle = tick()
    local lastUpdate = tick()
    local lastCycleStart = tick()
    local dotPosition = #displayName + 2

    local hb = RunService.Heartbeat:Connect(function()
        if not textLabel or not textLabel.Parent then return end
        local now = tick()
        if now - lastCursorToggle >= 0.5 then
            showCursor = not showCursor; lastCursorToggle = now
        end
        if now - lastCycleStart >= 5 then isHiding = true; lastCycleStart = now end
        if now - lastUpdate >= 0.05 then
            if isHiding then
                if visibleLength > 0 then visibleLength = visibleLength - 1
                else isHiding = false end
            else
                if visibleLength < #targetText then visibleLength = visibleLength + 1 end
            end
            lastUpdate = now
        end
        local displayText = targetText:sub(1, visibleLength)
        if not isHiding and visibleLength >= dotPosition then
            local beforeDot = displayText:sub(1, dotPosition - 1)
            local afterDot  = displayText:sub(dotPosition)
            displayText = beforeDot .. dotChar .. afterDot
        end
        textLabel.Text = displayText .. (showCursor and "|" or "")
    end)
    table.insert(connections, hb)
    typingEffectConnections[textLabel] = connections
end

frameAnimationConnections = {}
frameLabelsRegistry       = {}

function stopFrameAnimation(parentFrame)
    if frameAnimationConnections[parentFrame] then
        for _, c in ipairs(frameAnimationConnections[parentFrame]) do c:Disconnect() end
        frameAnimationConnections[parentFrame] = nil
    end
    local frameLabels = frameLabelsRegistry[parentFrame]
    if frameLabels then
        for _, fl in pairs(frameLabels) do pcall(function() fl:Destroy() end) end
        frameLabelsRegistry[parentFrame] = nil
    end
    if parentFrame and parentFrame.Parent then
        for _, child in ipairs(parentFrame:GetChildren()) do
            if child.Name:sub(1, 6) == "Frame_" then pcall(function() child:Destroy() end) end
        end
    end
end

function startFrameAnimation(parentFrame, config)
    local labels = {}

    if type(config.frameAssets) == "table" and #config.frameAssets >= 1 then
        for i = 1, #config.frameAssets do
            local frameLabel = Instance.new("ImageLabel")
            frameLabel.Name = "Frame_" .. (i - 1)
            frameLabel.Size = UDim2.new(1, 0, 1, 0)
            frameLabel.BackgroundTransparency = 1
            frameLabel.Image = config.frameAssets[i]
            frameLabel.ScaleType = Enum.ScaleType.Stretch
            frameLabel.Visible = (i == 1)
            frameLabel.ZIndex = -1
            frameLabel.Parent = parentFrame
            local bgCorner = Instance.new("UICorner")
            bgCorner.CornerRadius = UDim.new(0, 8)
            bgCorner.Parent = frameLabel
            labels[#labels + 1] = frameLabel
        end
    elseif config.isAnimated and (config.frameCount or 0) > 1 and config.frameBasePath then
        local frameBasePath = config.frameBasePath or ""
        local frameCount = config.frameCount or 1
        for i = 0, frameCount - 1 do
            local framePath = frameBasePath .. i .. ".png"
            if isfile and isfile(framePath) then
                local frameAsset = getAsset(framePath)
                if frameAsset then
                    local frameLabel = Instance.new("ImageLabel")
                    frameLabel.Name = "Frame_" .. i
                    frameLabel.Size = UDim2.new(1, 0, 1, 0)
                    frameLabel.BackgroundTransparency = 1
                    frameLabel.Image = frameAsset
                    frameLabel.ScaleType = Enum.ScaleType.Stretch
                    frameLabel.Visible = (#labels == 0)
                    frameLabel.ZIndex = -1
                    frameLabel.Parent = parentFrame
                    local bgCorner = Instance.new("UICorner")
                    bgCorner.CornerRadius = UDim.new(0, 8)
                    bgCorner.Parent = frameLabel
                    labels[#labels + 1] = frameLabel
                end
            end
        end
    end

    if #labels == 0 then return end
    local registry = {}
    for i = 1, #labels do registry[i - 1] = labels[i] end
    frameLabelsRegistry[parentFrame] = registry

    if #labels == 1 then return end

    local currentFrame    = 1
    local lastFrameUpdate = tick()
    local frameTime       = config.frameTime or 0.1
    local frameCount      = #labels

    local hb = RunService.Heartbeat:Connect(function()
        if not parentFrame or not parentFrame.Parent then return end
        local now = tick()
        if now - lastFrameUpdate >= frameTime then
            labels[currentFrame].Visible = false
            currentFrame = currentFrame % frameCount + 1
            lastFrameUpdate = now
            labels[currentFrame].Visible = true
        end
    end)
    frameAnimationConnections[parentFrame] = { hb }
end

function cleanupBillboardEffects(billboard)
    if not billboard then return end
    local tagFrame = billboard:FindFirstChild("TagFrame")
    if not tagFrame then return end
    local dn = tagFrame:FindFirstChild("DisplayName")
    if dn then stopTypingEffect(dn) end
    if frameAnimationConnections[tagFrame] then stopFrameAnimation(tagFrame) end
end

nametagEnabled       = true
nametagGui           = nil
nametagConnection    = nil
otherNametags        = {}
autoSyncEnabled      = true
originalDisplayTypes = {}
hiddenHumanoids      = {}
characterAddedConns  = {}
nametagConns          = {}
nametagGeneration     = 0

function monoGuiContainers()
    local list, seen = {}, {}
    local function push(inst)
        if inst and not seen[inst] then
            seen[inst] = true
            table.insert(list, inst)
        end
    end
    push(monoGuiRoot())
    push(CoreGui)
    push(PlayerGui)
    return list
end

function isNametagBillboard(child)
    if not child or typeof(child) ~= "Instance" then return false end
    local n = child.Name
    return n == "MonochromeNametag" or n:sub(1, #"MonochromeNametag_") == "MonochromeNametag_"
end

function purgeTagsByName(name)
    for _, host in ipairs(monoGuiContainers()) do
        for _, child in ipairs(host:GetChildren()) do
            if child.Name == name then
                cleanupBillboardEffects(child)
                pcall(function() child:Destroy() end)
            end
        end
    end
end

function MonochromeNametags.clearAllNametags()
    for textLabel in pairs(typingEffectConnections) do stopTypingEffect(textLabel) end
    for imageLabel in pairs(frameAnimationConnections) do stopFrameAnimation(imageLabel) end

    for _, host in ipairs(monoGuiContainers()) do
        for _, child in ipairs(host:GetChildren()) do
            if isNametagBillboard(child) then
                cleanupBillboardEffects(child)
                pcall(function() child:Destroy() end)
            end
        end
    end

    for _, tagData in pairs(otherNametags) do
        if tagData.connection then tagData.connection:Disconnect() end
    end
    otherNametags = {}
    if nametagConnection then nametagConnection:Disconnect(); nametagConnection = nil end
    nametagGui = nil
end

function buildMonochromeBillboard(player, config, head, isSelf)
    local hasCustomTag =
        config ~= nil and (
            config.imagePath ~= nil
            or config.isAnimated == true
        )

    local userBgColor           = config and config.bgColor or nil
    local userBorderColor       = (config and config.borderColor) or C.sep
    local userGradientColor     = config and config.gradientColor or nil
    local userGradientSpinColor = config and config.gradientSpinColor or nil

    local width  = (config and config.width)  or 150
    local height = (config and config.height) or 50

    local character = head and head.Parent
    local attachment = (character and character:FindFirstChild("HumanoidRootPart")) or head

    local billboard = Instance.new("BillboardGui")
    billboard.Name = isSelf and "MonochromeNametag" or ("MonochromeNametag_" .. player.UserId)
    billboard.Size = UDim2.new(0, width, 0, height)
    billboard.StudsOffsetWorldSpace = Vector3.new(0, MONO_NAMETAG_Y, 0)
    billboard.Adornee = attachment
    billboard.AlwaysOnTop = true
    billboard.MaxDistance = math.huge
    billboard.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    billboard.ClipsDescendants = false
    billboard.ResetOnSpawn = false
    if not isSelf then billboard.Active = true end
    pcall(function() billboard.DisplayOrder = MONO_ORDER.Toast end)
    monoGuiParent(billboard)

    local bgFrame = Instance.new("Frame")
    bgFrame.Name = "BgFrame"
    bgFrame.Size = UDim2.new(1, 4, 1, 4)
    bgFrame.Position = UDim2.new(0, -2, 0, -2)
    bgFrame.BackgroundColor3 = userBorderColor
    bgFrame.BorderSizePixel = 0
    bgFrame.Parent = billboard
    local bgCorner = Instance.new("UICorner")
    bgCorner.CornerRadius = UDim.new(0, 10)
    bgCorner.Parent = bgFrame

    local bgGradient = Instance.new("UIGradient")
    if hasCustomTag and userGradientColor and userGradientSpinColor then
        bgGradient.Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0,    userGradientSpinColor),
            ColorSequenceKeypoint.new(0.25, userGradientColor),
            ColorSequenceKeypoint.new(0.5,  userGradientSpinColor),
            ColorSequenceKeypoint.new(0.75, userGradientColor),
            ColorSequenceKeypoint.new(1,    userGradientSpinColor),
        })
    else
        bgGradient.Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0,    Color3.fromRGB(255,255,255)),
            ColorSequenceKeypoint.new(0.25, C.sep),
            ColorSequenceKeypoint.new(0.5,  Color3.fromRGB(20,20,20)),
            ColorSequenceKeypoint.new(0.75, C.sep),
            ColorSequenceKeypoint.new(1,    Color3.fromRGB(255,255,255)),
        })
    end
    bgGradient.Parent = bgFrame

    local frame = Instance.new("Frame")
    frame.Name = "TagFrame"
    frame.Size = UDim2.new(1, 0, 1, 0)
    frame.BackgroundColor3 = userBgColor or C.card
    frame.BackgroundTransparency =
        (userBgColor and 1)
        or (hasCustomTag and config.isAnimated and 1)
        or 0.1
    frame.BorderSizePixel = 0
    if not isSelf then frame.Active = true end
    frame.ClipsDescendants = true
    frame.Parent = billboard

    if config and ((config.frameAssets and #config.frameAssets >= 1) or (config.isAnimated and config.frameBasePath)) then
        startFrameAnimation(frame, config)

    elseif config and config.imagePath and isfile and isfile(config.imagePath) then
        local customAsset = getAsset(config.imagePath)
        if customAsset then
            local bgImage = Instance.new("ImageLabel")
            bgImage.Name = "BgImage"
            bgImage.Size = UDim2.new(1, 0, 1, 0)
            bgImage.BackgroundTransparency = 1
            bgImage.Image = customAsset
            bgImage.ScaleType = Enum.ScaleType.Stretch
            frame.BackgroundTransparency = 1
            bgImage.ZIndex = 1
            bgImage.Parent = frame
            local bc = Instance.new("UICorner")
            bc.CornerRadius = UDim.new(0, 8)
            bc.Parent = bgImage
        end
    end

    local tagCorner = Instance.new("UICorner")
    tagCorner.CornerRadius = UDim.new(0, 8)
    tagCorner.Parent = frame

    local displayNameLabel = Instance.new("TextLabel")
    displayNameLabel.Name = "DisplayName"
    displayNameLabel.Size = UDim2.new(1, -10, 0, 20)
    displayNameLabel.Position = UDim2.new(0, 5, 0, 5)
    displayNameLabel.BackgroundTransparency = 1
    local showDisplayName = true
    if config then
        local sd = config.showDisplayName
        if sd == false or sd == 0 or sd == "false" or sd == "0" then
            showDisplayName = false
        end
    end
    local nameText = ""
    if showDisplayName then
        nameText = (config and config.displayNameText) or player.DisplayName or ""
    end
    local hasTyping = showDisplayName and config and config.typingText and config.typingText ~= ""
    displayNameLabel.Text = hasTyping and "" or nameText
    displayNameLabel.Visible = showDisplayName and (hasTyping or nameText ~= "")
    displayNameLabel.TextColor3 = (config and config.textColor) or C.text
    displayNameLabel.TextSize   = (config and config.textSize) or 14
    displayNameLabel.Font       = (config and config.font) or Enum.Font.GothamBold
    displayNameLabel.TextXAlignment = Enum.TextXAlignment.Center
    displayNameLabel.ZIndex = 2
    displayNameLabel.Parent = frame
    displayNameLabel:SetAttribute("MonochromeShowDisplayName", showDisplayName and (hasTyping or nameText ~= ""))

    if hasTyping then
        startTypingEffect(displayNameLabel, nameText, config.typingText)
    end

    local showUsername = true
    if config then
        local su = config.showUsername
        if su == false or su == 0 or su == "false" or su == "0" then
            showUsername = false
        end
    end

    frame:SetAttribute("MonochromeShowDisplayName", showDisplayName == true)
    frame:SetAttribute("MonochromeShowUsername", showUsername == true)

    local usernameLabel = Instance.new("TextLabel")
    usernameLabel.Name = "Username"
    usernameLabel.Size = UDim2.new(1, -10, 0, 16)

    usernameLabel.Position = UDim2.new(0, 5, 0, showDisplayName and 25 or 5)
    usernameLabel.BackgroundTransparency = 1
    local unameText = ""
    if showUsername then
        unameText = (config and config.usernameText) or ""
        if unameText ~= "" then
            local prefix = (config and config.usernamePrefix) or "@"
            if prefix ~= "" and unameText:sub(1, #prefix) ~= prefix and unameText:sub(1, 1) ~= "@" then
                unameText = prefix .. unameText
            end
        else
            local prefix = (config and config.usernamePrefix)
            if prefix == nil then prefix = "@" end
            local namePart = player.Name or ""
            if namePart ~= "" then
                unameText = tostring(prefix) .. namePart
            else
                unameText = ""
            end
        end
        local stripped = unameText:gsub("^[%s@]+", ""):gsub("%s+$", "")
        if stripped == "" then unameText = "" end
    end
    usernameLabel.Text = unameText
    usernameLabel.TextColor3 = (config and config.usernameColor) or (hasCustomTag and C.text or C.textDim)
    usernameLabel.TextSize   = (config and config.usernameSize) or 11
    usernameLabel.Font       = Enum.Font.Gotham
    usernameLabel.TextXAlignment = Enum.TextXAlignment.Center
    usernameLabel.ZIndex     = 2

    if showUsername and unameText ~= "" then
        usernameLabel.Visible = true
        usernameLabel.Parent = frame
    else
        usernameLabel.Text = ""
        usernameLabel.Visible = false
        usernameLabel.Parent = frame
    end
    usernameLabel:SetAttribute("MonochromeShowUsername", showUsername and unameText ~= "")

    local smallLabel = Instance.new("TextLabel")
    smallLabel.Name = "SmallLabel"
    smallLabel.Size = UDim2.new(1, 0, 1, 0)
    smallLabel.BackgroundTransparency = 1
    
    
    smallLabel.Text = (config and config.distanceLabel) or "M"
    smallLabel.TextColor3 = (config and config.textColor) or C.text
    smallLabel.TextSize = (config and config.textSize) or 20
    smallLabel.Font = (config and config.font) or Enum.Font.GothamBold
    smallLabel.TextXAlignment = Enum.TextXAlignment.Center
    smallLabel.TextYAlignment = Enum.TextYAlignment.Center
    smallLabel.Visible = false
    smallLabel.ZIndex = 2
    smallLabel.Parent = frame

    return billboard, bgGradient, frame, displayNameLabel, usernameLabel, smallLabel, width, height
end

function MonochromeNametags.removeNametag()
    if nametagGui then
        cleanupBillboardEffects(nametagGui)
        pcall(function() nametagGui:Destroy() end)
        nametagGui = nil
    end
    if nametagConnection then nametagConnection:Disconnect(); nametagConnection = nil end
    if Players.LocalPlayer then appliedSignatures[Players.LocalPlayer.UserId] = nil end
end

creatingSelf = false
function MonochromeNametags.createNametag()

    if creatingSelf then return end
    if not monoLoadDone then return end
    creatingSelf = true
    pcall(MonochromeNametags._createNametag)
    creatingSelf = false
end



function monoNametagConfigFor(plr)
    local uid = plr.UserId
    
    
    
    if uid ~= LocalPlayer.UserId and presenceFetched
        and playerPresence[tonumber(uid)] == false then
        return nil
    end
    local cfg = getNametagConfig(uid)
    if cfg then return cfg end
    
    
    local row = remoteConfigs[uid]
    if row and row.enabled ~= false then
        return buildConfigFromRow(uid, row)
    end
    return nil
end

function MonochromeNametags._createNametag()
    local gen = nametagGeneration
    local player = Players.LocalPlayer
    if not player.Character then return end
    local head = player.Character:FindFirstChild("Head")
    if not head then return end

    configCache[player.UserId] = nil
    appliedSignatures[player.UserId] = nil

    local config = monoNametagConfigFor(player)
    if gen ~= nametagGeneration then return end
    head = player.Character and player.Character:FindFirstChild("Head")
    if not head then return end

    if not config then
        if nametagGui and nametagGui.Parent then
            appliedSignatures[player.UserId] = rowSignature(remoteConfigs[player.UserId])
            return
        end
        nametagGui = nil
        appliedSignatures[player.UserId] = rowSignature(remoteConfigs[player.UserId])
        MonochromeNametags.restoreDefaultNametag(player)
        return
    end

    MonochromeNametags.removeNametag()
    purgeTagsByName("MonochromeNametag")

    local bb, bgGradient = buildMonochromeBillboard(player, config, head, true)
    nametagGui = bb
    appliedSignatures[player.UserId] = rowSignature(remoteConfigs[player.UserId])
    if nametagEnabled then MonochromeNametags.hideDefaultNametag(player) end

    local tagY = MONO_NAMETAG_Y
    local gradAcc = 0
    nametagConnection = RunService.Heartbeat:Connect(function(dt)
        if not bb or not bb.Parent then return end
        gradAcc += dt
        if gradAcc >= 0.033 then
            local gstep = gradAcc
            gradAcc = 0
            if bgGradient and bgGradient.Parent then
                bgGradient.Rotation = (bgGradient.Rotation + 120 * gstep) % 360
            end
        end
        local charNow = player.Character
        local currentHead = charNow and charNow:FindFirstChild("Head")
        if currentHead then
            local currentRoot = charNow:FindFirstChild("HumanoidRootPart")
            bb.Adornee = currentRoot or currentHead
            bb.Enabled = nametagEnabled
            local targetY = monoNametagY(player.UserId, MONO_NAMETAG_Y)
            local alpha = 1 - math.exp(-10 * dt)
            tagY = tagY + (targetY - tagY) * alpha
            if math.abs(targetY - tagY) < 0.001 then tagY = targetY end
            pcall(function() bb.StudsOffsetWorldSpace = Vector3.new(0, tagY, 0) end)
        else
            bb.Enabled = false
        end
    end)
end

function MonochromeNametags.removeOtherNametag(userId)
    local entry = otherNametags[userId]
    if entry then
        if entry.gui then
            cleanupBillboardEffects(entry.gui)
            pcall(function() entry.gui:Destroy() end)
        end
        if entry.connection then entry.connection:Disconnect() end
        otherNametags[userId] = nil
    end
    appliedSignatures[userId] = nil
    local plr = Players:GetPlayerByUserId(userId)
    if plr then MonochromeNametags.restoreDefaultNametag(plr) end
end

creatingOther = {}
function MonochromeNametags.selfTagLive()
    return nametagGui ~= nil and nametagGui.Parent ~= nil
end

function MonochromeNametags.otherTagLive(userId)
    local e = otherNametags[userId]
    return e ~= nil and e.gui ~= nil and e.gui.Parent ~= nil
end

function MonochromeNametags.waitForHead(plr)
    for _ = 1, 40 do
        if plr.Character and plr.Character:FindFirstChild("Head") then return true end
        task.wait(0.1)
    end
    return false
end

function MonochromeNametags.createOtherNametag(plrObj)
    if not monoLoadDone then return false end
    if creatingOther[plrObj.UserId] then return MonochromeNametags.otherTagLive(plrObj.UserId) end
    creatingOther[plrObj.UserId] = true
    pcall(MonochromeNametags._createOtherNametag, plrObj)
    creatingOther[plrObj.UserId] = nil
    return MonochromeNametags.otherTagLive(plrObj.UserId)
end

function MonochromeNametags._createOtherNametag(plrObj)
    local gen = nametagGeneration
    if not plrObj.Character then return end
    local head = plrObj.Character:FindFirstChild("Head")
    if not head then return end

    configCache[plrObj.UserId] = nil
    appliedSignatures[plrObj.UserId] = nil

    local config = monoNametagConfigFor(plrObj)
    if gen ~= nametagGeneration then return end
    head = plrObj.Character and plrObj.Character:FindFirstChild("Head")
    if not head then return end

    if not config then
        if otherNametags[plrObj.UserId] then
            MonochromeNametags.removeOtherNametag(plrObj.UserId)
        end
        return
    end

    if otherNametags[plrObj.UserId] then
        MonochromeNametags.removeOtherNametag(plrObj.UserId)
    end
    purgeTagsByName("MonochromeNametag_" .. plrObj.UserId)

    local bb, bgGradient, frame, dn, un, sl, width, height =
        buildMonochromeBillboard(plrObj, config, head, false)

    frame.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 then
            local myChar = Players.LocalPlayer.Character
            local targetChar = plrObj.Character
            if myChar and myChar:FindFirstChild("HumanoidRootPart") and targetChar and targetChar:FindFirstChild("HumanoidRootPart") then
                local myHRP = myChar.HumanoidRootPart
                local targetHRP = targetChar.HumanoidRootPart
                local behind = targetHRP.CFrame * CFrame.new(0, 0, 3)
                myHRP.CFrame = CFrame.new(behind.Position, behind.Position + targetHRP.CFrame.LookVector)
            end
        end
    end)

    local lastFar = nil
    local tagY = MONO_NAMETAG_Y
    local gradAcc = 0
    local connection = RunService.Heartbeat:Connect(function(dt)
        if not bb or not bb.Parent then return end
        gradAcc += dt
        if gradAcc >= 0.033 then
            local gstep = gradAcc
            gradAcc = 0
            if bgGradient and bgGradient.Parent then
                bgGradient.Rotation = (bgGradient.Rotation + 120 * gstep) % 360
            end
        end
        local targetChar = plrObj.Character
        local targetHead = targetChar and targetChar:FindFirstChild("Head")
        if targetHead then
            local targetRoot = targetChar:FindFirstChild("HumanoidRootPart")
            bb.Adornee = targetRoot or targetHead
            bb.Enabled = nametagEnabled and not monoHiddenPlayers[plrObj.UserId]
            local targetY = monoNametagY(plrObj.UserId, MONO_NAMETAG_Y)
            local alpha = 1 - math.exp(-10 * dt)
            tagY = tagY + (targetY - tagY) * alpha
            if math.abs(targetY - tagY) < 0.001 then tagY = targetY end
            pcall(function() bb.StudsOffsetWorldSpace = Vector3.new(0, tagY, 0) end)
        else
            bb.Enabled = false
            return
        end
        local myChar = Players.LocalPlayer.Character
        if myChar and myChar:FindFirstChild("HumanoidRootPart") and targetChar and targetChar:FindFirstChild("HumanoidRootPart") then
            local dist = (myChar.HumanoidRootPart.Position - targetChar.HumanoidRootPart.Position).Magnitude
            local isFar = dist > 50
            local showDn = frame:GetAttribute("MonochromeShowDisplayName")
            if showDn == nil then showDn = dn:GetAttribute("MonochromeShowDisplayName") end
            if showDn == nil then showDn = true end
            local showUn = frame:GetAttribute("MonochromeShowUsername")
            if showUn == nil then showUn = un:GetAttribute("MonochromeShowUsername") end
            if showUn == nil then showUn = false end

            dn.Visible = (not isFar) and (showDn == true)
            un.Visible = (not isFar) and (showUn == true) and un.Text ~= ""
            sl.Visible = isFar
            if lastFar ~= isFar then
                lastFar = isFar
                ntTween(bb, 0.1, { Size = isFar and UDim2.new(0, 40, 0, 40) or UDim2.new(0, width, 0, height) })
            end
        end
    end)

    otherNametags[plrObj.UserId] = { gui = bb, connection = connection }
    appliedSignatures[plrObj.UserId] = rowSignature(remoteConfigs[plrObj.UserId])

    if nametagEnabled then MonochromeNametags.hideDefaultNametag(plrObj) end
end

function MonochromeNametags.hideDefaultNametag(plr)
    if not plr or not plr.Character then return end
    local humanoid = plr.Character:FindFirstChildWhichIsA("Humanoid")
    if not humanoid then return end
    if hiddenHumanoids[plr.UserId] == humanoid then return end
    originalDisplayTypes[plr.UserId] = humanoid.DisplayDistanceType
    hiddenHumanoids[plr.UserId] = humanoid
    humanoid.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
end

function MonochromeNametags.restoreDefaultNametag(plr)
    if not plr then return end
    local saved = originalDisplayTypes[plr.UserId]
    local humanoid = plr.Character and plr.Character:FindFirstChildWhichIsA("Humanoid")
    if humanoid then
        humanoid.DisplayDistanceType = saved or Enum.HumanoidDisplayDistanceType.Viewer
    end
    originalDisplayTypes[plr.UserId] = nil
    hiddenHumanoids[plr.UserId] = nil
end

function MonochromeNametags.setEnabled(enabled)
    enabled = enabled and true or false
    if nametagEnabled == enabled then return nametagEnabled end
    nametagEnabled = enabled
    if nametagEnabled then
        if nametagGui then nametagGui.Enabled = true else MonochromeNametags.createNametag() end
        for _, tagData in pairs(otherNametags) do
            if tagData.gui then tagData.gui.Enabled = true end
        end
        MonochromeNametags.hideDefaultNametag(LocalPlayer)
        for userId in pairs(otherNametags) do
            local plr = Players:GetPlayerByUserId(userId)
            if plr then MonochromeNametags.hideDefaultNametag(plr) end
        end
    else
        if nametagGui then nametagGui.Enabled = false end
        for _, tagData in pairs(otherNametags) do
            if tagData.gui then tagData.gui.Enabled = false end
        end
        MonochromeNametags.restoreDefaultNametag(LocalPlayer)
        for userId in pairs(otherNametags) do
            local plr = Players:GetPlayerByUserId(userId)
            if plr then MonochromeNametags.restoreDefaultNametag(plr) end
        end
    end
    return nametagEnabled
end

function MonochromeNametags.toggle() return MonochromeNametags.setEnabled(not nametagEnabled) end

function MonochromeNametags.isEnabled() return nametagEnabled end

function MonochromeNametags.setHidden(hidden)
    return MonochromeNametags.setEnabled(not (hidden and true or false))
end

function MonochromeNametags.isHidden() return not nametagEnabled end

function MonochromeNametags.updateOtherNametags()
    local myUserId = Players.LocalPlayer.UserId
    for _, plrObj in ipairs(Players:GetPlayers()) do
        if plrObj.UserId ~= myUserId then
            local row      = remoteConfigs[plrObj.UserId]
            local config   = monoNametagConfigFor(plrObj)
            local sig      = rowSignature(row)
            local existing = otherNametags[plrObj.UserId]
            local live    = MonochromeNametags.otherTagLive(plrObj.UserId)

            if config then
                if not live then
                    if plrObj.Character and plrObj.Character:FindFirstChild("Head") then
                        MonochromeNametags.createOtherNametag(plrObj)
                    end
                elseif appliedSignatures[plrObj.UserId] ~= sig then
                    MonochromeNametags.createOtherNametag(plrObj)
                end
            elseif existing then
                MonochromeNametags.removeOtherNametag(plrObj.UserId)
            end
        end
    end

    local currentPlayers = {}
    for _, plrObj in ipairs(Players:GetPlayers()) do currentPlayers[plrObj.UserId] = true end
    for userId in pairs(otherNametags) do
        if not currentPlayers[userId] then
            MonochromeNametags.removeOtherNametag(userId)
        end
    end
end

function MonochromeNametags.cleanup(keepDatabaseRow)
    for textLabel in pairs(typingEffectConnections) do stopTypingEffect(textLabel) end
    for imageLabel in pairs(frameAnimationConnections) do stopFrameAnimation(imageLabel) end

    nametagGeneration = nametagGeneration + 1
    autoSyncEnabled = false
    creatingSelf = false
    creatingOther = {}
    if LocalPlayer then task.spawn(function() pcall(markPresenceOffline, LocalPlayer.UserId) end) end
    for _, c in pairs(nametagConns) do pcall(function() c:Disconnect() end) end
    nametagConns = {}
    MonochromeNametags.restoreDefaultNametag(LocalPlayer)
    for uid in pairs(originalDisplayTypes) do
        local plr = Players:GetPlayerByUserId(uid)
        if plr then MonochromeNametags.restoreDefaultNametag(plr) end
    end
    MonochromeNametags.clearAllNametags()
    local player = LocalPlayer
    if not keepDatabaseRow and player then task.spawn(function() deleteUserRow(player.UserId) end) end
    nametagGui = nil
    nametagEnabled = false
    originalDisplayTypes = {}
    hiddenHumanoids = {}
    for uid, c in pairs(characterAddedConns) do
        pcall(function() c:Disconnect() end)
        characterAddedConns[uid] = nil
    end
end

function MonochromeNametags.shutdown()
    MonochromeNametags.cleanup(true)
end

function setupPlayerCharacterHandler(plr)
    if characterAddedConns[plr.UserId] then
        pcall(function() characterAddedConns[plr.UserId]:Disconnect() end)
    end
    characterAddedConns[plr.UserId] = plr.CharacterAdded:Connect(function(char)
        MonochromeNametags.waitForHead(plr)
        if plr == Players.LocalPlayer then
            MonochromeNametags.createNametag()
            if nametagEnabled and MonochromeNametags.selfTagLive() then MonochromeNametags.hideDefaultNametag(plr) end
            if nametagEnabled and not MonochromeNametags.selfTagLive() then MonochromeNametags.restoreDefaultNametag(plr) end
        else
            if getNametagConfig(plr.UserId) then
                local built = MonochromeNametags.createOtherNametag(plr)
                if nametagEnabled and built then MonochromeNametags.hideDefaultNametag(plr) end
                if not built then MonochromeNametags.restoreDefaultNametag(plr) end
            end
        end
    end)
end

function setupGrabCommand()
    local ReplicatedStorage = game:GetService("ReplicatedStorage")
    local localPlayer       = Players.LocalPlayer

    local function findPlayer(query)
        query = query:lower()
        for _, plr in ipairs(Players:GetPlayers()) do
            if plr ~= localPlayer and plr.DisplayName:lower() == query then
                return plr
            end
        end
        for _, plr in ipairs(Players:GetPlayers()) do
            if plr ~= localPlayer and plr.Name:lower() == query then
                return plr
            end
        end
        for _, plr in ipairs(Players:GetPlayers()) do
            if plr ~= localPlayer then
                local dn = plr.DisplayName:lower()
                local un = plr.Name:lower()
                if dn:find(query, 1, true) or un:find(query, 1, true) then
                    return plr
                end
            end
        end
        return nil
    end

    local function onMessage(message, fromUserId)
        if type(message) ~= "string" or message:sub(1, 1) ~= "." then return end
        local query = message:sub(2):gsub("^%s+", ""):gsub("%s+$", "")
        if query == "" then return end
        fromUserId = fromUserId or localPlayer.UserId
        local _lower = query:lower()

    if fromUserId ~= localPlayer.UserId then return end

        local target = findPlayer(query)
        if not target then
            return
        end

        local grabEvent   = ReplicatedStorage:FindFirstChild("GrabRequest")
        local acceptEvent = ReplicatedStorage:FindFirstChild("AcceptGrab")

        if grabEvent then
            pcall(function() grabEvent:FireServer(0, "left_shoulder") end)
        end

        if acceptEvent then
            pcall(function() acceptEvent:FireServer(target.UserId) end)
        end
    end

    pcall(function()
        localPlayer.Chatted:Connect(function(msg)
            onMessage(msg, localPlayer.UserId)
        end)
    end)

    pcall(function()
        local TCS = game:GetService("TextChatService")
        if TCS.ChatVersion ~= Enum.ChatVersion.TextChatService then return end

        local function hookChannel(channel)
            if not channel:IsA("TextChannel") then return end
            channel.MessageReceived:Connect(function(msg)
                if msg.TextSource then
                    onMessage(msg.Text, msg.TextSource.UserId)
                end
            end)
        end

        for _, ch in ipairs(TCS:GetDescendants()) do hookChannel(ch) end
        TCS.DescendantAdded:Connect(hookChannel)
    end)
end

function MonochromeNametags.initialize()
    local player = Players.LocalPlayer

    MonochromeNametags.clearAllNametags()

    syncPresence(true)
    ensureOwnRowIfMissing(false)

    task.wait(0.6)
    syncTags()

    if player.Character and player.Character:FindFirstChild("Head") then
        MonochromeNametags.createNametag()
        if nametagEnabled and MonochromeNametags.selfTagLive() then MonochromeNametags.hideDefaultNametag(player) end
    else
        nametagConns[#nametagConns + 1] = player.CharacterAdded:Once(function()
            task.wait(0.5)
            MonochromeNametags.createNametag()
            if nametagEnabled and MonochromeNametags.selfTagLive() then MonochromeNametags.hideDefaultNametag(player) end
        end)
    end

    MonochromeNametags.updateOtherNametags()

    for _, plr in ipairs(Players:GetPlayers()) do
        setupPlayerCharacterHandler(plr)
    end

    nametagConns[#nametagConns + 1] = Players.PlayerAdded:Connect(function(plr)
        setupPlayerCharacterHandler(plr)
        task.wait(1.5)
        pcall(syncTags)
        if getNametagConfig(plr.UserId) then
            if plr.Character and plr.Character:FindFirstChild("Head") then
                MonochromeNametags.createOtherNametag(plr)
            end
        end
    end)

    nametagConns[#nametagConns + 1] = Players.PlayerRemoving:Connect(function(leavingPlayer)
        if characterAddedConns[leavingPlayer.UserId] then
            pcall(function() characterAddedConns[leavingPlayer.UserId]:Disconnect() end)
            characterAddedConns[leavingPlayer.UserId] = nil
        end
        MonochromeNametags.removeOtherNametag(leavingPlayer.UserId)
        task.spawn(function() pcall(markPresenceOffline, leavingPlayer.UserId) end)
    end)

    task.spawn(function()
        while autoSyncEnabled do
            task.wait(SUPABASE.autoSyncInterval)
            if not autoSyncEnabled then break end
            pcall(syncTags)
            local mySig = rowSignature(remoteConfigs[player.UserId])
            if appliedSignatures[player.UserId] ~= mySig or not nametagGui then
                MonochromeNametags.createNametag()
            end
            MonochromeNametags.updateOtherNametags()
        end
    end)

    task.spawn(function()
        while autoSyncEnabled do
            task.wait(SUPABASE.presenceInterval)
            if not autoSyncEnabled then break end
            pcall(function() syncPresence(false) end)
        end
    end)

end

if setData.hideNametags then MonochromeNametags.setHidden(true) end

task.spawn(function()
    if not monoWaitLoad() then return end
    MonochromeNametags.initialize()
end)

task.spawn(setupGrabCommand)

Library:OnDestroy(function() MonochromeNametags.shutdown() end)

MONO_TERM_W = 340
MONO_TERM_H = 38
MONO_TERM_Y = 96
MONO_TERM_X = 32
MONO_TERM_SIZE = 13
MONO_TERM_FONT = Enum.Font.RobotoMono

if type(setData.terminalKey) == "string" and setData.terminalKey ~= "" then
    monoTermKey = setData.terminalKey
elseif setData.terminalKey == false then
    monoTermKey = false
else
    monoTermKey = "F5"
end

monoTerm = {
    built = false,
    open = false,
    justOpened = false,
    gui = nil,
    panel = nil,
    input = nil,
    ghost = nil,
    bg = nil,
    shade = nil,
    conn = nil,
}

function monoTermKeyName()
    if type(monoTermKey) == "string" and monoTermKey ~= "" then return monoTermKey end
    return nil
end

function monoTermBgSync()
    if not monoTerm.bg or not monoTerm.bg.Parent then return end
    local on = (monoBgImage
        and typeof(monoBgImage) == "Instance"
        and monoBgImage.Parent ~= nil
        and monoBgImage.Visible == true
        and monoBgImage.Image ~= "") and true or false
    monoTerm.bg.Visible = on
    monoTerm.bg.Image = on and monoBgImage.Image or ""
    monoTerm.bg.ImageTransparency = on and monoCustomBgTransparency() or 0
    if monoTerm.shade then
        local dim = setData and setData.bgDim or 55
        monoTerm.shade.BackgroundTransparency = on and (dim / 100) or 1
    end
    if monoTerm.panel and monoTerm.panel.Parent then
        local target = monoUiPanelTransparency()
        if math.abs(monoTerm.panel.BackgroundTransparency - target) > 0.001 then
            tween(monoTerm.panel, { BackgroundTransparency = target }, 0.2)
        end
    end
end

function monoTermGhostClear()
    if not monoTerm.ghost then return end
    monoTerm.ghost.Text = ""
    monoTerm.ghost.Position = UDim2.new(0, MONO_TERM_X, 0, 0)
end

function monoTermGhost()
    local input = monoTerm.input
    if not input or not monoTerm.ghost then return end
    local typed = input.Text
    if typed == "" or typed:find("%s") then
        monoTermGhostClear()
        return
    end
    local lower = typed:lower()
    for _, cmd in ipairs(monoCmdSorted()) do
        if cmd.name:sub(1, #lower) == lower then
            local w = game:GetService("TextService"):GetTextSize(
                typed, MONO_TERM_SIZE, MONO_TERM_FONT, Vector2.new(10000, MONO_TERM_H)).X
            monoTerm.ghost.Text = cmd.name:sub(#typed + 1)
            monoTerm.ghost.Position = UDim2.new(0, MONO_TERM_X + w, 0, 0)
            return
        end
    end
    monoTermGhostClear()
end

function monoTermSubmit()
    local input = monoTerm.input
    if not input then return end
    local line = input.Text
    if monoTerm.ghost and monoTerm.ghost.Text ~= "" then line = line .. monoTerm.ghost.Text end
    input.Text = ""
    monoTermClose()
    if line == "" then return end
    local args = {}
    for part in line:gmatch("%S+") do args[#args + 1] = part end
    if #args == 0 then return end
    args[1] = args[1]:lower()
    monoChatRun(args)
end

function monoTermOpen()
    if not monoTerm.built then monoTermBuild() end
    if not monoTerm.panel then return end
    if monoTerm.open then return end
    monoTerm.open = true
    monoTerm.justOpened = true
    monoTerm.panel.Visible = true
    monoTerm.panel.Size = UDim2.new(0, 0, 0, MONO_TERM_H)
    tween(monoTerm.panel, { Size = UDim2.new(0, MONO_TERM_W, 0, MONO_TERM_H) }, 0.22)
    task.delay(0.1, function() monoTerm.justOpened = false end)
    task.delay(0.06, function()
        if monoTerm.open and monoTerm.input then
            pcall(function() monoTerm.input:CaptureFocus() end)
        end
    end)
end

function monoTermClose()
    if not monoTerm.panel then return end
    if not monoTerm.open then return end
    monoTerm.open = false
    monoTerm.justOpened = false
    if monoTerm.input then
        pcall(function() monoTerm.input:ReleaseFocus() end)
        monoTerm.input.Text = ""
    end
    tween(monoTerm.panel, { Size = UDim2.new(0, 0, 0, MONO_TERM_H) }, 0.22)
    task.delay(0.22, function()
        local panel = monoTerm.panel
        if panel and panel.Visible and not monoTerm.open then
            panel.Visible = false
            panel.Size = UDim2.new(0, MONO_TERM_W, 0, MONO_TERM_H)
        end
    end)
end

function monoTermToggle()
    if monoTerm.open then
        monoTermClose()
    else
        monoTermOpen()
    end
end

function monoTermBindKey(name)
    monoTermKey = name
    if type(setData) == "table" then
        setData.terminalKey = name
        if type(setSave) == "function" then setSave() end
    end
    if type(toggleUIKeyName) == "string" and toggleUIKeyName == name then
        Window:ClearToggleKeyName()
        if type(setData) == "table" then
            setData.toggleUIKey = false
            if type(setSave) == "function" then setSave() end
        end
        notify("Monochrome", "toggleui keybind cleared", 2)
    end
    if type(monoCmdBinds) == "table" then
        for k, v in pairs(monoCmdBinds) do
            if v == name then monoCmdBindSet(k, nil) end
        end
    end
    if type(monoSneak) == "table" and monoSneak.key == name then monoSneakKeySet(nil) end
    notify("Monochrome", "terminal bound to " .. name, 2)
end

function monoTermUnbindKey()
    local had = monoTermKeyName()
    monoTermKey = false
    if type(setData) == "table" then
        setData.terminalKey = false
        if type(setSave) == "function" then setSave() end
    end
    if had then notify("Monochrome", "terminal keybind cleared", 2) end
end

function monoTermBuild()
    if monoTerm.built then return end
    monoTerm.built = true

    local old = monoGuiFind("MonochromeTerminal")
    if old then pcall(function() old:Destroy() end) end

    local gui = create("ScreenGui", {
        Name = "MonochromeTerminal",
        IgnoreGuiInset = true,
        ResetOnSpawn = false,
        ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
    })
    monoGuiParent(gui)
    applyDisplayOrder(gui, MONO_ORDER.Terminal, MONO_ORDER_OLD.Terminal)
    monoTerm.gui = gui

    local panel = create("Frame", {
        Name = "Panel",
        Size = UDim2.new(0, MONO_TERM_W, 0, MONO_TERM_H),
        Position = UDim2.new(0.5, 0, 1, -MONO_TERM_Y),
        AnchorPoint = Vector2.new(0.5, 1),
        BackgroundColor3 = C.panel,
        BackgroundTransparency = monoUiPanelTransparency(),
        BorderSizePixel = 0,
        Visible = false,
        ClipsDescendants = true,
    }, gui)
    corner(panel, 10)
    stroke(panel, C.border, 1, 0.3)
    monoTerm.panel = panel

    local bgClip = create("Frame", {
        Name = "BgClip", Size = UDim2.new(1, 0, 1, 0),
        BackgroundTransparency = 1, BorderSizePixel = 0, ClipsDescendants = true,
        ZIndex = 2,
    }, panel)
    corner(bgClip, 10)
    monoTerm.bg = create("ImageLabel", {
        Name = "Bg", Size = UDim2.new(1, 0, 1, 0),
        BackgroundTransparency = 1, BorderSizePixel = 0,
        Image = "", ScaleType = Enum.ScaleType.Crop, Visible = false,
        ZIndex = 2,
    }, bgClip)
    corner(monoTerm.bg, 10)
    monoTerm.shade = create("Frame", {
        Name = "BgShade", Size = UDim2.new(1, 0, 1, 0),
        BackgroundColor3 = C.bg, BackgroundTransparency = 1, BorderSizePixel = 0,
        ZIndex = 3,
    }, bgClip)
    corner(monoTerm.shade, 10)

    create("TextLabel", {
        Name = "Prompt",
        Size = UDim2.new(0, 24, 0, MONO_TERM_H),
        Position = UDim2.new(0, 8, 0, 0),
        BackgroundTransparency = 1,
        Text = ">",
        TextColor3 = C.text,
        TextSize = 18,
        Font = Enum.Font.Gotham,
        ZIndex = 101,
    }, panel)

    monoTerm.ghost = create("TextLabel", {
        Name = "Ghost",
        Size = UDim2.new(1, -44, 0, MONO_TERM_H),
        Position = UDim2.new(0, MONO_TERM_X, 0, 0),
        BackgroundTransparency = 1,
        Text = "",
        TextColor3 = C.textDim,
        TextSize = MONO_TERM_SIZE,
        Font = MONO_TERM_FONT,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextTruncate = Enum.TextTruncate.None,
        ZIndex = 102,
    }, panel)

    monoTerm.input = create("TextBox", {
        Name = "Input",
        Size = UDim2.new(1, -44, 0, MONO_TERM_H),
        Position = UDim2.new(0, MONO_TERM_X, 0, 0),
        BackgroundTransparency = 1,
        Text = "",
        PlaceholderText = "Type a command",
        PlaceholderColor3 = C.text,
        TextColor3 = C.text,
        TextSize = MONO_TERM_SIZE,
        Font = MONO_TERM_FONT,
        TextXAlignment = Enum.TextXAlignment.Left,
        ClearTextOnFocus = false,
        TextEditable = true,
        TextStrokeTransparency = 1,
        ZIndex = 105,
    }, panel)

    trackConn(monoTerm.input:GetPropertyChangedSignal("Text"):Connect(monoTermGhost))

    trackConn(monoTerm.input.FocusLost:Connect(function(enterPressed)
        if enterPressed then
            monoTermSubmit()
            return
        end
        if monoTerm.justOpened then return end
        monoTermClose()
    end))

    trackConn(UserInputService.InputBegan:Connect(function(input, gameProcessed)
        if not monoTerm.panel or not monoTerm.panel.Visible then return end
        if monoTerm.justOpened then return end
        if monoBindCapturing or monoBindSwallow then return end
        local focused = UserInputService:GetFocusedTextBox()
        if gameProcessed and focused ~= monoTerm.input then return end
        if input.KeyCode == Enum.KeyCode.Tab then
            local ghost = monoTerm.ghost
            if ghost and ghost.Text ~= "" then
                local full = monoTerm.input.Text .. ghost.Text
                monoTerm.input.Text = full
                monoTerm.input.CursorPosition = #full + 1
                ghost.Text = ""
            elseif monoTerm.input then
                pcall(function() monoTerm.input:CaptureFocus() end)
            end
        elseif input.KeyCode == Enum.KeyCode.Escape then
            monoTermClose()
        end
    end))

    monoTermBgSync()
end

function monoTermConnect()
    if monoTerm.conn then return end
    monoTerm.conn = UserInputService.InputBegan:Connect(function(input, gameProcessed)
        if gameProcessed or monoBindCapturing or monoBindSwallow or monoKeyCaptureActive then return end
        if input.UserInputType ~= Enum.UserInputType.Keyboard then return end
        if input.KeyCode == Enum.KeyCode.Unknown then return end
        local name = monoTermKeyName()
        if not name or input.KeyCode.Name ~= name then return end
        local focused = UserInputService:GetFocusedTextBox()
        if gameProcessed and focused ~= monoTerm.input then return end
        monoTermToggle()
    end)
end

function monoTermShutdown()
    if monoTerm.conn then
        pcall(function() monoTerm.conn:Disconnect() end)
        monoTerm.conn = nil
    end
    if monoTerm.input then pcall(function() monoTerm.input:ReleaseFocus() end) end
    if monoTerm.gui then pcall(function() monoTerm.gui:Destroy() end) end
    monoTerm.gui = nil
    monoTerm.panel = nil
    monoTerm.input = nil
    monoTerm.ghost = nil
    monoTerm.bg = nil
    monoTerm.shade = nil
    monoTerm.open = false
    monoTerm.justOpened = false
    monoTerm.built = false
end

monoTermConnect()
monoCmdOnDestroy("terminal", monoTermShutdown)

function settingSwitch(order, text, on, callback)
    local page = Settings._page
    local row = create("Frame", {
        Size = UDim2.new(1, 0, 0, 34), BackgroundColor3 = C.surface,
        BackgroundTransparency = 0.4, BorderSizePixel = 0, LayoutOrder = order,
    }, page)
    corner(row, 10); stroke(row, C.borderSoft, 1, 0.55)
    create("TextLabel", {
        Size = UDim2.new(1, -60, 1, 0), Position = UDim2.new(0, 14, 0, 0),
        BackgroundTransparency = 1, Text = text, TextColor3 = C.text,
        TextSize = 11, Font = Enum.Font.Gotham, TextXAlignment = Enum.TextXAlignment.Left,
    }, row)
    local sw = create("Frame", {
        Size = UDim2.new(0, 38, 0, 20), Position = UDim2.new(1, -52, 0.5, -10),
        BackgroundColor3 = on and C.accent or C.input, BorderSizePixel = 0,
    }, row)
    corner(sw, 999); stroke(sw, C.borderSoft, 1, 0.55)
    local knob = create("Frame", {
        Size = UDim2.new(0, 14, 0, 14),
        Position = on and UDim2.new(1, -17, 0.5, -7) or UDim2.new(0, 3, 0.5, -7),
        BackgroundColor3 = on and C.bg or C.text, BorderSizePixel = 0,
    }, sw)
    corner(knob, 999)
    local hit = create("TextButton", {
        Size = UDim2.new(1, 0, 1, 0), BackgroundTransparency = 1, Text = "",
    }, sw)
    hit.MouseButton1Click:Connect(function()
        on = not on
        tween(sw, { BackgroundColor3 = on and C.accent or C.input }, 0.2)
        tween(knob, {
            BackgroundColor3 = on and C.bg or C.text,
            Position = on and UDim2.new(1, -17, 0.5, -7) or UDim2.new(0, 3, 0.5, -7),
        }, 0.22)
        if callback then callback(on) end
    end)
    return row
end

function settingKeybind(order, text, getKey, applyKey, clearKey)
    local page = Settings._page
    local row = create("Frame", {
        Size = UDim2.new(1, 0, 0, 34), BackgroundColor3 = C.surface,
        BackgroundTransparency = 0.4, BorderSizePixel = 0, LayoutOrder = order,
    }, page)
    corner(row, 10); stroke(row, C.borderSoft, 1, 0.55)
    create("TextLabel", {
        Size = UDim2.new(1, -90, 1, 0), Position = UDim2.new(0, 14, 0, 0),
        BackgroundTransparency = 1, Text = text, TextColor3 = C.text,
        TextSize = 11, Font = Enum.Font.Gotham, TextXAlignment = Enum.TextXAlignment.Left,
    }, row)
    local btn = create("TextButton", {
        Size = UDim2.new(0, 52, 0, 20), Position = UDim2.new(1, -66, 0.5, -10),
        BackgroundColor3 = C.input, BorderSizePixel = 0,
        Text = monoCmdBindShort(getKey()), TextColor3 = getKey() and C.accent or C.textDim,
        TextSize = 10, Font = Enum.Font.Gotham, AutoButtonColor = false, ZIndex = 2,
    }, row)
    corner(btn, 6); stroke(btn, C.borderSoft, 1, 0.55)

    local function chipPaint(k)
        pcall(function()
            btn.Text = monoCmdBindShort(k)
            btn.TextColor3 = k and C.accent or C.textDim
        end)
    end

    btn.MouseButton1Click:Connect(function()
        if monoBindCapturing then
            monoBindEndCapture()
            chipPaint(getKey())
            clearKey()
            chipPaint(getKey())
            return
        end
        btn.Text = "..."
        btn.TextColor3 = C.accent
        monoBindCapture(function(input)
            local name = input.KeyCode.Name
            applyKey(name)
            chipPaint(name)
            monoCmdRefresh()
        end, function()
            chipPaint(getKey())
        end)
    end)
    return row
end

