CHAT_TABLE          = "monochrome_chat"
CHAT_FETCH_LIMIT    = 60
CHAT_MAX_LEN        = 300
CHAT_SEND_COOLDOWN  = 1.5
CHAT_POLL_INTERVAL  = 4
CHAT_LIST_INSET    = 46
CHAT_SCROLLBAR     = 3
FILTER_MESSAGES     = false

chatPage      = Chat._page
chatMessages = {}
chatLastId    = 0
chatNextSend  = 0
chatAlive      = true
chatListScroll = nil

function chatStamp(iso)
    local ok, dt = pcall(function() return DateTime.fromIsoDate(iso) end)
    if not ok or not dt then return "" end
    local ok2, s = pcall(function() return dt:FormatLocalTime("HH:mm", "en") end)
    if ok2 and s then return s end
    return tostring(iso):sub(12, 16)
end

function chatThumb(uid, imageLabel)
    pcall(function()
        local content = Players:GetUserThumbnailAsync(uid, Enum.ThumbnailType.HeadShot, Enum.ThumbnailSize.Size150x150)
        if content and imageLabel and imageLabel.Parent then imageLabel.Image = content end
    end)
end

function chatScrollToBottom()
    task.defer(function()
        if not chatListScroll or not chatListScroll.Parent then return end
        if chatListScroll.AbsoluteCanvasSize.Y <= chatListScroll.AbsoluteWindowSize.Y + 1 then
            chatListScroll.CanvasPosition = Vector2.new(0, 0)
            return
        end
        local maxY = math.max(0, chatListScroll.AbsoluteCanvasSize.Y - chatListScroll.AbsoluteWindowSize.Y)
        chatListScroll.CanvasPosition = Vector2.new(0, maxY)
    end)
end

function chatUpdateScrollState()
    if not chatListScroll or not chatListScroll.Parent then return end
    local over = chatListScroll.AbsoluteCanvasSize.Y > chatListScroll.AbsoluteWindowSize.Y + 1
    local want = over and CHAT_SCROLLBAR or 0
    if chatListScroll.ScrollBarThickness ~= want then chatListScroll.ScrollBarThickness = want end
end

function chatClear()
    for _, child in ipairs(chatListScroll:GetChildren()) do
        if child:IsA("Frame") then pcall(function() child:Destroy() end) end
    end
    table.clear(chatMessages)
    chatUpdateScrollState()
    chatScrollToBottom()
end

function chatDrawRow(m)
    local msg = tostring(m.message or "")
    local listW = chatListScroll.AbsoluteSize.X
    if listW < 40 then listW = 340 end
    local msgW = math.max(60, listW - 26)
    local textH = 16
    local okTs, ts = pcall(function()
        return game:GetService("TextService"):GetTextSize(msg, 11, Enum.Font.Gotham, Vector2.new(msgW, math.huge))
    end)
    if okTs and ts then textH = math.max(16, ts.Y + 4) end
    local rowH = math.min(44 + textH + 10, 420)

    local row = create("Frame", {
        Size = UDim2.new(1, -6, 0, rowH), BackgroundColor3 = C.surface,
        BackgroundTransparency = 0.4, BorderSizePixel = 0, LayoutOrder = 1,
    }, chatListScroll)
    corner(row, 10); stroke(row, C.borderSoft, 1, 0.55)

    local av = create("ImageLabel", {
        Size = UDim2.new(0, 36, 0, 36), Position = UDim2.new(0, 10, 0, 9),
        BackgroundColor3 = C.input, BorderSizePixel = 0,
        ScaleType = Enum.ScaleType.Crop, Image = "",
    }, row)
    corner(av, 999)
    chatThumb(m.user_id, av)

    create("TextLabel", {
        Size = UDim2.new(1, -150, 0, 15), Position = UDim2.new(0, 54, 0, 9),
        BackgroundTransparency = 1, Text = tostring(m.display_name or m.username or "?"),
        TextColor3 = C.text, TextSize = 11, Font = Enum.Font.GothamBold,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextTruncate = Enum.TextTruncate.AtEnd,
    }, row)

    create("TextLabel", {
        Size = UDim2.new(1, -150, 0, 14), Position = UDim2.new(0, 54, 0, 25),
        BackgroundTransparency = 1, Text = "@" .. tostring(m.username or "unknown"),
        TextColor3 = C.textDim, TextSize = 10, Font = Enum.Font.Gotham,
        TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd,
    }, row)

    create("TextLabel", {
        Size = UDim2.new(0, 66, 0, 13), Position = UDim2.new(1, -12, 0, 11),
        BackgroundTransparency = 1, Text = chatStamp(m.created_at),
        TextColor3 = C.textDim, TextSize = 8, Font = Enum.Font.Gotham,
        TextXAlignment = Enum.TextXAlignment.Right,
    }, row)

    create("TextLabel", {
        Size = UDim2.new(1, -20, 0, textH), Position = UDim2.new(0, 10, 0, 44),
        BackgroundTransparency = 1, Text = tostring(m.message or ""),
        TextColor3 = C.text, TextSize = 11, Font = Enum.Font.Gotham, TextWrapped = true,
        TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Top,
    }, row)

    create("UIPadding", { PaddingBottom = UDim.new(0, 10) }, row)
end

function chatAppend(rows)
    local added = false
    for _, m in ipairs(rows) do
        local id = tonumber(m.id)
        if id and not chatMessages[id] then
            chatMessages[id] = true
            chatDrawRow(m)
            added = true
        end
    end
    if added then
        chatUpdateScrollState()
        chatScrollToBottom()
    end
end

function chatFetchLatest()
    local rows = supabaseGet(CHAT_TABLE .. "?select=*&order=id.desc&limit=" .. CHAT_FETCH_LIMIT)
    if type(rows) ~= "table" then return end
    chatClear()
    local ordered = {}
    for _, m in ipairs(rows) do ordered[#ordered + 1] = m end
    table.sort(ordered, function(a, b) return (tonumber(a.id) or 0) < (tonumber(b.id) or 0) end)
    chatAppend(ordered)
    chatLastId = 0
    for _, m in ipairs(ordered) do
        local id = tonumber(m.id)
        if id and id > chatLastId then chatLastId = id end
    end
end

function chatFetchNew()
    if chatLastId <= 0 then return chatFetchLatest() end
    local rows = supabaseGet(CHAT_TABLE .. "?select=*&id=gt." .. chatLastId .. "&order=id.asc&limit=100")
    if type(rows) ~= "table" then return end
    for _, m in ipairs(rows) do
        local id = tonumber(m.id)
        if id and id > chatLastId then chatLastId = id end
    end
    chatAppend(rows)
    return nil
end

function chatSend()
    if not chatInput then return end
    local text = chatInput.Text
    text = text:gsub("^%s+", ""):gsub("%s+$", "")
    if text == "" then return end
    if tick() < chatNextSend then return end
    if #text > CHAT_MAX_LEN then text = text:sub(1, CHAT_MAX_LEN) end
    if FILTER_MESSAGES then
        local ok, filtered = pcall(function()
            return game:GetService("TextService"):FilterStringAsync(text, LocalPlayer.UserId)
        end)
        if ok and filtered and filtered.GetNonChatStringForBroadcastAsync then
            local ok2, clean = pcall(function() return filtered:GetNonChatStringForBroadcastAsync() end)
            if ok2 and clean and clean ~= "" then text = clean end
        end
    end
    chatNextSend = tick() + CHAT_SEND_COOLDOWN
    chatInput.Text = ""
    local _res = supabaseRequest("POST", CHAT_TABLE, {
        user_id      = LocalPlayer.UserId,
        username     = LocalPlayer.Name,
        display_name = LocalPlayer.DisplayName or LocalPlayer.Name,
        message      = text,
    })
end

chatListScroll = create("ScrollingFrame", {
    Name = "ChatList", Size = UDim2.new(1, 0, 1, -CHAT_LIST_INSET), BackgroundTransparency = 1,
    BorderSizePixel = 0, ClipsDescendants = true, ScrollBarThickness = 0,
    ScrollBarImageColor3 = C.border, CanvasSize = UDim2.new(0, 0, 0, 0), AutomaticCanvasSize = Enum.AutomaticSize.Y,
    ScrollingDirection = Enum.ScrollingDirection.Y, LayoutOrder = 1,
}, chatPage)

create("UIListLayout", {
    Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder,
    HorizontalAlignment = Enum.HorizontalAlignment.Center,
}, chatListScroll)
pcall(function() trackConn(chatListScroll:GetPropertyChangedSignal("AbsoluteCanvasSize"):Connect(chatUpdateScrollState)) end)
pcall(function() trackConn(chatListScroll:GetPropertyChangedSignal("AbsoluteWindowSize"):Connect(chatUpdateScrollState)) end)
task.defer(chatUpdateScrollState)

function chatSyncScroll()
    if not chatListScroll or not chatListScroll.Parent then return end
    chatUpdateScrollState()
end

task.spawn(function()
    while chatAlive do
        task.wait(0.5)
        if not chatAlive then break end
        chatSyncScroll()
    end
end)

chatInputRow = create("Frame", {
    Size = UDim2.new(1, 0, 0, 34), BackgroundTransparency = 1,
    BorderSizePixel = 0, LayoutOrder = 2,
}, chatPage)
chatInput = create("TextBox", {
    Size = UDim2.new(1, -74, 1, 0), Position = UDim2.new(0, 0, 0, 0),
    BackgroundColor3 = C.surface, BackgroundTransparency = 0.4,
    BorderSizePixel = 0, Text = "", PlaceholderText = "Message...",
    PlaceholderColor3 = C.textDim, TextColor3 = C.text, TextSize = 11,
    Font = Enum.Font.Gotham, TextXAlignment = Enum.TextXAlignment.Left,
    ClearTextOnFocus = false,
}, chatInputRow)
corner(chatInput, 10); stroke(chatInput, C.borderSoft, 1, 0.55)
create("UIPadding", { PaddingLeft = UDim.new(0, 10), PaddingRight = UDim.new(0, 6) }, chatInput)

chatSendBtn = create("TextButton", {
    Size = UDim2.new(0, 64, 1, 0), Position = UDim2.new(1, -68, 0, 0),
    BackgroundColor3 = C.accent, BorderSizePixel = 0, Text = "Send",
    TextColor3 = C.bg, TextSize = 11, Font = Enum.Font.GothamBold,
    AutoButtonColor = false,
}, chatInputRow)
corner(chatSendBtn, 10); stroke(chatSendBtn, C.borderSoft, 1, 0.55)

chatSendBtn.MouseEnter:Connect(function()
    tween(chatSendBtn, { BackgroundTransparency = 0.12 }, 0.15)
end)
chatSendBtn.MouseLeave:Connect(function()
    tween(chatSendBtn, { BackgroundTransparency = 0 }, 0.15)
end)
chatSendBtn.MouseButton1Down:Connect(function()
    tween(chatSendBtn, { BackgroundTransparency = 0.3 }, 0.08)
end)
chatSendBtn.MouseButton1Up:Connect(function()
    tween(chatSendBtn, { BackgroundTransparency = 0.12 }, 0.12)
end)

trackConn(chatSendBtn.MouseButton1Click:Connect(chatSend))
trackConn(chatInput.FocusLost:Connect(function(enter)
    if enter then chatSend() end
end))

task.defer(function()
    pcall(chatFetchLatest)
    while chatAlive do
        task.wait(CHAT_POLL_INTERVAL)
        if not chatAlive then break end
        pcall(chatFetchNew)
    end
end)

Library:OnDestroy(function()
    chatAlive = false
    for _, child in ipairs(chatListScroll:GetChildren()) do
        if child:IsA("Frame") then pcall(function() child:Destroy() end) end
    end
end)

task.spawn(function()
    while not monoLoadDone do task.wait(0.05) end
    monoHideEnsureEnforce()
    monoHideEnsurePlayerAdded()
    monoMuteEnsureEnforce()
    monoMuteEnsurePlayerAdded()
    if _G.MONO_HIDE_ALL == true then monoHideEnsureHideAll() end
end)

monoLoadDone = true

pcall(function() monoEnv.MONO_LIBRARY = Library end)
pcall(function() _G.MONO_LIBRARY = Library end)
return Library
